// ── Section 60: forge-xllm --result-file guard (challenge/rebuttal) + Engine Fallback Discipline ──
function smokeXllmResultFileGuard() {
  process.stdout.write('\n▸ Section 60: forge-xllm --result-file guard + Engine Fallback Discipline\n');
  const repo = path.dirname(SCRIPTS);
  const mockDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-s60-mock-'));
  writeMockCodex(mockDir, { payload: '{}', exitCode: 0 });

  // (a) challenge + --result-file → exit 2, stderr mentions result-file, file never created.
  {
    const dir = mkTmp('s60-challenge');
    const resFile = path.join(dir, 'g.json');
    const r = runXllm(['--mode', 'challenge', '--result-file', resFile, '--diff-cmd', 'echo diff', '--cwd', dir], mockDir, dir);
    assert(r.status === 2, '(a) challenge --result-file exits 2', `status=${r.status}`);
    assert(r.stderr.includes('result-file'), '(a) challenge --result-file stderr mentions result-file', r.stderr);
    assert(!fs.existsSync(resFile), '(a) challenge --result-file never creates the file');
    cleanup(dir);
  }

  // (b) rebuttal + --result-file → exit 2, same guard.
  {
    const dir = mkTmp('s60-rebuttal');
    const resFile = path.join(dir, 'g.json');
    const inputFile = path.join(dir, 'input.json');
    fs.writeFileSync(inputFile, JSON.stringify({ objections: [] }), 'utf8');
    const r = runXllm(['--mode', 'rebuttal', '--result-file', resFile, '--input', inputFile, '--cwd', dir], mockDir, dir);
    assert(r.status === 2, '(b) rebuttal --result-file exits 2', `status=${r.status}`);
    assert(r.stderr.includes('result-file'), '(b) rebuttal --result-file stderr mentions result-file', r.stderr);
    assert(!fs.existsSync(resFile), '(b) rebuttal --result-file never creates the file');
    cleanup(dir);
  }

  // (c) non-regression: execute + --result-file still succeeds (exit 0 + result JSON written).
  {
    const validPayload = JSON.stringify({
      status: 'done',
      summary: 'did the task',
      must_haves_status: [{ item: 'truth 1', status: 'met', note: 'ok' }],
      files_changed: [],
    });
    const gitRepo = mkGitRepo(mkTmp('s60-execute-repo'));
    const planDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-s60-plan-'));
    const planFile = path.join(planDir, 'plan.md');
    fs.writeFileSync(planFile, '# T05\ndo the thing\n', 'utf8');
    const resultDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-s60-result-'));
    const resultFile = path.join(resultDir, 'result.json');
    const execMockDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-s60-execmock-'));
    writeMockCodex(execMockDir, { payload: validPayload, exitCode: 0 });
    const r = runXllm(['--mode', 'execute', '--plan', planFile, '--result-file', resultFile, '--cwd', gitRepo], execMockDir, gitRepo);
    assert(r.status === 0, '(c) execute --result-file still exits 0 (no regression)', `status=${r.status} stderr=${r.stderr}`);
    let parsed = null;
    try { parsed = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch (e) { /* leave null */ }
    assert(!!parsed && parsed.status === 'done', '(c) execute --result-file JSON written and parseable', JSON.stringify(parsed));
    cleanup(gitRepo);
    cleanup(planDir);
    cleanup(resultDir);
    cleanup(execMockDir);
  }

  cleanup(mockDir);

  // (d) doc-presence with exact per-file counts — never document-wide includes() (M016 S03 R2 lesson).
  const spec = readRepoText(path.join(repo, 'shared', 'forge-dispatch.md'));
  const auto = sidecarSurface(path.join(repo, 'skills', 'forge-auto', 'SKILL.md'));  // sidecar surface (2026-08-23)
  const next = sidecarSurface(path.join(repo, 'skills', 'forge-next', 'SKILL.md'));
  const task = readRepoText(path.join(repo, 'skills', 'forge-task', 'SKILL.md'));
  const review = readRepoText(path.join(repo, 'shared', 'forge-review.md'));

  const NEEDLE = 'Engine Fallback Discipline';
  const EXPECTED = {
    'shared/forge-dispatch.md': 1,
    'skills/forge-auto/SKILL.md': 2,
    'skills/forge-next/SKILL.md': 2,
    'skills/forge-task/SKILL.md': 1,
    // 2 since TASK-009: § Agent unavailability cites the canonical enum home
    // alongside the pre-existing § Fallback challenger reference.
    'shared/forge-review.md': 2,
  };
  for (const [name, content] of [
    ['shared/forge-dispatch.md', spec],
    ['skills/forge-auto/SKILL.md', auto],
    ['skills/forge-next/SKILL.md', next],
    ['skills/forge-task/SKILL.md', task],
    ['shared/forge-review.md', review],
  ]) {
    const count = content.split(NEEDLE).length - 1;
    assert(count === EXPECTED[name],
      `(d) ${name} has exact "Engine Fallback Discipline" count (expected ${EXPECTED[name]}, got ${count})`);
  }

  // (e) canonical rule cites "unreliable" as the named anti-example; the invented
  // reason string never enters the enum.
  const unreliableCount = spec.split('unreliable').length - 1;
  assert(unreliableCount === 2, `(e) canonical cites "unreliable" as anti-example (expected 2 occurrences incl. codex-unreliable-session, got ${unreliableCount})`);
  assert(spec.includes('codex-unreliable-session'), '(e) canonical names the forbidden anti-example codex-unreliable-session');
  assert(!spec.includes('| `codex-unreliable-session`'), '(e) codex-unreliable-session is never a table row in the enum');

  // (f) sidecar-state-init-failed is a sanctioned enum member — doc-presence in the canonical spec.
  assert(spec.includes('sidecar-state-init-failed'), '(f) canonical enum includes sidecar-state-init-failed');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/smokeXllmResultFileGuard\(\);/.test(mainBody),
    '(g) Section 60 is registered in main()');
  pass('(final) Section 60: forge-xllm --result-file guard (challenge/rebuttal exit 2 + no-file, execute non-regression) and Engine Fallback Discipline rule presence verified');
}

// ── Section 61: ROUTING_DOMAINS injected into planner prompt templates + planner contract ──
function smokeRoutingDomains() {
  process.stdout.write('\n▸ Section 61: ROUTING_DOMAINS injection into planner prompts + contract\n');
  const repo = path.dirname(SCRIPTS);

  const NEEDLE = 'ROUTING_DOMAINS';
  const EXPECTED = {
    'shared/forge-dispatch.md': 2,
    'skills/forge-task/SKILL.md': 1,
    'skills/forge-new-milestone/SKILL.md': 1,
    'agents/forge-planner.md': 2,
  };
  const files = {
    'shared/forge-dispatch.md': path.join(repo, 'shared', 'forge-dispatch.md'),
    'skills/forge-task/SKILL.md': path.join(repo, 'skills', 'forge-task', 'SKILL.md'),
    'skills/forge-new-milestone/SKILL.md': path.join(repo, 'skills', 'forge-new-milestone', 'SKILL.md'),
    'agents/forge-planner.md': path.join(repo, 'agents', 'forge-planner.md'),
  };

  const contents = {};
  for (const [name, filePath] of Object.entries(files)) {
    const content = fs.readFileSync(filePath, 'utf8');
    contents[name] = content;
    const count = content.split(NEEDLE).length - 1;
    assert(count === EXPECTED[name],
      `(a) ${name} has exact "ROUTING_DOMAINS" count (expected ${EXPECTED[name]}, got ${count})`);
  }

  // (b) The EXECUTABLE templates carry the placeholder form, not a hardcoded value.
  // Repointed (review R1, conceded): this assert used to read shared/forge-dispatch.md and call it
  // "canonical templates". That file is prose documentation — its own header calls its template
  // bodies compatibility reference. The renderer reads shared/templates/dispatch/ (forge-prompt.js
  // candidateTemplateRoots), so the old target could stay green while the shipping template lost
  // the declaration. Section 92 covers the rendered output; this covers the declaration at rest.
  for (const rel of ['plan-slice.md', 'plan-milestone.md']) {
    const tpl = fs.readFileSync(path.join(repo, 'shared', 'templates', 'dispatch', rel), 'utf8');
    assert(tpl.includes('ROUTING_DOMAINS: {routing_domains}'),
      `(b) executable template ${rel} declares the {routing_domains} placeholder`);
  }

  // (c) Inline-path mirrors derive via the canonical helper. The renderer now owns auto/next injection.
  for (const name of ['skills/forge-task/SKILL.md', 'skills/forge-new-milestone/SKILL.md']) {
    assert(contents[name].includes('forge-routing.js" --list-domains'),
      `(c) ${name} derives ROUTING_DOMAINS via forge-routing.js --list-domains`);
  }

  // (d) planner contract preserves open-set (never invent a domain key) and no-keyword-matching.
  const planner = contents['agents/forge-planner.md'];
  assert(/open-set/i.test(planner), '(d) forge-planner.md still documents open-set domain contract');
  assert(/No keyword auto-detection/i.test(planner), '(d) forge-planner.md still documents no-keyword-detection rule');
  assert(planner.includes('omit `domain:`') || /omit.*domain:/i.test(planner),
    '(d) forge-planner.md documents omitting domain: when ROUTING_DOMAINS is absent/(none)');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/smokeRoutingDomains\(\);/.test(mainBody),
    '(e) Section 61 is registered in main()');
  pass('(final) Section 61: ROUTING_DOMAINS injected into planner prompt templates (canonical + mirrors + self-contained sites) and planner domain contract verified');
}

// ── Section 62: /forge-init git guarantee — no more NEVER-git-init prohibitions ──
function smokeInitGitGuarantee() {
  process.stdout.write('\n▸ Section 62: /forge-init git guarantee (rev-parse check + AskUserQuestion)\n');
  const repo = path.dirname(SCRIPTS);
  const read = (file) => readRepoText(path.join(repo, file));
  const init = read('commands/forge-init.md');

  assert(init.includes('git rev-parse --git-dir'),
    '(a) commands/forge-init.md runs git rev-parse --git-dir before routing');

  const forbidden = 'NEVER run `git init`';
  const forbiddenCount = init.split(forbidden).length - 1;
  assert(forbiddenCount === 0,
    `(b) commands/forge-init.md has zero occurrences of the old prohibition (got ${forbiddenCount})`);

  assert(init.includes('AskUserQuestion'),
    '(c) commands/forge-init.md uses AskUserQuestion in the git-guarantee flow');

  // (d) behavioral: --state-init against a non-git cwd is the real precondition the R1
  // `sidecar-state-init-failed` guard depends on ([ -n "$START_SHA" ] must fail) — assert
  // forge-surgical-reset.js actually exits non-zero (and prints nothing to stdout) there.
  const nonGitDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-nogit-'));
  try {
    const rp = spawnSync('git', ['-C', nonGitDir, 'rev-parse', '--git-dir'],
      { encoding: 'utf8' });
    assert(rp.status !== 0, '(d) tmpdir fixture is confirmed outside any git repo');

    const stateFile = path.join(nonGitDir, 'state.json');
    const result = spawnSync('node',
      [path.join(SCRIPTS, 'forge-surgical-reset.js'), '--state-init', '--state', stateFile, '--cwd', nonGitDir],
      { encoding: 'utf8' });
    assert(result.status !== 0,
      `(d) forge-surgical-reset.js --state-init exits non-zero outside a git repo (got ${result.status})`);
    assert(!(result.stdout || '').trim(),
      '(d) forge-surgical-reset.js --state-init prints no START_SHA outside a git repo');
  } finally {
    fs.rmSync(nonGitDir, { recursive: true, force: true });
  }

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/smokeInitGitGuarantee\(\);/.test(mainBody),
    '(final) Section 62 is registered in main()');
  pass('(final) Section 62: /forge-init git guarantee verified — no more unconditional NEVER-git-init prohibitions');
}

// ── Section 63: CODE_DIR multi-repo resolver (forge-code-dir.js) ────────────
function smokeCodeDirMultiRepo() {
  process.stdout.write('\n▸ Section 63: CODE_DIR multi-repo resolver + sidecar refusal reasons\n');
  const repoRoot = path.dirname(SCRIPTS);
  // sidecar surface: exact reason counts moved verbatim with the 2026-08-23 extraction
  const read = (file) => sidecarSurface(path.join(repoRoot, file));

  // Fixture: 2 real git repos under a NON-git root (the multi-repo workspace shape that
  // made the blind find(x=>x.worktree...) point the sidecar at the wrong repo). The
  // resolver is pure (D1), so $ISO_RESULT is hand-built — no forge-isolation --setup.
  const root = mkTmp('s63');
  try {
    const asgardDir = path.join(root, 'asgard');
    const freyrDir  = path.join(root, 'freyr');
    fs.mkdirSync(asgardDir, { recursive: true });
    fs.mkdirSync(freyrDir, { recursive: true });
    mkGitRepo(asgardDir);
    mkGitRepo(freyrDir);

    const wt = (name) => path.join(root, '.forge-worktrees', 'TASK-160', name);
    const isoMulti = JSON.stringify({
      mode: 'worktree',
      repos: [
        { path: asgardDir, branch: 'forge/TASK-160', worktree: wt('asgard'), status: 'created' },
        { path: freyrDir,  branch: 'forge/TASK-160', worktree: wt('freyr'),  status: 'created' },
      ],
    });
    const isoSingle = JSON.stringify({
      mode: 'worktree',
      repos: [{ path: freyrDir, branch: 'forge/TASK-160', worktree: wt('freyr'), status: 'created' }],
    });

    const writePlan = (name, body) => {
      const p = path.join(root, name);
      fs.writeFileSync(p, body);
      return p;
    };
    const resolve = (iso, plan) => {
      const r = runScript('forge-code-dir.js',
        ['--resolve', '--iso-result', iso, '--plan', plan, '--cwd', root, '--run', 'TASK-160']);
      let json = {};
      try { json = JSON.parse(r.stdout); } catch { json = {}; }
      return { status: r.status, json };
    };

    const planFreyr = writePlan('plan-freyr.md', [
      '---', 'id: T01', 'writes:', '  - "freyr/src/a.ts"', '  - "freyr/lib/**"', '---',
      '', '# plan', '',
    ].join('\n'));
    const planBoth = writePlan('plan-both.md', [
      '---', 'id: T02', 'writes:', '  - "freyr/src/a.ts"', '  - "asgard/src/b.ts"', '---',
      '', '# plan', '',
    ].join('\n'));
    const planBothDeclared = writePlan('plan-both-declared.md', [
      '---', 'id: T02b', 'repo: freyr', 'writes:', '  - "freyr/src/a.ts"', '  - "asgard/src/b.ts"', '---',
      '', '# plan', '',
    ].join('\n'));
    const planLegacy = writePlan('plan-legacy.md', [
      '---', 'id: T03', 'tier: heavy', 'effort: high', '---',
      '', '# plan', '', '## Steps', '', '1. do a thing', '',
    ].join('\n'));
    const planGsdMixed = writePlan('plan-gsd.md', [
      '---', 'id: T04', 'writes:', '  - ".gsd/tasks/T04/T04-SUMMARY.md"', '  - "asgard/src/c.ts"', '---',
      '', '# plan', '',
    ].join('\n'));
    const planFilesToChange = writePlan('plan-ftc.md', [
      '---', 'id: T05', 'tier: heavy', '---',
      '', '# plan', '', '## Files to Change', '',
      '- `asgard/src/d.ts` — 2 predicados de filter do cap (`:827`, `:1009`) ajustados.',
      '2. `asgard/docs/e.md` — nota de contrato (`:44`).',
      'not a bullet — ignored',
      '', '## Deferred', '', '- `freyr/src/zzz.ts` — out of scope, after the section end.', '',
    ].join('\n'));

    // (a) multi-repo, all declared paths under freyr/ → freyr's worktree, NEVER repos[0] (asgard).
    const a = resolve(isoMulti, planFreyr);
    assert(a.status === 0 && a.json.status === 'ok',
      `(a) multi-repo plan touching one repo → exit 0 / status ok (got ${a.status}/${a.json.status})`);
    assert(a.json.code_dir === wt('freyr'),
      '(a) code_dir is the freyr worktree (attributed), not repos[0]');
    assert(a.json.code_dir !== wt('asgard'),
      '(a) anti-regression: code_dir is NOT asgard — the blind find(x=>x.worktree...) would have picked it');

    // (b) declared paths span 2 repos → refusal, never an arbitrary pick.
    const b = resolve(isoMulti, planBoth);
    assert(b.status === 4 && b.json.status === 'cross-repo',
      `(b) cross-repo plan → exit 4 / status cross-repo (got ${b.status}/${b.json.status})`);
    assert(b.json.code_dir === '' && b.json.reason === 'sidecar-multirepo-unsupported',
      '(b) cross-repo yields an EMPTY code_dir + reason sidecar-multirepo-unsupported');
    assert(Array.isArray(b.json.repos_touched) && b.json.repos_touched.length === 2,
      `(b) repos_touched lists both repos (got ${JSON.stringify(b.json.repos_touched)})`);

    // (b1) the same complete scope is supported when repo: selects the primary.
    const b1 = resolve(isoMulti, planBothDeclared);
    assert(b1.status === 0 && b1.json.status === 'ok' && b1.json.code_dir === wt('freyr'),
      `(b1) declared cross-repo primary resolves (got ${b1.status}/${b1.json.status})`);
    assert(JSON.stringify(b1.json.repo_roots) === JSON.stringify([wt('freyr'), wt('asgard')]),
      `(b1) repo_roots keeps primary first (got ${JSON.stringify(b1.json.repo_roots)})`);
    assert(JSON.stringify(b1.json.writable_roots) === JSON.stringify([wt('asgard')]),
      `(b1) writable_roots contains only the secondary repo (got ${JSON.stringify(b1.json.writable_roots)})`);

    // (c) multi-repo + legacy plan with zero declared paths → distinct "planner gap" signal.
    const c = resolve(isoMulti, planLegacy);
    assert(c.status === 5 && c.json.status === 'undeclared',
      `(c) multi-repo + legacy plan → exit 5 / status undeclared (got ${c.status}/${c.json.status})`);
    assert(c.json.code_dir === '' && c.json.reason === 'sidecar-code-dir-undeclared',
      '(c) undeclared yields an EMPTY code_dir + reason sidecar-code-dir-undeclared');

    // (d) D6 non-regression: ONE usable repo → that worktree, plan never consulted.
    const d = resolve(isoSingle, planLegacy);
    assert(d.status === 0 && d.json.status === 'ok' && d.json.code_dir === wt('freyr'),
      `(d) single-repo workspace + legacy plan → exit 0 / ok / freyr worktree (got ${d.status}/${d.json.status})`);
    assert(d.json.paths_considered === 0 && d.json.source === 'none',
      '(d) single-repo short-circuit did not consult the plan at all');

    // (c2)/(b2) Refusal still refuses the SIDECAR, but the Claude executor gets a
    // real place to stand. Before this, it inherited the bootstrap WORKTREE_DIR —
    // the blind repos.find() first pick — so a two-repo task ran inside whichever
    // repo sorted first and the operator had to override CODE_DIR by hand.
    const runRoot = path.dirname(wt('freyr'));
    assert(b.json.multi_repo_root === runRoot,
      `(b2) cross-repo exposes the run root holding every worktree (got ${b.json.multi_repo_root})`);
    assert(c.json.multi_repo_root === runRoot,
      `(c2) undeclared in a multi-repo workspace exposes the run root (got ${c.json.multi_repo_root})`);
    assert(b.json.code_dir === '' && c.json.code_dir === '',
      '(b2) code_dir stays empty on refusal — it is the sidecar field and the sidecar still has no answer');
    assert(d.json.multi_repo_root === '',
      `(d2) single-repo workspace exposes NO run root — its parent is not a git repo (got ${d.json.multi_repo_root})`);

    // The three orchestrator mirrors must consume it, or the resolver change is inert.
    for (const skill of ['forge-auto', 'forge-next', 'forge-task']) {
      const body = readRepoText(path.join(path.dirname(SCRIPTS), 'skills', skill, 'SKILL.md'));
      assert(/CODE_DIR_MULTI_ROOT=\$\(node -e .*multi_repo_root/.test(body),
        `(e2) ${skill} reads multi_repo_root from the resolver`);
      assert(/\[ "\$CODE_DIR_STATUS" != "ok" \] && \[ -n "\$CODE_DIR_MULTI_ROOT" \] && CODE_DIR="\$CODE_DIR_MULTI_ROOT"/.test(body),
        `(e2) ${skill} stands the Claude fallback in the run root on refusal`);
      assert(!/executor Claude segue no WORKTREE_DIR do bootstrap/.test(body),
        `(e2) ${skill} no longer claims the fallback keeps the bootstrap worktree`);
    }

    // (m)/(n): repo-relative declarations have no workspace prefix, so only the
    // read-only second pass can resolve them. A tie deliberately remains closed.
    fs.mkdirSync(path.join(freyrDir, 'src'), { recursive: true });
    const planRepoRelative = writePlan('plan-repo-relative.md', [
      '---', 'id: T06', 'writes:', '  - "src/main.rs"', '---', '', '# plan', '',
    ].join('\n'));
    const m = resolve(isoMulti, planRepoRelative);
    assert(m.status === 0 && m.json.status === 'ok' && m.json.repo === freyrDir && m.json.resolution === 'fs-probe',
      `(m) unique repo-relative directory resolves by fs-probe (got ${m.status}/${m.json.status}/${m.json.repo}/${m.json.resolution})`);
    fs.mkdirSync(path.join(asgardDir, 'src'), { recursive: true });
    const n = resolve(isoMulti, planRepoRelative);
    assert(n.status === 5 && n.json.status === 'undeclared',
      `(n) tied repo-relative directory fails closed as undeclared (got ${n.status}/${n.json.status})`);

    // (o) A greenfield declaration selects a repo even when its target does not exist yet.
    const planDeclared = writePlan('plan-declared.md', [
      '---', 'id: T07', 'repo: freyr', 'writes:', '  - "src/v2/**"', '---', '', '# plan', '',
    ].join('\n'));
    const o = resolve(isoMulti, planDeclared);
    assert(o.status === 0 && o.json.status === 'ok' && o.json.code_dir === wt('freyr') && o.json.resolution === 'declared',
      `(o) greenfield repo: declaration resolves freyr (got ${o.status}/${o.json.status}/${o.json.code_dir}/${o.json.resolution})`);

    const planUnknownDeclared = writePlan('plan-unknown-declared.md', [
      '---', 'id: T08', 'repo: nosuchrepo', 'writes:', '  - "src/v2/**"', '---', '', '# plan', '',
    ].join('\n'));
    const p = resolve(isoMulti, planUnknownDeclared);
    assert(p.status === 5 && p.json.status === 'undeclared' && p.json.declared_repo_status === 'unknown' && p.json.code_dir === '',
      `(p) unknown repo: declaration refuses loudly (got ${p.status}/${p.json.status}/${p.json.declared_repo_status})`);

    const planConflictingDeclared = writePlan('plan-conflicting-declared.md', [
      '---', 'id: T09', 'repo: freyr', 'writes:', '  - "asgard/src/b.ts"', '---', '', '# plan', '',
    ].join('\n'));
    const q = resolve(isoMulti, planConflictingDeclared);
    assert(q.status === 5 && q.json.declared_repo_status === 'conflict' && q.json.code_dir === '',
      `(q) conflicting repo: declaration refuses loudly (got ${q.status}/${q.json.declared_repo_status})`);

    fs.mkdirSync(path.join(asgardDir, 'app', 'api', 'delivery'), { recursive: true });
    const planWeighted = writePlan('plan-weighted.md', [
      '---', 'id: T10', 'writes:', '  - "app/api/delivery/route.ts"', '  - "src/index.js"', '---', '', '# plan', '',
    ].join('\n'));
    const r = resolve(isoMulti, planWeighted);
    // Flat counting gave 1×1 here; measured depth makes asgard the strict winner.
    assert(r.status === 0 && r.json.repo === asgardDir && r.json.resolution === 'fs-probe' && r.json.probe === 'winner',
      `(r) weighted probe resolves heterogeneous evidence to asgard (got ${r.status}/${r.json.repo}/${r.json.probe})`);

    fs.mkdirSync(path.join(freyrDir, 'app', 'api', 'delivery'), { recursive: true });
    const s = resolve(isoMulti, planWeighted);
    assert(s.status === 5 && s.json.status === 'undeclared' && s.json.probe === 'tie',
      `(s) equally deep evidence remains a fail-closed tie (got ${s.status}/${s.json.probe})`);

    const t = resolve(isoMulti, planRepoRelative);
    assert(t.status === 5 && t.json.status === 'undeclared' && t.json.probe === 'weak',
      `(t) shared generic parent is weak rather than a fabricated tie (got ${t.status}/${t.json.probe})`);
    const { FS_PROBE_FLOOR } = require(path.join(SCRIPTS, 'forge-code-dir.js'));
    assert(FS_PROBE_FLOOR === 2, `(u) FS_PROBE_FLOOR remains 2 (got ${FS_PROBE_FLOOR})`);

    // (e) D4: `.gsd/**` never makes a plan cross-repo.
    const e = resolve(isoMulti, planGsdMixed);
    assert(e.status === 0 && e.json.status === 'ok' && e.json.code_dir === wt('asgard'),
      `(e) .gsd/** mixed with one repo's paths → exit 0 / ok / asgard (got ${e.status}/${e.json.status})`);

    // (f) `## Files to Change` free-text fallback, both bullet shapes + backticked line-refs.
    const f = resolve(isoMulti, planFilesToChange);
    assert(f.status === 0 && f.json.status === 'ok' && f.json.code_dir === wt('asgard'),
      `(f) files-to-change fallback attributes to asgard (got ${f.status}/${f.json.status}/${f.json.code_dir})`);
    assert(f.json.source === 'files-to-change' && f.json.paths_considered === 2,
      `(f) source is files-to-change with exactly the 2 in-section paths (got ${f.json.source}/${f.json.paths_considered})`);

    // (g) exact per-file counts of both reasons — never a document-wide includes() (M016 S03 R2).
    // dispatch: enum bullet + trigger row + step 0.5 verdict prose. task/next: gate + prose
    // trigger-list. auto has NO prose trigger-list (only the guard prose) → gate only.
    const REASON_COUNTS = {
      'shared/forge-dispatch.md':   3,
      'skills/forge-task/SKILL.md': 2,
      'skills/forge-next/SKILL.md': 2,
      'skills/forge-auto/SKILL.md': 1,
    };
    for (const [file, expected] of Object.entries(REASON_COUNTS)) {
      const content = read(file);
      for (const needle of ['sidecar-multirepo-unsupported', 'sidecar-code-dir-undeclared']) {
        const got = content.split(needle).length - 1;
        assert(got === expected, `(g) ${file} mentions ${needle} exactly ${expected}x (got ${got})`);
      }
    }

    // (h) contract note authored ONCE in the canonical spec (D13 formula-once).
    const spec = read('shared/forge-dispatch.md');
    const note = 'The sidecar always has one primary working copy as `--cwd`';
    const noteCount = spec.split(note).length - 1;
    assert(noteCount === 1, `(h) shared/forge-dispatch.md carries the contract note exactly once (got ${noteCount})`);

    // (i) Pitfall 2 guard: the fix is INERT unless the `worktree →` PROSE bullet points at the
    // per-unit variable — CODE_DIR/WORKER_CWD are prose variables, bash only consumes them.
    for (const file of ['skills/forge-auto/SKILL.md', 'skills/forge-next/SKILL.md', 'skills/forge-task/SKILL.md']) {
      const content = read(file);
      const invocations = content.split('forge-code-dir.js').length - 1;
      assert(invocations >= 1, `(i) ${file} invokes forge-code-dir.js (got ${invocations})`);
      const bullet = content.split(/\r?\n/).filter(l => /^- `?(worktree|ISOLATION_MODE == worktree)`? →/.test(l));
      assert(bullet.length === 1, `(i) ${file} has exactly one \`worktree →\` prose bullet (got ${bullet.length})`);
      assert(bullet[0].includes('explicit primary repo') && bullet[0].includes('repo_roots') && bullet[0].includes('writable_roots'),
        `(i) ${file} \`worktree →\` prose bullet names the primary and complete multi-repo scope (Pitfall 2)`);
      for (const needle of ['--repo-roots-file', '--writable-roots-file', 'multi-repo-reset-unverified']) {
        assert(content.includes(needle), `(i) ${file} wires ${needle}`);
      }
    }

    // (j) allowlist grep: the blind picker must survive EXACTLY once per mirror — the bootstrap
    // line is legitimate (no plan exists yet, and an empty WORKTREE_DIR is the all-repos-failed
    // STOP signal). Exactly-one, not zero: a second occurrence would be a new blind pick.
    for (const file of ['skills/forge-auto/SKILL.md', 'skills/forge-next/SKILL.md', 'skills/forge-task/SKILL.md']) {
      const got = read(file).split('find(x=>x.worktree').length - 1;
      assert(got === 1, `(j) ${file} keeps the bootstrap blind picker exactly once, and adds no second one (got ${got})`);
    }

    // (k) D11: the /forge-task plan template asks the planner for `writes:`.
    const taskSkill = read('skills/forge-task/SKILL.md');
    assert(/`writes:` \(an array of the file paths or globs/.test(taskSkill),
      '(k) skills/forge-task/SKILL.md Step 4 template asks for `writes:` in the frontmatter');
    const routingDomains = taskSkill.split('ROUTING_DOMAINS').length - 1;
    assert(routingDomains === 1,
      `(k) skills/forge-task/SKILL.md ROUTING_DOMAINS count unchanged at 1 (got ${routingDomains})`);

    // (l) CLI contract: no args → exit 2 + a forge-code-dir error line on stderr.
    const usage = runScript('forge-code-dir.js', []);
    assert(usage.status === 2 && /forge-code-dir error:/.test(usage.stderr),
      `(l) no-args invocation exits 2 with a forge-code-dir error line (got ${usage.status})`);

    // (v) R1 fix: a trailing inline comment on `repo:` must not defeat the declared-repo
    // arms — the docstring on parseScalarField promises comment-stripping.
    const planCommentedDeclared = writePlan('plan-commented-declared.md', [
      '---', 'id: T11', 'repo: freyr   # optional — see WORKSPACE_REPOS', 'writes:',
      '  - "src/v2/**"', '---', '', '# plan', '',
    ].join('\n'));
    const v = resolve(isoMulti, planCommentedDeclared);
    assert(v.status === 0 && v.json.status === 'ok' && v.json.code_dir === wt('freyr') && v.json.resolution === 'declared',
      `(v) trailing-comment repo: declaration still resolves freyr (got ${v.status}/${v.json.status}/${v.json.code_dir}/${v.json.resolution})`);

    // (w) R3 fix: byBasename is case-insensitive, byAbsolute/byRelative untouched. A
    // case-variant declaration must still resolve — never fall closed to unknown.
    const planCaseDrift = writePlan('plan-case-drift.md', [
      '---', 'id: T12', 'repo: FREYR', 'writes:', '  - "src/v2/**"', '---', '', '# plan', '',
    ].join('\n'));
    const w = resolve(isoMulti, planCaseDrift);
    assert(w.status === 0 && w.json.status === 'ok' && w.json.code_dir === wt('freyr') && w.json.resolution === 'declared',
      `(w) case-drifted repo: declaration (FREYR vs freyr) resolves freyr (got ${w.status}/${w.json.status}/${w.json.code_dir})`);

    // (x) safety preserved: two case-variant repos (e.g. `Freyr` and `freyr`) both matching
    // byBasename case-insensitively must still refuse as ambiguous — never a wrong-repo write.
    const freyrCapDir = path.join(root, 'Freyr');
    fs.mkdirSync(freyrCapDir, { recursive: true });
    mkGitRepo(freyrCapDir);
    const isoCaseAmbiguous = JSON.stringify({
      mode: 'worktree',
      repos: [
        { path: freyrDir, branch: 'forge/TASK-160', worktree: wt('freyr'), status: 'created' },
        { path: freyrCapDir, branch: 'forge/TASK-160', worktree: wt('Freyr'), status: 'created' },
      ],
    });
    const x = resolve(isoCaseAmbiguous, planCaseDrift);
    assert(x.status === 5 && x.json.status === 'undeclared' && x.json.declared_repo_status === 'ambiguous' && x.json.code_dir === '',
      `(x) two case-variant repos both matching byBasename refuse as ambiguous (got ${x.status}/${x.json.status}/${x.json.declared_repo_status})`);

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/smokeCodeDirMultiRepo\(\);/.test(mainBody),
      '(final) Section 63 is registered in main()');
    pass('(final) Section 63: CODE_DIR multi-repo resolution verified — attributed, refused, or short-circuited, never an arbitrary pick');
  } finally {
    cleanup(root);
  }
}

// ── Section 74: workspace repo injection anti-inertia guard ─────────────────
function smokeWorkspaceRepos() {
  process.stdout.write('\n▸ Section 74: workspace repo injection into planner prompts + contract\n');
  const repoRoot = path.dirname(SCRIPTS);
  const expected = {
    'shared/forge-dispatch.md': 1,
    'skills/forge-task/SKILL.md': 1,
    'agents/forge-planner.md': 2,
  };
  const contents = {};
  for (const [file, count] of Object.entries(expected)) {
    contents[file] = readRepoText(path.join(repoRoot, file));
    const got = contents[file].split('WORKSPACE_REPOS').length - 1;
    assert(got === count, `(a) ${file} has exact WORKSPACE_REPOS count (expected ${count}, got ${got})`);
  }
  // Repointed (review R1, conceded) — same reasoning as Section 61(b): assert the EXECUTABLE
  // template, not the prose doc. Also pins the asymmetry at rest: plan-milestone must NOT declare
  // it, because repo: is a T##-PLAN frontmatter field and T##-PLAN only exists at plan-slice.
  {
    const dispatchTpl = rel => fs.readFileSync(path.join(repoRoot, 'shared', 'templates', 'dispatch', rel), 'utf8');
    assert(dispatchTpl('plan-slice.md').includes('WORKSPACE_REPOS: {workspace_repos}'),
      '(b) executable plan-slice template declares the {workspace_repos} placeholder');
    assert(!dispatchTpl('plan-milestone.md').includes('WORKSPACE_REPOS'),
      '(b) executable plan-milestone template declares NO workspace repo placeholder (asymmetry is substantive)');
  }
  // The renderer now owns auto/next injection; only forge-task remains an inline path.
  for (const file of ['skills/forge-task/SKILL.md']) {
    assert(/forge-repos\.js" --list/.test(contents[file]),
      `(c) ${file} derives the injected repo list via forge-repos.js --list`);
  }
  const planner = contents['agents/forge-planner.md'];
  assert(/Omit `repo:` when the injected repo list says single repo or is absent/.test(planner),
    '(d) planner documents omitting repo: for a single/absent list');

  // (f) anti-inertia for the remaining inline path: a presence guard cannot catch a pipeline that silently no-ops.
  // Extract the actual `node -e '...'` one-liner from each mirror and EXECUTE it against
  // a synthetic 2-line multi-repo list — asserting it splits/derives, not just that it
  // "mentions" forge-repos.js. This must fail against the pre-fix double-escaped split.
  for (const file of ['skills/forge-task/SKILL.md']) {
    const body = contents[file];
    const m = body.match(/\| node -e '(const l=require\("fs"\)[\s\S]*?)'\)/);
    assert(m, `(f) ${file} has an extractable node -e workspace-repos pipeline`);
    const script = m[1];
    const r = spawnSync(process.execPath, ['-e', script], { input: '/ws/api\n/ws/web\n', encoding: 'utf8' });
    assert(r.status === 0, `(f) ${file} workspace-repos pipeline runs cleanly (got exit ${r.status}, stderr: ${r.stderr})`);
    assert(r.stdout === 'api, web',
      `(f) ${file} workspace-repos pipeline on a 2-line input yields "api, web" (got ${JSON.stringify(r.stdout)}) — inert split("\\\\n") would yield "(single repo — omit repo:)"`);
  }

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/smokeWorkspaceRepos\(\);/.test(mainBody), '(e) Section 74 is registered in main()');
  pass('(final) Section 74: workspace repo prompt injection and planner contract verified');
}

// ── Section 66: sidecar_model resolver and mirrors ──────────────────────────
function smokeSidecarModel() {
  process.stdout.write('\n▸ Section 66: sidecar_model contract + mirrors\n');
  const root = path.dirname(SCRIPTS);
  const files = ['skills/forge-auto/SKILL.md', 'skills/forge-next/SKILL.md', 'skills/forge-task/SKILL.md', 'shared/forge-dispatch.md'];
  for (const file of files) {
    const content = fs.readFileSync(path.join(root, file), 'utf8');
    const stale = content.split('--model %s\' "$CODEX_MODEL"').length - 1;
    assert(stale === 0, `(a) ${file} has zero stale --model CODEX_MODEL invocations (got ${stale})`);
    const sidecar = content.split('SIDECAR_MODEL').length - 1;
    assert(sidecar > 0, `(b) ${file} documents SIDECAR_MODEL (got ${sidecar})`);
  }
  const resolved = runScript('forge-dispatch-resolve.js', ['--unit-type', 'execute-task', '--json']);
  let parsed = {}; try { parsed = JSON.parse(resolved.stdout); } catch {}
  assert(resolved.status === 0 && Object.prototype.hasOwnProperty.call(parsed, 'sidecar_model'),
    '(c) resolver CLI emits additive sidecar_model');
  const source = fs.readFileSync(__filename, 'utf8');
  assert(/smokeSidecarModel\(\);/.test(source.slice(source.lastIndexOf('async function main()'))),
    '(final) Section 66 is registered in main()');
  pass('(final) Section 66: sidecar_model is resolver-owned and mirrors consume it');
}

// ── Section 67: verifier code/artifact roots ─────────────────────────────────
function smokeVerifierCodeDir() {
  process.stdout.write('\n▸ Section 67: verifier --code-dir roots\n');
  const usage = runScript('forge-verifier.js', []);
  assert(usage.status === 2 && usage.stderr.includes('--code-dir'), '(a) verifier usage includes optional --code-dir');
  const root = mkTmp('verifier-code-dir');
  const code = mkTmp('verifier-code');
  try {
    const taskDir = path.join(root, '.gsd', 'milestones', 'M001', 'slices', 'S01', 'tasks', 'T01');
    fs.mkdirSync(taskDir, { recursive: true });
    fs.writeFileSync(path.join(taskDir, 'T01-PLAN.md'), '---\nid: T01\nmust_haves:\n  truths:\n    - "artifact exists"\n  artifacts:\n    - path: src/only-code.js\n      provides: test\n      min_lines: 1\n  key_links: []\nexpected_output:\n  - src/only-code.js\n---\n', 'utf8');
    fs.mkdirSync(path.join(code, 'src'), { recursive: true });
    fs.writeFileSync(path.join(code, 'src', 'only-code.js'), 'module.exports = 1;\n', 'utf8');
    const args = ['--slice', 'S01', '--milestone', 'M001', '--cwd', root];
    const sameRun = runScript('forge-verifier.js', args);
    const explicitRun = runScript('forge-verifier.js', [...args, '--code-dir', root]);
    const otherRun = runScript('forge-verifier.js', [...args, '--code-dir', code]);
    let same = {}; let explicit = {}; let other = {};
    try { same = JSON.parse(sameRun.stdout); explicit = JSON.parse(explicitRun.stdout); other = JSON.parse(otherRun.stdout); } catch {}
    // The CLI adds generated_at/duration_ms on every independent run; compare the
    // stable contract bytes after removing those runtime-only observability fields.
    delete same.generated_at; delete same.duration_ms;
    delete explicit.generated_at; delete explicit.duration_ms;
    assert(JSON.stringify(same) === JSON.stringify(explicit), '(b) omitted code-dir keeps the stable JSON contract identical to code-dir=cwd');
    assert(same.rows.length > 0 && other.rows.length > 0 && other.rows[0].exists === true,
      '(b) plans remain under cwd while artifacts resolve under code-dir');
  } finally { cleanup(root); cleanup(code); }
  const source = fs.readFileSync(__filename, 'utf8');
  assert(/smokeVerifierCodeDir\(\);/.test(source.slice(source.lastIndexOf('async function main()'))),
    '(final) Section 67 is registered in main()');
  pass('(final) Section 67: verifier keeps artifact and code roots distinct');
}

// ── Section 70: Windows sandbox gate + worktree dependency provisioning ─────
function smokeWindowsSandboxAndWorktreeDeps() {
  process.stdout.write('\n▸ Section 70: Windows sandbox gate + worktree dependencies\n');
  // RETARGETED in M018 S05 T02 (precedent MEM028: retarget BEFORE the fixture
  // disappears, in the same task). These asserts used to be made against
  // codexSandboxArgs, the `codex exec` flag builder, which T02 deleted along with
  // the exec transport. The INVARIANT is unchanged and still has to hold, so it
  // moved onto buildAppServerSandboxPolicy — the surviving sandbox gate, which
  // carries the same win32 branch and the same four upstream issues: win32
  // ESCAPES for a write mode, read-only NEVER escapes, on any platform.
  const { buildAppServerSandboxPolicy, buildExecutePrompt } = require('./forge-xllm.js');
  const { resolvePackageManager, installWorktreeDeps } = require('./forge-isolation.js');
  const same = (a, b) => JSON.stringify(a) === JSON.stringify(b);
  const expectedWrite = { type: 'workspaceWrite', networkAccess: false };
  assert(same(buildAppServerSandboxPolicy('workspace-write', 'darwin'), expectedWrite)
    && same(buildAppServerSandboxPolicy('workspace-write', 'linux'), expectedWrite),
  '70a: POSIX workspace-write policy is byte-identical');
  assert(same(buildAppServerSandboxPolicy('workspace-write', 'win32'), { type: 'dangerFullAccess' })
    && buildAppServerSandboxPolicy('workspace-write', 'win32').type !== 'workspaceWrite',
  '70a: win32 workspace-write escapes to dangerFullAccess');
  assert(['darwin', 'linux', 'win32'].every((p) => same(buildAppServerSandboxPolicy('read-only', p), { type: 'readOnly', networkAccess: false })),
    '70b: read-only remains sandboxed on every platform (win32 included)');

  const xllmSource = fs.readFileSync(path.join(SCRIPTS, 'forge-xllm.js'), 'utf8');
  const gateStart = xllmSource.indexOf('function buildAppServerSandboxPolicy');
  const gateEnd = xllmSource.indexOf('\n}', gateStart) + 2;
  const outsideGate = xllmSource.slice(0, gateStart) + xllmSource.slice(gateEnd);
  // The exec-era literal pair (`'--sandbox', 'read-only'`) can no longer exist
  // anywhere; the app-server equivalent is a policy OBJECT, and the only place
  // allowed to build one is this gate.
  assert(!/['"]--sandbox['"]\s*,\s*['"](?:read-only|workspace-write)['"]/.test(outsideGate)
    && !/type:\s*['"](?:readOnly|dangerFullAccess|workspaceWrite)['"]/.test(outsideGate),
  '70c: forge-xllm builds no sandbox policy outside the gate');
  const gateComment = xllmSource.slice(Math.max(0, gateStart - 2000), gateEnd);
  assert(['15850', '17179', '14367', '5824', 'assertNoProtectedSidecarChanges'].every((s) => gateComment.includes(s)),
    '70d: gate comment documents Windows issues and surviving defense');

  const template = readRepoText(path.join(SCRIPTS, '..', 'shared', 'templates', 'dispatch', 'execute-task.md'));
  const sentinel = 'dependencies may not be installed';
  const prompt = buildExecutePrompt('# T70\n');
  assert(template.split(sentinel).length - 1 === 1 && prompt.includes(sentinel)
    && prompt.includes('unknown') && prompt.indexOf(sentinel) < prompt.indexOf('Must-have scope classification:'),
  '70e: dependency warning reaches template and sidecar prompt exactly once');

  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-t70-'));
  const wt = path.join(root, 'worktree');
  let calls = 0;
  try {
    fs.mkdirSync(wt);
    fs.writeFileSync(path.join(root, 'package.json'), '{}\n');
    fs.writeFileSync(path.join(root, 'package-lock.json'), '{}\n');
    const installed = installWorktreeDeps(root, wt, { runner: (cmd, args, runOpts) => {
      calls++; return { status: cmd === 'npm' && args[0] === 'ci' && runOpts.cwd === wt ? 0 : 1, stderr: '' };
    } });
    assert(installed.status === 'installed' && installed.manager === 'npm' && calls === 1,
      '70f: npm lockfile provisions through injected runner with worktree cwd');
    const failed = installWorktreeDeps(root, wt, { runner: () => ({ status: 1, stderr: 'npm ERR! failed install\nsecret ignored' }) });
    assert(failed.status === 'failed' && !!failed.error, '70g: install failure degrades without throwing');
    const redacted = installWorktreeDeps(root, wt, { runner: () => ({ status: 1, stderr: 'https://user:password@example.invalid/pkg' }) });
    assert(!redacted.error.includes('user:password@'), '70g: installer error redacts credential URLs');
    const npmToken = installWorktreeDeps(root, wt, { runner: () => ({ status: 1, stderr: '//registry.npmjs.org/:_authToken=npm_SECRET123 is invalid' }) });
    assert(!npmToken.error.includes('npm_SECRET123'), '70g: installer error redacts canonical npm per-registry token');
    const yarnToken = installWorktreeDeps(root, wt, { runner: () => ({ status: 1, stderr: 'npmAuthToken: yarn_SECRET456 rejected' }) });
    assert(!yarnToken.error.includes('yarn_SECRET456'), '70g: installer error redacts yarn npmAuthToken');
    const control = installWorktreeDeps(root, wt, { runner: () => ({ status: 1, stderr: 'plain error with no secrets at all here' }) });
    assert(control.error === 'plain error with no secrets at all here', '70g: installer error passes through stderr with no secret unchanged');
    const disabled = installWorktreeDeps(root, wt, { enabled: false, runner: () => { calls++; return { status: 0 }; } });
    assert(disabled.status === 'disabled' && calls === 1, '70h: disabled provisioning does not call runner');
    fs.unlinkSync(path.join(root, 'package-lock.json'));
    const noLock = installWorktreeDeps(root, wt, { runner: () => { calls++; return { status: 0 }; } });
    assert(noLock.status === 'no-lockfile' && calls === 1, '70h: no lockfile does not call runner');
    fs.writeFileSync(path.join(root, 'package-lock.json'), '{}\n');
    fs.writeFileSync(path.join(root, 'pnpm-lock.yaml'), 'lockfileVersion: 9\n');
    assert(resolvePackageManager(root).manager === 'pnpm', '70i: pnpm lockfile wins manager precedence');
  } finally { cleanup(root); }
  const source = fs.readFileSync(__filename, 'utf8');
  const isolationSource = fs.readFileSync(path.join(SCRIPTS, 'forge-isolation.js'), 'utf8');
  assert(/result\.status = 'created';\s*result\.deps = installWorktreeDeps/.test(isolationSource)
    && /status: 'skipped'.+worktree-already-exists/.test(isolationSource),
  '70j: created worktrees receive additive non-fatal deps; existing worktrees skip installs');
  assert(/smokeWindowsSandboxAndWorktreeDeps\(\);/.test(source.slice(source.lastIndexOf('async function main()'))),
    '(final) Section 70 is registered in main()');

  // 70k: every `isolation.<key>` read by readIsolationPrefs() must be declared in
  // forge-prefs.schema.json's forge_isolation block — closes the class of bug where
  // code reads a knob the schema (and therefore the generated reference doc and
  // /forge-prefs catalog) never declared, leaving the operator with no way to
  // discover the opt-out.
  const readKeys = new Set();
  const readIsoBody = isolationSource.slice(
    isolationSource.indexOf('function readIsolationPrefs'),
    isolationSource.indexOf('function resolvePackageManager'));
  for (const m of readIsoBody.matchAll(/isolation\.([a-zA-Z_][a-zA-Z0-9_]*)/g)) readKeys.add(m[1]);
  const schemaJson = JSON.parse(fs.readFileSync(path.join(SCRIPTS, '..', 'forge-prefs.schema.json'), 'utf8'));
  const isolationProps = Object.keys(
    schemaJson.properties.forge_isolation.properties || {});
  const missing = [...readKeys].filter((k) => k !== 'mode' && !isolationProps.includes(k));
  assert(missing.length === 0,
    `70k: readIsolationPrefs() keys all declared in forge_isolation schema (missing: ${missing.join(', ')})`);
  assert(isolationProps.includes('worktree_install_deps'), '70k: worktree_install_deps is declared in the schema');

  pass('(final) Section 70: platform gate and non-fatal dependency provisioning verified');
}

// ── Section 64: review agent unavailability — classifier behaviour + sanctioned path docs ──
// Only ONE surface here is mechanically executable: scripts/forge-classify-error.js (the retry
// decision behind § Agent unavailability). The per-mode policy itself is prose interpreted at
// runtime by the orchestrator — declared doc-presence-only (same limit as TASK-006 R2 / TASK-007 R3),
// asserted with exact per-file counts, never a document-wide includes().
function smokeReviewAgentUnavailable() {
  process.stdout.write('\n▸ Section 64: review-agent-unavailable — retry classifier + sanctioned path\n');
  const repoRoot = path.dirname(SCRIPTS);
  const read = (file) => readRepoText(path.join(repoRoot, file));

  // (a) behavioural: the classifier CLI drives the retry decision of the review binding.
  // The CLI always exits 0 — read the JSON on stdout, never the exit status.
  const classify = (msg) => {
    const r = runScript('forge-classify-error.js', ['--msg', msg]);
    return JSON.parse(r.stdout);
  };

  const rl = classify('429 rate limit');
  assert(rl.kind === 'rate-limit' && rl.retry === true && rl.backoffMs > 0,
    '(a) "429 rate limit" → rate-limit, retry:true, positive backoff', JSON.stringify(rl));
  assert(classify('Too Many Requests').retry === true,
    '(a) "Too Many Requests" → retry:true (advocate 429 is retried, not improvised around)');
  const srv = classify('HTTP 503 overloaded');
  assert(srv.kind === 'server' && srv.retry === true,
    '(a) "HTTP 503 overloaded" → server, retry:true', JSON.stringify(srv));
  assert(classify('internal server error 500').retry === true,
    '(a) "internal server error 500" → retry:true');

  // FAIL-SAFE: an unrecognised provider message must NOT loop forever — it falls into the
  // declared unavailability path (retry:false → review-agent-unavailable + per-mode policy).
  const unk = classify('weird opaque thing');
  assert(unk.kind === 'unknown' && unk.retry === false,
    '(a) opaque message → unknown, retry:false (fail-safe: declared unavailability, never infinite retry)',
    JSON.stringify(unk));
  const perm = classify('invalid api key');
  assert(perm.kind === 'permanent' && perm.retry === false,
    '(a) "invalid api key" → permanent, retry:false', JSON.stringify(perm));

  // (b) doc-presence with exact per-file counts.
  const spec = read('shared/forge-dispatch.md');
  const review = read('shared/forge-review.md');
  const auto = read('skills/forge-auto/SKILL.md');
  const next = read('skills/forge-next/SKILL.md');
  const task = read('skills/forge-task/SKILL.md');
  const count = (content, needle) => content.split(needle).length - 1;

  const REASONS = [
    ['review-agent-unavailable', { 'shared/forge-dispatch.md': 2, 'shared/forge-review.md': 11 }],
    // 7th occurrence: the forge-review-emit.js --unavailable-reason example in Step 8,
    // added when the event stopped being hand-written.
    // 8th and 9th: the Step 3 "Salvage before declaring unavailability" rule — one naming
    // the gate, one naming the only condition under which it may still be emitted. Added
    // when DEFENSE_FILE made a truncated defense recoverable instead of total loss.
    ['review-advocate-unavailable', { 'shared/forge-dispatch.md': 1, 'shared/forge-review.md': 9 }],
    ['review-challenger-unavailable', { 'shared/forge-dispatch.md': 1, 'shared/forge-review.md': 5 }],
    ['review-rebuttal-unavailable', { 'shared/forge-dispatch.md': 1, 'shared/forge-review.md': 3 }],
  ];
  for (const [needle, expected] of REASONS) {
    for (const [name, content] of [['shared/forge-dispatch.md', spec], ['shared/forge-review.md', review]]) {
      const got = count(content, needle);
      assert(got === expected[name],
        `(b) ${name} has exact "${needle}" count (expected ${expected[name]}, got ${got})`);
    }
  }

  // (c) REGRA CRÍTICA — verbatim in the canonical spec AND in all 3 orchestrator mirrors
  // (TASK-008 lesson: a rule only in the canonical spec is inert exactly where the improvisation
  // happened — the mirrors ARE the orchestrator).
  const RULE = 'NUNCA produz veredito de review no lugar de um agente indisponível';
  for (const [name, content] of [
    ['shared/forge-review.md', review],
    ['skills/forge-auto/SKILL.md', auto],
    ['skills/forge-next/SKILL.md', next],
    ['skills/forge-task/SKILL.md', task],
  ]) {
    const got = count(content, RULE);
    assert(got === 1, `(c) ${name} carries the REGRA CRÍTICA verbatim exactly once (got ${got})`);
  }

  // (d) anti-approval guard: the challenger-unavailable path may never render as clean.
  // Stated twice on purpose: once in the § Agent unavailability policy, once at the Step 2
  // throw binding (the exact spot that could otherwise slip into the NO_FLAGS branch).
  assert(count(review, 'ausência de review não é aprovação') === 2,
    `(d) forge-review.md states that absence of review is not approval in both required places (got ${count(review, 'ausência de review não é aprovação')})`);
  assert(/PROIBIDO.*NO_FLAGS/s.test(review),
    '(d) forge-review.md forbids the NO_FLAGS/clean-artifact branch on review-challenger-unavailable');

  // (e) override guard: review dispatches never inherit the Retry Handler CRITICAL terminal action.
  assert(/Exceção — dispatches da review/.test(spec),
    '(e) forge-dispatch.md § Retry Handler carries the named review exception');
  assert(/dispatches da review[\s\S]{0,600}caminho CRITICAL/.test(spec),
    '(e) the exception explicitly overrides the CRITICAL routing for review dispatches');

  // (f) Step 4 is skipped when the advocate could not be heard (no self-judged rebuttal).
  assert(/Step 4 \(rebuttal\) é PULADO/.test(review),
    '(f) forge-review.md documents Step 4 as skipped on review-advocate-unavailable');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/smokeReviewAgentUnavailable\(\);/.test(mainBody),
    '(final) Section 64 is registered in main()');
  pass('(final) Section 64: review agent unavailability — retry-first classification is fail-safe and the sanctioned path is documented in the canonical spec + all 3 mirrors');
}

// ── Section 68: shared reference glob — installer anti-drift guard ─────────
function smokeSharedGlob() {
  process.stdout.write('\n▸ Section 68: shared/*.md installer glob — dynamic anti-drift guard\n');
  const repo = path.dirname(SCRIPTS);
  const shPath = path.join(repo, 'install.sh');
  const psPath = path.join(repo, 'install.ps1');
  const sh = fs.readFileSync(shPath, 'utf8');
  const ps = fs.readFileSync(psPath, 'utf8');
  const expected = fs.readdirSync(path.join(repo, 'shared'))
    .filter((name) => name.endsWith('.md'));

  const installer = require('./forge-installer.js');
  assert(/forge-installer\.js/.test(sh) && installer.MANAGED_CORE.includes('shared'),
    '(a) install.sh delegates shared-tree installation to the Node core', sh);
  assert(!/^\s*copy "\$\{REPO_DIR\}\/shared\/forge-[^"]+\.md"/m.test(sh),
    '(b) install.sh has no individual shared forge copy blocks', sh);
  assert(/forge-installer\.js/.test(ps) && installer.MANAGED_CORE.includes('shared'),
    '(c) install.ps1 delegates shared-tree installation to the Node core', ps);
  assert(!/^\s*if \(Test-Path "\$RepoDir\\shared\\forge-[^"]+\.md"\)/m.test(ps),
    '(d) install.ps1 has no individual shared forge Test-Path blocks', ps);
  assert(!fs.readFileSync(psPath).includes(0x0c),
    '(e) install.ps1 contains no literal 0x0C byte', psPath);

  const bashProbe = spawnSync('bash', ['--version'], { encoding: 'utf8' });
  if (bashProbe.error || bashProbe.status !== 0) {
    pass('(f) shared/*.md dry-run guard skipped (bash unavailable)');
  } else {
    const dryHome = mkTmp('install-shared-glob-home');
    try {
      fs.mkdirSync(path.join(dryHome, '.claude'), { recursive: true });
      const dry = spawnSync('bash', [shPath, '--dry-run', '--update',
        '--source', 'local', '--repo', repo, '--runtime', 'claude'], {
        encoding: 'utf8',
        env: { ...process.env, HOME: dryHome },
      });
      const output = `${dry.stdout || ''}${dry.stderr || ''}`;
      assert(dry.status === 0, '(g) shared/*.md dry-run exits 0', output);
      for (const name of expected) {
        assert(output.includes(name),
          `(g) shared/*.md dry-run includes ${name}`, output);
      }
    } finally {
      cleanup(dryHome);
    }
  }

  pass('(final) Section 68: shared reference installers are glob-driven and protected against new-file drift');
}

// ── Section 65: live phases table — resolver-derived rows + anti-drift guard ──
// The fixture intentionally contains both the default and a named domain. This
// makes routing resolution observable without relying on developer-machine
// preferences, and keeps the expected table shape hermetic. Assertions read
// the structured helper output rather than its human-facing text table: the
// latter remains free to improve spacing and localisation without weakening
// these contract checks. The document comparison is bidirectional so a newly
// added resolver default cannot disappear from the prose table, while an old
// prose-only row cannot silently claim a dispatch that no longer exists.
// No synthetic dispatch contract is assembled here. The helper invokes the
// production resolver once for every row, including the tier-only phases.
// Consequently this section also protects future resolver-side changes to
// aliases, engines, fallback chains, and default-domain inheritance.
// The CLI is separately covered through the ordinary smoke execution path.
// This test's responsibility is the reusable structured API contract.
// Keep the assertions in phase order for diagnostic output readability.
function smokePhasesTable() {
  process.stdout.write('\n▸ Section 65: live phases table — resolver-derived rows + anti-drift guard\n');
  const repoRoot = path.join(__dirname, '..');
  const { buildPhases, renderPhases } = require(path.join(SCRIPTS, 'forge-phases.js'));
  const { TIER_DEFAULTS } = require(path.join(SCRIPTS, 'forge-dispatch-resolve.js'));
  const root = mkTmp('phases-table');
  try {
    fs.writeFileSync(path.join(root, '.gsd', 'forge-prefs.jsonc'), JSON.stringify({
      routing: {
        default: {
          executor: { standard: ['claude-sonnet-5'] },
          planner: { heavy: ['claude-opus-4-8[1m]'] },
        },
        backend: {
          executor: { standard: ['gpt-5.6-luna', 'claude-sonnet-5'] },
          planner: { heavy: ['claude-opus-4-8[1m]'] },
        },
      },
    }), 'utf8');
    const table = buildPhases(root);
    const routed = table.rows.filter((row) => row.unit_type === 'execute-task' || row.unit_type === 'plan-slice');
    const tierOnly = new Set(['research-milestone', 'research-slice', 'discuss-milestone', 'discuss-slice', 'complete-slice', 'complete-milestone', 'memory-extract']);

    assert(routed.every((row) => /^routing\./.test(row.config_key)),
      '(a) execute-task and plan-slice rows configure through routing', JSON.stringify(routed));
    assert(table.rows.filter((row) => tierOnly.has(row.unit_type)).every((row) => /^tier_models\./.test(row.config_key)),
      '(b) non-routable unit types configure through tier_models');
    const milestone = table.rows.find((row) => row.unit_type === 'plan-milestone');
    assert(milestone && milestone.config_key === 'tier_models.max' && milestone.routable === false,
      '(c) plan-milestone is non-routable and configures through tier_models.max', JSON.stringify(milestone));
    assert(!/travado|locked/i.test(renderPhases(root)),
      '(c) rendered plan-milestone note has no misleading locked configuration key');
    assert(renderPhases(root).includes(`tem tier fixo ${TIER_DEFAULTS['plan-milestone']}`)
      && renderPhases(root).includes(`tier_models.${TIER_DEFAULTS['plan-milestone']}`),
      '(c) plan-milestone footnote reflects TIER_DEFAULTS, not a hardcoded literal');

    const expected = Object.keys(TIER_DEFAULTS);
    const actual = table.unit_types;
    assert(expected.every((unitType) => actual.includes(unitType)) && actual.every((unitType) => expected.includes(unitType)),
      '(d) buildPhases unit_types and TIER_DEFAULTS match bidirectionally');
    const tierDoc = readRepoText(path.join(repoRoot, 'shared', 'forge-tiers.md'));
    const section = tierDoc.slice(tierDoc.indexOf('## Unit Type → Default Tier'))
      .split(/\n(?:## |---)/)[0];
    const docTypes = [...section.matchAll(/^\|\s*`([a-z-]+)`\s*\|\s*(light|standard|heavy|max)\s*\|/gm)]
      .map((match) => match[1]);
    assert(expected.every((unitType) => docTypes.includes(unitType)) && docTypes.every((unitType) => expected.includes(unitType)),
      '(d) canonical tier document and TIER_DEFAULTS match bidirectionally', JSON.stringify(docTypes));

    const executeRows = table.rows.filter((row) => row.unit_type === 'execute-task');
    assert(executeRows.length >= 2 && new Set(executeRows.map((row) => row.config_key)).size >= 2,
      '(e) execute-task renders multiple domains with distinct routing keys', JSON.stringify(executeRows));

    const schema = JSON.parse(fs.readFileSync(path.join(repoRoot, 'forge-prefs.schema.json'), 'utf8'));
    const skill = readRepoText(path.join(repoRoot, 'skills', 'forge-prefs', 'SKILL.md'));
    const resolver = fs.readFileSync(path.join(SCRIPTS, 'forge-dispatch-resolve.js'), 'utf8');
    assert(/### Domain-routable vs tier_models-only/.test(tierDoc), '(f) tier documentation has routability subsection');
    assert(schema.properties.routing.description.includes('Somente execute-task (executor) e plan-slice (planner)'),
      '(f) routing schema description explains captured phases');
    assert(/### "phases"/.test(skill) && !skill.includes('Fase legada'),
      '(f) prefs skill exposes phases and removes the drifted legacy table');
    assert(/flag === '--domain'/.test(resolver), '(f) dispatch resolver parseArgs accepts --domain');

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/smokePhasesTable\(\);/.test(mainBody), '(final) Section 65 is registered in main()');
    pass('(final) Section 65: live phase resolution is resolver-derived and protected against documentation drift');
  } finally {
    cleanup(root);
  }
}

const crashedSections = [];

// One section's crash must not cost the sections behind it. The label is read
// back out of the thunk's own source so each call site stays a literal
// `smokeThing();` — several sections assert their own registration in main() by
// grepping for exactly that text.
async function runSection(body) {
  const label = (String(body).match(/smoke\w+/) || ['unknown-section'])[0];
  try {
    await body();
  } catch (error) {
    crashedSections.push(label);
    fail(`${label} crashed — every assertion left in it was skipped`,
      (error && (error.stack || error.message)) || String(error));
  }
}

// ── Section 75: refusal explains itself + doctor lists the affected plans ───
// Every assertion here EXECUTES the pipeline (resolver CLI, doctor CLI, and the actual
// one-liner extracted from each mirror). A presence-only grep is exactly how a dead
// pipeline shipped green before (Section 74 (f) carries the same lesson).
function smokeDoctorPlanRepo() {
  process.stdout.write('\n▸ Section 75: plan repo declaration hint + doctor advisory layer\n');
  const repoRoot = path.dirname(SCRIPTS);
  const root = mkTmp('s75');
  try {
    const apiDir = path.join(root, 'api');
    const webDir = path.join(root, 'web');
    fs.mkdirSync(apiDir, { recursive: true });
    fs.mkdirSync(webDir, { recursive: true });
    mkGitRepo(apiDir);
    mkGitRepo(webDir);
    const wt = (name) => path.join(root, '.forge-worktrees', 'TASK-018', name);
    const iso = JSON.stringify({
      mode: 'worktree',
      repos: [
        { path: apiDir, branch: 'forge/TASK-018', worktree: wt('api'), status: 'created' },
        { path: webDir, branch: 'forge/TASK-018', worktree: wt('web'), status: 'created' },
      ],
    });

    const slice = path.join(root, '.gsd', 'milestones', 'M001', 'slices', 'S01', 'tasks');
    const writePlan = (file, lines) => {
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, lines.join('\n') + '\n', 'utf8');
      return file;
    };
    const pending = writePlan(path.join(slice, 'T01', 'T01-PLAN.md'),
      ['---', 'id: T01', 'writes:', '  - "does/not/exist/a.ts"', '---', '', '# plan']);
    writePlan(path.join(root, '.gsd', 'archive', 'M000', 'slices', 'S01', 'tasks', 'T09', 'T09-PLAN.md'),
      ['---', 'id: T09', '---', '', '# plan']);

    // (a) the refusal is unchanged (exit 5) and now carries actionable prose.
    const r = runScript('forge-code-dir.js',
      ['--resolve', '--iso-result', iso, '--plan', pending, '--cwd', root, '--run', 'TASK-018']);
    let json = {}; try { json = JSON.parse(r.stdout); } catch { json = {}; }
    assert(r.status === 5 && json.status === 'undeclared',
      `(a) plan without repo: still refuses with exit 5 (got ${r.status}/${json.status})`);
    assert(typeof json.hint === 'string' && json.hint.length > 0 && json.hint.includes('repo:'),
      `(a) the refusal JSON carries a non-empty hint naming repo: (got ${JSON.stringify(json.hint)})`);

    // (b) the doctor names the pending plan and stays advisory (exit 0), never reading archive/.
    const d = runScript('forge-doctor.js', ['--check', 'plan-repo-declared', '--cwd', root]);
    assert(d.status === 0, `(b) plan-repo-declared is advisory — exit 0 (got ${d.status}, stderr: ${d.stderr})`);
    assert(d.stdout.includes('T01/T01-PLAN.md'),
      `(b) doctor names the pending plan without repo: (stdout: ${d.stdout})`);
    assert(!d.stdout.includes('T09'), '(b) doctor never reports a plan under .gsd/archive/');
  } finally { cleanup(root); }

  // (c) anti-inertia: extract the real one-liner from each mirror and RUN it. A mirror that
  // copied the pipeline wrong prints nothing and fails here, not silently in production.
  for (const file of ['skills/forge-auto/SKILL.md', 'skills/forge-next/SKILL.md', 'skills/forge-task/SKILL.md']) {
    const body = readRepoText(path.join(repoRoot, file));
    const m = body.match(/CODE_DIR_HINT=\$\(node -e "([^"]+)" "\$CD_JSON"\)/);
    assert(m, `(c) ${file} has an extractable CODE_DIR_HINT one-liner`);
    if (!m) continue; // a missing pipeline is already a failure; never crash the section
    const out = spawnSync(process.execPath, ['-e', m[1], '{"hint":"X"}'], { encoding: 'utf8' });
    assert(out.status === 0 && out.stdout === 'X',
      `(c) ${file} hint one-liner prints the hint (got exit ${out.status}, stdout ${JSON.stringify(out.stdout)})`);
    assert(/\$\{CODE_DIR_HINT:\+ — \$CODE_DIR_HINT\}/.test(body),
      `(c) ${file} appends the hint to the refusal warning line`);
  }
  // (d) F2: the loose-task mirror keeps its own run id — removing it to "match" the others
  // would be a regression in the forge-task path.
  const taskMirror = readRepoText(path.join(repoRoot, 'skills/forge-task/SKILL.md'));
  assert(/forge-code-dir\.js[\s\S]{0,400}--run "\$TASK_ID"/.test(taskMirror),
    '(d) forge-task still passes --run "$TASK_ID" to forge-code-dir.js');

  const source = fs.readFileSync(__filename, 'utf8');
  assert(/smokeDoctorPlanRepo\(\);/.test(source.slice(source.lastIndexOf('async function main()'))),
    '(e) Section 75 is registered in main()');
  pass('(final) Section 75: the refusal explains itself and the doctor lists every affected plan');
}

// ── Section 76: real SVN fixture + counted skip ────────────────────────────
// This section intentionally exercises the VCS detector through the same
// fixture that proves SVN 1.7's root-only metadata layout.  The checkout root
// has .svn, while the committed child directory does not.  Keeping both calls
// next to the filesystem assertions makes the boundary visible: root detection
// is the compatibility fast-path and child detection is the wc-root probe.
// The corresponding test suite stubs the probe so this behavioral contract is
// also covered on hosts where the svn executable is unavailable (notably CI on
// Windows).  The real fixture remains gated by hasSvn(), preserving the smoke
// runner's counted-skip contract instead of silently dropping coverage.
//
// T02 counterfactual record: commenting out the single `svnWcRoot(dir)` branch
// makes the child assertion below fail with `none`; restoring that branch makes
// the assertion pass with `svn`.  This is stronger than checking only source
// text because the fixture is a real repository and the child is versioned.
// The git and no-VCS calls are deliberately included in the same cleanup scope
// to guard the unchanged return values and the git fast-path's no-spawn rule.
// No KEEP-dependent state is used by these detector assertions: every temporary
// directory belongs to this invocation and is removed in the local finally
// blocks.  The SVN config directory is likewise fixture-local and hermetic.
// Keeping the assertions behavioral also protects consumers of detectVcs:
// applyIgnore and validateIgnore inherit the same root-aware classification.
// A failed svn info probe is intentionally not surfaced as an exception here:
// missing binaries, permissions, and non-working-copy paths all mean `none`.
// The probe output is treated as a path, never as a localized diagnostic.
// These notes document why the fixture uses `--show-item wc-root` explicitly.
// They are part of the Section 76 acceptance record and should remain with it.
// The workflow assertion deliberately reads the checked-in file used by CI.
// This keeps the smoke contract coupled to the runner setup that guarantees svn.
// The exact occurrence count prevents a prose-only mention from satisfying it.
// The ordering check models the executable sequence, not merely document presence.
// The Linux condition protects local macOS and Windows development environments.
// The extracted decision test makes the enforced branch independently replayable.
// Its collaborators are plain values, so no platform mutation is required.
// A CI Linux runner with no binary is therefore a counted failure.
// A local machine with no binary remains a counted skip for developer ergonomics.
// A present binary takes the fixture path and exercises the real detector.
// These three outcomes are intentionally mutually exclusive.
// Keeping the gate before fixture setup also makes missing-tool behavior immediate.
// The workflow installation remains the source of truth for Linux availability.
// The smoke assertion protects that source of truth from accidental removal.
// Changes to the workflow must preserve both the install step and its position.
// This section does not infer availability from runner labels alone.
// It probes the executable and then applies the environment-specific policy.
// The result is binary for enforcement while retaining local skip accounting.
// Section 76's real fixture assertions remain unchanged after the gate.
// The acceptance record is intentionally kept beside the guarded fixture.
function smokeSvnFixture() {
  process.stdout.write('\n▸ Section 76: fixture SVN real + skip contado\n');
  const source = fs.readFileSync(__filename, 'utf8');
  const repoRoot = path.dirname(SCRIPTS);
  const ci = fs.readFileSync(path.join(repoRoot, '.github', 'workflows', 'ci.yml'), 'utf8');
  // Case-insensitive count of the installation ACTION only (the `run:` line),
  // excluding the `- name:` step label — a step's display name ("Install
  // Subversion") is not itself an installation reference, and counting it
  // would double-count the same single step. Case-insensitive so a
  // `Subversion`/`SUBVERSION` variant in the install command itself is never
  // silently missed by a literal-lowercase match.
  const installLines = ci.split('\n').filter((l) => !/^\s*-\s*name\s*:/i.test(l));
  const svnCount = installLines.join('\n').toLowerCase().split('subversion').length - 1;
  const installIndex = ci.indexOf('Install Subversion');
  const smokeIndex = ci.indexOf('Smoke suite');
  const installStep = ci.slice(installIndex, smokeIndex);
  assert(svnCount === 1, '(h) ci.yml contains exactly one subversion installation reference', `count=${svnCount}`);
  assert(installIndex >= 0 && smokeIndex >= 0 && installIndex < smokeIndex,
    '(h) Subversion installation precedes the smoke suite', JSON.stringify({ installIndex, smokeIndex }));
  assert(/if:\s*runner\.os\s*==\s*'Linux'/.test(installStep),
    '(h) Subversion installation is Linux-only', installStep);

  const decisionMatch = source.match(/function svnGateDecision\(env, platform, present\) \{[\s\S]*?\n\}/);
  assert(!!decisionMatch, '(h) svn gate decision can be extracted from source');
  if (decisionMatch) {
    const decision = new Function(`${decisionMatch[0]}; return svnGateDecision;`)();
    assert(decision({ CI: '1' }, 'linux', false) === 'fail',
      '(h) Linux CI without svn selects fail');
    assert(decision({}, 'darwin', false) === 'skip',
      '(h) non-Linux/non-CI without svn selects skip');
    assert(decision({}, 'linux', false) === 'skip',
      '(h) Linux without CI and without svn selects skip');
    assert(decision({ CI: '1' }, 'darwin', false) === 'skip',
      '(h) CI on non-Linux without svn selects skip');
  }

  const svnDecision = svnGateDecision(process.env, process.platform, hasSvn());
  if (svnDecision === 'fail') {
    fail('Section 76: svn ausente no runner que deve gatear',
      'ci.yml instala subversion no runner Linux — ausência aqui é falso-verde, não skip');
    return;
  }
  if (svnDecision === 'skip') {
    skip('Section 76: fixture SVN', 'svn não está no PATH');
    return;
  }

  const fixture = initSvnRepo('svn-fixture');
  if (!fixture) return;
  try {
    assert(fs.existsSync(path.join(fixture.wc, '.svn')), '(a) checkout produces wc/.svn');

    fs.writeFileSync(path.join(fixture.wc, 'a.txt'), 'initial\n', 'utf8');
    fs.mkdirSync(path.join(fixture.wc, 'sub'));
    fs.writeFileSync(path.join(fixture.wc, 'sub', 'nested.txt'), 'nested\n', 'utf8');
    const added = svnq(fixture.wc, ['add', 'a.txt', 'sub'], fixture.configDir);
    const committed = svnq(fixture.wc, ['commit', '-m', 'init'], fixture.configDir);
    assert(added.status === 0 && committed.status === 0,
      '(b) svn add + commit return status 0', JSON.stringify({ added, committed }));
    const info = svnq(fixture.wc, ['info', '--show-item', 'revision', 'a.txt'], fixture.configDir);
    assert(info.status === 0 && info.stdout.trim() === '1',
      '(b) initial commit has revision 1', JSON.stringify(info));

    fs.writeFileSync(path.join(fixture.wc, 'a.txt'), 'modified\n', 'utf8');
    const status = svnq(fixture.wc, ['status', '--xml'], fixture.configDir);
    assert(status.status === 0 && /<status(?:\s|>)/.test(status.stdout)
      && /<entry\s+path="a\.txt"/.test(status.stdout),
    '(c) dirty svn status --xml is parseable and contains a.txt', status.stdout);
    assert(fs.existsSync(path.join(fixture.wc, 'sub'))
      && !fs.existsSync(path.join(fixture.wc, 'sub', '.svn')),
    '(d) versioned subdirectory has no nested .svn');
    assert(forgeIgnore.detectVcs(fixture.wc) === 'svn',
      '(f) detectVcs recognizes the SVN working-copy root');
    assert(forgeIgnore.detectVcs(path.join(fixture.wc, 'sub')) === 'svn',
      '(f) detectVcs recognizes an SVN working-copy subdirectory');
    const gitDir = mkTmp('svn-git-detection');
    const noneDir = mkTmp('svn-none-detection');
    try {
      fs.mkdirSync(path.join(gitDir, '.git'), { recursive: true });
      assert(forgeIgnore.detectVcs(gitDir) === 'git', '(f) detectVcs keeps git detection');
      assert(forgeIgnore.detectVcs(noneDir) === 'none', '(f) detectVcs keeps none detection');
    } finally {
      cleanup(gitDir);
      cleanup(noneDir);
    }

    const skipMatch = source.match(/function skip\(name, reason\) \{[\s\S]*?\n\}/);
    assert(!!skipMatch, '(e) skip implementation can be extracted from source');
    if (skipMatch) {
      const output = [];
      const extracted = new Function('write',
        `const process = { stdout: { write } }; let skips = 0; const skipped = [];\n${skipMatch[0]}\nreturn { skip, count: () => skips, items: skipped };`)(
          (line) => output.push(line));
      extracted.skip('fixture gate', 'stub reason');
      assert(extracted.count() === 1 && extracted.items.length === 1
        && output.length === 1 && /fixture gate/.test(output[0]),
      '(e) extracted skip increments and prints via stubbed collaborators', JSON.stringify({ output, items: extracted.items }));
    }
    assert(/smokeSvnFixture\(\);/.test(source.slice(source.lastIndexOf('async function main()'))),
      '(g) Section 76 is registered in main()');
    pass('(final) Section 76: fixture SVN real + skip contado verificada');
  } finally {
    cleanup(fixture.dir);
  }
}

// ── Section 77: VCS seam — behavioral parity and executable absence guards ──
// This section proves the seam against these counterfactuals: reintroducing a
// literal git call into the reset engine, weakening restore/remove/preserve
// semantics in the wrapper, or collapsing the .gsd-inclusive and .gsd-exclusive
// consumer views into one. It uses real fixtures and executes the relevant CLIs.
function smokeVcsSeam() {
  process.stdout.write('\n▸ Section 77: VCS seam — paridade git + absence-guard\n');
  const SR = path.join(SCRIPTS, 'forge-surgical-reset.js');
  const VCS = path.join(SCRIPTS, 'forge-vcs.js');
  const xllm = require(path.join(SCRIPTS, 'forge-xllm.js'));
  const sr = require(SR);
  const W = (dir, rel, content) => {
    const abs = path.join(dir, rel);
    fs.mkdirSync(path.dirname(abs), { recursive: true });
    fs.writeFileSync(abs, content, 'utf8');
  };
  const R = (dir, rel) => fs.readFileSync(path.join(dir, rel), 'utf8');
  const digest = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  const gitq = (cwd, args) => spawnSync('git', ['-C', cwd, ...args], { encoding: 'utf8' });
  const commit = (dir, message) => gitq(dir, ['add', '-A']) && gitq(dir, ['-c', 'user.email=smoke@forge', '-c', 'user.name=smoke', 'commit', '-qm', message]);
  const runReset = (stateFile, args) => runScript('forge-surgical-reset.js', args || ['--reset', '--state', stateFile]);

  // (a) Executable source guard: exact counts prevent a doc-only occurrence
  // from masking a reintroduced literal git argv in the reset engine.
  const source = fs.readFileSync(SR, 'utf8');
  const spawnGitCount = source.split("spawnSync('git'").length - 1;
  const revParseCount = source.split("'rev-parse'").length - 1;
  const hashObjectCount = source.split("'hash-object'").length - 1;
  const checkoutCount = source.split("'checkout'").length - 1;
  const seamRequireCount = source.split("require('./forge-vcs.js')").length - 1;
  assert(spawnGitCount === 0, `(a) reset source has zero spawnSync('git') argv literals (measured ${spawnGitCount})`);
  assert(revParseCount === 0, `(a) reset source has zero 'rev-parse' argv literals (measured ${revParseCount})`);
  assert(hashObjectCount === 0, `(a) reset source has zero 'hash-object' argv literals (measured ${hashObjectCount})`);
  assert(checkoutCount === 0, `(a) reset source has zero 'checkout' argv literals (measured ${checkoutCount})`);
  assert(seamRequireCount === 1, `(a) reset source requires forge-vcs.js exactly once (measured ${seamRequireCount})`);

  // (b)+(c) A real git fixture covers restore/remove/preserve behavior and
  // deliberately keeps the two .gsd consumer views observably asymmetric.
  const dir = mkTmp('vcs-seam');
  try {
    gitq(dir, ['init', '-q', '-b', 'main']);
    gitq(dir, ['config', 'user.email', 'smoke@forge']);
    gitq(dir, ['config', 'user.name', 'smoke@forge']);
    W(dir, 'a.txt', 'a baseline\n');
    W(dir, 'sub/s.txt', 'sub baseline\n');
    W(dir, 'b.txt', 'b baseline\n');
    commit(dir, 'seed');
    W(dir, 'b.txt', 'operator pre-existing work\n');
    const bPath = path.join(dir, 'b.txt');
    const beforeB = digest(bPath);
    const stateFile = path.join(dir, '.gsd', 'forge', 'vcs-seam-state.json');
    const init = runScript('forge-surgical-reset.js', ['--state-init', '--state', stateFile, '--cwd', dir]);
    assert(init.status === 0 && /^[0-9a-f]{40}\n?$/.test(init.stdout), '(b) --state-init exits 0 and prints START_SHA', JSON.stringify(init));

    W(dir, 'a.txt', 'sidecar changed a\n');
    W(dir, 'novo/lixo.txt', 'sidecar-only file\n');
    W(dir, '.gsd/x.json', '{"dirty":true}\n');
    const derived = xllm.deriveFilesChanged(dir, [], JSON.parse(fs.readFileSync(stateFile, 'utf8')).start_sha);
    const captured = sr.captureSnapshot(dir);
    const post = sr.computePostChanges(dir, JSON.parse(fs.readFileSync(stateFile, 'utf8')).start_sha);
    assert(derived.some((entry) => entry.path === '.gsd/x.json'), '(c) deriveFilesChanged includes .gsd/x.json while captureSnapshot/computePostChanges exclude it', JSON.stringify(derived));
    assert(!captured.some((entry) => entry.path === '.gsd/x.json'), '(c) captureSnapshot preserves the .gsd-exclusive view (not collapsed with deriveFilesChanged)', JSON.stringify(captured));
    assert(!post.some((entry) => entry.path === '.gsd/x.json'), '(c) computePostChanges preserves the .gsd-exclusive view (not collapsed with deriveFilesChanged)', JSON.stringify(post));

    const reset = runReset(stateFile);
    let resetOut = null;
    try { resetOut = JSON.parse(reset.stdout); } catch {}
    assert(reset.status === 0 && resetOut && resetOut.verified === true, '(b) --reset exits 0 and verifies the sidecar reset', reset.stdout + reset.stderr);
    assert(resetOut && resetOut.restored.includes('a.txt') && resetOut.removed.includes('novo/lixo.txt'), '(b) reset reports restored a.txt and removed novo/lixo.txt', JSON.stringify(resetOut));
    const afterB = digest(bPath);
    assert(afterB === beforeB, `(b) pre-existing b.txt SHA-256 is byte-identical before/after (${beforeB} !== ${afterB})`);
    assert(!fs.existsSync(path.join(dir, 'novo/lixo.txt')), '(b) sidecar-only file is removed from disk');
  } finally {
    cleanup(dir);
  }

  const overlapDir = mkTmp('vcs-seam-overlap');
  try {
    gitq(overlapDir, ['init', '-q', '-b', 'main']);
    gitq(overlapDir, ['config', 'user.email', 'smoke@forge']);
    gitq(overlapDir, ['config', 'user.name', 'smoke@forge']);
    W(overlapDir, 'a.txt', 'a baseline\n');
    W(overlapDir, 'b.txt', 'b baseline\n');
    commit(overlapDir, 'seed');
    W(overlapDir, 'b.txt', 'operator pre-existing work\n');
    const stateFile = path.join(overlapDir, '.gsd', 'forge', 'vcs-seam-overlap-state.json');
    const init = runScript('forge-surgical-reset.js', ['--state-init', '--state', stateFile, '--cwd', overlapDir]);
    assert(init.status === 0, '(b) overlap fixture state-init exits 0', init.stdout + init.stderr);
    W(overlapDir, 'a.txt', 'sidecar changed a\n');
    W(overlapDir, 'b.txt', 'sidecar overwrote overlap\n');
    W(overlapDir, 'novo/lixo.txt', 'must remain after overlap abort\n');
    const reset = runReset(stateFile);
    let overlapOut = null;
    try { overlapOut = JSON.parse(reset.stdout); } catch {}
    assert(reset.status === 3, '(b) overlap reset exits 3', reset.stdout + reset.stderr);
    assert(overlapOut && Array.isArray(overlapOut.overlap) && overlapOut.overlap.length > 0, '(b) overlap result is non-empty', JSON.stringify(overlapOut));
    assert(R(overlapDir, 'a.txt') === 'sidecar changed a\n' && R(overlapDir, 'b.txt') === 'sidecar overwrote overlap\n' && fs.existsSync(path.join(overlapDir, 'novo/lixo.txt')), '(b) overlap abort performs zero resets');
  } finally {
    cleanup(overlapDir);
  }

  // (d) The seam CLI has an explicit detect mode and an explicit usage error.
  const cliDir = mkTmp('vcs-seam-cli');
  try {
    gitq(cliDir, ['init', '-q', '-b', 'main']);
    gitq(cliDir, ['config', 'user.email', 'smoke@forge']);
    gitq(cliDir, ['config', 'user.name', 'smoke@forge']);
    const detected = runScript('forge-vcs.js', ['--detect', '--cwd', cliDir]);
    let detectedOut = null;
    try { detectedOut = JSON.parse(detected.stdout); } catch {}
    assert(detected.status === 0 && detectedOut && detectedOut.vcs === 'git', '(d) forge-vcs --detect reports git and exits 0', detected.stdout + detected.stderr);
    const missing = runScript('forge-vcs.js', []);
    assert(missing.status !== 0 && missing.stderr.startsWith('forge-vcs:'), '(d) forge-vcs without --detect exits non-zero with forge-vcs: usage error', missing.stderr);
  } finally {
    cleanup(cliDir);
  }

  const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeVcsSeam\(\); \}/.test(mainBody), '(g) Section 77 is registered through a closure in main()');
  pass('(final) Section 77: VCS seam — paridade git, assimetria .gsd, CLI e absence-guard verificadas');
}

// ── Section 78: real SVN primitives — surgical-reset safety proof ──────────
function smokeSvnPrimitives() {
  process.stdout.write('\n▸ Section 78: primitivas SVN — prova de segurança real\n');
  const decision = svnGateDecision(process.env, process.platform, hasSvn());
  if (decision === 'fail') {
    fail('Section 78: svn ausente no runner que deve gatear',
      'ci.yml instala subversion no runner Linux — ausência aqui é falso-verde, não skip');
    return;
  }
  if (decision === 'skip') {
    skip('Section 78: primitivas SVN', 'svn não está no PATH');
    return;
  }

  const vcs = require('./forge-vcs.js');
  const { computeResetTarget } = require('./forge-surgical-reset.js');
  const OPTS = { vcs: 'svn' };
  const sha256 = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  const write = (wc, rel, content) => {
    const file = path.join(wc, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
  };
  const seed = (label, files) => {
    const fixture = initSvnRepo(label);
    if (!fixture) return null;
    for (const [rel, content] of Object.entries(files)) write(fixture.wc, rel, content);
    const added = svnq(fixture.wc, ['add', '--parents', ...Object.keys(files)], fixture.configDir);
    const committed = svnq(fixture.wc, ['commit', '-m', 'r1'], fixture.configDir);
    // A checkout made before r1 reports 0:1 until it is updated.  Normalize it
    // to an r1 root so baselineId has the documented clean value of exactly 1.
    const updated = committed.status === 0 && svnq(fixture.wc, ['update'], fixture.configDir);
    assert(added.status === 0 && committed.status === 0 && updated && updated.status === 0, `(a) ${label} commits r1`,
      JSON.stringify({ added, committed, updated }));
    return fixture;
  };
  const entriesHave = (entries, rel) => entries.some((entry) => entry.path === rel);
  const tree = (root) => {
    const out = new Map();
    const visit = (dir, prefix) => {
      for (const name of fs.readdirSync(dir)) {
        if (name === '.svn') continue;
        const rel = prefix ? `${prefix}/${name}` : name;
        const abs = path.join(dir, name);
        const stat = fs.lstatSync(abs);
        if (stat.isDirectory()) { out.set(`${rel}/`, 'dir'); visit(abs, rel); }
        else out.set(rel, sha256(abs));
      }
    };
    visit(root, '');
    return [...out.entries()].sort((a, b) => a[0].localeCompare(b[0]));
  };

  // The central ROADMAP demo: this hash oracle deliberately uses local crypto,
  // never vcs.hashPath, so a broken seam cannot attest to its own correctness.
  const central = seed('svn-primitives', { 'a.txt': 'alpha\n', 'b.txt': 'bravo\n', 'sub/s.txt': 'sierra\n' });
  if (central) try {
    const centralOpts = { ...OPTS, configDir: central.configDir };
    const cleanBase = vcs.baselineId(central.wc, centralOpts);
    assert(cleanBase.ok && cleanBase.id === '1', '(a) SVN baselineId is r1 while clean', JSON.stringify(cleanBase));
    write(central.wc, 'b.txt', 'bravo LOCAL EDIT\n');
    const shaBBefore = sha256(path.join(central.wc, 'b.txt'));
    const pre = vcs.captureDirty(central.wc, centralOpts);
    assert(pre.ok && entriesHave(pre.entries, 'b.txt') && pre.entries.find((e) => e.path === 'b.txt').hash !== null,
      '(b) pre-dispatch snapshot protects b.txt with a hash', JSON.stringify(pre));
    write(central.wc, 'a.txt', 'alpha SIDECAR\n');
    write(central.wc, 'sub/s.txt', 'sierra SIDECAR\n');
    write(central.wc, 'junk.txt', 'junk\n');
    write(central.wc, 'junkdir/inner/deep.txt', 'deep junk\n');
    const post = vcs.postChanges(central.wc, null, centralOpts);
    const target = computeResetTarget(post.entries, pre.entries, (p) => vcs.hashPath(central.wc, p, centralOpts).hash);
    assert(post.ok && target.overlap.length === 0 && target.preserved.includes('b.txt'),
      '(d) central target preserves b.txt and has no overlap', JSON.stringify({ post, target }));
    const done = vcs.restoreAndRemove(central.wc, null, target, centralOpts);
    assert(done.ok, '(d) central restore/remove succeeds', JSON.stringify(done));
    assert(fs.readFileSync(path.join(central.wc, 'a.txt'), 'utf8') === 'alpha\n'
      && fs.readFileSync(path.join(central.wc, 'sub/s.txt'), 'utf8') === 'sierra\n',
    '(e) tracked sidecar edits return to committed content');
    assert(!fs.existsSync(path.join(central.wc, 'junk.txt')) && !fs.existsSync(path.join(central.wc, 'junkdir')),
      '(e) sidecar file and recursive unversioned directory are absent');
    assert(sha256(path.join(central.wc, 'b.txt')) === shaBBefore,
      '(e) independent sha256(b.txt) before dispatch equals after reset');
    const after = vcs.postChanges(central.wc, null, centralOpts);
    assert(after.ok && after.entries.length === 1 && after.entries[0].path === 'b.txt',
      '(e) only the operator edit remains after central reset', JSON.stringify(after));
    const dirtyBase = vcs.baselineId(central.wc, centralOpts);
    assert(dirtyBase.ok && /^1M?$/.test(dirtyBase.id), '(i) dirty SVN baseline is raw r1 marker', JSON.stringify(dirtyBase));

    // Newlines must travel as one argv value; --targets would split this into
    // invented paths and leave the file behind while svn still exits zero.
    write(central.wc, 'nl\nfile.txt', 'newline sidecar junk\n');
    const newlinePost = vcs.postChanges(central.wc, null, centralOpts);
    const newlineTarget = computeResetTarget(newlinePost.entries, pre.entries,
      (p) => vcs.hashPath(central.wc, p, centralOpts).hash);
    const newlineDone = vcs.restoreAndRemove(central.wc, null, newlineTarget, centralOpts);
    assert(newlineDone.ok && !fs.existsSync(path.join(central.wc, 'nl\nfile.txt')),
      '(i) newline path is removed through argv routing', JSON.stringify(newlineDone));
    const anchored = vcs.captureDirty(path.join(central.wc, 'sub'), centralOpts);
    assert(!anchored.ok && /svn-wcroot-mismatch/.test(anchored.error) && JSON.stringify(anchored.entries) === '[]',
      '(j) SVN primitives refuse a non-root working-copy path', JSON.stringify(anchored));
  } finally { cleanup(central.dir); }

  // This is the exit-3 semantic proof. CLI/state-file wiring is deliberately S04.
  const overlap = seed('svn-overlap', { 'a.txt': 'alpha\n', 'b.txt': 'bravo\n', 'sub/s.txt': 'sierra\n' });
  if (overlap) try {
    const overlapOpts = { ...OPTS, configDir: overlap.configDir };
    write(overlap.wc, 'b.txt', 'operator edit\n');
    const pre = vcs.captureDirty(overlap.wc, overlapOpts);
    write(overlap.wc, 'b.txt', 'sidecar overwrote operator\n');
    write(overlap.wc, 'extra.txt', 'sidecar extra\n');
    const post = vcs.postChanges(overlap.wc, null, overlapOpts);
    const target = computeResetTarget(post.entries, pre.entries, (p) => vcs.hashPath(overlap.wc, p, overlapOpts).hash);
    assert(target.overlap.includes('b.txt'), '(f) overlap detects sidecar rewrite of operator path', JSON.stringify(target));
    const beforeThrow = tree(overlap.wc);
    let thrown = null;
    try { vcs.restoreAndRemove(overlap.wc, null, target, overlapOpts); } catch (error) { thrown = error; }
    assert(thrown && /overlap is non-empty/.test(thrown.message), '(f) overlap hard guard throws its semantic error', String(thrown && thrown.message));
    assert(JSON.stringify(tree(overlap.wc)) === JSON.stringify(beforeThrow),
      '(f) overlap hard guard leaves every non-.svn tree file byte-identical');
  } finally { cleanup(overlap.dir); }

  const props = seed('svn-props', { 'a.txt': 'alpha\n', 'b2.txt': 'bravo two\n' });
  if (props) try {
    const propsOpts = { ...OPTS, configDir: props.configDir };
    const setProp = svnq(props.wc, ['propset', 'svn:mime-type', 'text/plain', 'b2.txt'], props.configDir);
    assert(setProp.status === 0, '(g) operator sets a prop-only change before snapshot', JSON.stringify(setProp));
    const pre = vcs.captureDirty(props.wc, propsOpts);
    assert(pre.ok && entriesHave(pre.entries, 'b2.txt'), '(g) normal+props=modified enters dirty snapshot', JSON.stringify(pre));
    write(props.wc, 'a.txt', 'sidecar change\n');
    const safePost = vcs.postChanges(props.wc, null, propsOpts);
    const safeTarget = computeResetTarget(safePost.entries, pre.entries, (p) => vcs.hashPath(props.wc, p, propsOpts).hash);
    const safeDone = vcs.restoreAndRemove(props.wc, null, safeTarget, propsOpts);
    const safeStatus = svnq(props.wc, ['status', '--xml'], props.configDir);
    assert(safeDone.ok && /path="b2\.txt"[\s\S]*?props="modified"/.test(safeStatus.stdout),
      '(g) reset of another sidecar edit preserves operator prop-only work', JSON.stringify({ safeDone, status: safeStatus.stdout }));
    const aggressivePre = vcs.captureDirty(props.wc, propsOpts);
    write(props.wc, 'b2.txt', 'sidecar changed b2 content\n');
    const aggressivePost = vcs.postChanges(props.wc, null, propsOpts);
    const aggressiveTarget = computeResetTarget(aggressivePost.entries, aggressivePre.entries,
      (p) => vcs.hashPath(props.wc, p, propsOpts).hash);
    let thrown = null;
    try { vcs.restoreAndRemove(props.wc, null, aggressiveTarget, propsOpts); } catch (error) { thrown = error; }
    const aggressiveStatus = svnq(props.wc, ['status', '--xml'], props.configDir);
    assert(aggressiveTarget.overlap.includes('b2.txt') && thrown && /overlap is non-empty/.test(thrown.message)
      && /path="b2\.txt"[\s\S]*?props="modified"/.test(aggressiveStatus.stdout),
    '(g) aggressive prop scenario aborts instead of reverting the operator property', JSON.stringify({ aggressiveTarget, message: thrown && thrown.message, status: aggressiveStatus.stdout }));
  } finally { cleanup(props.dir); }

  // Directory-level prop change (svn:ignore) must not blanket-recurse and
  // destroy a preserved sibling nested under that directory. This is the
  // R1-conceded review finding, reproduced against real svn as a contra-
  // factual: it fails against the pre-fix code (unconditional --depth
  // infinity on the whole batch) and must pass against the fix (directory
  // targets with a preserved descendant revert at --depth empty).
  const dirProp = seed('svn-dirprop', { 'dirA/keep.txt': 'keep original\n', 'other.txt': 'other\n' });
  if (dirProp) try {
    const dirPropOpts = { ...OPTS, configDir: dirProp.configDir };
    write(dirProp.wc, 'dirA/keep.txt', 'OPERATOR PRECIOUS WORK\n');
    const pre = vcs.captureDirty(dirProp.wc, dirPropOpts);
    assert(pre.ok && entriesHave(pre.entries, 'dirA/keep.txt'),
      '(k) operator edit under dirA enters the pre-dispatch dirty snapshot', JSON.stringify(pre));
    const setIgnore = svnq(dirProp.wc, ['propset', 'svn:ignore', '*.log', 'dirA'], dirProp.configDir);
    assert(setIgnore.status === 0, '(k) sidecar sets a directory-level prop after snapshot', JSON.stringify(setIgnore));
    const post = vcs.postChanges(dirProp.wc, null, dirPropOpts);
    const target = computeResetTarget(post.entries, pre.entries, (p) => vcs.hashPath(dirProp.wc, p, dirPropOpts).hash);
    assert(target.overlap.length === 0 && target.restore.includes('dirA') && target.preserved.includes('dirA/keep.txt'),
      '(k) target restores the dir-prop change and preserves the sibling operator file', JSON.stringify(target));
    const done = vcs.restoreAndRemove(dirProp.wc, null, target, dirPropOpts);
    assert(done.ok, '(k) restore/remove of the dir-prop target succeeds', JSON.stringify(done));
    // This is the R1 contrafactual: pre-fix, --depth infinity on the whole
    // batch recurses into dirA and reverts keep.txt to its committed content,
    // silently destroying the operator's precious work even though target
    // .preserved says it should have survived. Post-fix it must read back
    // byte-identical.
    assert(fs.readFileSync(path.join(dirProp.wc, 'dirA/keep.txt'), 'utf8') === 'OPERATOR PRECIOUS WORK\n',
      '(k) R1: preserved sibling under a reverted directory survives byte-identical');
    const dirStatus = svnq(dirProp.wc, ['status', '--xml'], dirProp.configDir);
    assert(!/svn:ignore/.test(dirStatus.stdout) || !/path="dirA"[\s\S]*?props="modified"/.test(dirStatus.stdout),
      '(k) the directory-level prop itself was reverted', dirStatus.stdout);
  } finally { cleanup(dirProp.dir); }

  const external = seed('svn-external-main', { 'a.txt': 'alpha\n' });
  const externalSource = seed('svn-external-src', { 'inside.txt': 'external base\n' });
  if (external && externalSource) try {
    const externalOpts = { ...OPTS, configDir: external.configDir };
    const externalUrl = require('url').pathToFileURL(externalSource.repo).href;
    const configured = svnq(external.wc, ['propset', 'svn:externals', `ext ${externalUrl}`, '.'], external.configDir);
    const committed = configured.status === 0 && svnq(external.wc, ['commit', '-m', 'external'], external.configDir);
    const updated = committed && committed.status === 0 && svnq(external.wc, ['update'], external.configDir);
    if (configured.status !== 0 || !committed || !updated || updated.status !== 0 || !fs.existsSync(path.join(external.wc, 'ext', 'inside.txt'))) {
      skip('Section 78: external SVN', 'fixture external setup falhou neste svn; sub-cenário não foi degradado a assert vacuo');
    } else {
      write(external.wc, 'ext/inside.txt', 'external operator dirty\n');
      const captured = vcs.captureDirty(external.wc, externalOpts);
      const posted = vcs.postChanges(external.wc, null, externalOpts);
      write(external.wc, 'a.txt', 'sidecar main change\n');
      const target = computeResetTarget(vcs.postChanges(external.wc, null, externalOpts).entries, captured.entries,
        (p) => vcs.hashPath(external.wc, p, externalOpts).hash);
      const done = vcs.restoreAndRemove(external.wc, null, target, externalOpts);
      assert(captured.ok && posted.ok && !captured.entries.some((e) => e.path.startsWith('ext/'))
        && !posted.entries.some((e) => e.path.startsWith('ext/')) && done.ok
        && fs.readFileSync(path.join(external.wc, 'ext', 'inside.txt'), 'utf8') === 'external operator dirty\n',
      '(h) external is absent from snapshots and survives reset untouched', JSON.stringify({ captured, posted, done }));
    }
  } finally { if (external) cleanup(external.dir); if (externalSource) cleanup(externalSource.dir); }

  const conflict = seed('svn-conflict', { 'a.txt': 'alpha\n' });
  if (conflict) try {
    const conflictOpts = { ...OPTS, configDir: conflict.configDir };
    const wc2 = path.join(conflict.dir, 'wc2');
    const checkedOut = svnq(conflict.dir, ['checkout', require('url').pathToFileURL(conflict.repo).href, wc2], conflict.configDir);
    if (checkedOut.status !== 0) {
      skip('Section 78: conflito SVN', 'segundo checkout da fixture falhou; fallback é a cobertura mapSvnItem de T01');
    } else {
      write(conflict.wc, 'a.txt', 'local conflicting change\n');
      write(wc2, 'a.txt', 'remote conflicting change\n');
      const remoteCommit = svnq(wc2, ['commit', '-m', 'remote'], conflict.configDir);
      const updated = remoteCommit.status === 0 && svnq(conflict.wc, ['update'], conflict.configDir);
      const captured = vcs.captureDirty(conflict.wc, conflictOpts);
      assert(updated && !captured.ok && /svn-status-unhandled:conflicted/.test(captured.error),
        '(h) real SVN conflict fails closed in captureDirty', JSON.stringify({ remoteCommit, updated, captured }));
    }
  } finally { cleanup(conflict.dir); }

  pass('(final) Section 78: prova SVN real — preservação, overlap, props, external, conflito e paths especiais verificados');
}

// ── Section 79: real SVN revision guard — partial-update safety proof ──────
function smokeSvnRevisionGuard() {
  process.stdout.write('\n▸ Section 79: guarda de revisão SVN — update parcial real\n');
  const { parseSvnBaseline } = require('./forge-surgical-reset.js');
  const decision = svnGateDecision(process.env, process.platform, hasSvn() && hasSvnversion());
  if (decision === 'fail') {
    fail('Section 79: svn ou svnversion ausente no runner que deve gatear',
      'ci.yml instala subversion no runner Linux — ausência aqui é falso-verde, não skip');
    return;
  }
  if (decision === 'skip') {
    skip('Section 79: guarda de revisão SVN', 'svn e svnversion devem estar no PATH');
    return;
  }

  // This is intentionally a local oracle, never forge-vcs.hashPath: otherwise
  // the seam under test could attest to its own preservation claim.
  const sha256 = (file) => crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
  const write = (wc, rel, content) => {
    const file = path.join(wc, rel);
    fs.mkdirSync(path.dirname(file), { recursive: true });
    fs.writeFileSync(file, content, 'utf8');
  };
  const tree = (root) => {
    const entries = [];
    const visit = (dir, prefix) => {
      for (const name of fs.readdirSync(dir)) {
        if (name === '.svn') continue;
        const abs = path.join(dir, name);
        const rel = prefix ? `${prefix}/${name}` : name;
        if (fs.lstatSync(abs).isDirectory()) visit(abs, rel);
        else entries.push([rel, sha256(abs)]);
      }
    };
    visit(root, '');
    return entries.sort((a, b) => a[0].localeCompare(b[0]));
  };
  const cli = (args, fixture) => {
    // The reset CLI has no config-dir flag.  Pin its default config home to
    // this fixture while direct svn calls remain explicitly argv/config-dir.
    const home = path.join(fixture.dir, 'svn-home');
    fs.mkdirSync(home, { recursive: true });
    const configLink = path.join(home, '.subversion');
    if (!fs.existsSync(configLink)) fs.symlinkSync(fixture.configDir, configLink, 'dir');
    return runScript('forge-surgical-reset.js', args, {
      env: { ...process.env, HOME: home, USERPROFILE: home },
    });
  };
  const json = (result) => {
    try { return JSON.parse(result.stdout); } catch { return null; }
  };
  const seed = (label, files) => {
    const fixture = initSvnRepo(label);
    if (!fixture) return null;
    for (const [rel, content] of Object.entries(files)) write(fixture.wc, rel, content);
    const added = svnq(fixture.wc, ['add', '--parents', ...Object.keys(files)], fixture.configDir);
    const committed = svnq(fixture.wc, ['commit', '-m', 'r1'], fixture.configDir);
    const updated = committed.status === 0 && svnq(fixture.wc, ['update'], fixture.configDir);
    assert(added.status === 0 && committed.status === 0 && updated && updated.status === 0,
      `(a) ${label} commits and updates r1`, JSON.stringify({ added, committed, updated }));
    return fixture;
  };
  const teammateCommit = (fixture, rel, content) => {
    const wc2 = path.join(fixture.dir, 'wc-teammate');
    const checkout = svnq(fixture.dir, ['checkout', require('url').pathToFileURL(fixture.repo).href, wc2], fixture.configDir);
    if (checkout.status !== 0) return { checkout, commit: null, wc2 };
    write(wc2, rel, content);
    return { checkout, commit: svnq(wc2, ['commit', '-m', 'r2'], fixture.configDir), wc2 };
  };

  // (a) Establish the premise directly in svn: partial update + raw revert
  // really can replace the operator's sidecar content with a teammate's r2.
  const premise = seed('svn-revision-premise', { 'sub/c.txt': 'c-v1\n' });
  if (premise) try {
    write(premise.wc, 'sub/c.txt', 'c-SIDECAR\n');
    const teammate = teammateCommit(premise, 'sub/c.txt', 'c-TEAMMATE\n');
    const updated = teammate.commit && teammate.commit.status === 0
      && svnq(premise.wc, ['update', '--accept', 'theirs-full', 'sub'], premise.configDir);
    const reverted = updated && updated.status === 0
      && svnq(premise.wc, ['revert', 'sub/c.txt'], premise.configDir);
    assert(teammate.checkout.status === 0 && teammate.commit && teammate.commit.status === 0
      && updated && updated.status === 0 && reverted && reverted.status === 0
      && fs.readFileSync(path.join(premise.wc, 'sub/c.txt'), 'utf8') === 'c-TEAMMATE\n',
    '(a) raw svn revert after partial update restores teammate r2 (the measured danger)',
    JSON.stringify({ teammate, updated, reverted }));
  } finally { cleanup(premise.dir); }

  // (b) Primary E2: only sub moves to r2.  Root svn info remains 1, proving a
  // root-only sensor is blind, while svnversion correctly returns the 1:2 range.
  const partial = seed('svn-revision-partial', { 'b.txt': 'b-v1\n', 'sub/c.txt': 'c-v1\n' });
  if (partial) try {
    const stateFile = path.join(partial.dir, 'state.json');
    const initialized = cli(['--state-init', '--state', stateFile, '--cwd', partial.wc], partial);
    const state = fs.existsSync(stateFile) ? JSON.parse(fs.readFileSync(stateFile, 'utf8')) : null;
    assert(initialized.status === 0 && initialized.stdout.trim() === '1' && state
      && state.vcs === 'svn' && state.start_sha === '1',
    '(b) state-init persists svn baseline 1 and emits non-empty stdout', JSON.stringify({ initialized, state }));
    write(partial.wc, 'sub/c.txt', 'c-SIDECAR\n');
    write(partial.wc, 'junk.txt', 'sidecar junk\n');
    const teammate = teammateCommit(partial, 'sub/c.txt', 'c-TEAMMATE\n');
    const updated = teammate.commit && teammate.commit.status === 0
      && svnq(partial.wc, ['update', '--accept', 'mine-full', 'sub'], partial.configDir);
    const rootRevision = svnq(partial.wc, ['info', '--show-item', 'revision'], partial.configDir);
    assert(updated && updated.status === 0 && rootRevision.status === 0 && rootRevision.stdout.trim() === '1',
      '(b) partial update leaves root svn info at r1 (blind-sensor premise)', JSON.stringify({ updated, rootRevision }));
    const before = tree(partial.wc);
    const reset = cli(['--reset', '--state', stateFile], partial);
    const result = json(reset);
    assert(reset.status === 3 && result && result.abort === 'svn-revision-moved'
      && result.baseline === '1' && result.current === '1:2' && JSON.stringify(result.overlap) === '[]',
    '(b) partial update aborts with the discriminated svn revision result', JSON.stringify({ reset, result }));
    assert(JSON.stringify(tree(partial.wc)) === JSON.stringify(before) && fs.existsSync(path.join(partial.wc, 'junk.txt')),
      '(b) abort leaves every working-copy file byte-identical, including sidecar junk');
  } finally { cleanup(partial.dir); }

  // (c) B3 is the anti-inert counterexample: dirty r1 is still r1, not a move.
  const dirty = seed('svn-revision-dirty', { 'b.txt': 'b-v1\n', 'sub/c.txt': 'c-v1\n' });
  if (dirty) try {
    write(dirty.wc, 'b.txt', 'b-OPERATOR\n');
    const bBefore = sha256(path.join(dirty.wc, 'b.txt'));
    const stateFile = path.join(dirty.dir, 'state.json');
    const initialized = cli(['--state-init', '--state', stateFile, '--cwd', dirty.wc], dirty);
    write(dirty.wc, 'sub/c.txt', 'c-SIDECAR\n');
    write(dirty.wc, 'junk.txt', 'sidecar junk\n');
    const reset = cli(['--reset', '--state', stateFile], dirty);
    const result = json(reset);
    assert(initialized.status === 0 && reset.status === 0 && result && result.ok === true
      && !fs.existsSync(path.join(dirty.wc, 'junk.txt'))
      && fs.readFileSync(path.join(dirty.wc, 'sub/c.txt'), 'utf8') === 'c-v1\n'
      && sha256(path.join(dirty.wc, 'b.txt')) === bBefore && result.preserved.includes('b.txt'),
    '(c) dirty-only r1 resets sidecar changes and preserves the operator file', JSON.stringify({ initialized, reset, result }));
  } finally { cleanup(dirty.dir); }

  // (d) A whole-WC update is secondary coverage; it must still be refused.
  const complete = seed('svn-revision-complete', { 'sub/c.txt': 'c-v1\n' });
  if (complete) try {
    const stateFile = path.join(complete.dir, 'state.json');
    const initialized = cli(['--state-init', '--state', stateFile, '--cwd', complete.wc], complete);
    const teammate = teammateCommit(complete, 'sub/c.txt', 'c-TEAMMATE\n');
    const updated = teammate.commit && teammate.commit.status === 0
      && svnq(complete.wc, ['update', '--accept', 'theirs-full'], complete.configDir);
    const reset = cli(['--reset', '--state', stateFile], complete);
    const result = json(reset);
    assert(initialized.status === 0 && updated && updated.status === 0 && reset.status === 3 && result
      && result.abort === 'svn-revision-moved' && result.current === '2',
    '(d) complete update is also refused with current r2', JSON.stringify({ initialized, teammate, updated, reset, result }));
  } finally { cleanup(complete.dir); }

  // (e) A pre-update checkout after its first commit has svnversion 0:1 and
  // cannot become a durable baseline.  stdout must be literally empty.
  const zero = initSvnRepo('svn-revision-zero');
  if (zero) try {
    write(zero.wc, 'a.txt', 'a-r1\n');
    const added = svnq(zero.wc, ['add', 'a.txt'], zero.configDir);
    const committed = added.status === 0 && svnq(zero.wc, ['commit', '-m', 'r1'], zero.configDir);
    const version = spawnSync('svnversion', [], { cwd: zero.wc, encoding: 'utf8' });
    const parsed = parseSvnBaseline(version.stdout);
    const initialized = cli(['--state-init', '--state', path.join(zero.dir, 'state.json'), '--cwd', zero.wc], zero);
    assert(committed && committed.status === 0 && version.status === 0 && version.stdout.trim() === '0:1',
      '(e) post-commit pre-update checkout reports svnversion 0:1', JSON.stringify({ added, committed, version }));
    assert(parsed.ok === false && parsed.error === 'svn-baseline-zero-revision'
      && initialized.status !== 0 && initialized.stdout.trim() === ''
      && initialized.stderr.includes('svn-baseline-zero-revision'),
    '(e) zero revision parser and state-init reject with empty stdout', JSON.stringify({ parsed, initialized }));
  } finally { cleanup(zero.dir); }

  // (f) This fixture intentionally uses the real CLI contract.  It remains
  // inside the SVN gate so an SVN-less runner has one named, counted skip.
  const gitDir = mkTmp('svn-revision-vcs-mismatch');
  try {
    const gitq = (args) => spawnSync('git', ['-C', gitDir, ...args], { encoding: 'utf8' });
    const created = gitq(['init', '-q', '-b', 'main']);
    const email = created.status === 0 && gitq(['config', 'user.email', 'smoke@forge']);
    const name = email && email.status === 0 && gitq(['config', 'user.name', 'smoke']);
    write(gitDir, 'tracked.txt', 'baseline\n');
    const added = name && name.status === 0 && gitq(['add', 'tracked.txt']);
    const committed = added && added.status === 0 && gitq(['commit', '-qm', 'r1']);
    const stateFile = path.join(gitDir, 'state.json');
    const initialized = committed && committed.status === 0 && runScript('forge-surgical-reset.js', ['--state-init', '--state', stateFile, '--cwd', gitDir]);
    write(gitDir, 'junk-git.txt', 'sidecar junk\n');
    const svnState = fs.existsSync(stateFile) ? { ...JSON.parse(fs.readFileSync(stateFile, 'utf8')), vcs: 'svn' } : null;
    if (svnState) fs.writeFileSync(stateFile, JSON.stringify(svnState), 'utf8');
    const mismatch = runScript('forge-surgical-reset.js', ['--reset', '--state', stateFile]);
    const mismatchResult = json(mismatch);
    assert(initialized && initialized.status === 0 && mismatch.status === 3 && mismatchResult
      && mismatchResult.abort === 'vcs-state-mismatch' && fs.existsSync(path.join(gitDir, 'junk-git.txt')),
    '(f) svn state on a git WC aborts and leaves its tree intact', JSON.stringify({ initialized, mismatch, mismatchResult }));
    const legacy = svnState && { ...svnState };
    if (legacy) { delete legacy.vcs; fs.writeFileSync(stateFile, JSON.stringify(legacy), 'utf8'); }
    const legacyReset = runScript('forge-surgical-reset.js', ['--reset', '--state', stateFile]);
    assert(legacyReset.status === 0 && !fs.existsSync(path.join(gitDir, 'junk-git.txt')),
      '(f) legacy state without vcs retains the git reset path', JSON.stringify(legacyReset));
  } finally { cleanup(gitDir); }

  const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeSvnRevisionGuard\(\); \}/.test(mainBody),
    '(g) Section 79 is registered through a closure in main()');
  pass('(final) Section 79: revisão SVN — premissa, update parcial, B3, zero e compatibilidade verificados');
}

// ── Section 81: canonical post-run change set — mirrors + VCS proof ───────
function smokeSidecarDiffCanonical() {
  process.stdout.write('\n▸ Section 81: canonical post-run change set — mirrors, git parity, SVN state-init\n');
  const repoRoot = path.dirname(SCRIPTS);
  const VCS = path.join(SCRIPTS, 'forge-vcs.js');
  const SR = path.join(SCRIPTS, 'forge-surgical-reset.js');
  const title = '#### Post-run change set + baseline (canonical — VCS-agnostic)';
  const canonicalReference = 'shared/forge-dispatch.md § Post-run change set + baseline (canonical — VCS-agnostic)';
  const mirrors = [
    'skills/forge-auto/SKILL.md',
    'skills/forge-next/SKILL.md',
    'skills/forge-task/SKILL.md',
  ];
  const read = (rel) => sidecarSurface(path.join(repoRoot, rel));  // sidecar surface (2026-08-23)

  // (a)+(b) Documentation is intentionally a text guard: the executable
  // assertions below own behavior; these prevent mirrors from re-copying the
  // formula that the canonical spec owns exactly once.
  for (const mirror of mirrors) {
    const text = read(mirror);
    assert(text.includes(canonicalReference),
      `(a) ${mirror} names the canonical post-run change-set block`);
    const copied = text.split('diff --name-status').length - 1;
    assert(copied === 0,
      `(b) ${mirror} has zero copied diff --name-status literals (got ${copied})`);
  }
  const spec = read('shared/forge-dispatch.md');
  const titleCount = spec.split(title).length - 1;
  assert(titleCount === 1,
    `(a) shared/forge-dispatch.md carries the canonical post-run block exactly once (got ${titleCount})`);
  assert(spec.includes('forge-vcs.js" --changes'),
    '(a) canonical post-run block invokes forge-vcs.js --changes');

  // (c) The git CLI must be byte-for-byte compatible with git's own
  // name-status presentation, except for the terminal newline contract.
  const gitDir = mkTmp('section81-git');
  try {
    const gitq = (args) => spawnSync('git', ['-C', gitDir, ...args], { encoding: 'utf8' });
    const write = (rel, value) => {
      const file = path.join(gitDir, rel);
      fs.mkdirSync(path.dirname(file), { recursive: true });
      fs.writeFileSync(file, value, 'utf8');
    };
    gitq(['init', '-q', '-b', 'main']);
    gitq(['config', 'user.email', 'smoke@forge']);
    gitq(['config', 'user.name', 'smoke']);
    write('modified.txt', 'before\n');
    write('deleted.txt', 'before\n');
    const seeded = gitq(['add', '-A']);
    const committed = seeded.status === 0 && gitq(['commit', '-qm', 'seed']);
    const base = committed && committed.status === 0 ? gitq(['rev-parse', 'HEAD']).stdout.trim() : '';
    assert(!!base, '(c) git fixture has a committed baseline', JSON.stringify({ seeded, committed, base }));
    if (base) {
      write('added.txt', 'added\n');
      gitq(['add', 'added.txt']); // git diff <BASE> now includes the new path too.
      write('modified.txt', 'after\n');
      fs.rmSync(path.join(gitDir, 'deleted.txt'));
      const actual = spawnSync('node', [VCS, '--changes', '--cwd', gitDir, '--since', base], { encoding: 'utf8' });
      const expected = gitq(['diff', '--name-status', base]);
      assert(actual.status === 0 && expected.status === 0
        && actual.stdout.replace(/\n$/, '') === expected.stdout.replace(/\n$/, ''),
      '(c) forge-vcs --changes is string-identical to git diff --name-status',
      JSON.stringify({ actual, expected }));
      // Restore the fixture before proving the empty-delta contract.
      gitq(['checkout', '--', 'modified.txt', 'deleted.txt']);
      gitq(['reset', '--', 'added.txt']);
      fs.rmSync(path.join(gitDir, 'added.txt'));
      const empty = spawnSync('node', [VCS, '--changes', '--cwd', gitDir, '--since', base], { encoding: 'utf8' });
      assert(empty.status === 0 && empty.stdout === '',
        '(c) forge-vcs --changes has exit 0 and empty stdout for an empty git delta', JSON.stringify(empty));
    }
  } finally { cleanup(gitDir); }

  const noVcs = mkTmp('section81-no-vcs');
  try {
    const none = spawnSync('node', [VCS, '--changes', '--cwd', noVcs, '--since', 'baseline'], { encoding: 'utf8' });
    assert(none.status !== 0 && none.stdout === '',
      '(c) forge-vcs --changes outside VCS fails with empty stdout', JSON.stringify(none));
    // R2 (review): --baseline must fail symmetrically with --changes outside
    // any VCS, not just silently return an empty/undefined id.
    const noneBaseline = spawnSync('node', [VCS, '--baseline', '--cwd', noVcs], { encoding: 'utf8' });
    assert(noneBaseline.status !== 0 && noneBaseline.stdout === '',
      '(c) forge-vcs --baseline outside VCS fails with empty stdout', JSON.stringify(noneBaseline));
  } finally { cleanup(noVcs); }

  // (d)+(e) SVN is gated exactly like the other real-SVN sections: Linux CI
  // cannot turn a missing prerequisite into a false-green skip, while other
  // runners retain an explicit, counted skip.
  const decision = svnGateDecision(process.env, process.platform, hasSvn() && hasSvnversion());
  if (decision === 'fail') {
    fail('Section 81: svn, svnadmin ou svnversion ausente no runner que deve gatear',
      'ci.yml instala subversion no runner Linux — ausência aqui é falso-verde, não skip');
    return;
  }
  if (decision === 'skip') {
    skip('Section 81: SVN change/state-init fixture', 'svn, svnadmin e svnversion devem estar no PATH');
    return;
  }

  const fixture = initSvnRepo('section81-svn');
  if (!fixture) return;
  try {
    const write = (rel, value) => fs.writeFileSync(path.join(fixture.wc, rel), value, 'utf8');
    write('tracked.txt', 'baseline\n');
    const added = svnq(fixture.wc, ['add', 'tracked.txt'], fixture.configDir);
    const committed = added.status === 0 && svnq(fixture.wc, ['commit', '-m', 'seed'], fixture.configDir);
    const updated = committed && committed.status === 0 && svnq(fixture.wc, ['update'], fixture.configDir);
    assert(added.status === 0 && committed && committed.status === 0 && updated && updated.status === 0,
      '(d) SVN fixture commits and updates revision 1', JSON.stringify({ added, committed, updated }));
    const baseline = spawnSync('node', [VCS, '--baseline', '--cwd', fixture.wc], { encoding: 'utf8' });
    assert(baseline.status === 0 && baseline.stdout.trim() === '1',
      '(d) forge-vcs --baseline emits SVN revision 1', JSON.stringify(baseline));
    if (baseline.status !== 0 || !baseline.stdout.trim()) return;
    write('added.txt', 'added\n');
    write('tracked.txt', 'changed\n');
    const changed = spawnSync('node', [VCS, '--changes', '--cwd', fixture.wc, '--since', baseline.stdout.trim()], { encoding: 'utf8' });
    const expectedSvn = 'A\tadded.txt\nM\ttracked.txt\n';
    assert(changed.status === 0 && changed.stdout === expectedSvn,
      '(d) forge-vcs --changes lists exactly the SVN-written paths and statuses', JSON.stringify(changed));

    const state = path.join(fixture.dir, 'state.json');
    const initialized = spawnSync('node', [SR, '--state-init', '--state', state, '--cwd', fixture.wc], { encoding: 'utf8' });
    assert(initialized.status === 0 && initialized.stdout.trim() !== '',
      '(e) SVN state-init exits 0 and prints a non-empty START_SHA', JSON.stringify(initialized));
    const events = path.join(fixture.dir, 'events.jsonl');
    const guard = spawnSync('bash', ['-c',
      'START_SHA="$1"; REASON=""; [ -n "$START_SHA" ] || REASON="sidecar-state-init-failed"; [ -n "$REASON" ] && echo "{\\"event\\":\\"worker-engine-fallback\\",\\"reason\\":\\"$REASON\\"}" >> "$2"; echo "REASON=$REASON"',
      'section81-guard', initialized.stdout.trim(), events], { encoding: 'utf8' });
    const eventText = fs.existsSync(events) ? fs.readFileSync(events, 'utf8') : '';
    assert(guard.status === 0 && guard.stdout.trim() === 'REASON=' && !eventText.includes('sidecar-state-init-failed'),
      '(e) literal mirror guard leaves REASON empty and emits no SVN state-init failure event', JSON.stringify({ guard, eventText }));

    const invalid = mkTmp('section81-invalid-vcs');
    try {
      const invalidState = path.join(invalid, 'state.json');
      const invalidInit = spawnSync('node', [SR, '--state-init', '--state', invalidState, '--cwd', invalid], { encoding: 'utf8' });
      const invalidEvents = path.join(invalid, 'events.jsonl');
      const invalidGuard = spawnSync('bash', ['-c',
        'START_SHA="$1"; REASON=""; [ -n "$START_SHA" ] || REASON="sidecar-state-init-failed"; [ -n "$REASON" ] && echo "{\\"event\\":\\"worker-engine-fallback\\",\\"reason\\":\\"$REASON\\"}" >> "$2"; echo "REASON=$REASON"',
        'section81-guard', invalidInit.stdout.trim(), invalidEvents], { encoding: 'utf8' });
      const invalidText = fs.existsSync(invalidEvents) ? fs.readFileSync(invalidEvents, 'utf8') : '';
      assert(invalidInit.status !== 0 && invalidInit.stdout === '' && invalidGuard.stdout.trim() === 'REASON=sidecar-state-init-failed'
        && invalidText.includes('sidecar-state-init-failed'),
      '(e) literal mirror guard distinguishes a no-VCS state-init failure', JSON.stringify({ invalidInit, invalidGuard, invalidText }));
    } finally { cleanup(invalid); }
  } finally { cleanup(fixture.dir); }

  const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeSidecarDiffCanonical\(\); \}/.test(mainBody),
    '(final) Section 81 is registered through a closure in main()');
  pass('(final) Section 81: canonical mirrors, git parity, SVN changes, and state-init fallback guard verified');
}

// ── Section 73: the harness protects its own coverage ──────────────────────
async function smokeSectionIsolation() {
  process.stdout.write('\n▸ Section 73: section isolation\n');
  // Normalized: this section slices its own source, and a CRLF checkout would
  // otherwise make every '\n'-anchored boundary miss silently.
  const src = fs.readFileSync(__filename, 'utf8').replace(/\r\n/g, '\n');
  const mainBody = src.slice(src.indexOf('async function main()'));

  // (a) No section may be called bare inside main() — a bare call is exactly
  // the shape that let one throw abort the run.
  const bare = mainBody.split('\n').filter(line => /^\s*(await )?smoke\w+\(\);\s*$/.test(line));
  assert(bare.length === 0, '(a) every section in main() is routed through runSection', `bare calls=${JSON.stringify(bare)}`);
  assert(/\]\) await runSection\(body\);/.test(mainBody), '(a) main() awaits runSection for each section body');

  // (b) A crashed section is announced separately from the pass/fail tally.
  assert(/crashedSections\.length > 0/.test(mainBody) && /section\(s\) crashed and did not finish/.test(mainBody),
    '(b) a crashed section is reported loudly, not folded into the tally');

  // (c) Behavioural: instantiate the real runSection with stubbed collaborators
  // and prove a throwing body is contained, labelled and recorded.
  const declaration = src.slice(src.indexOf('async function runSection(body)'));
  const source = declaration.slice(0, declaration.indexOf('\n}\n') + 3);
  const recorded = [];
  const crashes = [];
  const isolated = new Function('fail', 'crashedSections',
    `${source}; return runSection;`)((name, detail) => recorded.push({ name, detail }), crashes);

  let escaped = null;
  try {
    await isolated(() => { smokeBoomFixture(); });
  } catch (error) { escaped = error; }
  assert(escaped === null, '(c) a throwing section does not escape runSection', String(escaped && escaped.message));
  assert(crashes.length === 1 && crashes[0] === 'smokeBoomFixture',
    '(c) the crashed section is labelled from its own call site', JSON.stringify(crashes));
  assert(recorded.length === 1 && /crashed/.test(recorded[0].name),
    '(c) the crash is recorded as a failure', JSON.stringify(recorded));

  let ran = false;
  await isolated(() => { ran = true; });
  assert(ran && crashes.length === 1, '(c) a healthy section still runs and records no crash');
}

// Deliberately throws — the fixture body for the isolation guard above.
function smokeBoomFixture() {
  throw new TypeError("Cannot read properties of undefined (reading '0')");
}

// ── Section 82: isolation in SVN + vcs dispatch telemetry ─────────────────
function smokeIsolationSvnAndVcsTelemetry() {
  process.stdout.write('\n▸ Section 82: isolation in SVN + vcs dispatch telemetry\n');
  const isolation = path.join(SCRIPTS, 'forge-isolation.js');
  const prefs = {
    forge_isolation: { mode: 'worktree' },
    workers: { require_worktree: true },
  };
  const writePrefs = (dir) => {
    fs.mkdirSync(path.join(dir, '.gsd'), { recursive: true });
    fs.writeFileSync(path.join(dir, '.gsd', 'forge-prefs.jsonc'), JSON.stringify(prefs), 'utf8');
  };
  const jsonRun = (args, opts) => {
    const r = spawnSync('node', [isolation, ...args], { encoding: 'utf8', ...opts });
    let value = null;
    try { value = JSON.parse(r.stdout); } catch {}
    return { status: r.status, value, stderr: r.stderr || '', stdout: r.stdout || '' };
  };

  // (a)+(c): the SVN setup must return a named shared no-op rather than
  // entering git worktree setup and producing the all-repositories STOP shape.
  const decision = svnGateDecision(process.env, process.platform, hasSvn());
  if (decision === 'fail') {
    fail('Section 82: svn e svnadmin ausentes no runner que deve gatear',
      'ci.yml instala subversion no runner Linux — ausência aqui é falso-verde, não skip');
  } else if (decision === 'skip') {
    skip('Section 82: SVN effective-mode/setup fixture', 'svn e svnadmin devem estar no PATH');
  } else {
    const fixture = initSvnRepo('section82-svn');
    if (fixture) {
      try {
        writePrefs(fixture.wc);
        const effective = jsonRun(['--effective-mode', '--cwd', fixture.wc], {
          env: { ...process.env, SVN_CONFIG_DIR: fixture.configDir },
        });
        assert(effective.status === 0 && effective.value
          && effective.value.mode === 'shared' && effective.value.elevated === false
          && effective.value.vcs === 'svn' && effective.value.user_mode === 'worktree'
          && /svn/i.test(effective.value.elevation_reason || ''),
        '(a) SVN worktree request resolves to named shared mode and preserves user_mode', JSON.stringify(effective));

        const setup = jsonRun(['--setup', '--run', 'S82-SVN', '--cwd', fixture.wc], {
          env: { ...process.env, SVN_CONFIG_DIR: fixture.configDir },
        });
        assert(setup.status === 0 && setup.value && setup.value.mode === 'shared'
          && setup.value.vcs === 'svn' && Array.isArray(setup.value.repos)
          && setup.value.repos.length === 0,
        '(c) SVN setup is a shared no-op, never the all-repositories-failed STOP shape', JSON.stringify(setup));

        const cleanupResult = jsonRun(['--cleanup', '--run', 'S82-SVN', '--cwd', fixture.wc], {
          env: { ...process.env, SVN_CONFIG_DIR: fixture.configDir },
        });
        assert(cleanupResult.status === 0 && cleanupResult.value && cleanupResult.value.vcs === 'svn',
          '(c) cleanup JSON propagates additive vcs for SVN', JSON.stringify(cleanupResult));
      } finally { cleanup(fixture.dir); }
    }
  }

  // (b): same prefs, different VCS. This is intentionally a real git repo so
  // it proves the SVN guard is positively scoped and leaves git elevation intact.
  const gitDir = mkTmp('section82-git');
  try {
    const init = spawnSync('git', ['init', '-q', '-b', 'main', gitDir], { encoding: 'utf8' });
    if (init.status !== 0) {
      fail('Section 82: git fixture initializes', JSON.stringify(init));
    } else {
      writePrefs(gitDir);
      const effective = jsonRun(['--effective-mode', '--cwd', gitDir]);
      assert(effective.status === 0 && effective.value
        && effective.value.mode === 'worktree' && effective.value.elevated === false
        && effective.value.vcs === 'git' && effective.value.user_mode === 'worktree',
      '(b) identical worktree prefs retain git worktree mode and report vcs:git', JSON.stringify(effective));
    }
  } finally { cleanup(gitDir); }

  // (d): count each mirror's dispatch emitters. Presence must be per emitter,
  // so a forgotten line cannot be masked by another correctly updated line.
  const skills = [
    ['forge-auto', 'forge-auto/SKILL.md', 4],
    ['forge-next', 'forge-next/SKILL.md', 3],
    ['forge-task', 'forge-task/SKILL.md', 2],
  ];
  for (const [name, rel, expected] of skills) {
    const source = sidecarSurface(path.join(path.dirname(SCRIPTS), 'skills', rel));  // sidecar surface (2026-08-23)
    const lines = source.split(/\r?\n/).filter(line => line.includes('\\"event\\":\\"dispatch\\"'));
    assert(lines.length === expected && lines.every(line => line.includes('\\"vcs\\":')),
      `(d) ${name} has vcs on all ${expected} dispatch event emitters`, JSON.stringify(lines));
  }
  const dispatchSpec = fs.readFileSync(path.join(path.dirname(SCRIPTS), 'shared', 'forge-dispatch.md'), 'utf8');
  assert(/\| `vcs` \| string \| `detectVcs\(CODE_DIR\)` \| `"git"` \|/.test(dispatchSpec)
    && /`vcs` is likewise additive/.test(dispatchSpec),
  '(d) dispatch spec documents additive vcs field and git example');

  // (e) DISPATCH_VCS prelude: 9 emitters across 3 files must carry a
  // byte-identical extraction line, named-reference the canonical block in
  // shared/forge-dispatch.md, and the canonical title must appear exactly
  // once. Reviewer R1: a single site edited in isolation must turn this red.
  const dispatchVcsTitle = '#### DISPATCH_VCS prelude (canonical — VCS-agnostic)';
  const dispatchVcsReference = 'shared/forge-dispatch.md § DISPATCH_VCS prelude (canonical — VCS-agnostic)';
  const dispatchVcsMirrors = [
    ['forge-auto', 'forge-auto/SKILL.md', 4],
    ['forge-next', 'forge-next/SKILL.md', 3],
    ['forge-task', 'forge-task/SKILL.md', 2],
  ];
  const dispatchVcsLine = 'DISPATCH_VCS=$(node "$FORGE_SCRIPTS_DIR/forge-vcs.js" --detect --field vcs --cwd "${CODE_DIR:-$WORKING_DIR}" 2>/dev/null || echo "unknown")';
  for (const [name, rel, expected] of dispatchVcsMirrors) {
    const source = sidecarSurface(path.join(path.dirname(SCRIPTS), 'skills', rel));  // sidecar surface (2026-08-23)
    const referenceCount = source.split(dispatchVcsReference).length - 1;
    const extractionLines = source.split(/\r?\n/)
      .map(line => line.trim())
      .filter(line => line.startsWith('DISPATCH_VCS='));
    assert(referenceCount === expected,
      `(e) ${name} names the DISPATCH_VCS prelude exactly ${expected}x (got ${referenceCount})`);
    assert(extractionLines.length === expected && extractionLines.every(line => line === dispatchVcsLine),
      `(e) ${name} has ${expected} byte-identical DISPATCH_VCS extraction lines`, JSON.stringify(extractionLines));
  }
  const dispatchVcsTitleCount = dispatchSpec.split(dispatchVcsTitle).length - 1;
  assert(dispatchVcsTitleCount === 1,
    `(e) shared/forge-dispatch.md carries the DISPATCH_VCS prelude block exactly once (got ${dispatchVcsTitleCount})`);
  assert(dispatchSpec.includes('forge-vcs.js" --detect --field vcs'),
    '(e) DISPATCH_VCS prelude block invokes forge-vcs.js --detect --field vcs');
  for (const rel of ['forge-auto/SKILL.md', 'forge-next/SKILL.md', 'forge-task/SKILL.md']) {
    const text = fs.readFileSync(path.join(path.dirname(SCRIPTS), 'skills', rel), 'utf8');
    assert(!text.includes('${DISPATCH_VCS:-git}'), `(e) ${rel} never converts none/unknown into git`);
  }
  assert(!dispatchSpec.includes('|| echo "git"'), '(e) detector failure is named unknown, never git');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeIsolationSvnAndVcsTelemetry\(\); \}/.test(mainBody),
    '(final) Section 82 is registered through a closure in main()');
  pass('(final) Section 82: SVN shared isolation, git preservation, setup/cleanup vcs, DISPATCH_VCS prelude, and nine telemetry emitters verified');
}

// ── Section 83: detector de rota inerte ───────────────────────────────────
function smokeRouteAudit() {
  process.stdout.write('\n▸ Section 83: detector de rota inerte\n');
  const dir = mkTmp('route-audit');
  try {
    const summary = path.join(dir, '.gsd', 'S03-SUMMARY.md');
    const events = path.join(dir, '.gsd', 'forge', 'events.jsonl');
    fs.writeFileSync(summary, '# Summary\n\n## Forward Intelligence\nkeep\n', 'utf8');
    fs.writeFileSync(events, [
      JSON.stringify({ event: 'dispatch', milestone: 'M127', slice: 'S03', unit: 'execute-task/T01', engine: 'codex' }),
      JSON.stringify({ event: 'worker-engine-fallback', milestone: 'M127', slice: 'S03', unit: 'execute-task/T01', reason: 'timeout', hint: 'x' }),
      JSON.stringify({ event: 'dispatch', milestone: 'M127', slice: 'S03', unit: 'execute-task/T01', engine: 'claude' }),
    ].join('\n') + '\n', 'utf8');
    const args = ['--slice', 'S03', '--milestone', 'M127', '--cwd', dir, '--json'];
    const inspect = runScript('forge-route-audit.js', args);
    assert(inspect.status === 0 && JSON.parse(inspect.stdout).units.length === 1 && !fs.readFileSync(summary, 'utf8').includes('## Route'), '(a) inspection is pure read');
    const writeArgs = [...args, '--write', summary];
    const first = runScript('forge-route-audit.js', writeArgs); const once = fs.readFileSync(summary, 'utf8');
    const second = runScript('forge-route-audit.js', writeArgs); const twice = fs.readFileSync(summary, 'utf8');
    assert(first.status === 0 && second.status === 0 && once === twice && (twice.match(/^## Route$/gm) || []).length === 1, '(b) write is idempotent with one Route section');
    assert(twice.indexOf('## Route') < twice.indexOf('## Forward Intelligence'), '(c) Route precedes Forward Intelligence');
    fs.unlinkSync(events);
    assert(runScript('forge-route-audit.js', args).status === 0, '(d) absent events exit zero');
    fs.writeFileSync(events, '{truncated\n', 'utf8');
    assert(runScript('forge-route-audit.js', args).status === 0, '(d) corrupt events exit zero');
    const outside = path.join(dir, 'outside.md'); fs.writeFileSync(outside, 'keep\n');
    const refused = runScript('forge-route-audit.js', [...args, '--write', outside]);
    assert(refused.status === 0 && fs.readFileSync(outside, 'utf8') === 'keep\n', '(f) outside .gsd is refused without write');
    const expected = [
      ['skills/forge-auto/SKILL.md', 2], ['skills/forge-next/SKILL.md', 2], ['skills/forge-task/SKILL.md', 1],
      ['shared/forge-dispatch.md', 2],
    ];
    for (const [file, count] of expected) {
      const text = sidecarSurface(path.join(path.dirname(SCRIPTS), file));  // sidecar surface (2026-08-23)
      // The hint is computed ONCE, in the fence that resolves CODE_DIR, and persisted; every emitter
      // re-reads it from that durable file, because shell state dies at the Bash-tool boundary.
      assert(text.split('"hint":%s').length - 1 === count, `(e) exact hint emitter count in ${file}`);
      assert(text.split('HINT_JSON=$(node -e').length - 1 === 1
        && text.split('printf \'%s\' "$HINT_JSON" > "$CODE_DIR_HINT_FILE"').length - 1 === 1,
        `(e) ${file} computes and persists the hint exactly once, in the CODE_DIR fence`);
      assert(text.split('HINT_JSON=$(cat "${CODE_DIR_HINT_FILE:-$WORKING_DIR/.gsd/forge/code-dir-hint.json}"').length - 1 === count,
        `(e) ${file} re-reads the persisted hint at each of its ${count} emitter(s)`);
      assert(text.split('[ -n "$HINT_JSON" ] || HINT_JSON=\'""\'').length - 1 === count + 1,
        `(e) ${file} guards every HINT_JSON against an empty substitution`);
    }
    // 2026-08-24: the completer's slice body moved verbatim to the on-demand
    // spec (agents/forge-completer.md is now a thin dispatcher) — the sub-step
    // lives in shared/forge-completer-slice.md, and the agent must still point
    // at that spec or the sub-step is unreachable.
    const completerSpec = readRepoText(path.join(path.dirname(SCRIPTS), 'shared/forge-completer-slice.md'));
    assert((completerSpec.match(/^1\.85\./gm) || []).length === 1, '(e) completer has sub-step 1.85');
    assert(readRepoText(path.join(path.dirname(SCRIPTS), 'agents/forge-completer.md')).includes('shared/forge-completer-slice.md'),
      '(e) completer agent still points at the slice spec that carries 1.85');
    const source = fs.readFileSync(__filename, 'utf8'); const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeRouteAudit\(\); \}/.test(mainBody), '(g) Section 83 is registered through a closure in main()');
    pass('(final) Section 83: detector de rota inerte, upsert, refusal, docs and registration verified');
  } finally { cleanup(dir); }
}

// ── Section 84: registry schema + migração + guarda ENOGSD ────────────────
//
// Everything here runs against a synthetic `$HOME` under mkdtemp, driven through
// the CLI's `--home`/`--file` flags. The operator's real
// `~/.claude/forge-gate-workspaces.json` is never read and never written by this
// suite: a migration is a one-way door, and a regression gate that rehearses it
// on live data is the accident it was meant to prevent.
function smokeRegistrySchemaAndEnogsd() {
  process.stdout.write('\n▸ Section 84: registry schema + migração + guarda ENOGSD\n');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-registry-'));
  try {
    // ── fixture: one synthetic home holding every pathology the live registry has
    const home = path.join(dir, 'home');
    const mkProject = p => { fs.mkdirSync(path.join(p, '.gsd', 'milestones'), { recursive: true }); return p; };
    const mkTouched = p => { fs.mkdirSync(path.join(p, '.gsd', 'forge'), { recursive: true }); return p; };
    const dev = path.join(home, 'Development');
    const agent = mkProject(path.join(dev, 'forge-agent'));
    const ws = mkProject(path.join(dev, 'lookchina'));            // unregistered → promotion
    const odin = mkProject(path.join(ws, 'apps', 'odin'));
    const services = mkTouched(path.join(ws, 'services'));         // registered but touched
    const glitnir = mkTouched(path.join(ws, 'apps', 'glitnir'));
    // A path with spaces, because the live registry has one and a path that only
    // survives when it is never shell-interpolated is the interesting case.
    const sandbox = mkProject(path.join(home, 'Library', 'Application Support', 'Forge', 'Sandbox'));
    const gone = path.join(dev, 'deleted-project');                // registered, absent from disk
    // Exists but holds nothing active — must NOT be seeded as a root.
    fs.mkdirSync(path.join(home, 'Documents'), { recursive: true });

    const legacy = [agent, odin, services, glitnir, sandbox, gone];
    const file = path.join(home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    const legacyBytes = JSON.stringify(legacy, null, 2) + '\n';
    fs.writeFileSync(file, legacyBytes, 'utf8');
    const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
    const beforeSha = sha(file);
    const beforeMtime = fs.statSync(file).mtimeMs;
    const bak = file + '.bak';
    const cli = args => runScript('forge-workspace.js', ['--home', home, '--file', file, ...args]);

    // (a) --dry-run is a preview: every input path reported, zero bytes written.
    const dry = cli(['--migrate', '--dry-run']);
    assert(dry.status === 0 && /--dry-run: nenhuma escrita realizada/.test(dry.stdout),
      '(a) --migrate --dry-run exits zero and says it wrote nothing', dry.stderr || dry.stdout);
    assert(legacy.every(p => dry.stdout.includes(p)) && new RegExp(`entradas lidas: ${legacy.length}`).test(dry.stdout),
      '(a) dry-run reports one line for every input entry, count measured not constant', dry.stdout);
    assert(sha(file) === beforeSha && fs.statSync(file).mtimeMs === beforeMtime && !fs.existsSync(bak),
      '(a) dry-run left sha256 and mtime untouched and produced no .bak');

    // (b) the real migration: backup proven byte-identical, then the new shape.
    const run = cli(['--migrate']);
    assert(run.status === 0 && fs.existsSync(bak) && sha(bak) === beforeSha,
      '(b) --migrate wrote a .bak byte-identical to the pre-migration file', run.stderr);
    const migrated = JSON.parse(fs.readFileSync(file, 'utf8'));
    assert(migrated.version === 1 && Array.isArray(migrated.roots) && Array.isArray(migrated.entries)
      && Array.isArray(migrated.quarantine), '(b) migrated file parses as the version-1 object');
    assert(migrated.roots.length === 1 && migrated.roots[0].path === '~/Development' && migrated.roots[0].primary === true,
      '(b) only the root holding active entries is seeded, and it is primary', JSON.stringify(migrated.roots));

    // (c) dispositions — read through --registry --json so the assertion covers
    //     the codec round-trip rather than the in-memory object.
    const view = cli(['--registry', '--json']);
    const reg = JSON.parse(view.stdout);
    const entryFor = abs => reg.entries.find(e => e.abs === abs);
    const quarFor = abs => reg.quarantine.find(q => q.abs === abs);
    assert(view.status === 0 && reg.version === 1 && reg.legacy !== true,
      '(c) --registry --json prints the versioned view', view.stderr);
    assert(entryFor(agent) && entryFor(agent).kind === 'project' && entryFor(odin),
      '(c) real projects stay active');
    assert(entryFor(ws) && entryFor(ws).kind === 'workspace',
      '(c) the unregistered containing project is promoted to kind workspace');
    assert(!entryFor(services) && quarFor(services) && quarFor(services).reason === 'touched',
      '(c) a touched dir leaves the active list without being discarded');
    assert(quarFor(glitnir) && quarFor(glitnir).reason === 'touched',
      '(c) every touched dir is quarantined, not deleted');
    assert(quarFor(sandbox) && quarFor(sandbox).reason === 'scratch' && quarFor(sandbox).root === null,
      '(c) the scratch dir with spaces is quarantined scratch with root null',
      JSON.stringify(quarFor(sandbox)));
    assert(quarFor(gone) && quarFor(gone).reason === 'touched',
      '(c) a path missing from disk is preserved in quarantine');

    // (d) second --migrate is an explicit no-op and does not touch the backup.
    const bakSha = sha(bak);
    const migratedMtime = fs.statSync(file).mtimeMs;
    const again = cli(['--migrate']);
    assert(again.status === 0 && /already migrated, version 1/.test(again.stdout),
      '(d) a second --migrate says already migrated', again.stdout + again.stderr);
    assert(sha(bak) === bakSha && fs.statSync(file).mtimeMs === migratedMtime,
      '(d) the no-op rewrote neither the registry nor the .bak');

    // (e) portability: the stored paths are root-relative, so the same bytes
    //     resolve under a different $HOME. This is what makes the file movable
    //     between machines instead of pinned to one operator's username.
    const home2 = path.join(dir, 'home2');
    fs.mkdirSync(path.join(home2, '.claude'), { recursive: true });
    for (const p of [agent, odin, ws]) mkProject(p.replace(home, home2));
    const file2 = path.join(home2, '.claude', 'forge-gate-workspaces.json');
    fs.copyFileSync(file, file2);
    const view2 = JSON.parse(runScript('forge-workspace.js', ['--home', home2, '--file', file2, '--registry', '--json']).stdout);
    assert(view2.entries.length === reg.entries.length
      && view2.entries.every(e => e.abs.startsWith(home2 + path.sep))
      && view2.entries.some(e => e.abs === agent.replace(home, home2)),
      '(e) a registry written under one $HOME resolves under another');

    // (f) the fourth `.gsd/` manufacturer stays closed: add() refuses rather
    //     than enrolling a clean repo by writing the very marker the app reads.
    const clean = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-enogsd-'));
    try {
      delete require.cache[require.resolve(path.join(SCRIPTS, 'forge-runs.js'))];
      const runs = require(path.join(SCRIPTS, 'forge-runs.js'));
      let code = null;
      try { runs.add(clean, { id: 'M001', kind: 'milestone', session_id: 's1' }); } catch (e) { code = e.code; }
      assert(code === 'ENOGSD' && !fs.existsSync(path.join(clean, '.gsd')),
        '(f) forge-runs.add() throws ENOGSD in a clean dir and manufactures no .gsd/',
        `code=${code} gsd=${fs.existsSync(path.join(clean, '.gsd'))}`);
    } finally { cleanup(clean); }

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeRegistrySchemaAndEnogsd\(\); \}/.test(mainBody),
      '(g) Section 84 is registered through a closure in main()');
    pass('(final) Section 84: registry schema, dry-run zero-write, migração + .bak, no-op, portabilidade e ENOGSD verificados');
  } finally { cleanup(dir); }
}

// ── Section 85: hierarquia derivada — role, containment transitivo e pastas
//    sintetizadas ───────────────────────────────────────────────────────────
//
// Like Section 84, every fixture here lives under a synthetic `$HOME` in
// mkdtemp, and the registry it drives is written through the codec
// (`writeRegistry` + `encodeEntryPath`), never by hand. The operator's real
// `~/.claude/forge-gate-workspaces.json` is never read here.
function smokeHierarchyDerived() {
  process.stdout.write(
    '\n▸ Section 85: hierarquia derivada — role, containment transitivo e pastas sintetizadas\n');
  const workspace = require(path.join(SCRIPTS, 'forge-workspace.js'));
  const { containmentCounts, resolveRole, normalizeRegistry, encodeEntryPath, writeRegistry } = workspace;

  // (a) containmentCounts is transitive and separator-guarded: a grandparent
  //     counts a grandchild, and a sibling with the same prefix does not fool
  //     the separator check.
  const grand = '/a/Dev';
  const parent = '/a/Dev/mid';
  const child = '/a/Dev/mid/leaf';
  const sibling = '/a/Development'; // shares the "/a/Dev" prefix but is not under it
  const counts = containmentCounts([grand, parent, child, sibling]);
  assert(counts[grand] === 2, '(a) the grandparent counts both the mid child and the deep grandchild', JSON.stringify(counts));
  assert(counts[parent] === 1, '(a) the parent counts only its direct child', JSON.stringify(counts));
  assert(counts[child] === 0, '(a) the leaf has no descendants', JSON.stringify(counts));
  assert(counts[sibling] === 0,
    '(a) "/a/Dev" does not contain "/a/Development" — prefix match without a separator boundary must not count',
    JSON.stringify(counts));

  // (b) resolveRole across the four cases, with classifyFn injected so no disk
  //     is touched: workspace, project, folder (including the touched-below
  //     case), null.
  const rootPath = '/home/dev/lookchina';
  const memberPath = '/home/dev/lookchina/apps/odin';
  const touchedPath = '/home/dev/lookchina/services'; // registered as touched, not itself active
  const foldersOnly = '/home/dev/lookchina/apps'; // never a project, sits above an active member
  const unrelated = '/home/dev/elsewhere';
  const classifyFn = p => ({
    kind: (p === rootPath || p === memberPath) ? 'project' : 'none',
    signals: [],
  });
  const activesForRole = [rootPath, memberPath]; // touchedPath is deliberately NOT active — it is a quarantined dir, not a registry entry
  assert(resolveRole(rootPath, activesForRole, classifyFn) === 'workspace',
    '(b) a project that strictly contains another active path is role workspace');
  assert(resolveRole(memberPath, activesForRole, classifyFn) === 'project',
    '(b) a project with no active descendant is role project');
  assert(resolveRole(foldersOnly, activesForRole, classifyFn) === 'folder',
    '(b) a non-project ancestor of an active path is role folder (synthesised display node)');
  assert(resolveRole(touchedPath, activesForRole, classifyFn) === null,
    '(b) a touched (quarantined, non-active) dir with no active descendant of its own resolves to null role — quarantine is not membership');
  assert(resolveRole(unrelated, activesForRole, classifyFn) === null,
    '(b) a path unrelated to any active entry has no role');

  // (c) the CLI reports `role` end to end: a synthetic $HOME, a registry
  //     written through the codec (never hand-rolled JSON) describing a
  //     workspace root with a member under apps/, then --home/--file/--json.
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-hierarchy-'));
  try {
    const home = path.join(dir, 'home');
    const dev = path.join(home, 'Development');
    const ws = path.join(dev, 'lookchina');
    const apps = path.join(ws, 'apps');
    const odin = path.join(apps, 'odin');
    fs.mkdirSync(path.join(ws, '.gsd', 'milestones'), { recursive: true });
    fs.mkdirSync(path.join(odin, '.gsd', 'milestones'), { recursive: true });

    const roots = [{ path: '~/Development', primary: true }];
    const wsEnc = encodeEntryPath(ws, roots, home);
    const odinEnc = encodeEntryPath(odin, roots, home);
    const registry = {
      version: 1,
      roots,
      entries: [
        { path: wsEnc.path, root: wsEnc.root, kind: 'workspace', repos: [] },
        { path: odinEnc.path, root: odinEnc.root, kind: 'project', repos: [] },
      ],
      quarantine: [],
    };
    const file = path.join(home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    writeRegistry(file, registry);

    const cli = target => runScript('forge-workspace.js', ['--home', home, '--file', file, target, '--json']);
    const rootView = JSON.parse(cli(ws).stdout);
    assert(rootView.role === 'workspace', '(c) the CLI reports role "workspace" for the registered root', JSON.stringify(rootView));
    const appsView = JSON.parse(cli(apps).stdout);
    assert(appsView.role === 'folder',
      '(c) the CLI reports role "folder" for a non-project ancestor of an active member (apps/)', JSON.stringify(appsView));
  } finally { cleanup(dir); }

  // (d) `folder` is never accepted as a stored entry `kind` — the loader
  //     coerces anything it does not recognise to null and lets the kind be
  //     recomputed, because a folder is a synthesised display node, not
  //     something the registry can register.
  const rawFolderKind = {
    version: 1,
    roots: [],
    entries: [{ path: '~/Development/lookchina/apps', root: null, kind: 'folder', repos: [] }],
    quarantine: [],
  };
  const normalized = normalizeRegistry(rawFolderKind, { home: '/home/dev' });
  assert(normalized.entries[0].kind === null,
    '(d) a stored entry with kind "folder" is coerced to null on load — folder is never a registry entry kind, ' +
    'it is derived at read time from the active set; if this assertion becomes hard to write, T02 loosened the refusal — report it, do not weaken the check',
    JSON.stringify(normalized.entries[0]));

  // (e) the ownership table covers the ambiguous lookchina cases: scripts,
  //     libs, infra, and the .gsd-without-substance case (services).
  const ownershipDoc = fs.readFileSync(path.join(SCRIPTS, '..', 'shared', 'forge-ownership.md'), 'utf8');
  assert(/WS\/scripts/.test(ownershipDoc),
    '(e) shared/forge-ownership.md must document the WS/scripts ambiguous case — CONTEXT D1 requires explicit coverage of lookchina\'s ambiguous directories',
    ownershipDoc.length + ' bytes read');
  assert(/WS\/libs/.test(ownershipDoc),
    '(e) shared/forge-ownership.md must document the WS/libs ambiguous case — CONTEXT D1 requires explicit coverage of lookchina\'s ambiguous directories');
  assert(/WS\/infra/.test(ownershipDoc),
    '(e) shared/forge-ownership.md must document the WS/infra ambiguous case — CONTEXT D1 requires explicit coverage of lookchina\'s ambiguous directories');
  assert(/WS\/services/.test(ownershipDoc) && /touched/.test(ownershipDoc),
    '(e) shared/forge-ownership.md must document the .gsd/-without-substance case (WS/services, touched not project) — CONTEXT D1 requires it',
    ownershipDoc.length + ' bytes read');

  // (f) live wiring: Projects.swift references ProjectTree and no longer
  //     references ProjectOrganiser.groups. Duplicates T04's parity pin on
  //     purpose — this is the net that runs in CI even when the parity suite
  //     does not.
  const projectsSwiftPath = path.join(SCRIPTS, '..', 'app', 'Sources', 'Forge', 'Projects.swift');
  const projectsSwift = fs.readFileSync(projectsSwiftPath, 'utf8');
  assert(/ProjectTree\b/.test(projectsSwift),
    '(f) Projects.swift must reference ProjectTree — the app is wired to the new hierarchy view');
  assert(!/ProjectOrganiser\.groups\b/.test(projectsSwift),
    '(f) Projects.swift must no longer reference ProjectOrganiser.groups — that is the pre-hierarchy grouping this milestone replaces');

  // (g) registration in main() through a closure, same structural check as
  //     Sections 83/84.
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeHierarchyDerived\(\); \}/.test(mainBody),
    '(g) Section 85 is registered through a closure in main()');

  pass('(final) Section 85: role transitivo, containment, recusa de folder como kind de entry, ' +
    'cobertura da tabela de posse e fiação viva verificados');
}

// ── Section 86: multi-repo sob workspace — sync, resolução cwd-invariante,
//    fallback de marcador, precedência do registry, divergência advisory e o
//    pino do caso TASK-021 ─────────────────────────────────────────────────
//
// Like Sections 84/85, every fixture lives under a synthetic `$HOME` in
// mkdtemp/os.tmpdir(), driven through the CLIs' `--home`/`--file` flags. The
// operator's real `~/.claude/forge-gate-workspaces.json` is never read and
// never written here.
function smokeMultiRepoResolution() {
  process.stdout.write(
    '\n▸ Section 86: multi-repo sob workspace — sync, resolução, marcador, divergência\n');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-multirepo-'));
  try {
    const workspace = require(path.join(SCRIPTS, 'forge-workspace.js'));
    const { encodeEntryPath, writeRegistry } = workspace;

    const home = path.join(dir, 'home');
    const dev = path.join(home, 'Development');
    const ws = path.join(dev, 'WS');
    const web = path.join(ws, 'web');                 // 1 level — what discoverRepos alone can see
    const appsA = path.join(ws, 'apps', 'a');          // 2 levels
    const freyr = path.join(ws, 'services', 'freyr');  // 2 levels — the TASK-021 payoff repo
    const decoy = path.join(ws, 'node_modules', 'x');  // must never be discovered
    for (const d of [web, appsA, freyr, decoy]) fs.mkdirSync(path.join(d, '.git'), { recursive: true });
    // `kind` is recomputed from disk on load (`deriveEntryKind`), never trusted
    // from the stored value — a registered dir is `workspace` only when it is
    // itself a `.gsd/` project AND strictly contains another active entry
    // (Section 85 established this). Both facts must be real on disk here, or
    // `--sync-repos` would silently skip WS as a plain `project` (measured: it
    // did, the first time this fixture was written without them).
    fs.mkdirSync(path.join(ws, '.gsd', 'milestones'), { recursive: true });
    fs.mkdirSync(path.join(appsA, '.gsd', 'milestones'), { recursive: true });

    const roots = [{ path: '~/Development', primary: true }];
    const wsEnc = encodeEntryPath(ws, roots, home);
    const appsAEnc = encodeEntryPath(appsA, roots, home);
    const registry = {
      version: 1,
      roots,
      entries: [
        { path: wsEnc.path, root: wsEnc.root, kind: 'workspace', repos: [] },
        { path: appsAEnc.path, root: appsAEnc.root, kind: 'project', repos: [] },
      ],
      quarantine: [],
    };
    const file = path.join(home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    writeRegistry(file, registry);

    const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
    const beforeSha = sha(file);
    const beforeMtime = fs.statSync(file).mtimeMs;
    const cli = args => runScript('forge-workspace.js', ['--home', home, '--file', file, ...args]);

    // (a) --sync-repos --dry-run is a preview: nothing written, and the
    //     discovered repos are reported, node_modules decoy excluded.
    const dry = cli(['--sync-repos', '--dry-run']);
    assert(dry.status === 0, '(a) --sync-repos --dry-run exits 0', dry.stdout + dry.stderr);
    assert(sha(file) === beforeSha && fs.statSync(file).mtimeMs === beforeMtime,
      '(a) --sync-repos --dry-run leaves the registry byte-identical, mtime untouched');
    assert(/services\/freyr/.test(dry.stdout) && /apps\/a/.test(dry.stdout) && /\bweb\b/.test(dry.stdout),
      '(a) dry-run preview lists every discovered repo, one and two levels deep', dry.stdout);
    assert(!/node_modules/.test(dry.stdout), '(a) the node_modules decoy never appears in the preview', dry.stdout);

    // (a2) the real --sync-repos populates repos[] on the workspace entry.
    const sync = cli(['--sync-repos']);
    assert(sync.status === 0, '(a2) --sync-repos exits 0', sync.stderr);
    const view = JSON.parse(cli(['--registry', '--json']).stdout);
    const wsEntry = view.entries.find(e => e.abs === ws);
    assert(wsEntry && Array.isArray(wsEntry.repos)
      && wsEntry.repos.includes('services/freyr') && wsEntry.repos.includes('apps/a') && wsEntry.repos.includes('web'),
      '(a2) after sync the workspace entry carries repos[] with all three real repos', JSON.stringify(wsEntry));
    assert(!wsEntry.repos.some(r => r.includes('node_modules')),
      '(a2) the node_modules decoy never enters repos[]', JSON.stringify(wsEntry));

    // (b) --resolve freyr returns the SAME absolute path from four distinct
    //     cwds — the workspace root, a member directory, a worktree OUTSIDE
    //     the workspace tree entirely, and an unrelated directory. Cwd is a
    //     tiebreaker only; a unique registry match never depends on it.
    const runRoot = path.join(dir, 'run-root', '.forge-worktrees', 'RUN');
    const webWt = path.join(runRoot, 'web');
    const freyrWt = path.join(runRoot, 'freyr-checkout');
    fs.mkdirSync(webWt, { recursive: true });
    fs.mkdirSync(freyrWt, { recursive: true });
    const cwds = [ws, appsA, freyrWt, dir];
    const resolved = cwds.map(cwd => {
      const r = runScript('forge-repo-index.js',
        ['--resolve', 'freyr', '--home', home, '--file', file, '--cwd', cwd, '--json']);
      let json = {}; try { json = JSON.parse(r.stdout); } catch { json = {}; }
      return { cwd, status: r.status, json };
    });
    assert(resolved.every(r => r.status === 0 && r.json.status === 'ok' && r.json.path === freyr),
      '(b) --resolve freyr yields the identical absolute path from all four cwds, including a worktree outside WS',
      JSON.stringify(resolved.map(r => ({ cwd: r.cwd, status: r.status, path: r.json.path }))));

    // (c)/(d) marker precedence (D3): write a marker for WS, then disagree
    //     with it on purpose. Registry present → registry wins, always.
    //     Registry absent/unreadable → marker is the only door.
    const marker = require(path.join(SCRIPTS, 'forge-marker.js'));
    const derived = marker.deriveMarkerFromRegistry(home, ws);
    marker.writeMarker(ws, derived);
    const markerFile = path.join(ws, marker.MARKER_FILENAMES[0]);
    const markerData = JSON.parse(fs.readFileSync(markerFile, 'utf8'));
    let sawFreyr = false;
    for (const r of markerData.repos) {
      if (r.name === 'freyr') { r.path = 'services/freyr-DISAGREES'; sawFreyr = true; }
    }
    assert(sawFreyr, '(c) the derived marker actually carries a freyr entry to disagree with', JSON.stringify(markerData));
    fs.writeFileSync(markerFile, JSON.stringify(markerData, null, 2) + '\n', 'utf8');

    delete require.cache[require.resolve(path.join(SCRIPTS, 'forge-repo-index.js'))];
    const repoIndex = require(path.join(SCRIPTS, 'forge-repo-index.js'));

    const idxWithRegistry = repoIndex.buildRepoIndex({ home, registryFile: file, cwd: ws });
    const resWithRegistry = repoIndex.resolveRepoName('freyr', { index: idxWithRegistry, cwd: ws });
    assert(resWithRegistry.status === 'ok' && resWithRegistry.source === 'registry' && resWithRegistry.path === freyr,
      '(c) registry present + a deliberately disagreeing marker → the registry still wins', JSON.stringify(resWithRegistry));

    const registryBytes = fs.readFileSync(file);
    fs.unlinkSync(file);
    const idxNoRegistry = repoIndex.buildRepoIndex({ home, registryFile: file, cwd: ws });
    const resNoRegistry = repoIndex.resolveRepoName('freyr', { index: idxNoRegistry, cwd: ws });
    assert(resNoRegistry.status === 'ok' && resNoRegistry.source === 'marker',
      '(d) registry absent → resolution falls back to the on-disk marker (the only door)', JSON.stringify(resNoRegistry));
    fs.writeFileSync(file, registryBytes);

    // (e) forge-workspace-consistency --check reports the divergence and
    //     ALWAYS exits 0 — advisory, never blocking.
    const consistency = runScript('forge-workspace-consistency.js', ['--check', '--home', home, '--file', file, '--json']);
    assert(consistency.status === 0, '(e) forge-workspace-consistency --check exits 0 unconditionally', consistency.stderr);
    const consistencyJson = JSON.parse(consistency.stdout);
    const wsResult = (consistencyJson.workspaces || []).find(w => w.workspace === ws);
    assert(wsResult && wsResult.status === 'divergent' && wsResult.diffs.some(d => d.name === 'freyr'),
      '(e) the guard names the freyr divergence between registry and marker', JSON.stringify(wsResult));

    // (f) forge-doctor --check workspace-consistency surfaces the same
    //     divergence, still exit 0 (D3). checkWorkspaceConsistency reads
    //     HOME from the environment, not a --home flag, so HOME is injected.
    const doctor = runScript('forge-doctor.js', ['--check', 'workspace-consistency', '--cwd', ws],
      { env: Object.assign({}, process.env, { HOME: home }) });
    assert(doctor.status === 0, '(f) forge-doctor --check workspace-consistency exits 0 (advisory, D3)',
      doctor.stdout + doctor.stderr);
    assert(/divergente/i.test(doctor.stdout), '(f) forge-doctor surfaces the divergence in its human output', doctor.stdout);

    // (g) the TASK-021 pin — end to end through the CLI, with our own
    //     workspace fixture. The isolation has TWO repos one level deep
    //     (`web`, `apps/a` — exactly what pre-S05 `discoverRepos` could see;
    //     TWO, never one, or `resolveCodeDir`'s D6 single-repo short-circuit
    //     would answer without ever consulting `repo:` at all — see Section
    //     63's own (d)); `freyr` was never isolated. `repo: freyr` ADDRESSES
    //     via the index (declared_repo_path is the exact absolute path) even
    //     though it stays refused (unisolated, same reason, same exit 5) —
    //     T05's documented scope: addressing succeeded, scoping did not.
    //     Without the index the identical fixture reproduces the pre-S05
    //     `unknown`.
    const appsAWt = path.join(runRoot, 'apps-a');
    fs.mkdirSync(appsAWt, { recursive: true });
    const isoResult = JSON.stringify({
      mode: 'worktree',
      repos: [
        { path: web, worktree: webWt, status: 'ok' },
        { path: appsA, worktree: appsAWt, status: 'ok' },
      ],
    });
    const pinPlan = path.join(dir, 'T-pin-PLAN.md');
    fs.writeFileSync(pinPlan, ['---', 'id: T01', 'repo: freyr', 'writes:', '  - "src/a.ts"', '---', '', '# plano', ''].join('\n'));

    const withIndex = runScript('forge-code-dir.js', [
      '--resolve', '--iso-result', isoResult, '--plan', pinPlan,
      '--cwd', freyrWt, '--home', home, '--registry-file', file, '--run', 'RUN',
    ]);
    let withIndexJson = {}; try { withIndexJson = JSON.parse(withIndex.stdout); } catch { withIndexJson = {}; }
    assert(withIndex.status === 5 && withIndexJson.status === 'undeclared'
      && withIndexJson.declared_repo_status === 'unisolated' && withIndexJson.declared_repo_path === freyr,
      '(g) with the index, repo: freyr ADDRESSES to the exact path (unisolated, not unknown) even with no worktree for it',
      JSON.stringify(withIndexJson));
    assert(typeof withIndexJson.hint === 'string' && withIndexJson.hint.includes(freyr),
      '(g) the refusal hint names the resolved absolute path', withIndexJson.hint);

    const withoutIndex = runScript('forge-code-dir.js', [
      '--resolve', '--no-repo-index', '--iso-result', isoResult, '--plan', pinPlan,
      '--cwd', freyrWt, '--home', home, '--registry-file', file, '--run', 'RUN',
    ]);
    let withoutIndexJson = {}; try { withoutIndexJson = JSON.parse(withoutIndex.stdout); } catch { withoutIndexJson = {}; }
    assert(withoutIndex.status === 5 && withoutIndexJson.declared_repo_status === 'unknown'
      && withoutIndexJson.declared_repo_path === '',
      '(g) --no-repo-index on the identical fixture reproduces the pre-S05 unknown verdict',
      JSON.stringify(withoutIndexJson));

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeMultiRepoResolution\(\); \}/.test(mainBody),
      '(h) Section 86 is registered through a closure in main()');
    pass('(final) Section 86: repos[] sync, resolução cwd-invariante, precedência de marcador, ' +
      'divergência advisory (workspace-consistency + doctor) e o pino do caso TASK-021 verificados');
  } finally { cleanup(dir); }
}

// ── Section 87: duas runs, mesmo projeto, branches diferentes — visíveis,
//    endereçáveis e não-corrompentes ──────────────────────────────────────────
//
// The pre-S06 failure mode this exists to make visible: two runs on the same
// project in different branches had BYTE-IDENTICAL `cwd` and no field that
// separated them. They were two filenames, not two addresses. The sabotage step
// (e) reproduces exactly that state — `branch` stripped from both records — and
// the assertion that distinguishes them is watched going RED before it is
// trusted green. A green never observed failing proves nothing about what it
// detects; this milestone has paid for that lesson three times.
//
// Integrity is proven by HASH, never by inspection: each run's artifact is
// hashed, the OTHER run writes, and the first is re-hashed for byte-identity.
//
// Like Sections 84/85/86, every path lives under a synthetic `$HOME` in
// mkdtemp/os.tmpdir(). The registry every spawned CLI here can see is the
// fixture's own copy inside that synthetic home — the no-write property is
// measured on THAT copy at (h), with a positive control. A previous version
// watched the operator's live `~/.claude/forge-gate-workspaces.json` by mtime
// instead; that cannot prove the property, because the live file is
// legitimately written by the app and by any concurrent forge session, so the
// assert only held on an idle machine (same pathology as
// forge-touch.test.js R5 / forge-resources-census R13, fixed in 0810c59).
function smokeConcurrentRunAddresses() {
  process.stdout.write(
    '\n▸ Section 87: duas runs, mesmo projeto, branches diferentes — visíveis e não-corrompentes\n');
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-concurrent-runs-'));
  try {
    const workspace = require(path.join(SCRIPTS, 'forge-workspace.js'));
    const { encodeEntryPath, writeRegistry } = workspace;

    const home = path.join(dir, 'home');
    const dev  = path.join(home, 'Development');
    const ws   = path.join(dev, 'WS');            // the ONE project both runs share
    const web  = path.join(ws, 'web');
    const api  = path.join(ws, 'services', 'api');
    const memb = path.join(ws, 'apps', 'a');      // registered member — makes WS a `workspace`
    for (const d of [web, api, memb]) fs.mkdirSync(path.join(d, '.git'), { recursive: true });
    fs.mkdirSync(path.join(ws, '.gsd', 'milestones'), { recursive: true });
    fs.mkdirSync(path.join(memb, '.gsd', 'milestones'), { recursive: true });

    const roots = [{ path: '~/Development', primary: true }];
    const wsEnc = encodeEntryPath(ws, roots, home);
    const mbEnc = encodeEntryPath(memb, roots, home);
    const file = path.join(home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(file), { recursive: true });
    writeRegistry(file, {
      version: 1,
      roots,
      entries: [
        { path: wsEnc.path, root: wsEnc.root, kind: 'workspace', repos: [] },
        { path: mbEnc.path, root: mbEnc.root, kind: 'project',   repos: [] },
      ],
      quarantine: [],
    });
    runScript('forge-workspace.js', ['--home', home, '--file', file, '--sync-repos']);

    // (h, opening half) After setup, no operation below may write the registry.
    // The stamp is taken on the fixture's copy — the only registry any spawned
    // process can reach, because every spawn below runs with HOME/USERPROFILE
    // pointed at the synthetic home.
    const registryStamp = () => `${fs.statSync(file).mtimeMs}:${fs.statSync(file).size}:`
      + crypto.createHash('sha256').update(fs.readFileSync(file)).digest('hex');
    const registryAfterSetup = registryStamp();

    const env = Object.assign({}, process.env, { HOME: home, USERPROFILE: home });
    const runsCli = args => runScript('forge-runs.js', ['--cwd', ws, ...args], { env });
    const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
    const runFile = id => path.join(ws, '.gsd', 'forge', 'runs', `${id}.json`);

    // (a) TWO runs, SAME project (`--cwd` byte-identical by construction), two
    //     different branches. Nothing but `--branch` separates them.
    const addA = runsCli(['--add', '--id', 'M-a', '--kind', 'milestone', '--session', 'sess-a',
      '--isolation-mode', 'branch', '--branch', 'forge/M-a']);
    const addB = runsCli(['--add', '--id', 'M-b', '--kind', 'milestone', '--session', 'sess-b',
      '--isolation-mode', 'branch', '--branch', 'forge/M-b']);
    assert(addA.status === 0 && addB.status === 0, '(a) both runs register on the same project',
      addA.stderr + addB.stderr);
    const recA0 = JSON.parse(addA.stdout);
    const recB0 = JSON.parse(addB.stdout);
    assert(recA0.cwd === recB0.cwd,
      '(a) the two runs really do share a byte-identical cwd — the pre-S06 collision is reproduced, not avoided',
      `${recA0.cwd} vs ${recB0.cwd}`);
    assert(recA0.branch === 'forge/M-a' && recB0.branch === 'forge/M-b',
      '(a) --branch is recorded verbatim on each record', JSON.stringify([recA0.branch, recB0.branch]));

    // started_at pinned so "oldest active" is a fact of the fixture and not of
    // millisecond luck between two spawns.
    runsCli(['--update', 'M-a', '--json', JSON.stringify({ started_at: 1000 })]);
    runsCli(['--update', 'M-b', '--json', JSON.stringify({ started_at: 2000 })]);

    // (b) VISIBILITY: both appear in --list-active, each reporting its own branch.
    const listed = JSON.parse(runsCli(['--list-active', '--json']).stdout);
    const ids = listed.map(r => r.id).sort();
    assert(ids.length === 2 && ids[0] === 'M-a' && ids[1] === 'M-b',
      '(b) --list-active shows BOTH runs', JSON.stringify(ids));
    assert(listed.find(r => r.id === 'M-a').branch === 'forge/M-a'
        && listed.find(r => r.id === 'M-b').branch === 'forge/M-b',
      '(b) each listed run reports its OWN branch', JSON.stringify(listed.map(r => [r.id, r.branch])));

    // (c) DISTINCT ADDRESSES: same root/project/repos chain (it IS the same
    //     project), different `run.branch`. That difference is the whole reason
    //     two runs sharing a cwd are separately addressable.
    const address = (id, fromCwd) => {
      const r = runScript('forge-run-address.js',
        ['--address', id, '--json', '--cwd', fromCwd || ws], { env });
      let json = null; try { json = JSON.parse(r.stdout); } catch { json = null; }
      return { status: r.status, json, stderr: r.stderr };
    };
    // The predicate under test, named once and reused verbatim by the RED proof
    // at (e). If the sabotage ran a DIFFERENT expression than the green run, the
    // red would prove nothing about this assertion.
    const branchesDistinguish = () => {
      const a = address('M-a').json;
      const b = address('M-b').json;
      if (!a || !b) return false;
      return !!a.run.branch && !!b.run.branch && a.run.branch !== b.run.branch;
    };
    const chainOf = addr => JSON.stringify({ root: addr.root, project: addr.project, repos: addr.repos });

    const aAddr = address('M-a');
    const bAddr = address('M-b');
    assert(aAddr.status === 0 && bAddr.status === 0, '(c) both runs resolve an address',
      aAddr.stderr + bAddr.stderr);
    assert(chainOf(aAddr.json) === chainOf(bAddr.json),
      '(c) root → project → repos is byte-identical for both runs — same project, as it must be',
      chainOf(aAddr.json) + '\n' + chainOf(bAddr.json));
    assert(aAddr.json.repos.length >= 2 && aAddr.json.repos.some(r => r.name === 'api'),
      '(c) the shared chain actually reaches the repo leg (not vacuously equal at [])',
      JSON.stringify(aAddr.json.repos));
    assert(aAddr.json.run.branch === 'forge/M-a' && bAddr.json.run.branch === 'forge/M-b',
      '(c) each address reports its own branch — the one field that separates them',
      JSON.stringify([aAddr.json.run.branch, bAddr.json.run.branch]));
    assert(branchesDistinguish(), '(c) the distinguishing predicate is GREEN before sabotage');
    // …and from a cwd outside the tree entirely, the same two answers.
    const outside = path.join(dir, 'elsewhere');
    fs.mkdirSync(outside, { recursive: true });
    const aOut = address('M-a', outside);
    delete aAddr.json.resolved_from; delete (aOut.json || {}).resolved_from;
    assert(aOut.status === 0 && JSON.stringify(aOut.json) === JSON.stringify(aAddr.json),
      '(c) resolving from outside the tree yields a byte-identical address (resolved_from excluded)',
      JSON.stringify(aOut.json));

    // (d) NON-CORRUPTION BY HASH. One artifact per run under its own
    //     milestone_dir; B writes, A is re-hashed for byte-identity; then the
    //     inverse. Hash, not inspection.
    const artifact = id => path.join(ws, '.gsd', 'milestones', id, `${id}-STATE.md`);
    for (const id of ['M-a', 'M-b']) {
      fs.mkdirSync(path.dirname(artifact(id)), { recursive: true });
      fs.writeFileSync(artifact(id), `# ${id}\nphase: execute\n`, 'utf8');
    }
    const artA0 = sha(artifact('M-a'));
    const artB0 = sha(artifact('M-b'));
    const runA0 = sha(runFile('M-a'));
    const runB0 = sha(runFile('M-b'));

    fs.writeFileSync(artifact('M-b'), `# M-b\nphase: complete\nmutated\n`, 'utf8');
    runsCli(['--update', 'M-b', '--json', JSON.stringify({ worker: 'execute-task/T09' })]);
    assert(sha(artifact('M-a')) === artA0,
      "(d) run B writing its artifact leaves run A's artifact byte-identical");
    assert(sha(runFile('M-a')) === runA0,
      "(d) run B's registry write leaves run A's record file byte-identical");

    const artB1 = sha(artifact('M-b'));
    fs.writeFileSync(artifact('M-a'), `# M-a\nphase: review\nmutated\n`, 'utf8');
    runsCli(['--update', 'M-a', '--json', JSON.stringify({ worker: 'execute-task/T01' })]);
    assert(sha(artifact('M-b')) === artB1 && sha(artifact('M-b')) !== artB0,
      "(d) the inverse holds: A writing leaves B's (already mutated) artifact byte-identical");

    // (d2) The per-run-file invariant asserted rather than assumed
    //      (shared/forge-state.md §2: no lockfile for runs/*.json because each
    //      file is per-run). Interleaved updates lose no field from either.
    const finalA = JSON.parse(fs.readFileSync(runFile('M-a'), 'utf8'));
    const finalB = JSON.parse(fs.readFileSync(runFile('M-b'), 'utf8'));
    const keysA = Object.keys(recA0).every(k => k in finalA);
    const keysB = Object.keys(recB0).every(k => k in finalB);
    assert(keysA && keysB && finalA.branch === 'forge/M-a' && finalB.branch === 'forge/M-b'
        && finalA.worker === 'execute-task/T01' && finalB.worker === 'execute-task/T09',
      '(d2) interleaved writes preserve every field of BOTH records — per-run files, no shared mutable path',
      JSON.stringify([finalA, finalB]));
    const runsDirFiles = fs.readdirSync(path.join(ws, '.gsd', 'forge', 'runs')).sort();
    assert(runsDirFiles.length === 2 && runsDirFiles.join(',') === 'M-a.json,M-b.json',
      '(d2) the registry is two per-run files — there is no single shared runs file to corrupt',
      runsDirFiles.join(','));
    assert(sha(runFile('M-b')) !== runB0,
      "(d2) B's file really did change under its own write — the identity asserts above are not testing a frozen disk");

    // (e) RED PROOF. Strip `branch` from BOTH records — the exact pre-S06 shape
    //     — and watch the (c) predicate go red. Restore from the saved bytes and
    //     watch it green again, with the file hashes proving the restore was
    //     byte-identical and not merely equivalent.
    const bytesA = fs.readFileSync(runFile('M-a'));
    const bytesB = fs.readFileSync(runFile('M-b'));
    const shaBeforeSabotage = [sha(runFile('M-a')), sha(runFile('M-b'))];
    for (const id of ['M-a', 'M-b']) {
      const rec = JSON.parse(fs.readFileSync(runFile(id), 'utf8'));
      delete rec.branch;
      fs.writeFileSync(runFile(id), JSON.stringify(rec, null, 2) + '\n', 'utf8');
    }
    const sabotaged = branchesDistinguish();
    assert(sabotaged === false,
      '(e) RED PROOF: with branch stripped from both records the distinguishing predicate FAILS — observed red, not assumed',
      `predicate returned ${sabotaged}`);
    const aSab = address('M-a').json;
    const bSab = address('M-b').json;
    const strippedIdentity = addr => {
      const copy = JSON.parse(JSON.stringify(addr));
      copy.run.id = '<id>'; delete copy.resolved_from;
      return JSON.stringify(copy);
    };
    assert(strippedIdentity(aSab) === strippedIdentity(bSab),
      '(e) sabotaged, the two addresses are indistinguishable apart from the filename-derived id — exactly the pre-S06 defect',
      strippedIdentity(aSab) + '\n' + strippedIdentity(bSab));
    assert(aSab.run.branch === null && bSab.run.branch === null,
      '(e) a record with no branch key reads back as null, never undefined (S06/T03 defaulting)',
      JSON.stringify([aSab.run.branch, bSab.run.branch]));
    fs.writeFileSync(runFile('M-a'), bytesA);
    fs.writeFileSync(runFile('M-b'), bytesB);
    assert(sha(runFile('M-a')) === shaBeforeSabotage[0] && sha(runFile('M-b')) === shaBeforeSabotage[1],
      '(e) the restore is byte-identical, proven by hash');
    assert(branchesDistinguish() === true,
      '(e) restored, the same predicate is GREEN again — the assertion has now been seen both ways');

    // (f) MIRROR, NEVER TRUTH (shared/forge-state.md §5). With two active runs
    //     auto-mode.json reflects exactly ONE of them — the oldest by
    //     started_at — and carries no run id at all. Whoever reads it as the
    //     source of truth loses a run; the point is asserted, not narrated.
    const refresh = runsCli(['--refresh-legacy-alias']);
    assert(refresh.status === 0, '(f) --refresh-legacy-alias exits 0', refresh.stderr);
    const alias = JSON.parse(fs.readFileSync(path.join(ws, '.gsd', 'forge', 'auto-mode.json'), 'utf8'));
    assert(alias.active === true && alias.started_at === 1000,
      '(f) auto-mode.json mirrors exactly ONE run — the oldest active by started_at', JSON.stringify(alias));
    assert(!('id' in alias) && !('run_id' in alias) && !('branch' in alias),
      '(f) the mirror carries no id and no branch — run M-b is not merely unlisted there, it is UNNAMEABLE from it',
      JSON.stringify(alias));
    const stillActive = JSON.parse(runsCli(['--list-active', '--json']).stdout).map(r => r.id).sort();
    const bStill = address('M-b');
    assert(stillActive.join(',') === 'M-a,M-b' && bStill.status === 0
        && bStill.json.run.branch === 'forge/M-b',
      '(f) the non-mirrored run stays fully visible AND fully addressable — the mirror is a projection, not the registry',
      JSON.stringify({ stillActive, b: bStill.json && bStill.json.run }));

    // (g) The shared write path that DOES exist — the dashboard's single
    //     `.gsd/STATE.md`, written under lock — represents both runs rather
    //     than clobbering one. (Step 4 of the plan: assert the invariant,
    //     don't assume it.)
    const dash = runScript('forge-dashboard.js', ['--cwd', ws, '--holder', 'smoke:87'], { env });
    const stateMd = path.join(ws, '.gsd', 'STATE.md');
    const stateTxt = fs.existsSync(stateMd) ? fs.readFileSync(stateMd, 'utf8') : '';
    assert(dash.status === 0 && /M-a/.test(stateTxt) && /M-b/.test(stateTxt),
      '(g) the one shared artifact (.gsd/STATE.md, under lock) lists BOTH runs — no run is clobbered by the other',
      dash.stdout + dash.stderr + '\n' + stateTxt.slice(0, 400));

    // (h) Zero registry writes, measured on the isolated copy — not on the
    //     operator's live file, which a concurrent forge session may
    //     legitimately write at any moment.
    assert(registryStamp() === registryAfterSetup,
      '(h) the synthetic-home registry is byte-identical (mtime:size:sha256) after every runs/dashboard operation — the CLIs read it, never write it',
      `${registryAfterSetup} → ${registryStamp()}`);
    // Positive control: the same comparator must bite on a real write —
    // an equality never seen failing proves nothing about what it detects.
    fs.appendFileSync(file, '\n');
    assert(registryStamp() !== registryAfterSetup,
      '(h control) a deliberate append IS detected by the same comparator');
    assert(!fs.existsSync(path.join(process.cwd(), '.gsd', 'milestones', 'M-a')),
      '(h) no .gsd/ outside the fixture was created by this section');

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeConcurrentRunAddresses\(\); \}/.test(mainBody),
      '(i) Section 87 is registered through a closure in main()');
    pass('(final) Section 87: duas runs no mesmo projeto em branches diferentes — visíveis, ' +
      'endereçáveis, integridade provada por hash, espelho ≠ verdade, e a asserção vista vermelha antes de verde');
  } finally { cleanup(dir); }
}

// ── Section 88: doc-claims guard is wired into acceptance, and cannot be
// silently undone — the revocation this scanner protects (S06/T01) stays
// revoked only as long as SOMETHING in the acceptance suite calls the
// in-process scanner and fails on either a real violation or a floor
// breach. This section ties that invocation to forge-smoke.js itself, so a
// future edit that removes the call cannot pass this suite unnoticed.
function smokeDocClaimsGuard() {
  process.stdout.write('\n▸ Section 88: doc-claims guard amarrado à suíte de aceitação\n');
  const docClaims = require('./forge-doc-claims.js');
  const ROOT = path.dirname(SCRIPTS);

  // (a) the real tree is clean AND above the anti-silence floor — this is
  // the actual acceptance assertion for S06 criterion #13. If a future edit
  // reintroduces the revoked claim anywhere in the tree, or the scanner
  // regresses to scanning 0 files, this line goes red.
  const real = docClaims.checkTree(ROOT);
  assert(real.ok === true, '(a) real tree scan: ok === true (no revoked-claim violations)', JSON.stringify(real));
  assert(real.scanned >= docClaims.MIN_SCANNED_FLOOR,
    `(a) real tree scan: scanned (${real.scanned}) >= anti-silence floor (${docClaims.MIN_SCANNED_FLOOR})`);
  assert(Array.isArray(real.violations) && real.violations.length === 0,
    '(a) real tree scan: violations array is empty', JSON.stringify(real.violations));

  // (b) bite, proven again HERE (not merely trusted from T02's own suite):
  // reinject the revoked claim into a fixture file, including one inside a
  // .gitignore-covered name pattern equivalent (CLAUDE.md), and require RED.
  const dir = mkTmp('doc-claims-guard');
  try {
    // The revoked-claim string is assembled from parts at runtime (as T02's
    // own test does) rather than written as one contiguous literal — so this
    // file's own source text never carries the claim it is proving the
    // scanner catches, and does not self-flag when this suite scans itself.
    const claimParts = ['- **STATE.md', 'é', 'single source of truth', '** — reinjected for bite proof\n'];
    const claimFile = path.join(dir, 'CLAUDE.md');
    fs.writeFileSync(claimFile, claimParts.join(' '));
    const dirty = docClaims.checkTree(dir, { floor: 1 });
    assert(dirty.ok === false, '(b) fixture with reinjected claim: ok === false (bite observed RED)', JSON.stringify(dirty));
    assert(dirty.violations.length >= 1, '(b) fixture with reinjected claim: >= 1 violation reported');

    // (c) removing the claim restores GREEN — both directions proven, not
    // just the one that happens to be convenient.
    fs.writeFileSync(claimFile, '- STATE.md is documented as a generated projection, not a source of truth\n');
    const clean = docClaims.checkTree(dir, { floor: 1 });
    assert(clean.ok === true, '(c) fixture with claim removed: ok === true again (GREEN restored)', JSON.stringify(clean));
  } finally { cleanup(dir); }

  // (d) the shell-grep blind spot this whole guard exists because of, proven
  // right here rather than only narrated: the ugrep-wrapping `grep` in this
  // environment honors .gitignore and CLAUDE.md is listed there, so a bare
  // `grep -rni` over the repo root never reaches it. This assertion does not
  // shell out (the scanner it is checking is itself in-process for the same
  // reason) — it reads .gitignore directly and confirms CLAUDE.md is listed,
  // which is the precondition for the blind spot to exist at all.
  let gitignore = '';
  try { gitignore = fs.readFileSync(path.join(ROOT, '.gitignore'), 'utf8'); } catch {}
  assert(/CLAUDE\.md/.test(gitignore),
    '(d) .gitignore lists CLAUDE.md — the measured precondition for the shell-grep blind spot ' +
    '(bare `grep -rn` never sees the file carrying the revoked claim; only /usr/bin/grep or an ' +
    'explicit file argument reaches it — this scanner never shells out, so it is immune)');

  // (e) registration in main() through a closure, same structural check used
  // by Sections 83/84/85 — this is what makes it impossible to silently
  // un-wire the call and still pass: a future edit that deletes the closure
  // from main()'s list is not merely a missing section (silent), it fails
  // this specific assertion inside the section that IS still running today.
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeDocClaimsGuard\(\); \}/.test(mainBody),
    '(e) Section 88 is registered through a closure in main()');

  pass('(final) Section 88: doc-claims guard scans the real tree clean above the anti-silence floor, ' +
    'bites on reinjection (both directions proven), and the shell-grep blind spot precondition is confirmed live');
}

// ── Section 89: o sinal de sobreposição entre runs, ponta-a-ponta ───────────
//
// S07's whole claim in one section: two runs that touched the same file are
// VISIBLE before the merge, two runs that did not are reported `clean` ONLY
// after real comparison work, and neither verdict costs anybody a gate.
//
// The verdict floor is the load-bearing part and the reason this section is
// long. `clean` is a claim about work performed — "I confronted these pairs
// and found no collision". A comparator that emits it having confronted
// nothing reports its own inactivity as good news, and that report is
// byte-for-byte indistinguishable from a detector that is simply broken.
// This milestone paid three rounds for exactly that shape (a `grep` that
// honored .gitignore and so scanned nothing; the scanner that replaced it,
// blind to its own target wording; the widened pattern still evadable by
// rewording). So `inconclusive` and `clean` are asserted as DIFFERENT
// verdicts, in a fixture built to produce each, and the assertions were
// observed RED under additive mutation before their green was trusted — the
// four runs are transcribed in T04-SUMMARY.md, not merely claimed here.
//
// Everything spawns the REAL CLIs (`forge-touch --record`, `forge-overlap
// --check`, `forge-doctor --check`), never just the modules: `exit 0 always`
// is a property of the process, and only a process can be asked about it.
//
// Every fixture lives under a synthetic `$HOME` in mkdtemp/os.tmpdir(), and
// every registry a spawned CLI can see is a copy inside one of those synthetic
// homes — including (c2), which runs against a real-shaped COPY of the
// operator's registry, never the live file. The no-write property is measured
// on those copies at (g), with a positive control. A previous version watched
// the operator's live ~/.claude/forge-gate-workspaces.json by mtime:size;
// that cannot prove the property, because the live file is legitimately
// written by the app and by any concurrent forge session, so an innocent
// suite failed whenever the machine was not idle (same pathology as
// forge-touch.test.js R5 / forge-resources-census R13, fixed in 0810c59).
function smokeRunOverlapSignal() {
  process.stdout.write('\n▸ Section 89: sinal de sobreposição entre runs — overlap, clean e o piso inconclusive\n');

  const ROOT = path.dirname(SCRIPTS);
  const liveRegistry = path.join(os.homedir(), '.claude', 'forge-gate-workspaces.json');

  const dirs = [];
  // Every fixture registry, stamped at creation — compared at (g) against the
  // same stamp to prove the spawned CLIs never write any registry they see.
  const registryCopies = [];
  const regStamp = (f) => `${fs.statSync(f).mtimeMs}:${fs.statSync(f).size}:`
    + crypto.createHash('sha256').update(fs.readFileSync(f)).digest('hex');
  const git = (cwd, args) => execFileSync('git', args, { cwd, encoding: 'utf8' });
  const sha = p => crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');

  /** A minimal git repo on `main` with one commit — the base every fixture repo starts from. */
  const makeRepo = (dir) => {
    fs.mkdirSync(dir, { recursive: true });
    git(dir, ['init', '-q']);
    git(dir, ['checkout', '-q', '-b', 'main']);
    git(dir, ['config', 'user.email', 'fixture@example.com']);
    git(dir, ['config', 'user.name', 'Fixture']);
    fs.writeFileSync(path.join(dir, 'base.txt'), 'base\n', 'utf8');
    git(dir, ['add', 'base.txt']);
    git(dir, ['commit', '-q', '-m', 'init']);
    return dir;
  };

  /**
   * A workspace with two git repos and N run records, wired exactly like
   * forge-touch.test.js's own `makeFixture` (registry roots + entries + per-run
   * files) so this section exercises the shipped address→touch→overlap chain
   * rather than a smoke-local imitation of it.
   */
  const makeFixture = (label, runIds) => {
    const tmp = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), `forge-smoke-overlap-${label}-`)));
    dirs.push(tmp);
    const home = path.join(tmp, 'home');
    const ws = path.join(home, 'Development', 'ws');
    fs.mkdirSync(path.join(ws, '.gsd'), { recursive: true });
    fs.writeFileSync(path.join(ws, '.gsd', 'PROJECT.md'), '# fixture\n', 'utf8');

    const repoNames = ['repo-a', 'repo-b'];
    for (const n of repoNames) makeRepo(path.join(ws, n));

    for (const id of runIds) {
      const f = path.join(ws, '.gsd', 'forge', 'runs', `${id}.json`);
      fs.mkdirSync(path.dirname(f), { recursive: true });
      fs.writeFileSync(f, JSON.stringify({
        kind: 'milestone', id, session_id: `sess-${id}`, active: true,
        started_at: 1785763253000, last_heartbeat: 1785763253000,
        worker: null, worker_started: null, isolation_mode: 'branch',
        milestone_dir: `.gsd/milestones/${id}/`, cwd: ws,
      }, null, 2), 'utf8');
    }

    const regFile = path.join(home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(regFile), { recursive: true });
    fs.writeFileSync(regFile, JSON.stringify({
      version: 1,
      roots: [{ path: '~/Development', primary: true }],
      entries: [{ path: 'ws', root: '~/Development', kind: 'workspace', repos: repoNames }],
      quarantine: [],
    }, null, 2), 'utf8');
    registryCopies.push({ label, regFile, stamp: regStamp(regFile) });

    const env = Object.assign({}, process.env, { HOME: home, USERPROFILE: home });
    return { tmp, home, ws, env, repoNames };
  };

  const record = (fx, id) => runScript('forge-touch.js', ['--record', id, '--json', '--cwd', fx.ws], { env: fx.env });
  const check = (fx, extra) => runScript('forge-overlap.js', ['--check', '--cwd', fx.ws, ...(extra || [])], { env: fx.env });
  const checkJson = (fx) => {
    const r = check(fx, ['--json']);
    let json = null;
    try { json = JSON.parse(r.stdout); } catch { json = null; }
    return { status: r.status, json, stdout: r.stdout, stderr: r.stderr };
  };

  try {
    // ── (f) ENVIRONMENTAL PRECONDITION, asserted BEFORE any verdict is read.
    //    Section 88's anti-silence floor, applied here: a section whose fixture
    //    silently built zero runs or zero touched files would sail through every
    //    verdict assertion below while proving nothing at all. So the fixture is
    //    measured first, and the measurement is what the verdicts are read
    //    against.
    const fxOverlap = makeFixture('overlap', ['M-r1', 'M-r2']);
    fs.writeFileSync(path.join(fxOverlap.ws, 'repo-a', 'shared.ts'), 'export const x = 1;\n', 'utf8');
    const rec1 = record(fxOverlap, 'M-r1');
    const rec2 = record(fxOverlap, 'M-r2');
    assert(rec1.status === 0 && rec2.status === 0,
      '(f) forge-touch --record exits 0 for both runs', rec1.stderr + rec2.stderr);
    let t1 = null; let t2 = null;
    try { t1 = JSON.parse(rec1.stdout); t2 = JSON.parse(rec2.stdout); } catch { /* asserted next */ }
    const filesOf = t => (t && t.repos ? t.repos.reduce((n, r) => n + (r.files || []).length, 0) : 0);
    assert(t1 && t2 && t1.examined === 2 && t2.examined === 2,
      '(f) precondition: BOTH runs examined the 2 addressed repos — the fixture is not vacuous',
      JSON.stringify([t1 && t1.examined, t2 && t2.examined]));
    assert(filesOf(t1) >= 1 && filesOf(t2) >= 1,
      '(f) precondition: BOTH snapshots carry at least one touched file — a verdict over empty snapshots proves nothing',
      JSON.stringify([filesOf(t1), filesOf(t2)]));

    // ── (a) OVERLAP: two runs, same file, and the CLI still exits 0.
    const over = checkJson(fxOverlap);
    assert(over.json && over.json.verdict === 'overlap',
      '(a) two runs touching the same file produce verdict === "overlap"',
      over.stdout + over.stderr);
    assert(over.status === 0,
      '(a) the overlap verdict still exits 0 — advisory is a measured property of the process, not an adjective',
      `status=${over.status}`);
    const hit = over.json && over.json.overlaps[0];
    assert(hit && hit.repo === 'repo-a' && hit.files.includes('shared.ts'),
      '(a) the report names the repo and the colliding FILE', JSON.stringify(over.json && over.json.overlaps));
    assert(hit && [hit.runs[0], hit.runs[1]].sort().join(',') === 'M-r1,M-r2',
      '(a) the report names BOTH run ids', JSON.stringify(hit && hit.runs));

    // ── (d) ADVISORY, in two halves, both measured.
    //    First: `--check` writes NOTHING. Proven by hashing every runs/*.json
    //    before and after, not by reading the code and believing it.
    const runsDir = path.join(fxOverlap.ws, '.gsd', 'forge', 'runs');
    const hashRuns = () => fs.readdirSync(runsDir).sort()
      .map(f => `${f}:${sha(path.join(runsDir, f))}`).join('|');
    const runsBefore = hashRuns();
    check(fxOverlap, ['--json']);
    check(fxOverlap);
    assert(hashRuns() === runsBefore,
      '(d) every runs/*.json is byte-identical after two --check invocations — the detector reads, never writes',
      `${runsBefore}\n${hashRuns()}`);

    //    Second: the doctor surface. `--fix` seeds SCHEMA-VERSION so that the
    //    exit code of `--check all` reflects the overlap and nothing else;
    //    without it a missing schema file would mask the very thing under test.
    const fix = runScript('forge-doctor.js', ['--fix', '--cwd', fxOverlap.ws], { env: fxOverlap.env });
    assert(fix.status === 0, '(d) forge-doctor --fix seeds the fixture so the exit code isolates run-overlap', fix.stderr);
    const docOne = runScript('forge-doctor.js', ['--check', 'run-overlap', '--cwd', fxOverlap.ws], { env: fxOverlap.env });
    assert(docOne.status === 0 && /Cross-run overlap/.test(docOne.stdout) && /shared\.ts/.test(docOne.stdout),
      '(d) forge-doctor --check run-overlap surfaces the collision AND exits 0',
      `status=${docOne.status}\n${docOne.stdout}${docOne.stderr}`);
    const docAll = runScript('forge-doctor.js', ['--check', 'all', '--cwd', fxOverlap.ws], { env: fxOverlap.env });
    assert(docAll.status === 0,
      '(d) --check all still exits 0 WITH an overlap present — the signal informs, it does not gate',
      `status=${docAll.status}\n${docAll.stdout}${docAll.stderr}`);

    // ── (i) THE WORKTREE CASE, through the shipped CLIs (S07 review-fix).
    //    The case (a) above cannot reach: two runs in `worktree` isolation, in
    //    two real `git worktree`s of ONE repo, both editing `shared.ts`.
    //    Reviewed and conceded as two composing HIGH defects — forge-touch
    //    derived from the REGISTRY checkout (so both runs snapshotted the same
    //    unrelated tree) and reposMatch compared PATHS (so two worktrees of one
    //    repo could never match). Either one alone answers `clean` here, with a
    //    full and confident census, about two runs headed for a merge conflict.
    //    `worktree` is S04's shape-derived default wherever a workspace exists,
    //    i.e. exactly where concurrent runs are plausible.
    //    Run records are written by hand below (they need `worktrees[]` and
    //    real worktree paths that only exist after `git worktree add`), so the
    //    fixture is asked for zero runs and the registry dir is created here.
    const fxWt = makeFixture('worktree', []);
    fs.mkdirSync(path.join(fxWt.ws, '.gsd', 'forge', 'runs'), { recursive: true });
    const wtRepo = path.join(fxWt.ws, 'repo-a');
    fs.writeFileSync(path.join(wtRepo, 'shared.ts'), 'export const v = 0;\n', 'utf8');
    git(wtRepo, ['add', 'shared.ts']);
    git(wtRepo, ['commit', '-q', '-m', 'seed shared.ts']);
    const wtIds = ['M-w1', 'M-w2'];
    const wtPaths = {};
    for (const id of wtIds) {
      const wt = path.join(fxWt.ws, '.forge-worktrees', id, 'repo-a');
      git(wtRepo, ['worktree', 'add', '-q', wt, '-b', `forge/${id}`, 'main']);
      git(wt, ['config', 'user.email', 'fixture@example.com']);
      git(wt, ['config', 'user.name', 'Fixture']);
      fs.writeFileSync(path.join(wt, 'shared.ts'), `export const v = '${id}';\n`, 'utf8');
      fs.writeFileSync(path.join(wt, `${id}-only.ts`), 'x\n', 'utf8');
      git(wt, ['add', '.']);
      git(wt, ['commit', '-q', '-m', `work in ${id}`]);
      wtPaths[id] = wt;
      fs.writeFileSync(path.join(fxWt.ws, '.gsd', 'forge', 'runs', `${id}.json`), JSON.stringify({
        kind: 'milestone', id, session_id: `sess-${id}`, active: true,
        started_at: 1785763253000, last_heartbeat: 1785763253000,
        worker: null, worker_started: null,
        isolation_mode: 'worktree', branch: `forge/${id}`,
        worktrees: [{ repo: wtRepo, path: wt }],
        milestone_dir: `.gsd/milestones/${id}/`, cwd: fxWt.ws,
      }, null, 2), 'utf8');
    }
    //    PRECONDITION FIRST, same discipline as (f): a fixture that derived
    //    nothing would sail through the verdict below proving nothing.
    const wtSnaps = wtIds.map(id => {
      const r = record(fxWt, id);
      try { return JSON.parse(r.stdout); } catch { return null; }
    });
    const wtRepoEntries = wtSnaps.map(s => (s && s.repos ? s.repos.find(x => x.name === 'repo-a') : null));
    assert(wtRepoEntries.every(e => e && e.source === 'worktree' && e.files.includes('shared.ts')),
      "(i) precondition: BOTH runs derived from their own worktree (source === 'worktree') and see their committed work",
      JSON.stringify(wtRepoEntries.map(e => e && [e.source, e.path, e.files])));
    assert(wtRepoEntries[0].path !== wtRepoEntries[1].path
      && wtRepoEntries[0].repo_id && wtRepoEntries[0].repo_id === wtRepoEntries[1].repo_id,
      '(i) precondition: two genuinely DIFFERENT working trees resolving to ONE repository identity — the whole point of the case',
      JSON.stringify(wtRepoEntries.map(e => e && [e.path, e.repo_id])));
    const wtVerdict = checkJson(fxWt);
    assert(wtVerdict.json && wtVerdict.json.verdict === 'overlap',
      '(i) two worktrees of one repo touching the same file produce "overlap" — NOT the confident `clean` two path-compared checkouts used to yield',
      wtVerdict.stdout + wtVerdict.stderr);
    const wtHit = wtVerdict.json && wtVerdict.json.overlaps[0];
    assert(wtHit && wtHit.files.join(',') === 'shared.ts',
      '(i) only the shared file is flagged — each run\'s exclusive file is not a collision',
      JSON.stringify(wtVerdict.json && wtVerdict.json.overlaps));
    assert(wtVerdict.status === 0, '(i) and it still exits 0', `status=${wtVerdict.status}`);
    //    NEGATIVE CONTROL for the identity itself: a detector that matched on
    //    NAME alone would pass every assertion above while collapsing the
    //    operator's default-case basename collision (apps/norns +
    //    services/norns) into one repo. Asserted at the seam, spawned-CLI
    //    output being unable to reach it.
    const rm = require(path.join(SCRIPTS, 'forge-overlap.js')).reposMatch;
    assert(rm({ name: 'norns', path: '/w/apps/norns', repo_id: '/w/apps/norns/.git' },
      { name: 'norns', path: '/w/services/norns', repo_id: '/w/services/norns/.git' }) === false,
    '(i) negative control: same NAME, different repositories still do not match — the fix did not degrade to name-only matching');
    assert(rm({ name: 'freyr', path: '/w/wt/A/freyr', repo_id: '/w/freyr/.git' },
      { name: 'freyr', path: '/w/wt/B/freyr', repo_id: '/w/freyr/.git' }) === true,
    '(i) positive control: different paths, one repository identity DO match');

    // ── (b) CLEAN, and only with proof of work. Same two runs, snapshots taken
    //    at different tree states, so their touched sets are genuinely disjoint.
    //    `pairs_compared >= 1` is asserted in the SAME breath as the verdict:
    //    `clean` alone is the exact statement this section exists to distrust.
    const fxClean = makeFixture('clean', ['M-c1', 'M-c2']);
    fs.writeFileSync(path.join(fxClean.ws, 'repo-a', 'alpha.ts'), 'a\n', 'utf8');
    record(fxClean, 'M-c1');
    fs.unlinkSync(path.join(fxClean.ws, 'repo-a', 'alpha.ts'));
    fs.writeFileSync(path.join(fxClean.ws, 'repo-b', 'beta.ts'), 'b\n', 'utf8');
    record(fxClean, 'M-c2');
    const clean = checkJson(fxClean);
    assert(clean.json && clean.json.verdict === 'clean' && clean.json.pairs_compared >= 1,
      '(b) disjoint touches produce "clean" AND pairs_compared >= 1 — the verdict is backed by comparison actually performed',
      clean.stdout + clean.stderr);
    assert(clean.json && clean.json.files_compared >= 2 && clean.json.overlaps.length === 0,
      '(b) the census shows real paths walked and no collision', JSON.stringify(clean.json));
    assert(clean.status === 0, '(b) clean exits 0', `status=${clean.status}`);

    // ── (c) THE FLOOR. One run with a snapshot, one without: nothing to
    //    compare, so the verdict is `inconclusive` — and `!== "clean"` is
    //    asserted explicitly, because the whole bug class this section guards
    //    is the two collapsing into one.
    const fxFloor = makeFixture('floor', ['M-f1', 'M-f2']);
    fs.writeFileSync(path.join(fxFloor.ws, 'repo-a', 'only.ts'), 'o\n', 'utf8');
    record(fxFloor, 'M-f1');
    const floor = checkJson(fxFloor);
    assert(floor.json && floor.json.verdict === 'inconclusive',
      '(c) fewer than two runs with touch data produce "inconclusive"', floor.stdout + floor.stderr);
    assert(floor.json && floor.json.verdict !== 'clean',
      '(c) and it is explicitly NOT "clean" — a comparator that confronted nothing must never report good news',
      String(floor.json && floor.json.verdict));
    assert(floor.json && floor.json.pairs_compared === 0 && floor.json.runs_with_touch_data === 1,
      '(c) the census states plainly WHY: 1 run with data, 0 pairs', JSON.stringify(floor.json));
    const floorHuman = check(fxFloor);
    assert(/inconclusive/.test(floorHuman.stdout) && /nada a comparar/.test(floorHuman.stdout),
      '(c) the human output carries the REASON on the verdict line — a mute inconclusive repeats the defect one level up',
      floorHuman.stdout);
    assert(/M-f2 \(no-touch-record\)/.test(floorHuman.stdout),
      '(c) the run that left the comparison leaves a NAMED reason behind — nothing is discarded silently',
      floorHuman.stdout);
    assert(floorHuman.status === 0, '(c) inconclusive exits 0 too', `status=${floorHuman.status}`);

    // ── (c2) THE SAME FLOOR, AGAINST THE REAL RUN RECORDS OF THIS REPO.
    //    Today this tree has runs but none carrying touch data, so the honest
    //    answer is `inconclusive`; a build that answered `clean` here would be
    //    the bug, reporting "no collisions" about a comparison it never
    //    performed. The assertion is written as the IMPLICATION rather than
    //    the literal verdict so it stays true — and stays load-bearing — on
    //    the day this tree does have two recorded runs.
    //
    //    The registry this spawn sees is a real-shaped COPY of the operator's
    //    in a synthetic home (minimal valid fallback on machines without one,
    //    so the assert still runs instead of skipping) — the live file is
    //    copied once, read-only, and never pointed at by any HOME below. The
    //    copy joins the (g) measurement like every other fixture registry.
    const c2Tmp = fs.realpathSync(fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-overlap-c2home-')));
    dirs.push(c2Tmp);
    const c2Home = path.join(c2Tmp, 'home');
    const c2Reg = path.join(c2Home, '.claude', 'forge-gate-workspaces.json');
    fs.mkdirSync(path.dirname(c2Reg), { recursive: true });
    if (fs.existsSync(liveRegistry)) fs.copyFileSync(liveRegistry, c2Reg);
    else fs.writeFileSync(c2Reg, JSON.stringify({ version: 1, roots: [], entries: [], quarantine: [] }, null, 2), 'utf8');
    registryCopies.push({ label: 'c2-real-shaped', regFile: c2Reg, stamp: regStamp(c2Reg) });
    const c2Env = Object.assign({}, process.env, { HOME: c2Home, USERPROFILE: c2Home });
    const liveRaw = runScript('forge-overlap.js', ['--check', '--json', '--cwd', ROOT], { env: c2Env });
    let live = null;
    try { live = JSON.parse(liveRaw.stdout); } catch { /* asserted next */ }
    assert(live && typeof live.verdict === 'string' && liveRaw.status === 0,
      '(c2) the real run records of this repo answer, and exit 0', liveRaw.stdout + liveRaw.stderr);
    assert(!live || live.runs_with_touch_data >= 2 || live.verdict !== 'clean',
      '(c2) live tree: fewer than two runs with touch data can NEVER yield "clean" — the distinction is load-bearing on real data, not only in fixtures',
      JSON.stringify(live));
    assert(live && (live.skipped.length + live.runs_with_touch_data) === live.runs_examined,
      '(c2) live census accounts for EVERY run — comparable + named skips === examined, no silent shrinkage',
      JSON.stringify(live && { examined: live.runs_examined, withData: live.runs_with_touch_data, skipped: live.skipped.length }));
    assert(live && live.skipped.every(s => typeof s.reason === 'string' && s.reason.length > 0),
      '(c2) every live skip carries a named reason', JSON.stringify(live && live.skipped));
    process.stdout.write(`    (c2) live census: examined ${live && live.runs_examined}`
      + ` · with-data ${live && live.runs_with_touch_data} · verdict ${live && live.verdict}\n`);

    // ── (e) SCOPE, as an assertion rather than a sentence. S07 introduces no
    //    shared JS↔Swift constant and writes nothing under app/, which is why
    //    criterion #15's parity guard was deliberately NOT extended. That
    //    declaration is worth exactly as much as its verification, so it is
    //    verified here.
    //
    //    Selection is per-COMMIT, not per-range: b3904a7 ("fix(S03/hazard)") is
    //    a UAT fix that landed BETWEEN T01 and T02 and does touch app/. A naive
    //    `base..HEAD` diff would attribute it to S07 and go red for a reason
    //    that has nothing to do with this slice — so a commit belongs to S07
    //    only if it touches an S07-exclusive file or names S07 in its subject,
    //    and every excluded commit is printed rather than dropped.
    const gitRoot = (args) => {
      try { return execFileSync('git', args, { cwd: ROOT, encoding: 'utf8' }).trim(); }
      catch { return null; }
    };
    const addCommit = (gitRoot(['log', '--diff-filter=A', '--format=%H', '--', 'scripts/forge-touch.js']) || '')
      .split('\n').filter(Boolean).pop();
    const sliceBase = addCommit ? gitRoot(['rev-parse', `${addCommit}^`]) : null;
    if (!sliceBase) {
      // FAIL, never skip: a scope check that silently excuses itself when its
      // base does not resolve is the precise defect this milestone spent a
      // whole slice hunting.
      fail('(e) slice base resolves (parent of the commit that added scripts/forge-touch.js)',
        `addCommit=${addCommit}`);
    } else {
      const S07_EXCLUSIVE = [
        'scripts/forge-touch.js', 'scripts/forge-touch.test.js',
        'scripts/forge-overlap.js', 'scripts/forge-overlap.test.js',
        'scripts/forge-doctor-run-overlap.test.js',
      ];
      const shas = (gitRoot(['rev-list', `${sliceBase}..HEAD`]) || '').split('\n').filter(Boolean);
      const commits = shas.map(h => ({
        sha: h,
        subject: gitRoot(['log', '-1', '--format=%s', h]) || '',
        files: (gitRoot(['show', '--name-only', '--format=', h]) || '').split('\n').filter(Boolean),
      }));
      const isS07 = c => /\bS07\b/.test(c.subject) || c.files.some(f => S07_EXCLUSIVE.includes(f));
      const selected = commits.filter(isS07);
      const foreign = commits.filter(c => !isS07(c));
      const appPaths = f => f.split('/')[0] === 'app';
      const squashed = selected.some(c => c.files.length >= 30);

      for (const c of foreign) {
        process.stdout.write(`    (e) fora do escopo de S07: ${c.sha.slice(0, 7)} ${c.subject}`
          + ` [${c.files.filter(appPaths).length} arquivo(s) em app/]\n`);
      }

      if (squashed) {
        // Enumerated and printed, never silent: once this branch is squash-
        // merged, a single commit carries every slice of the milestone and the
        // per-commit attribution above stops being meaningful.
        skip('(e) slice diff carries no app/ path',
          'slice-history-squashed — a selected commit touches >= 30 files, so per-commit S07 attribution no longer holds');
      } else {
        assert(selected.length >= 3,
          `(e) the S07 commit selector actually selected commits (${selected.length} >= 3) — a selector that matches nothing proves nothing`,
          JSON.stringify(commits.map(c => [c.sha.slice(0, 7), c.subject, isS07(c)])));
        const offending = selected.flatMap(c => c.files.filter(appPaths).map(f => `${c.sha.slice(0, 7)}:${f}`));
        assert(offending.length === 0,
          '(e) no S07 commit touches app/ — criterion #15 did not fire because its condition never arose, verified rather than omitted',
          offending.join(', '));
        assert(foreign.every(c => !/\bS07\b/.test(c.subject)),
          '(e) every commit excluded from the S07 set is genuinely foreign — an S07-labelled commit could not hide in the exclusions',
          JSON.stringify(foreign.map(c => [c.sha.slice(0, 7), c.subject])));
        // POSITIVE CONTROL for the predicate itself. The three prior anti-
        // silence bugs of this milestone were all detectors blind to their own
        // target; a scope check trusted green without ever having been shown
        // firing would be the fourth.
        const control = ['app/Sources/ForgeKit/Models.swift', 'scripts/forge-overlap.js']
          .filter(appPaths);
        assert(control.length === 1 && control[0].startsWith('app/'),
          '(e) positive control: the same app/ predicate DOES fire on a synthetic app/ path — it is not blind',
          JSON.stringify(control));
      }
    }

    // ── (g) Zero registry writes, measured on the isolated copies only —
    //    every registry a spawned CLI could see in this section, including the
    //    real-shaped (c2) copy. The operator's live file is out of the
    //    measurement on purpose: it is legitimately written by concurrent
    //    forge sessions, and watching it made an innocent suite fail on a
    //    busy machine.
    assert(registryCopies.length >= 4,
      `(g) the measurement covers every fixture registry plus the (c2) copy (${registryCopies.length} >= 4) — a census of one proves little`,
      JSON.stringify(registryCopies.map(c => c.label)));
    for (const c of registryCopies) {
      assert(regStamp(c.regFile) === c.stamp,
        `(g) registry copy "${c.label}" is byte-identical (mtime:size:sha256) — the CLIs read it, never write it`,
        `${c.stamp} → ${regStamp(c.regFile)}`);
    }
    // Positive control: the comparator must bite on a real write — an
    // equality never seen failing proves nothing about what it detects.
    fs.appendFileSync(registryCopies[0].regFile, '\n');
    assert(regStamp(registryCopies[0].regFile) !== registryCopies[0].stamp,
      '(g control) a deliberate append IS detected by the same comparator');
    assert(!fs.existsSync(path.join(ROOT, '.gsd', 'forge', 'runs', 'M-r1.json')),
      '(g) no fixture run leaked into this repo\'s own registry');

    // ── (h) Registration in main(), the same structural check Sections 87/88
    //    use: deleting the closure is not merely a missing section (silent) —
    //    it fails this assertion inside the section that is still running.
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeRunOverlapSignal\(\); \}/.test(mainBody),
      '(h) Section 89 is registered through a closure in main()');
    const idxSelf = mainBody.indexOf('smokeRunOverlapSignal();');
    const idxIso = mainBody.indexOf('await smokeSectionIsolation();');
    assert(idxSelf > 0 && idxIso > idxSelf,
      '(h) Section 89 is registered BEFORE smokeSectionIsolation, which stays the last entry',
      `self=${idxSelf} isolation=${idxIso}`);

    pass('(final) Section 89: overlap nomeia arquivo/repo/runs e sai 0, clean só com par confrontado, '
      + 'inconclusive nunca vira clean (fixture e run records reais), o detector não escreve, '
      + 'o doctor não bloqueia, e o diff da slice não toca app/ — com o piso visto vermelho antes de verde');
  } finally {
    for (const d of dirs) cleanup(d);
  }
}

// ── Section 90: guard direcional de schema fiado nos 4 leitores ───────────
// End-to-end através das CLIs reais. A suíte de wiring
// (forge-schema-guard-wiring.test.js) cobre a fronteira de módulo; aqui o que
// se prova é que os processos de verdade — os que o orquestrador invoca —
// avisam ALTO na leitura, continuam com exit 0, e RECUSAM a escrita quando o
// major em .gsd/SCHEMA-VERSION está à frente do que a tooling entende.
// Regressão que isto trava: um leitor voltar a degradar em silêncio.
function smokeSchemaGuardWiring() {
  process.stdout.write('\n▸ Section 90: guard direcional de schema nos 4 leitores\n');
  const dir = mkTmp('schema-guard-wiring');
  try {
    const CURRENT = require(path.join(SCRIPTS, 'forge-doctor.js')).CURRENT_SCHEMA;
    const major = Number(String(CURRENT).match(/@(\d+)\./)[1]);
    const WARN_RE = /schema do Forge à frente da tooling local/;
    const ledgerId = 'M-20260101000000-smoke90';

    // Fixture: um fragmento em cada store, os três stores povoados.
    const mkStores = (root) => {
      for (const store of ['ledger', 'decisions', 'memory']) {
        fs.mkdirSync(path.join(root, '.gsd', store), { recursive: true });
      }
      fs.writeFileSync(path.join(root, '.gsd', 'ledger', `${ledgerId}.md`),
        `---\nid: ${ledgerId}\ntitle: Smoke 90\ncompleted_at: 2026-01-01T00:00:00Z\nslices: [S01]\nkey_files: []\nkey_decisions: []\n---\n\nBody.\n`, 'utf8');
      fs.writeFileSync(path.join(root, '.gsd', 'memory', `${ledgerId}.md`),
        `---\nunit_id: ${ledgerId}\nfacts:\n  - mem_id: S90-1\n    category: gotcha\n    text: smoke 90 fixture\n    created_at: 2026-01-01\n    source_unit: ${ledgerId}\nstats: []\n---\n`, 'utf8');
    };

    const clean = path.join(dir, 'clean');
    const ahead = path.join(dir, 'ahead');
    mkStores(clean);
    mkStores(ahead);
    fs.writeFileSync(path.join(ahead, '.gsd', 'SCHEMA-VERSION'), `fragment-store@${major + 1}.0.0\n`, 'utf8');

    const entry = (id) => JSON.stringify({
      id, title: 'W', completed_at: '2026-02-02T00:00:00Z',
      slices: [], key_files: [], key_decisions: [], body: 'x',
    });
    const writeTarget = (root) => path.join(root, '.gsd', 'ledger', 'M-20260202000000-w.md');

    // (a) fail-open: sem SCHEMA-VERSION nada muda — nem stderr, nem chave nova.
    const cleanList = runScript('forge-ledger.js', ['--list', '--cwd', clean]);
    const cleanStale = runScript('forge-projection.js', ['--stale', '--cwd', clean]);
    assert(cleanList.status === 0 && !WARN_RE.test(cleanList.stderr)
      && Array.isArray(JSON.parse(cleanList.stdout))
      && cleanStale.status === 0 && !WARN_RE.test(cleanStale.stderr)
      && Object.keys(JSON.parse(cleanStale.stdout)).sort().join(',') === 'decisions,ledger,memory',
      '(a) fail-open read is byte-identical: no warning, no schema_partial key');

    const cleanWrite = runScript('forge-ledger.js', ['--write', '--cwd', clean],
      { input: entry('M-20260202000000-w') });
    assert(cleanWrite.status === 0 && fs.existsSync(writeTarget(clean)),
      '(a) fail-open write succeeds and lands on disk');

    // (b) major à frente, leitura: exit 0 + warning em stderr, envelope marcado.
    for (const cli of ['forge-ledger.js', 'forge-decisions.js', 'forge-memory.js']) {
      const r = runScript(cli, ['--list', '--cwd', ahead]);
      assert(r.status === 0 && WARN_RE.test(r.stderr) && Array.isArray(JSON.parse(r.stdout)),
        `(b) ${cli} --list warns on stderr, exits 0 and keeps its array shape`);
    }
    const aheadStale = runScript('forge-projection.js', ['--stale', '--cwd', ahead]);
    const staleJson = aheadStale.status === 0 ? JSON.parse(aheadStale.stdout) : {};
    assert(aheadStale.status === 0 && WARN_RE.test(aheadStale.stderr)
      && staleJson.schema_partial === true && typeof staleJson.schema_warning === 'string'
      && typeof staleJson.ledger === 'boolean',
      '(b) --stale envelope gains schema_partial/schema_warning without losing its keys');

    // (c) --read e --render não ganham NADA no stdout — o dado não muda de forma.
    const aheadRead = runScript('forge-ledger.js', ['--read', ledgerId, '--cwd', ahead]);
    const readJson = aheadRead.status === 0 ? JSON.parse(aheadRead.stdout) : {};
    const aheadRender = runScript('forge-projection.js', ['--render', 'ledger', '--cwd', ahead]);
    const cleanRender = runScript('forge-projection.js', ['--render', 'ledger', '--cwd', clean]);
    assert(aheadRead.status === 0 && WARN_RE.test(aheadRead.stderr)
      && !('schema_partial' in readJson) && !('schema_warning' in readJson),
      '(c) --read prints the fragment untouched; the signal is stderr-only');
    assert(aheadRender.status === 0 && WARN_RE.test(aheadRender.stderr)
      && !WARN_RE.test(aheadRender.stdout)
      && aheadRender.stdout.startsWith(cleanRender.stdout.slice(0, 40)),
      '(c) --render markdown stdout carries no extra text');

    // (d) uma emissão por processo por cwd — senão o aviso se afoga em ruído.
    const renderMemory = runScript('forge-projection.js', ['--render', 'memory', '--cwd', ahead]);
    assert(renderMemory.status === 0
      && (renderMemory.stderr.match(/schema do Forge à frente da tooling local/g) || []).length === 1,
      '(d) a render walking several guarded reads emits exactly one warning');

    // (e) escrita recusada: exit != 0 E nada em disco (conteúdo, não só o code).
    for (const [cli, payload, target] of [
      ['forge-ledger.js', entry('M-20260202000000-w'), writeTarget(ahead)],
      ['forge-decisions.js', JSON.stringify({ unit_id: 'M-20260202000000-w', decisions: [] }),
        path.join(ahead, '.gsd', 'decisions', 'M-20260202000000-w.md')],
      ['forge-memory.js', JSON.stringify({ unit_id: 'M-20260202000000-w', facts: [], stats: [] }),
        path.join(ahead, '.gsd', 'memory', 'M-20260202000000-w.md')],
    ]) {
      const r = runScript(cli, ['--write', '--cwd', ahead], { input: payload });
      assert(r.status !== 0 && WARN_RE.test(r.stderr) && !fs.existsSync(target),
        `(e) ${cli} --write is refused with exit != 0 and writes nothing`);
    }

    const existingBefore = fs.readFileSync(path.join(ahead, '.gsd', 'ledger', `${ledgerId}.md`), 'utf8');
    const clobber = runScript('forge-ledger.js', ['--write', '--cwd', ahead], { input: entry(ledgerId) });
    assert(clobber.status !== 0
      && fs.readFileSync(path.join(ahead, '.gsd', 'ledger', `${ledgerId}.md`), 'utf8') === existingBefore,
      '(e) a refused overwrite leaves the existing fragment byte-identical');

    // --force cobre o guard de monolito não-migrado, NÃO este: tooling velha
    // escrevendo sobre dado novo é outro perigo, e não tem override.
    const writeAll = runScript('forge-projection.js', ['--write-all', '--cwd', ahead]);
    const writeAllForced = runScript('forge-projection.js', ['--write-all', '--force', '--cwd', ahead]);
    assert(writeAll.status !== 0 && writeAllForced.status !== 0
      && WARN_RE.test(writeAll.stderr)
      && !fs.existsSync(path.join(ahead, '.gsd', 'LEDGER.md')),
      '(e) --write-all is refused with and without --force, and writes no monolith');

    // (e2) stamp ILEGÍVEL (a repro do dogfood da PR #70): `.gsd/SCHEMA-VERSION`
    // como DIRETÓRIO fazia toda escrita passar com exit 0 e arquivo em disco —
    // o EISDIR virava null e o null virava "não está à frente". Agora recusa,
    // nomeando o errno, e SEM alegar que o dado está à frente (ninguém mediu
    // direção nenhuma). A leitura continua limpa: a assimetria é o desenho.
    const unread = path.join(dir, 'unreadable');
    mkStores(unread);
    fs.mkdirSync(path.join(unread, '.gsd', 'SCHEMA-VERSION'), { recursive: true });
    const UNREADABLE_RE = /não pôde ser lido/;
    const unreadWrite = runScript('forge-ledger.js', ['--write', '--cwd', unread],
      { input: entry('M-20260202000000-w') });
    assert(unreadWrite.status !== 0 && UNREADABLE_RE.test(unreadWrite.stderr)
      && /EISDIR/.test(unreadWrite.stderr) && !WARN_RE.test(unreadWrite.stderr)
      && !fs.existsSync(writeTarget(unread)),
      '(e2) an unreadable stamp refuses the write, names the errno, and claims nothing about direction',
      `status=${unreadWrite.status} stderr=${unreadWrite.stderr}`);
    const unreadRead = runScript('forge-ledger.js', ['--list', '--cwd', unread]);
    assert(unreadRead.status === 0 && !UNREADABLE_RE.test(unreadRead.stderr) && !WARN_RE.test(unreadRead.stderr)
      && Array.isArray(JSON.parse(unreadRead.stdout)),
      '(e2) reading under an unreadable stamp stays clean and silent (fail-open preserved)');

    // (f) o helper é a única fonte da lógica: nenhum dos 4 leitores relê
    // SCHEMA-VERSION nem compara versão por conta própria.
    for (const reader of ['forge-projection.js', 'forge-ledger.js', 'forge-decisions.js', 'forge-memory.js']) {
      const text = fs.readFileSync(path.join(SCRIPTS, reader), 'utf8');
      assert(text.includes("require('./forge-schema-guard')"),
        `(f) ${reader} requires the guard helper`);
      assert(!/SCHEMA-VERSION/.test(text.replace(/^\s*\/\/.*$/gm, '')),
        `(f) ${reader} never re-reads .gsd/SCHEMA-VERSION outside the helper`);
    }

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeSchemaGuardWiring\(\); \}/.test(mainBody),
      '(g) Section 90 is registered through a closure in main()');
    pass('(final) Section 90: read warns/marks, write refuses, fail-open untouched, single source of schema logic');
  } finally { cleanup(dir); }
}

// ── Section 91: nenhum byte de controle inesperado em scripts/*.js ─────────
// Regressão que isto trava: um byte NUL (ou VT/FF) cru no fonte. Dois deles
// viviam em scripts/forge-memory-index.js e um em forge-review-diff.test.js —
// invisíveis na leitura, mas suficientes para o git e o grep classificarem o
// arquivo inteiro como BINÁRIO. O efeito não é cosmético: `grep` para de
// mostrar as linhas, o diff da PR vira "Binary file … differs", e a revisão
// perde o arquivo de vista exatamente onde ele deveria ser lido. O conserto é
// o escape de duas letras (\0); esta seção existe para que o byte cru não
// volte. Também vale para 0x0b/0x0c — a regra do `\f` no install.ps1 (ver
// CLAUDE.md) é a mesma classe de defeito, com a mesma causa: um escape que
// virou byte na hora de escrever o arquivo.
//
// Esta seção NUNCA escreve um byte de controle literal no próprio fonte: o
// fixture de mordida monta o byte com String.fromCharCode em runtime, senão
// forge-smoke.js seria o próximo arquivo a se auto-flagrar.
const CONTROL_BYTES = new Map([[0x00, 'NUL (0x00)'], [0x0b, 'VT (0x0b)'], [0x0c, 'FF (0x0c)']]);
const CONTROL_BYTE_FLOOR = 50; // scripts/ tem ~170 .js; 0 varridos é falha, não passe limpo

// { ok, scanned, violations: [{ file, byte, offset }] }
function scanControlBytes(rootDir, opts) {
  const floor = (opts && opts.floor) || CONTROL_BYTE_FLOOR;
  const { collectFiles } = require('./forge-doc-claims.js');
  const files = collectFiles(rootDir, { extensions: ['.js'] });
  const violations = [];
  let scanned = 0;
  for (const file of files) {
    let buf;
    try { buf = fs.readFileSync(file); } catch { continue; } // ilegível: não conta como varrido
    scanned++;
    for (let i = 0; i < buf.length; i++) {
      const label = CONTROL_BYTES.get(buf[i]);
      if (label) violations.push({ file, byte: label, offset: i });
    }
  }
  // Piso anti-silêncio (padrão de forge-doc-claims.js): "0 violações" e
  // "0 arquivos varridos" precisam ser distinguíveis — um scanner apontado
  // para o diretório errado deve ficar VERMELHO, não verde.
  const ok = violations.length === 0 && scanned >= floor;
  return { ok, scanned, floor, violations };
}

function smokeControlBytes() {
  process.stdout.write('\n▸ Section 91: bytes de controle inesperados em scripts/*.js\n');

  // (a) a árvore real está limpa E acima do piso — a asserção de aceitação.
  const real = scanControlBytes(SCRIPTS);
  assert(real.scanned >= real.floor,
    `(a) scanned (${real.scanned}) >= piso anti-silêncio (${real.floor})`);
  assert(real.violations.length === 0,
    '(a) scripts/*.js não contém 0x00/0x0b/0x0c',
    JSON.stringify(real.violations.slice(0, 5).map(v => `${path.basename(v.file)}@${v.offset}:${v.byte}`)));
  assert(real.ok === true, '(a) varredura real: ok === true');

  const dir = mkTmp('control-bytes');
  try {
    const file = path.join(dir, 'injected.js');
    // (b) mordida: com o byte cru, VERMELHO.
    fs.writeFileSync(file, `const key = 'a'${String.fromCharCode(0)}'b';\n`, 'utf8');
    const dirty = scanControlBytes(dir, { floor: 1 });
    assert(dirty.ok === false, '(b) fixture com NUL cru: ok === false (mordida observada)');
    assert(dirty.violations.length === 1 && dirty.violations[0].byte === 'NUL (0x00)',
      '(b) fixture com NUL cru: a violação é reportada com o byte nomeado', JSON.stringify(dirty.violations));

    // (c) com o escape de duas letras no lugar, VERDE — as duas direções.
    fs.writeFileSync(file, 'const key = \'a\' + \'\\0\' + \'b\';\n', 'utf8');
    const clean = scanControlBytes(dir, { floor: 1 });
    assert(clean.ok === true, '(c) fixture com o escape \\0: ok === true (verde restaurado)', JSON.stringify(clean.violations));

    // (d) o piso morde sozinho: diretório vazio é FALHA, não passe limpo.
    const empty = mkTmp('control-bytes-empty');
    try {
      const none = scanControlBytes(path.join(empty, 'nao-existe'));
      assert(none.ok === false && none.scanned === 0,
        '(d) diretório inexistente: 0 varridos é falha (piso anti-silêncio morde)', JSON.stringify(none));
    } finally { cleanup(empty); }
  } finally { cleanup(dir); }

  // (e) auto-registro em main() — impede desfiar a seção em silêncio.
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeControlBytes\(\); \}/.test(mainBody),
    '(e) Section 91 is registered through a closure in main()');

  pass('(final) Section 91: nenhum 0x00/0x0b/0x0c em scripts/*.js, acima do piso anti-silêncio, ' +
    'com mordida e volta ao verde provadas no fixture');
}

// ── Section 92: guard de drift do schema pinado do app-server ─────────────
// O fixture começa na projeção pequena do pin, não no schema bruto gerado pelo
// app-server. Isso mantém o smoke determinístico e ainda atravessa a CLI real,
// que é a fronteira usada pelo orquestrador.
function smokeAppServerSchemaPin() {
  process.stdout.write('\n▸ Section 92: guard de drift do schema pinado do app-server\n');
  const dir = mkTmp('schema-pin');
  const root = path.dirname(SCRIPTS);
  const pin = JSON.parse(fs.readFileSync(path.join(root, 'shared', 'schemas', 'codex-appserver-pin.json'), 'utf8'));
  const schemaFile = 'codex_app_server_protocol.v2.schemas.json';
  const projectedFiles = {
    TurnStartParams: path.join('v2', 'TurnStartParams.json'),
    ItemCompletedNotification: path.join('v2', 'ItemCompletedNotification.json'),
    TurnCompletedNotification: path.join('v2', 'TurnCompletedNotification.json'),
    JSONRPCError: 'JSONRPCError.json',
  };

  const writeJson = (file, value) => {
    const target = path.join(dir, file);
    fs.mkdirSync(path.dirname(target), { recursive: true });
    fs.writeFileSync(target, `${JSON.stringify(value, null, 2)}\n`, 'utf8');
  };
  const projectedType = (name, value) => ({
    title: value.title || name,
    type: value.type || 'object',
    required: value.required || [],
    properties: value.properties || {},
  });
  // The fixture carries the referenced closure too: the roots are all-`$ref`, so an
  // aggregate holding only ThreadItem would leave every pointer unresolved.
  const writeFixture = (mutate) => {
    const definitions = JSON.parse(JSON.stringify(pin.definitions));
    const referenced = JSON.parse(JSON.stringify(pin.referenced));
    if (mutate) mutate(definitions, referenced);
    writeJson(schemaFile, { definitions: { ThreadItem: definitions.ThreadItem, ...referenced } });
    for (const [name, file] of Object.entries(projectedFiles)) {
      writeJson(file, projectedType(name, definitions[name]));
    }
  };
  const reorder = (value, parentKey) => {
    if (Array.isArray(value)) {
      const items = value.map((item) => reorder(item));
      return parentKey === 'required' && items.every((item) => typeof item === 'string')
        ? items.reverse() : items;
    }
    if (!value || typeof value !== 'object') return value;
    return Object.fromEntries(Object.entries(value).reverse().map(([key, child]) => [key, reorder(child, key)]));
  };
  const check = (extraArgs, env) => {
    const result = runScript('forge-schema-pin.js', ['--check', '--json', ...extraArgs], { env: { ...process.env, ...env } });
    let json = null;
    try { json = JSON.parse(result.stdout); } catch {}
    return { ...result, json };
  };
  try {
    // (a) object keys and required arrays are ordering noise, not drift.
    // On its own this case cannot fail: it applies exactly the two transformations
    // canonicalize implements, so it is a tautology unless something pins down what
    // the fixture actually did. Two things do. First, the reordering must be REAL —
    // a no-op `reorder` would make the green meaningless. Second, case (a2) below
    // reorders an array whose order IS semantic, and must come out red: together the
    // pair states that the green in (a) is a claim about one bounded, closed set of
    // noise, and shows where that set ends.
    writeFixture((definitions, referenced) => {
      for (const name of Object.keys(definitions)) definitions[name] = reorder(definitions[name]);
      for (const name of Object.keys(referenced)) referenced[name] = reorder(referenced[name]);
    });
    const rawReordered = fs.readFileSync(path.join(dir, schemaFile), 'utf8');
    assert(rawReordered !== JSON.stringify({ definitions: { ThreadItem: pin.definitions.ThreadItem, ...pin.referenced } }, null, 2) + '\n'
      && /"required": \[\s*"type"/.test(rawReordered),
      '(a0) a fixture reordenada difere byte a byte da projeção pinada (o caso (a) não é no-op)');
    const reordered = check(['--schema-dir', dir]);
    assert(reordered.status === 0 && reordered.json && reordered.json.outcome === 'match',
      '(a) fixture reordenada preserva match (B1)', JSON.stringify(reordered.json));

    // (a2) the bite of (a): oneOf order is semantic, so canonicalize must NOT absorb it.
    writeFixture((definitions) => {
      definitions.ThreadItem.oneOf = definitions.ThreadItem.oneOf.slice().reverse();
    });
    const resorted = check(['--schema-dir', dir]);
    assert(resorted.status !== 0 && resorted.json && resorted.json.outcome === 'drift',
      '(a2) reordenar oneOf (ordem semântica) rende drift — a tolerância de (a) tem fronteira',
      JSON.stringify(resorted.json));

    // (b) a renamed field must name the exact removed path in the JSON result.
    writeFixture((definitions) => {
      const variant = definitions.ThreadItem.oneOf.find((item) => item.title === 'CommandExecutionThreadItem');
      variant.properties.exit_code = variant.properties.exitCode;
      delete variant.properties.exitCode;
    });
    const renamed = check(['--schema-dir', dir]);
    const renamedPaths = (renamed.json && renamed.json.fields || []).map((field) => field.path);
    assert(renamed.status !== 0 && renamed.json && renamed.json.outcome === 'drift'
      && renamedPaths.includes('definitions.ThreadItem.oneOf[5].properties.exitCode'),
      '(b) rename rende drift e nomeia definitions.ThreadItem.oneOf[5].properties.exitCode',
      JSON.stringify(renamed.json));

    // (b2) THE R1 CASE. The roots keep `properties` verbatim, and those properties are
    // `$ref` pointers, so a change INSIDE a referenced type leaves every root byte-
    // identical. Measured before the closure existed: renaming SandboxPolicy.networkAccess
    // and replacing CommandExecutionStatus' enum both returned `match`, exit 0 — and
    // networkAccess is the exact field premise A2 was executed to prove, while
    // commandExecution.status is what S04/S06 read. Without this case the closure is
    // unverified, and cases (a)–(d) all pass on a pin that sees none of it.
    writeFixture((definitions, referenced) => {
      referenced.SandboxPolicy = JSON.parse(JSON.stringify(referenced.SandboxPolicy).replace(/networkAccess/g, 'network_access'));
      referenced.CommandExecutionStatus = { enum: ['totally', 'different'], type: 'string' };
    });
    const inner = check(['--schema-dir', dir]);
    const innerPaths = (inner.json && inner.json.fields || []).map((field) => field.path);
    assert(inner.status !== 0 && inner.json && inner.json.outcome === 'drift'
      && innerPaths.some((p) => p.startsWith('referenced.SandboxPolicy') && p.endsWith('networkAccess'))
      && innerPaths.some((p) => p.startsWith('referenced.CommandExecutionStatus.enum'))
      && inner.json.counts.referenced_compared > 0,
      '(b2) mutação DENTRO de um tipo referenciado rende drift nomeando referenced.SandboxPolicy…networkAccess e referenced.CommandExecutionStatus.enum (R1)',
      JSON.stringify(inner.json));

    // (c) inability to invoke the generator is explicitly not a clean result.
    const missing = check([], { FORGE_SCHEMA_PIN_CODEX_BIN: path.join(dir, 'does-not-exist') });
    assert(missing.status !== 0 && missing.json && missing.json.outcome === 'generator-missing'
      && missing.json.outcome !== 'match',
      '(c) binário ausente rende generator-missing, nunca match (D8)',
      JSON.stringify(missing.json));

    // (c2) the same floor on the guard's OWN input. An absent or truncated pin used to
    // leave through an uncaught readJson/JSON.parse, printing a stack trace that parses
    // as neither match nor drift — every generator-side error had a named outcome and
    // the pin side had none. "Could not read the pin" is never "no drift" (D8).
    writeFixture();
    const truncated = path.join(dir, 'truncated-pin.json');
    fs.writeFileSync(truncated, '{ "definitions": ', 'utf8');
    for (const [label, pinFile] of [['truncado', truncated], ['ausente', path.join(dir, 'no-such-pin.json')]]) {
      const unreadable = check(['--schema-dir', dir], { FORGE_SCHEMA_PIN_FILE: pinFile });
      assert(unreadable.status !== 0 && unreadable.json && unreadable.json.outcome === 'pin-unreadable'
        && unreadable.json.outcome !== 'match' && unreadable.json.outcome !== 'drift'
        && unreadable.json.counts.definitions_compared === 0,
        `(c2) pin ${label} rende pin-unreadable dentro do enum fechado, nunca match (D8/R6)`,
        JSON.stringify(unreadable.json) + ' | stderr=' + String(unreadable.stderr).slice(0, 200));
    }

    // (d) an upstream ThreadItem variant changes the measured oneOf shape.
    writeFixture((definitions) => {
      definitions.ThreadItem.oneOf.push({
        title: 'FutureThreadItem', type: 'object', required: ['id', 'type'],
        properties: { id: { type: 'string' }, type: { enum: ['futureThreadItem'], type: 'string' } },
      });
    });
    const extra = check(['--schema-dir', dir]);
    const extraPaths = (extra.json && extra.json.fields || []).map((field) => field.path);
    assert(extra.status !== 0 && extra.json && extra.json.outcome === 'drift'
      && extraPaths.includes('definitions.ThreadItem.oneOf[18]'),
      '(d) 19ª variante rende drift nomeando definitions.ThreadItem.oneOf[18]',
      JSON.stringify(extra.json));

    // (e) exercise generation against the installed binary when available.
    const codex = spawnSync('codex', ['--version'], { encoding: 'utf8', stdio: ['ignore', 'ignore', 'ignore'] });
    if (codex.status === 0) {
      const live = check([]);
      assert(live.status === 0 && live.json && live.json.outcome === 'match',
        '(e) live codex app-server schema matches the pin', JSON.stringify(live.json));
    } else {
      skip('(e) live codex schema check', 'codex binary not installed — live check coberto pelas fixtures');
    }

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeAppServerSchemaPin\(\); \}/.test(mainBody),
      '(g) Section 92 is registered through a closure in main()');
    pass('(final) Section 92: reordenação verde com fronteira provada, rename/variante/tipo-referenciado nomeados, generator-missing e pin-unreadable distintos de match, live verificado');
  } finally { cleanup(dir); }
}

// ── Section 93: transporte app-server do execute, ponta a ponta ─────────────
// A Seção 92 prova o SCHEMA pinado; esta prova o TRANSPORTE: a CLI real
// (`forge-xllm.js --mode execute`) conversando com um app-server mockado, a
// degradação nomeada nas DUAS direções, a tolerância do caminho `agy` a um
// cliente de sessão envenenado (IN-15) e a permanência de `extractLastJsonBlock`
// (D9). Desde M018 S05 T02 a varredura também prova a AUSÊNCIA: `runPlan` migrou
// para o app-server e não tem mais call site de `invokeCodexDetached` — o assert
// (d) inverteu de `>= 1` para `=== 0`, e o controle sintético de (e) inverteu
// junto (fonte COM o call site, para provar que o scanner ainda acusa a
// presença). Um scanner que só sabe dizer "sim" é o defeito que esta milestone
// existe para eliminar; um que só sabe dizer "não" também.

// Mock do app-server no molde da suíte reparada da T03 (forge-xllm-appserver.test.js):
// programa Node puro — nada de shell, quoting ou utilitário POSIX no fixture do
// protocolo — lançado via FORGE_XLLM_CODEX_BIN.
function writeMockAppServer(dir) {
  const source = String.raw`'use strict';
const scenario = process.env.FORGE_MOCK_SCENARIO || 'conforming';
// Watchdog: um mock que trava apaga o sinal da suíte inteira (medido: >600s, 0
// bytes de saída, S02 T02). Falhar alto é sempre melhor que pendurar.
const WATCHDOG_MS = Number(process.env.FORGE_MOCK_APPSERVER_TIMEOUT_MS || 30000);
const watchdog = setTimeout(() => {
  process.stderr.write('mock app-server: watchdog ' + WATCHDOG_MS + 'ms sem turn completo\n');
  process.exit(89);
}, WATCHDOG_MS);
let initialized = false;
function send(value) { process.stdout.write(JSON.stringify(value) + '\n'); }
function result() {
  return { status: 'done', summary: 'section 93 result', must_haves_status: [], files_changed: [] };
}
function answer() {
  if (scenario === 'narrated') {
    return 'Narrating the work first.\nHere is the result:\n' + JSON.stringify(result()) + '\nDone.';
  }
  return JSON.stringify(result());
}
let pending = '';
process.stdin.setEncoding('utf8');
process.stdin.on('data', (chunk) => {
  pending += chunk;
  let end;
  while ((end = pending.indexOf('\n')) >= 0) {
    const line = pending.slice(0, end); pending = pending.slice(end + 1);
    if (!line.trim()) continue;
    const message = JSON.parse(line);
    // O dialeto do app-server OMITE o membro jsonrpc (M018/T01/MEM001).
    if (Object.prototype.hasOwnProperty.call(message, 'jsonrpc')) process.exit(91);
    if (message.method === 'initialize') send({ id: message.id, result: { serverInfo: { name: 'smoke-93' } } });
    else if (message.method === 'initialized') initialized = true;
    else if (message.method === 'thread/start') {
      if (!initialized) process.exit(92);
      send({ id: message.id, result: { thread: { id: 'thread-93' } } });
    } else if (message.method === 'turn/start') {
      if (!initialized) process.exit(93);
      clearTimeout(watchdog);
      send({ id: message.id, result: { turn: { id: 'turn-93' } } });
      // Extra ThreadItems, opt-in via env, so Section 95 can drive a REAL item
      // stream through the real adapter without a second mock (the Standards of
      // T04 name this file as the single source). Unset env => byte-identical
      // behaviour for Section 93, which is why the branch is env-gated and not a
      // new parameter threaded through every caller.
      const extra = process.env.FORGE_MOCK_EXTRA_ITEMS;
      if (extra) {
        for (const item of JSON.parse(extra)) send({ method: 'item/completed', params: { item: item } });
      }
      send({ method: 'item/completed', params: { item: { type: 'agentMessage', phase: 'final_answer', text: answer() } } });
      send({ method: 'turn/completed', params: { turn: { id: 'turn-93', status: 'completed' } } });
      setTimeout(() => process.exit(0), 50);
    }
  }
});
setInterval(() => {}, 1000);
`;
  const file = path.join(dir, 'mock-app-server.js');
  fs.writeFileSync(file, source, 'utf8');
  return file;
}

// Varredura IN-PROCESS de scripts/forge-xllm.js: `fs.readFileSync`, zero
// shell-out. O `grep` deste shell é uma função sobre `ugrep --ignore-files`, que
// honra .gitignore — não serve como prova (achado da S06). Contagem exata via
// split(NEEDLE).length-1, nunca includes() sobre o documento inteiro.
// Needle ASSEMBLED, never spelled out: this file is the live harness that proves
// the retired transport's absence (Section 96 scans the REAL repo through the T03
// scanner), so a literal call-form spelling here would make the hunter count as
// its own prey — the same reason forge-exec-callsites.js excludes its own fixture
// files by basename ("permanent, unfixable noise, never a real violation"). The
// assembly changes only the spelling INSIDE the hunter, never the predicate:
// Section 96 (b) proves the predicate still fires on the real spelling, from a
// fixture written to disk.
const DETACHED_NEEDLE = `invokeCodexDetached${'('}`;
const RETIRED_PHRASE = `codex ${'ex'}ec`;
const EXEC_ARG_TOKEN = `${'ex'}ec`;

function scanXllmContracts(source) {
  const count = (haystack, needle) => haystack.split(needle).length - 1;
  const between = (start, end) => {
    const from = source.indexOf(start);
    if (from < 0) return '';
    const to = end ? source.indexOf(end, from + start.length) : -1;
    return to < 0 ? source.slice(from) : source.slice(from, to);
  };
  const exportsBlock = between('module.exports = {', '};');
  const executeBody = between('async function runExecute(', '\nasync function ');
  const planBody = between('async function runPlan(', '\nmodule.exports');
  const lines = source.split('\n');
  // Top-level = coluna 0: um require fora de corpo de função carrega o cliente de
  // sessão em TODO consumidor do adapter, inclusive o caminho agy (IN-15).
  const clientRequire = /require\(['"]\.\/forge-appserver-client(\.js)?['"]\)/;
  let topLevelClientRequires = 0;
  let lazyClientRequires = 0;
  for (const line of lines) {
    if (!clientRequire.test(line)) continue;
    if (/^\S/.test(line)) topLevelClientRequires += 1; else lazyClientRequires += 1;
  }
  return {
    exportsExtractLastJsonBlock: count(exportsBlock, 'extractLastJsonBlock'),
    executeExtractCallSites: count(executeBody, 'extractLastJsonBlock('),
    planDetachedCallSites: count(planBody, DETACHED_NEEDLE),
    planAppServerCallSites: count(planBody, 'invokeCodexAppServer('),
    topLevelClientRequires,
    lazyClientRequires,
  };
}

async function smokeAppServerTransport() {
  process.stdout.write('\n▸ Section 93: transporte app-server do execute (e2e, degradação, IN-15, D9)\n');

  const dir = mkTmp('appserver-transport');
  // S06 review R12: declared OUTSIDE the try so the `finally` can reach them.
  // They used to be cleaned by the last statement INSIDE each block, so any red
  // assert leaked a git repo per run — and a dirty tree is load-bearing here
  // (cleanupWorktreeOne refuses --force on one). Same declare-outside pattern
  // this same diff already uses in Sections 94 and 95.
  let happyRepo = null;
  let narratedRepo = null;
  let agyDir = null;
  let agyRepo = null;
  let poisonedRepo = null;
  try {
    const mock = writeMockAppServer(dir);
    const planFile = path.join(dir, 'T93-PLAN.md');
    fs.writeFileSync(planFile, '# T93\nexecute fixture for the app-server transport\n', 'utf8');

    const runExecuteCli = (repo, resultFile, extraEnv) => {
      const env = {
        ...process.env,
        FORGE_XLLM_CODEX_BIN: mock,
        FORGE_MOCK_SCENARIO: (extraEnv && extraEnv.FORGE_MOCK_SCENARIO) || 'conforming',
        ...(extraEnv || {}),
      };
      const r = spawnSync(process.execPath, [
        path.join(SCRIPTS, 'forge-xllm.js'), '--mode', 'execute',
        '--plan', planFile, '--result-file', resultFile, '--cwd', repo, '--timeout', '20',
      ], { encoding: 'utf8', cwd: repo, env });
      let parsed = null;
      try { parsed = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch { /* leave null */ }
      return { status: r.status, stdout: r.stdout || '', stderr: r.stderr || '', parsed };
    };

    // (a) e2e pela CLI: o transporte completa e o result-file nomeia o caminho
    // de parse. O happy path NÃO pode carregar `degradation` — é a metade
    // "verde" da mordida bidirecional.
    {
      happyRepo = mkGitRepo(mkTmp('appserver-transport-happy'));
      const resultFile = path.join(dir, 'happy-result.json');
      const r = runExecuteCli(happyRepo, resultFile);
      assert(r.status === 0, '(a) execute via app-server pela CLI sai 0', `status=${r.status} stderr=${r.stderr}`);
      assert(!!r.parsed && r.parsed.status === 'done' && r.parsed.parse_path === 'output-schema',
        '(a) result-file traz parse_path=output-schema', JSON.stringify(r.parsed));
      assert(!!r.parsed && !Object.prototype.hasOwnProperty.call(r.parsed, 'degradation'),
        '(a) happy path NÃO emite degradation (mordida na direção verde)', JSON.stringify(r.parsed));
      assert(!!r.parsed && r.parsed.appserver && typeof r.parsed.appserver.discarded_count === 'number',
        '(a) diagnostics do app-server chegam ao result-file', JSON.stringify(r.parsed && r.parsed.appserver));
    }

    // (b) degradação nomeada (IN-6/D9): a MESMA CLI, o MESMO mock, só a resposta
    // narrada — parse_path muda e `degradation` aparece. Sem (a), este assert não
    // provaria que o campo distingue alguma coisa.
    {
      narratedRepo = mkGitRepo(mkTmp('appserver-transport-narrated'));
      const resultFile = path.join(dir, 'narrated-result.json');
      const r = runExecuteCli(narratedRepo, resultFile, { FORGE_MOCK_SCENARIO: 'narrated' });
      assert(r.status === 0, '(b) resposta narrada ainda completa (degradação, não falha)', `status=${r.status} stderr=${r.stderr}`);
      assert(!!r.parsed && r.parsed.parse_path === 'extract-last-json-block',
        '(b) parse_path=extract-last-json-block no caminho degradado', JSON.stringify(r.parsed));
      assert(!!r.parsed && r.parsed.degradation === 'output-schema-not-honored',
        "(b) degradation === 'output-schema-not-honored'", JSON.stringify(r.parsed));
      assert(/outputSchema degraded/.test(r.stderr),
        '(b) a degradação também é dita em stderr', `stderr=${r.stderr}`);
    }

    // (c) IN-15 com controle positivo: um preload faz o require de
    // forge-appserver-client LANÇAR. O caminho agy completa mesmo assim (nunca
    // carrega código de sessão) e o MESMO veneno derruba o execute codex — sem o
    // controle, (c1) passaria num mundo onde o shim não morde nada.
    {
      const poison = path.join(dir, 'poison-preload.js');
      fs.writeFileSync(poison, [
        "'use strict';",
        "const Module = require('module');",
        'const load = Module._load;',
        'Module._load = function (request) {',
        "  if (String(request).includes('forge-appserver-client')) {",
        "    throw new Error('poisoned: forge-appserver-client loaded on a path that must not need it');",
        '  }',
        // eslint-disable-next-line prefer-rest-params — o preload precisa repassar a assinatura original
        '  return load.apply(this, arguments);',
        '};',
        '',
      ].join('\n'), 'utf8');
      const nodeOptions = `--require "${poison.replace(/\\/g, '/')}"`;

      agyDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-93-agy-'));
      agyRepo = mkTmp('appserver-transport-agy');
      const agyPayload = JSON.stringify({
        objections: [{ id: 'R1', path_line: 'src/a.js:12', claim: 'x', suggested_fix: 'y', challenge: 'z?', severity: 'high' }],
      });
      const agyMock = writeMockAgy(agyDir, { payload: agyPayload, exitCode: 0 });
      const agy = runXllm(['--mode', 'challenge', '--engine', 'agy', '--diff-cmd', 'echo diff', '--cwd', agyRepo],
        null, agyRepo, { FORGE_XLLM_AGY_BIN: agyMock, NODE_OPTIONS: nodeOptions });
      assert(agy.status === 0, '(c1) IN-15: challenge --engine agy completa COM o cliente envenenado',
        `status=${agy.status} stderr=${agy.stderr}`);

      poisonedRepo = mkGitRepo(mkTmp('appserver-transport-poisoned'));
      const poisonedResult = path.join(dir, 'poisoned-result.json');
      const poisoned = runExecuteCli(poisonedRepo, poisonedResult, { NODE_OPTIONS: nodeOptions });
      assert(poisoned.status !== 0, '(c2) controle positivo: o MESMO veneno derruba o execute codex',
        `status=${poisoned.status} stderr=${poisoned.stderr}`);
      assert(/poisoned: forge-appserver-client/.test(poisoned.stderr),
        '(c2) o erro nomeia o require envenenado (o shim mordeu de fato)', `stderr=${poisoned.stderr}`);
    }

    // (d) D9/IN-6 + ausência do transporte exec em runPlan, por varredura
    // in-process do adapter real.
    const xllmSource = fs.readFileSync(path.join(SCRIPTS, 'forge-xllm.js'), 'utf8');
    const scan = scanXllmContracts(xllmSource);
    assert(scan.exportsExtractLastJsonBlock >= 1,
      '(d) D9: extractLastJsonBlock permanece em module.exports', JSON.stringify(scan));
    assert(scan.executeExtractCallSites >= 1,
      '(d) D9: extractLastJsonBlock tem call site no caminho de execute', JSON.stringify(scan));
    assert(scan.topLevelClientRequires === 0 && scan.lazyClientRequires >= 1,
      '(d) IN-15: o require de forge-appserver-client é lazy (0 no topo, >= 1 em função)', JSON.stringify(scan));
    assert(scan.planDetachedCallSites === 0,
      '(d) runPlan não tem mais call site de invokeCodexDetached (S05 migrou)', JSON.stringify(scan));
    assert(scan.planAppServerCallSites >= 1,
      '(d) runPlan alcança o app-server (invokeCodexAppServer tem call site no corpo)', JSON.stringify(scan));

    // (e) mordida do próprio scanner: nas fontes sintéticas abaixo cada asserção
    // de (d) TEM de virar falsa. Um scanner que só sabe dizer "sim" é o defeito
    // que esta milestone existe para eliminar.
    {
      const stripped = [
        "const x = require('./forge-appserver-client');",
        'async function runExecute(o) { return JSON.parse(o); }',
        // INVERTIDO em M018 S05 T02: antes esta fonte NÃO tinha o call site e
        // provava que o scanner acusa a ausência. Agora o adapter real é o que
        // não o tem, então a fonte sintética precisa TÊ-LO para provar que o
        // scanner ainda acusa a PRESENÇA — e que o `=== 0` de (d) é um fato
        // medido, não um predicado que perdeu a mordida.
        `async function runPlan(o) { return ${DETACHED_NEEDLE}o); }`,
        'module.exports = { runExecute };',
        '',
      ].join('\n');
      const bitten = scanXllmContracts(stripped);
      assert(bitten.exportsExtractLastJsonBlock === 0 && bitten.executeExtractCallSites === 0,
        '(e) fonte sem extractLastJsonBlock: o scanner acusa (D9 morde)', JSON.stringify(bitten));
      assert(bitten.topLevelClientRequires === 1 && bitten.lazyClientRequires === 0,
        '(e) require no topo é contado como top-level (IN-15 morde)', JSON.stringify(bitten));
      assert(bitten.planDetachedCallSites === 1 && bitten.planAppServerCallSites === 0,
        '(e) runPlan COM invokeCodexDetached: o scanner acusa a presença (e não vê app-server)', JSON.stringify(bitten));
    }

    // R6 (nenhum mirror tocado) é acceptance DA SLICE, verificada pelo orquestrador
    // contra o diff do branch — deliberadamente fora daqui: uma asserção sobre a
    // working tree do momento viraria mina para qualquer slice futura que edite
    // skills/ legitimamente, e um smoke vermelho por isso não diria nada sobre o
    // transporte que esta seção existe para provar.

    // (g) auto-registro em main() por closure — a Section 73 rejeita chamada bare,
    // e uma seção não registrada é uma seção que some em silêncio.
    const selfSource = fs.readFileSync(__filename, 'utf8');
    const mainBody = selfSource.slice(selfSource.lastIndexOf('async function main()'));
    // Strict form only. The second alternative was a SUBSTRING of the first, so the
    // disjunction accepted a bare call in main() — the very form Section 73 rejects,
    // and the form Sections 92/94 assert against (S03 review R9).
    assert(/\(\) => \{ await smokeAppServerTransport\(\); \}/.test(mainBody),
      '(g) Section 93 is registered through a closure in main()');

    pass('(final) Section 93: execute completa pela CLI via app-server, degradação nomeada nas duas direções, '
      + 'IN-15 provado com controle positivo, D9 e a AUSÊNCIA do exec em runPlan verificados por varredura in-process com mordida');
  } finally {
    for (const leaked of [happyRepo, narratedRepo, agyDir, agyRepo, poisonedRepo]) {
      if (leaked) cleanup(leaked);
    }
    cleanup(dir);
  }
}

// ── Section 94: capability por turn do app-server ─────────────────────────
// This fixture is deliberately a wire observer: writeMockCodex records the
// actual turn/start params that arrived over JSONL, so each direction can fail
// independently of the adapter's own return value.
async function smokeCapabilityPerTurn() {
  process.stdout.write('\n▸ Section 94: capability por turn (mock app-server + guidance)\n');
  const dir = mkTmp('capability-per-turn');
  const { buildExecutePrompt, buildPlanPrompt } = require('./forge-xllm');
  const expectedPolicies = {
    readonly: { type: 'readOnly', networkAccess: false },
    workspace: { type: 'workspaceWrite', networkAccess: false },
    networked: { type: 'workspaceWrite', networkAccess: true },
  };
  const planText = (capability) => [
    '---',
    'id: T94',
    'slice: S03',
    'milestone: M018',
    'title: capability fixture',
    ...(capability === null ? [] : [`capability: ${capability}`]),
    'must_haves:',
    '  truths:',
    '    - "fixture truth"',
    '  artifacts: []',
    '  key_links: []',
    '  expected_output: []',
    '---',
    '# fixture',
    '',
  ].join('\n');
  // Declared OUTSIDE the try so the finally can reach them: cleanup(mockDir) and
  // cleanup(repo) used to be the last statements INSIDE the try, so any red assert
  // leaked a mock dir and a git repo per run — and a dirty tree is load-bearing here
  // (cleanupWorktreeOne refuses --force on one) (S03 review R11).
  let mockDir = null;
  let repo = null;
  try {
    mockDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-94-mock-'));
    repo = mkGitRepo(mkTmp('capability-per-turn-repo'));
    const payload = JSON.stringify({ status: 'done', summary: 'section 94', must_haves_status: [], files_changed: [] });
    const runFixture = (name, capability) => {
      const plan = path.join(dir, `${name}-PLAN.md`);
      const result = path.join(dir, `${name}-result.json`);
      const observed = path.join(dir, `${name}-turn-start.json`);
      fs.writeFileSync(plan, planText(capability), 'utf8');
      writeMockCodex(mockDir, { payload, checkContract: true, turnStartFile: observed });
      const r = runXllm([
        '--mode', 'execute', '--engine', 'codex', '--plan', plan,
        '--result-file', result, '--cwd', repo, '--timeout', '20',
      ], mockDir, repo);
      let params = null;
      let parsed = null;
      try { params = JSON.parse(fs.readFileSync(observed, 'utf8')); } catch { /* assertion below names the missing observation */ }
      try { parsed = JSON.parse(fs.readFileSync(result, 'utf8')); } catch { /* assertion below names the missing result */ }
      return { r, params, parsed };
    };

    for (const [capability, expected] of Object.entries(expectedPolicies)) {
      const got = runFixture(capability, capability);
      assert(got.r.status === 0, `(a) ${capability}: execute mockado termina 0`, `stderr=${got.r.stderr}`);
      assert(!!got.params && JSON.stringify(got.params.sandboxPolicy) === JSON.stringify(expected),
        `(a) ${capability}: mock observou a sandboxPolicy correta no turn/start`, JSON.stringify(got.params));
    }

    const legacy = runFixture('legacy', null);
    const legacyLiteral = { type: 'workspaceWrite', networkAccess: false };
    assert(legacy.r.status === 0, '(b) plano legado sem capability termina 0', `stderr=${legacy.r.stderr}`);
    assert(!!legacy.params && JSON.stringify(legacy.params.sandboxPolicy) === JSON.stringify(legacyLiteral),
      '(b) plano legado preserva o literal exato workspaceWrite/networkAccess:false', JSON.stringify(legacy.params));

    const unknown = runFixture('banana', 'banana');
    assert(unknown.r.status === 0, '(c) capability desconhecida completa pela rota de downgrade', `stderr=${unknown.r.stderr}`);
    // O FIO, antes do auto-relato. Este era o único caso que lia só `parsed`: provava
    // que o adapter DIZ workspace sem provar que o turn enviado não carregava
    // networkAccess:true — a direção em que um bug de resolução é escape de sandbox
    // (S03 review R8).
    assert(!!unknown.params && JSON.stringify(unknown.params.sandboxPolicy) === JSON.stringify(legacyLiteral),
      '(c) o turn do downgrade carrega a policy de workspace no fio, não apenas no relato',
      JSON.stringify(unknown.params));
    assert(!!unknown.parsed && unknown.parsed.capability === 'workspace'
      && unknown.parsed.capability_declared === 'banana'
      && unknown.parsed.capability_event === 'capability-unrecognized',
    '(c) result-file expõe capability, declaração e evento capability-unrecognized', JSON.stringify(unknown.parsed));

    // W2: in-process document proof; restrict the counts to the one section so
    // a word elsewhere in the planner cannot satisfy the claim accidentally.
    const planner = fs.readFileSync(path.join(path.dirname(SCRIPTS), 'agents', 'forge-planner.md'), 'utf8');
    const marker = '## Capability Hints';
    const hints = planner.split(marker)[1] || '';
    const nextHeading = hints.search(/\n## /);
    const hintSection = nextHeading >= 0 ? hints.slice(0, nextHeading) : hints;
    assert(planner.split(marker).length - 1 === 1, '(d) agents/forge-planner.md tem exatamente uma seção Capability Hints');
    // Direção, não frequência. As contagens exatas ({readonly:4, workspace:6,
    // networked:6}) quebravam com qualquer reescrita inócua e passavam com a guidance
    // INVERTIDA de mesma contagem — asseriam que as palavras estão lá, nunca que dizem
    // a coisa certa (S03 review R10). Cada asserção abaixo lê a LINHA da tabela que
    // define a capability, então trocar duas posturas de lugar fica vermelho.
    const rowFor = (name) => (hintSection.split('\n').find((line) => line.trim().startsWith(`| \`${name}\``)) || '');
    for (const name of ['readonly', 'workspace', 'networked']) {
      assert(rowFor(name) !== '', `(d) Capability Hints tem a linha de tabela de ${name}`, hintSection);
    }
    assert(/no files/i.test(rowFor('readonly')) && !/network/i.test(rowFor('readonly')),
      '(d) readonly é definido por ausência de escrita, não por rede', rowFor('readonly'));
    assert(/default/i.test(rowFor('workspace')) && /no network|sem rede/i.test(rowFor('workspace')),
      '(d) workspace é o default e não concede rede', rowFor('workspace'));
    assert(/network/i.test(rowFor('networked')) && /install|fetch/i.test(rowFor('networked')),
      '(d) networked é a única postura que nomeia rede/install', rowFor('networked'));
    assert(/Emit only `readonly`, `workspace`, or `networked`/.test(hintSection),
      '(d) o conjunto fechado é declarado com os três valores exatos', hintSection);
    // R26: onde o campo vai. `tier:`/`effort:` dizem; `capability:` não dizia, e um
    // planner que o aninhasse sob must_haves produziria sandbox inerte SEM evento.
    assert(/top-level/i.test(hintSection) && /must_haves/.test(hintSection),
      '(d) a guidance diz que capability é chave top-level irmã de must_haves', hintSection);

    const workspacePrompt = buildExecutePrompt('# plan', { capability: 'workspace' });
    const networkedPrompt = buildExecutePrompt('# plan', { capability: 'networked' });
    const baselinePlanPrompt = buildPlanPrompt('context');
    assert(workspacePrompt.includes('Git reads are allowed') && workspacePrompt.includes('NEVER write with git'),
      '(e) buildExecutePrompt mantém a postura git bidirecional');
    assert(workspacePrompt.includes('The network is DISABLED') && !workspacePrompt.includes('Network access is ENABLED'),
      '(e) capability workspace produz linha de rede bloqueada');
    assert(networkedPrompt.includes('Network access is ENABLED') && !networkedPrompt.includes('The network is DISABLED'),
      '(e) capability networked produz linha de rede habilitada');
    assert(baselinePlanPrompt.includes('but you must NOT change anything.'),
      '(e) buildPlanPrompt permanece com postura legada read-only');

    // (f) ANTI-INERTE do guard turn↔thread (S05 review R10). A ligação entre o
    // turn e a thread emitida era gateada só por `initialized`, então um adapter
    // que ignorasse o threadId (ou o hardcodasse) ficava VERDE na suíte inteira
    // enquanto o app-server real rejeitava. Aqui o mock é dirigido DIRETAMENTE
    // por um cliente JSONL de fixture, sem passar pelo adapter, para que o guard
    // seja provado nas duas direções sem depender do que o adapter faz hoje.
    const driveMock = (turnStartMsg) => {
      const child = spawnSync(process.execPath, [path.join(mockDir, 'codex-mock.js'), 'app-server'], {
        input: [
          JSON.stringify({ id: 1, method: 'initialize', params: {} }),
          JSON.stringify({ method: 'initialized', params: {} }),
          JSON.stringify({ id: 2, method: 'thread/start', params: {} }),
          JSON.stringify(turnStartMsg),
          '',
        ].join('\n'),
        encoding: 'utf8',
        env: { ...process.env, FORGE_MOCK_APPSERVER_TIMEOUT_MS: '8000' },
        cwd: repo,
        timeout: 20000,
      });
      return child;
    };
    const wrongId = driveMock({ id: 3, method: 'turn/start', params: { threadId: 'thread-WRONG', input: [{ type: 'text', text: 'x' }] } });
    assert(wrongId.status === 94, '(f) turn/start com threadId errado morre com o código dedicado 94', `status=${wrongId.status} stderr=${wrongId.stderr}`);
    assert(/threadId mismatch/.test(String(wrongId.stderr)), '(f) o guard nomeia o mismatch em stderr', String(wrongId.stderr));

    const absentId = driveMock({ id: 3, method: 'turn/start', params: { input: [{ type: 'text', text: 'x' }] } });
    assert(absentId.status === 94, '(f) turn/start sem threadId também morre 94 — ausência não é passe livre', `status=${absentId.status} stderr=${absentId.stderr}`);

    // Controle positivo: o mesmo cliente, com o id EXATO que o thread/start
    // devolveu, atravessa o guard e chega ao runTurn (que roda a fixture sh e
    // sai 0). Sem isto, um guard que rejeitasse tudo passaria nos dois asserts
    // acima e quebraria o transporte inteiro sem ser notado.
    const rightId = driveMock({ id: 3, method: 'turn/start', params: { threadId: 'thread-smoke', input: [{ type: 'text', text: 'x' }], outputSchema: {}, sandboxPolicy: { type: 'workspaceWrite', networkAccess: false } } });
    assert(rightId.status === 0, '(f) controle positivo: o threadId correto atravessa o guard e o turn completa', `status=${rightId.status} stderr=${rightId.stderr}`);

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ await smokeCapabilityPerTurn\(\); \}/.test(mainBody),
      '(g) Section 94 is registered through a closure in main()');
    pass('(final) Section 94: três capabilities observadas no fio, legado byte-idêntico, downgrade visível, guidance/prompt provados e o vínculo turn↔thread provado nas duas direções');
  } finally {
    if (mockDir) cleanup(mockDir);
    if (repo) cleanup(repo);
    cleanup(dir);
  }
}

// ── Section 95: evidência runtime-observada (S04) ──────────────────────────
// A Seção 94 prova a POLICY que o turn carrega; esta prova o que o turn
// DEVOLVE virando evidência: admissibilidade por nome, rejeição de variante
// desconhecida, a contagem de 18 confrontada com o pin, os três desfechos do
// materializador distintos DOIS A DOIS, e a coexistência das duas `source` no
// mesmo arquivo.
//
// Varredura de documento é IN-PROCESS (`fs` + split exato), nunca `grep` de
// shell: o `grep` deste shell honra .gitignore e não serve como prova (S06).
// `includes()` sobre o documento inteiro também não conta — a pergunta aqui é
// "quantas vezes", e um mirror que invoca o materializador duas vezes escreveria
// dois censos para uma unidade, que é justamente o silêncio invertido.
const INVOKE_NEEDLE = 'node "$FORGE_SCRIPTS_DIR/forge-evidence-materialize.js"';

function scanEvidenceDocs(dispatchSource, mirrorSources) {
  const count = (haystack, needle) => haystack.split(needle).length - 1;
  const from = dispatchSource.indexOf('**7. Evidence lines into');
  let section7 = '';
  if (from >= 0) {
    const to = dispatchSource.indexOf('\n#### ', from);
    section7 = to < 0 ? dispatchSource.slice(from) : dispatchSource.slice(from, to);
  }
  const bIndex = section7.indexOf('**7b.');
  const part7b = bIndex < 0 ? '' : section7.slice(bIndex);
  const part7a = (() => {
    const aIndex = section7.indexOf('**7a.');
    if (aIndex < 0) return '';
    return bIndex > aIndex ? section7.slice(aIndex, bIndex) : section7.slice(aIndex);
  })();
  return {
    section7Found: from >= 0,
    parts7a: count(section7, '**7a.'),
    parts7b: count(section7, '**7b.'),
    runtimeObservedHeading: count(section7, '**7b. Runtime-observed lines'),
    // A afirmação de A7 é sobre a evidência NOVA: o 7b não pode chamá-la de
    // sintetizada. O 7a continua devendo chamar — as duas metades abaixo são a
    // mordida nas duas direções da mesma varredura.
    synthesizedIn7b: count(part7b, 'ynthesized'),
    synthesizedIn7a: count(part7a, 'ynthesized'),
    runtimeSourceIn7b: count(part7b, 'codex-runtime'),
    // INVOCAÇÃO, não menção. O 7b nomeia o script duas vezes de propósito — uma
    // no bloco de comando e outra na prosa que o declara dono da fórmula — então
    // contar o nome mede a redação, não o número de vezes que o materializador
    // roda. A pergunta que importa ("quantos censos uma unidade gera") só é
    // respondida pela linha de comando. Medido: contar o nome dava 2 no §7b real.
    materializeIn7b: count(part7b, INVOKE_NEEDLE),
    mentionsIn7b: count(part7b, 'forge-evidence-materialize.js'),
    mirrorInvocations: mirrorSources.map((source) => count(source, INVOKE_NEEDLE)),
    // S06 review R9: a contagem sozinha não diz ONDE. Invocado só no passo
    // Success, a terceira linha da tabela canônica (result-file ilegível →
    // collector-failed) era INALCANÇÁVEL de todo call site — uma linha que
    // documenta um detector que nada consegue disparar. A invocação tem de
    // pousar ANTES do split Success/Failure, isto é, antes do primeiro
    // `**Success` do mirror. -1 em qualquer um dos dois é reportado como -1,
    // nunca coagido a "está tudo bem".
    mirrorInvokeBeforeSuccess: mirrorSources.map((source) => {
      const invoke = source.indexOf(INVOKE_NEEDLE);
      const success = source.indexOf('**Success');
      return { invoke, success, ok: invoke >= 0 && success >= 0 && invoke < success };
    }),
  };
}

function smokeEvidenceRuntime() {
  process.stdout.write('\n▸ Section 95: evidência runtime-observada (admissibilidade, rejeição, contagem confrontada, 3 desfechos, coexistência, §7)\n');
  const {
    evidenceFileName, SOURCE, LEGACY_SOURCE, CENSUS_KIND,
  } = require('./forge-evidence-materialize');

  // `mkTmp` seeds only `.gsd/forge`, and `forge` is NOT a WORK_ENTRY — so the
  // directory is not a project. Since PR #94 the materializer (and the hook)
  // REFUSE to write when no owner resolves, rather than manufacturing an
  // orphan `.gsd/` (S01 review R1 / D-S01-1). That refusal is the invariant,
  // not the bug: these scenarios have to hand it a real project. Seeding one
  // WORK_ENTRY is the whole difference between `owner-unresolved` and a write.
  const mkEvidenceProject = (label) => {
    const made = mkTmp(label);
    fs.writeFileSync(path.join(made, '.gsd', 'PROJECT.md'), '# fixture project\n', 'utf8');
    return made;
  };

  const dir = mkTmp('evidence-runtime');
  // Declarados FORA do try para que o finally os alcance mesmo com assert
  // vermelho — a pegadinha já anotada na Seção 94 (um repo git vazado deixa
  // árvore suja, e cleanupWorktreeOne recusa --force sobre uma).
  let repo = null;
  try {
    const mock = writeMockAppServer(dir);
    const planFile = path.join(dir, 'T95-PLAN.md');
    fs.writeFileSync(planFile, '# T95\nexecute fixture for runtime evidence\n', 'utf8');
    repo = mkGitRepo(mkTmp('evidence-runtime-repo'));

    // Roda o adapter REAL pela CLI contra o mock, com os itens do stream
    // controlados por env. O que se mede aqui é o que o adapter de fato grava no
    // result-file — não uma chamada direta ao classificador, que provaria só o
    // classificador.
    const runExecute = (label, extraItems) => {
      const resultFile = path.join(dir, `${label}-result.json`);
      const r = spawnSync(process.execPath, [
        path.join(SCRIPTS, 'forge-xllm.js'), '--mode', 'execute',
        '--plan', planFile, '--result-file', resultFile, '--cwd', repo, '--timeout', '20',
      ], {
        encoding: 'utf8',
        cwd: repo,
        env: {
          ...process.env,
          FORGE_XLLM_CODEX_BIN: mock,
          FORGE_MOCK_SCENARIO: 'conforming',
          FORGE_MOCK_EXTRA_ITEMS: JSON.stringify(extraItems),
        },
      });
      let parsed = null;
      try { parsed = JSON.parse(fs.readFileSync(resultFile, 'utf8')); } catch { /* asserção abaixo nomeia a ausência */ }
      return { r, parsed, resultFile };
    };

    // (a) ADMISSIBILIDADE. Um turn cujos itens são só prosa do modelo produz
    // ZERO entries — e mesmo assim é `collected`, com o censo contando os itens.
    // "Nada admitido" e "nada coletado" são fatos diferentes.
    {
      const prose = [
        { type: 'agentMessage', text: 'narrating the work' },
        { type: 'reasoning', text: 'thinking about it' },
        { type: 'plan', steps: [] },
      ];
      const got = runExecute('prose', prose);
      assert(got.r.status === 0, '(a) execute com itens só-prosa termina 0', `status=${got.r.status} stderr=${got.r.stderr}`);
      const ev = got.parsed && got.parsed.runtime_evidence;
      assert(!!ev && ev.census.outcome === 'collected' && ev.census.admitted === 0 && ev.entries.length === 0,
        '(a) agentMessage/reasoning/plan produzem ZERO entries e censo collected/admitted:0', JSON.stringify(ev));
      // O piso: coletado-e-vazio nunca vira not-collected, nem no result-file
      // nem no jsonl. Sem esta linha, (a) passaria num mundo onde o vazio é
      // relatado como "não coletei" — o defeito de origem desta milestone.
      assert(ev.census.outcome !== 'not-collected' && ev.census.items_received >= 3,
        '(a) coletado-e-vazio NÃO colapsa em not-collected e o censo conta os itens recebidos', JSON.stringify(ev.census));

      const cwdA = mkEvidenceProject('evidence-runtime-empty');
      try {
        const mat = runScript('forge-evidence-materialize.js',
          ['--result', got.resultFile, '--unit', 'execute-task/T95', '--cwd', cwdA, '--json']);
        const out = JSON.parse(mat.stdout);
        const lines = fs.readFileSync(path.join(cwdA, '.gsd', 'forge', evidenceFileName('execute-task/T95')), 'utf8')
          .trim().split('\n').map((l) => JSON.parse(l));
        assert(out.outcome === 'collected' && out.entries_written === 0 && out.census_written === 1,
          '(a) materializador rende collected com 0 entries e EXATAMENTE 1 censo', mat.stdout);
        assert(lines.length === 1 && lines[0].kind === CENSUS_KIND && lines[0].outcome === 'collected'
          && lines[0].admitted === 0 && lines[0].written === 0,
          '(a) o jsonl do coletado-e-vazio tem só a linha de censo, e ela diz collected/admitted:0', JSON.stringify(lines));
      } finally { cleanup(cwdA); }
    }

    // (b) REJEIÇÃO de variante desconhecida, com um item admissível ao lado: sem
    // o vizinho admitido, "entries não contém a desconhecida" seria satisfeito
    // por um coletor que não produz entry nenhuma.
    let mixedResultFile = null;
    {
      const mixed = [
        { type: 'quantumThing', payload: 'from a future protocol' },
        {
          type: 'commandExecution', id: 'exec-95', command: 'node -e "process.exit(3)"',
          cwd: '/tmp/section-95', status: 'failed', exitCode: 3, durationMs: 12,
        },
      ];
      const got = runExecute('mixed', mixed);
      mixedResultFile = got.resultFile;
      assert(got.r.status === 0, '(b) execute com variante desconhecida termina 0 (coletor nunca derruba a unidade)', `stderr=${got.r.stderr}`);
      const ev = got.parsed && got.parsed.runtime_evidence;
      const rejected = (ev && ev.census.rejected) || [];
      assert(rejected.some((entry) => entry.type === 'quantumThing' && entry.count === 1),
        '(b) census.rejected NOMEIA quantumThing', JSON.stringify(ev && ev.census));
      assert(!ev.entries.some((entry) => JSON.stringify(entry).includes('quantumThing')),
        '(b) entries NÃO contém a variante rejeitada (nunca repassada)', JSON.stringify(ev.entries));
      // IN-4: o exit code vem do STREAM, não de inferência sobre a árvore.
      const command = ev.entries.find((entry) => entry.kind === 'command');
      assert(!!command && command.exit_code === 3 && command.source === SOURCE,
        '(b) a entry de comando carrega exit_code:3 lido do item do stream, com source codex-runtime', JSON.stringify(ev.entries));
      assert(ev.census.admitted === 1,
        '(b) o censo admite exatamente o item admissível, ao lado da rejeição', JSON.stringify(ev.census));
    }

    // (c) CONTAGEM CONFRONTADA. Mordida nas duas direções sobre um pin FIXTURE —
    // o pin real nunca é editado (é o oráculo; mutá-lo em disco trocaria o
    // oráculo pelo teste).
    {
      const realPin = path.join(path.dirname(SCRIPTS), 'shared', 'schemas', 'codex-appserver-pin.json');
      const realPinBytes = fs.readFileSync(realPin, 'utf8');
      const pin = JSON.parse(realPinBytes);
      const intact = path.join(dir, 'pin-intact.json');
      fs.writeFileSync(intact, JSON.stringify(pin), 'utf8');
      const okRun = runScript('forge-evidence-admit.js', ['--check-schema', '--pin', intact, '--json']);
      const okJson = JSON.parse(okRun.stdout);
      assert(okRun.status === 0 && okJson.ok === true && okJson.variants === 18 && okJson.admissible === 2,
        '(c) pin íntegro passa: 18 variantes, 2 admissíveis', okRun.stdout);

      const mutated = JSON.parse(JSON.stringify(pin));
      const dropped = 'sleep';
      mutated.definitions.ThreadItem.oneOf = mutated.definitions.ThreadItem.oneOf.filter((variant) => {
        const typeProp = variant && variant.properties && variant.properties.type;
        return !(typeProp && Array.isArray(typeProp.enum) && typeProp.enum[0] === dropped);
      });
      // meta.variant_count acompanha, senão o guard para antes na checagem do pin
      // contra SI MESMO e nunca chega à confrontação por nome — o caso (c) mediria
      // a consistência interna do pin, não a cobertura do mapa.
      if (mutated.meta) mutated.meta.variant_count = mutated.definitions.ThreadItem.oneOf.length;
      const mutatedFile = path.join(dir, 'pin-17.json');
      fs.writeFileSync(mutatedFile, JSON.stringify(mutated), 'utf8');
      const badRun = runScript('forge-evidence-admit.js', ['--check-schema', '--pin', mutatedFile, '--json']);
      const badJson = JSON.parse(badRun.stdout);
      assert(mutated.definitions.ThreadItem.oneOf.length === 17,
        '(c) o fixture mutado de fato tem 17 variantes (o caso não é no-op)');
      assert(badRun.status !== 0 && badJson.ok === false
        && (badJson.missing_in_pin || []).includes(dropped),
        `(c) pin com 17 variantes falha NOMEANDO '${dropped}', nunca só uma contagem`, badRun.stdout);
      // Igualdade estrita contra os bytes lidos ANTES do caso. Uma disjunção com
      // `existsSync` passaria sempre — o pin é o oráculo, e um caso que o edita
      // troca o oráculo pelo teste sem que nada fique vermelho.
      assert(fs.readFileSync(realPin, 'utf8') === realPinBytes,
        '(c) o pin real permanece byte-idêntico — a mordida foi toda sobre fixture');
    }

    // (d) OS TRÊS DESFECHOS, comparados DOIS A DOIS. Ler um só e declarar
    // "distinto" é exatamente a forma de erro que esta milestone existe para
    // fechar: distinção é uma afirmação sobre um par.
    {
      const scenarios = {
        // `collected` com admitted 0 — o desfecho que mais se parece com os outros
        // dois e que jamais pode ser confundido com eles.
        'collected-empty': {
          status: 'done',
          runtime_evidence: {
            census: {
              outcome: 'collected', items_received: 2, types_seen: { agentMessage: 2 },
              admitted: 0, inadmissible: 2, rejected: [], turn_status: 'completed',
            },
            entries: [],
          },
        },
        // Campo AUSENTE — a única entrada que pode render not-collected.
        'not-collected': { status: 'done' },
        // Campo presente e malformado (`null`): hasOwnProperty distingue isto de
        // ausência, e o desfecho tem de ser outro.
        'collector-failed': { status: 'done', runtime_evidence: null },
      };
      const rendered = {};
      for (const [label, payload] of Object.entries(scenarios)) {
        const resultFile = path.join(dir, `${label}-payload.json`);
        fs.writeFileSync(resultFile, JSON.stringify(payload), 'utf8');
        const cwdX = mkEvidenceProject(`evidence-runtime-${label}`);
        try {
          const mat = runScript('forge-evidence-materialize.js',
            ['--result', resultFile, '--unit', 'execute-task/T95', '--cwd', cwdX, '--json']);
          const jsonl = fs.readFileSync(path.join(cwdX, '.gsd', 'forge', evidenceFileName('execute-task/T95')), 'utf8');
          const lines = jsonl.trim().split('\n').map((l) => JSON.parse(l));
          assert(mat.status === 0, `(d) ${label}: materializador sai 0 (advisory)`, mat.stderr);
          assert(lines.filter((l) => l.kind === CENSUS_KIND).length === 1,
            `(d) ${label}: EXATAMENTE uma linha de censo, inclusive sem entries`, jsonl);
          // ts e o caminho absoluto do tmpdir variam por execução; normalizá-los é
          // o que torna a distinção atribuível ao DESFECHO, e não ao relógio.
          const normalize = (text) => text.replace(/"ts":"[^"]*"/g, '"ts":"<ts>"').replace(/[^"]*\.gsd/g, '<cwd>/.gsd');
          rendered[label] = {
            jsonl: normalize(jsonl),
            stdout: normalize(mat.stdout),
            outcome: JSON.parse(mat.stdout).outcome,
          };
        } finally { cleanup(cwdX); }
      }

      const labels = Object.keys(rendered);
      let pairs = 0;
      for (let i = 0; i < labels.length; i += 1) {
        for (let j = i + 1; j < labels.length; j += 1) {
          const a = rendered[labels[i]];
          const b = rendered[labels[j]];
          pairs += 1;
          assert(a.jsonl !== b.jsonl && a.stdout !== b.stdout && a.outcome !== b.outcome,
            `(d) ${labels[i]} × ${labels[j]}: jsonl, stdout e outcome distintos`,
            `${a.jsonl} || ${b.jsonl}`);
        }
      }
      // Piso anti-silêncio do próprio caso (d), no molde de S07: um comparador
      // que não comparou par nenhum não pode reportar "distintos".
      assert(pairs === 3, '(d) os três desfechos foram comparados nos 3 pares, não um só', `pairs=${pairs}`);
      assert(rendered['collected-empty'].outcome === 'collected'
        && rendered['not-collected'].outcome === 'not-collected'
        && rendered['collector-failed'].outcome === 'collector-failed',
        '(d) zero admitido renderiza collected — nunca "not collected"',
        JSON.stringify(Object.fromEntries(labels.map((l) => [l, rendered[l].outcome]))));
    }

    // (e) COEXISTÊNCIA das duas `source` no MESMO arquivo, separáveis por
    // igualdade estrita. A linha sintetizada legada é pré-gravada como o §7a a
    // grava; o materializador acrescenta as runtime.
    {
      const cwdE = mkEvidenceProject('evidence-runtime-coexist');
      try {
        const file = path.join(cwdE, '.gsd', 'forge', evidenceFileName('execute-task/T95'));
        fs.writeFileSync(file, `${JSON.stringify({
          ts: new Date().toISOString(), source: LEGACY_SOURCE, kind: 'file',
          unit: 'execute-task/T95', file: 'scripts/x.js', change_kind: 'M',
        })}\n`, 'utf8');
        // O payload MENTE a source: declara codex-sidecar numa entry runtime. Se
        // o materializador confiasse no payload, as duas ficariam indistinguíveis
        // — que é o oposto exato do ponto.
        const lying = JSON.parse(fs.readFileSync(mixedResultFile, 'utf8'));
        lying.runtime_evidence.entries = lying.runtime_evidence.entries.map((entry) => ({ ...entry, source: LEGACY_SOURCE }));
        const lyingFile = path.join(dir, 'lying-result.json');
        fs.writeFileSync(lyingFile, JSON.stringify(lying), 'utf8');

        const mat = runScript('forge-evidence-materialize.js',
          ['--result', lyingFile, '--unit', 'execute-task/T95', '--cwd', cwdE, '--json']);
        assert(mat.status === 0, '(e) materializador sai 0 sobre o arquivo que já tinha linha legada', mat.stderr);
        const lines = fs.readFileSync(file, 'utf8').trim().split('\n').map((l) => JSON.parse(l));
        const legacy = lines.filter((l) => l.source === LEGACY_SOURCE);
        const runtime = lines.filter((l) => l.source === SOURCE);
        assert(legacy.length === 1 && runtime.length === lines.length - 1 && runtime.length >= 2,
          '(e) as duas source coexistem e um filtro de igualdade estrita as separa', JSON.stringify(lines));
        assert(legacy[0].kind === 'file' && legacy[0].file === 'scripts/x.js',
          '(e) a linha sintetizada legada sobrevive intacta (D7 não aposenta nada)', JSON.stringify(legacy));
        assert(runtime.some((l) => l.kind === 'command' && l.exit_code === 3),
          '(e) a linha runtime carrega o exit_code observado no stream', JSON.stringify(runtime));
        assert(!runtime.some((l) => l.source === LEGACY_SOURCE),
          '(e) source é FORÇADA: o payload mentiroso não disfarça uma linha runtime de sintetizada', JSON.stringify(runtime));
      } finally { cleanup(cwdE); }
    }

    // (f) §7 e os 3 mirrors, por varredura IN-PROCESS com contagem exata.
    {
      const root = path.dirname(SCRIPTS);
      const dispatch = fs.readFileSync(path.join(root, 'shared', 'forge-dispatch.md'), 'utf8');
      const mirrorFiles = [
        path.join(root, 'skills', 'forge-auto', 'SKILL.md'),
        path.join(root, 'skills', 'forge-next', 'SKILL.md'),
        path.join(root, 'skills', 'forge-task', 'SKILL.md'),
      ];
      const scan = scanEvidenceDocs(dispatch, mirrorFiles.map((f) => sidecarSurface(f)));  // sidecar surface (2026-08-23)
      assert(scan.section7Found && scan.parts7a === 1 && scan.parts7b === 1,
        '(f) §7 tem exatamente uma parte 7a e uma parte 7b', JSON.stringify(scan));
      assert(scan.runtimeObservedHeading === 1 && scan.runtimeSourceIn7b >= 1,
        '(f) a parte 7b é a runtime-observada e nomeia source codex-runtime', JSON.stringify(scan));
      assert(scan.synthesizedIn7b === 0 && scan.synthesizedIn7a >= 1,
        '(f) A7: o 7b NÃO chama essa evidência de sintetizada, e o 7a (legado) continua chamando',
        JSON.stringify(scan));
      assert(scan.materializeIn7b === 1,
        '(f) a INVOCAÇÃO do materializador aparece exatamente uma vez no 7b', JSON.stringify(scan));
      assert(scan.mentionsIn7b > scan.materializeIn7b,
        '(f) o 7b também NOMEIA o script fora do bloco de comando — por isso a contagem é sobre a invocação, não sobre o nome',
        JSON.stringify(scan));
      assert(scan.mirrorInvocations.length === 3 && scan.mirrorInvocations.every((n) => n === 1),
        '(f) cada um dos 3 mirrors invoca o materializador EXATAMENTE uma vez', JSON.stringify(scan.mirrorInvocations));
      // R9: e essa única invocação está no passo de DESFECHO TERMINAL, antes do
      // split Success/Failure — senão a linha "result-file ilegível →
      // collector-failed" segue sem call site. Um censo por desfecho terminal,
      // nunca um por retry: por isso a contagem exata de 1 CONTINUA valendo.
      assert(scan.mirrorInvokeBeforeSuccess.length === 3
        && scan.mirrorInvokeBeforeSuccess.every((p) => p.ok === true),
        '(f) R9: nos 3 mirrors a invocação vem ANTES do passo Success (alcançável em qualquer desfecho)',
        JSON.stringify(scan.mirrorInvokeBeforeSuccess));

      // Mordida do próprio scanner: sobre fontes sintéticas cada asserção acima
      // tem de virar falsa. Um scanner que só sabe dizer "sim" é o defeito que
      // esta seção existe para eliminar (mesmo molde do (e) da Seção 93).
      const stripped = [
        '**7. Evidence lines into `.gsd/forge/evidence-{unitId}.jsonl`.**',
        '**7a. Synthesized lines (legacy, advisory — preserved).** tagged `source: codex-sidecar`.',
        '',
        '#### Sidecar dispatch state machine — Branch D',
        `${INVOKE_NEEDLE} --result "$RESULT_FILE"`,
        '',
      ].join('\n');
      const bitten = scanEvidenceDocs(stripped, ['', `${INVOKE_NEEDLE} x ${INVOKE_NEEDLE}`]);
      assert(bitten.parts7b === 0 && bitten.runtimeObservedHeading === 0 && bitten.materializeIn7b === 0,
        '(f) doc sem a parte 7b: o scanner acusa — e a invocação DEPOIS do §7 não conta como dentro dele',
        JSON.stringify(bitten));
      assert(bitten.synthesizedIn7a === 1 && bitten.synthesizedIn7b === 0,
        '(f) o scanner localiza "synthesized" na parte certa, não no documento inteiro', JSON.stringify(bitten));
      assert(JSON.stringify(bitten.mirrorInvocations) === JSON.stringify([0, 2]),
        '(f) mirror sem invocação e mirror com invocação dupla são ambos contados', JSON.stringify(bitten.mirrorInvocations));
      // Mordida do predicado posicional de R9: um mirror que invoca DEPOIS do
      // `**Success` é o defeito original, e tem de ser acusado. Sem isto, o
      // `every(ok)` acima seria compatível com um predicado sempre-verdadeiro.
      const positional = scanEvidenceDocs(stripped, [
        `**Success — passo 6.**\n${INVOKE_NEEDLE} --result "$RESULT_FILE"`,
        `4.5 desfecho terminal\n${INVOKE_NEEDLE} --result "$RESULT_FILE"\n**Success — passo 6.**`,
      ]).mirrorInvokeBeforeSuccess;
      assert(positional[0].ok === false && positional[1].ok === true,
        '(f) R9 mordida: invocação DEPOIS do Success é acusada; antes dele passa',
        JSON.stringify(positional));
    }

    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeEvidenceRuntime\(\); \}/.test(mainBody),
      '(g) Section 95 is registered through a closure in main()');
    pass('(final) Section 95: prosa não vira evidência, desconhecida é rejeitada por nome, 18 confrontadas com mordida, '
      + '3 desfechos distintos nos 3 pares, duas source coexistindo e §7b/mirrors contados in-process com mordida');
  } finally {
    if (repo) cleanup(repo);
    cleanup(dir);
  }
}

// ── Section 96: o transporte aposentado, provado ausente AO VIVO ───────────
// A Seção 93 prova que o transporte NOVO funciona; esta prova que o VELHO acabou.
// Três coisas, e cada uma existe porque a outra sozinha seria insuficiente:
//   • a ausência é medida contra os arquivos REAIS do repo, pela CLI da T03 —
//     este smoke CONSOME o scanner, nunca reimplementa o predicado (duas
//     implementações do mesmo predicado divergem, e a divergência é invisível
//     exatamente quando importa);
//   • o predicado MORDE — fonte sintética com call site é acusada nomeando
//     arquivo e linha, nas duas formas que (d) depende (argv e símbolo removido);
//   • e o piso anti-silêncio: uma varredura que não leu nada FALHA, jamais
//     "passa limpa" (mesmo invariante da S06 `scanned===0` e da S07
//     `pairs_compared===0` → inconclusive).
// O número 96 foi verificado contra o máximo REAL do arquivo (95 = Section 95),
// não herdado do ROADMAP nem do Asset Map — que ainda diz "próxima livre = 92" e
// está desatualizado. A lição da S04 é justamente essa.
function smokeExecCallSitesRetired() {
  process.stdout.write('\n▸ Section 96: o transporte aposentado, ausência ao vivo + verdade documental\n');
  const dir = mkTmp('exec-callsites-retired');
  const root = path.dirname(SCRIPTS);
  const scan = (args, cwd) => {
    const r = runScript('forge-exec-callsites.js', ['--check', '--json', ...args], { cwd });
    let json = null;
    try { json = JSON.parse(r.stdout); } catch { /* leave null — the assert says so */ }
    return { ...r, json };
  };
  const count = (haystack, needle) => haystack.split(needle).length - 1;
  const between = (source, start, end) => {
    const from = source.indexOf(start);
    if (from < 0) return '';
    const to = source.indexOf(end, from + start.length);
    return to < 0 ? source.slice(from) : source.slice(from, to);
  };

  try {
    // (a) AUSÊNCIA AO VIVO — a CLI real, contra o repo real. Esta é a evidência do
    // critério de aceitação #1 da slice. A mensagem de falha IMPRIME os call sites:
    // um assert vermelho que não diz ONDE custa uma rodada inteira de investigação.
    {
      const live = scan([], root);
      const found = (live.json && live.json.call_sites) || [];
      assert(live.status === 0 && !!live.json && live.json.outcome === 'clean',
        '(a) o repo real não tem call site executável do transporte aposentado',
        `status=${live.status} outcome=${live.json && live.json.outcome} call_sites=${JSON.stringify(found, null, 1)}`);
      assert(!!live.json && live.json.scanned > 0 && found.length === 0,
        '(a) a varredura leu arquivos de verdade e não achou nenhum call site',
        JSON.stringify({ scanned: live.json && live.json.scanned, hits: found.length }));
      // Anti-vacuidade do próprio (a): o repo CONTINUA falando do transporte antigo
      // em prosa (docs, comentários, este arquivo). Se as menções sumissem, o verde
      // acima poderia significar "o scanner não leu nada relevante" em vez de
      // "leu e classificou como prosa".
      const prose = (live.json && live.json.prose_mentions) || [];
      assert(prose.length > 0 && prose.some((m) => m.file.endsWith('.md')),
        '(a) menções em PROSA sobrevivem e são classificadas como prosa (o verde não é vácuo)',
        JSON.stringify({ prose: prose.length, md: prose.filter((m) => m.file.endsWith('.md')).length }));
    }

    // (b) MORDIDA na direção da presença — duas fontes sintéticas em disco, uma por
    // forma que (d) depende. Sem este ponto, (a) passaria num mundo onde o scanner
    // não morde nada, e um scanner que só sabe dizer "não" é o mesmo defeito de um
    // que só sabe dizer "sim".
    {
      const fixtureDir = path.join(dir, 'fixture');
      fs.mkdirSync(fixtureDir, { recursive: true });
      // Os tokens são MONTADOS aqui pela mesma razão declarada em DETACHED_NEEDLE:
      // este arquivo é o caçador, e (a) o varre. A montagem muda a grafia dentro do
      // caçador; o arquivo escrito em disco carrega a grafia REAL, que é o que o
      // predicado enxerga — por isso é aqui, e não em (a), que a mordida é provada.
      const argvFixture = [
        "const { spawnSync } = require('child_process');",
        "function resolveCodexCommand() { return { cmd: 'codex', prefixArgs: [] }; }",
        `const args = ['${EXEC_ARG_TOKEN}', '--sandbox', 'read-only'];`,
        'spawnSync(resolveCodexCommand().cmd, args);',
        '',
      ].join('\n');
      const symbolFixture = [
        'async function runPlan(o) {',
        `  return ${DETACHED_NEEDLE}o);`,
        '}',
        '',
      ].join('\n');
      fs.writeFileSync(path.join(fixtureDir, 'argv-call-site.js'), argvFixture, 'utf8');
      fs.writeFileSync(path.join(fixtureDir, 'symbol-call-site.js'), symbolFixture, 'utf8');

      const bitten = scan(['--root', '.'], fixtureDir);
      const sites = (bitten.json && bitten.json.call_sites) || [];
      assert(bitten.status === 2 && !!bitten.json && bitten.json.outcome === 'found',
        '(b) fonte sintética com call site: outcome=found e exit 2 (nunca clean)',
        `status=${bitten.status} ${JSON.stringify(bitten.json && bitten.json.outcome)}`);
      const argvHit = sites.find((s) => s.file.endsWith('argv-call-site.js'));
      assert(!!argvHit && argvHit.line === 3 && argvHit.form === 'exec-arg-array',
        '(b) o item nomeia ARQUIVO e LINHA do argv (argv-call-site.js:3, forma exec-arg-array)',
        JSON.stringify(sites));
      const symbolHit = sites.find((s) => s.file.endsWith('symbol-call-site.js'));
      assert(!!symbolHit && symbolHit.line === 2 && symbolHit.form === 'removed-symbol',
        '(b) e nomeia arquivo e linha do símbolo removido (symbol-call-site.js:2, forma removed-symbol)',
        JSON.stringify(sites));
      assert(!!bitten.json && bitten.json.files_with_hits === 2,
        '(b) as duas formas são contadas em arquivos distintos', JSON.stringify(bitten.json && bitten.json.files_with_hits));
    }

    // (c) PISO ANTI-SILÊNCIO, nas duas maneiras de não ler nada: um root vazio e um
    // root inexistente. Nenhuma das duas pode render `clean` — um detector que
    // relata a própria inatividade como boa notícia é byte a byte indistinguível
    // de um detector quebrado, e é o defeito de origem desta milestone.
    {
      const emptyDir = path.join(dir, 'empty-root');
      fs.mkdirSync(emptyDir, { recursive: true });
      const empty = scan(['--root', '.'], emptyDir);
      assert(empty.status === 2 && !!empty.json && empty.json.outcome === 'scan-failed'
        && empty.json.outcome !== 'clean' && empty.json.scanned === 0,
        '(c) root vazio: scanned=0 rende scan-failed, jamais clean', JSON.stringify(empty.json));

      const absent = scan(['--root', 'does-not-exist'], dir);
      const reasons = ((absent.json && absent.json.skipped) || []).map((s) => s.reason);
      assert(absent.status === 2 && !!absent.json && absent.json.outcome === 'scan-failed'
        && reasons.includes('root-not-found'),
        '(c) root inexistente: scan-failed COM razão nomeada (root-not-found), nunca descarte silencioso',
        JSON.stringify(absent.json && absent.json.skipped));
    }

    // (d) SÍMBOLOS REMOVIDOS — varredura in-process do adapter real, contagem exata
    // (`split(NEEDLE).length-1`), nunca includes() sobre o documento inteiro. As
    // agulhas com parêntese são montadas (ver DETACHED_NEEDLE); os nomes nus não
    // precisam ser, porque nome nu não é forma de chamada.
    const xllm = readRepoText(path.join(SCRIPTS, 'forge-xllm.js'));
    const PAREN = '(';
    const REMOVED = ['invokeCodex', 'invokeCodexDetached', 'codexSandboxArgs'];
    for (const name of REMOVED) {
      assert(count(xllm, `function ${name}${PAREN}`) === 0,
        `(d) a declaração de ${name} não existe mais em forge-xllm.js`,
        `count=${count(xllm, `function ${name}${PAREN}`)}`);
    }
    // `module.exports` precisa de igualdade por ENTRADA, não de substring:
    // `invokeCodexAppServer` CONTÉM `invokeCodex`, então um count() ingênuo daria
    // falso positivo permanente sobre o símbolo que SUBSTITUIU os removidos.
    const exportsBlock = between(xllm, 'module.exports = {', '\n};');
    const exportedNames = new Set(exportsBlock.split('\n')
      .map((line) => line.trim().replace(/,$/, '').split(':')[0].trim())
      .filter(Boolean));
    for (const name of REMOVED) {
      assert(!exportedNames.has(name), `(d) ${name} não está em module.exports`,
        JSON.stringify([...exportedNames].filter((n) => n.toLowerCase().includes('codex'))));
    }
    // Controle positivo: um arquivo vazio (ou um `between` que não casou nada)
    // passaria em TODOS os asserts acima. Estes dizem que o adapter lido é o real e
    // que o transporte que substituiu os removidos está de fato alcançável.
    assert(exportedNames.has('invokeCodexAppServer'),
      '(d) controle positivo: invokeCodexAppServer ESTÁ em module.exports',
      JSON.stringify([...exportedNames].slice(0, 8)));
    const planBody = between(xllm, 'async function runPlan(', '\nmodule.exports');
    const engineBody = between(xllm, 'function invokeEngine(', '\nfunction ');
    assert(count(planBody, 'invokeCodexAppServer(') >= 1,
      '(d) o caminho de plan alcança o app-server', `count=${count(planBody, 'invokeCodexAppServer(')}`);
    assert(count(engineBody, 'invokeCodexAppServer(') >= 1,
      '(d) o caminho de review (invokeEngine) alcança o app-server', `count=${count(engineBody, 'invokeCodexAppServer(')}`);
    for (const mode of ['runChallenge', 'runDefend', 'runRebuttal']) {
      const body = between(xllm, `async function ${mode}(`, '\nasync function ');
      assert(count(body, 'invokeEngine(') >= 1,
        `(d) ${mode} chega ao transporte pelo invokeEngine`, `count=${count(body, 'invokeEngine(')}`);
    }
    // Mordida de (d): sobre uma fonte que RESSUSCITA os símbolos, cada contagem
    // acima tem de virar diferente de zero. Sem isto, os `=== 0` seriam compatíveis
    // com um scanner que não conta nada.
    {
      const revived = [
        `function invokeCodex${PAREN}o) { return 1; }`,
        `function invokeCodexDetached${PAREN}o) { return 2; }`,
        `function codexSandboxArgs${PAREN}) { return []; }`,
        'module.exports = {',
        '  invokeCodex,',
        '  codexSandboxArgs,',
        '};',
        '',
      ].join('\n');
      const revivedExports = new Set(between(revived, 'module.exports = {', '\n};').split('\n')
        .map((line) => line.trim().replace(/,$/, '').split(':')[0].trim()).filter(Boolean));
      assert(REMOVED.every((name) => count(revived, `function ${name}${PAREN}`) === 1),
        '(d) fonte que ressuscita os 3 símbolos: a contagem de declaração acusa cada um');
      assert(revivedExports.has('invokeCodex') && revivedExports.has('codexSandboxArgs')
        && !revivedExports.has('invokeCodexAppServer'),
        '(d) e a igualdade por entrada acusa a reexportação sem confundir com invokeCodexAppServer',
        JSON.stringify([...revivedExports]));
    }

    // (e) VERDADE DOCUMENTAL — presença POR ARQUIVO, contagem exata, mensagem
    // distinta em cada um. Nunca `includes()` sobre o documento inteiro (lição
    // M016 S03 R2 + M013 S04 R1): um assert que só sabe dizer "a palavra aparece
    // em algum lugar" não distingue a correção do documento errado.
    {
      const reviewDoc = readRepoText(path.join(root, 'shared', 'forge-review.md'));
      assert(count(reviewDoc, RETIRED_PHRASE) === 0,
        '(e) shared/forge-review.md não descreve mais o challenger rodando pelo transporte aposentado',
        `count=${count(reviewDoc, RETIRED_PHRASE)}`);
      assert(count(reviewDoc, 'codex app-server') >= 1,
        '(e) shared/forge-review.md nomeia o app-server como o transporte do challenger codex',
        `count=${count(reviewDoc, 'codex app-server')}`);
      // A MECÂNICA do fallback não pode ter sido reescrita de passagem junto com a
      // descrição do transporte — é contrato, não prosa de apoio.
      assert(count(reviewDoc, 'review-challenger-fallback') >= 1 && count(reviewDoc, 'forge-reviewer') >= 1,
        '(e) e a mecânica do fallback (review-challenger-fallback → forge-reviewer) segue intacta',
        JSON.stringify({ fallback: count(reviewDoc, 'review-challenger-fallback'), reviewer: count(reviewDoc, 'forge-reviewer') }));

      const prefsDoc = readRepoText(path.join(root, 'shared', 'forge-prefs-reference.md'));
      assert(count(prefsDoc, RETIRED_PHRASE) === 0,
        '(e) shared/forge-prefs-reference.md corrige a descrição de review.challenger',
        `count=${count(prefsDoc, RETIRED_PHRASE)}`);
      assert(count(prefsDoc, 'codex app-server') >= 1,
        '(e) shared/forge-prefs-reference.md nomeia o app-server na mesma descrição',
        `count=${count(prefsDoc, 'codex app-server')}`);

      // O documento histórico é o caso INVERSO, e é por isso que ele está aqui: a
      // medição de 2026-07-15 continua válida COMO REGISTRO. Reescrevê-la seria
      // apagar arqueologia; o que ele ganha é uma nota datada. Se alguém "limpar" as
      // ocorrências do corpo, este assert fica vermelho — de propósito.
      const gapDoc = readRepoText(path.join(root, 'docs', 'xllm-review-svn-gap.md'));
      const gapBody = gapDoc.slice(gapDoc.indexOf('## TL;DR'));
      assert(gapBody.length > 0 && count(gapBody, RETIRED_PHRASE) === 6,
        '(e) docs/xllm-review-svn-gap.md MANTÉM as 6 ocorrências históricas no corpo (não reescrito)',
        `count=${count(gapBody, RETIRED_PHRASE)}`);
      assert(count(gapDoc, 'DOCUMENTO HISTÓRICO') === 1 && count(gapDoc, 'M018/S05') >= 1,
        '(e) e ganhou exatamente uma nota datada declarando-o histórico, nomeando M018/S05',
        JSON.stringify({ nota: count(gapDoc, 'DOCUMENTO HISTÓRICO'), ref: count(gapDoc, 'M018/S05') }));
      assert(gapDoc.indexOf('DOCUMENTO HISTÓRICO') < gapDoc.indexOf('## TL;DR'),
        '(e) a nota está NO TOPO, antes do corpo que ela contextualiza');
    }

    // (f) R6 (nenhum dos 3 mirrors tocado) é acceptance DA SLICE, verificada pelo
    // orquestrador contra o diff do branch — deliberadamente FORA daqui, pela mesma
    // razão que a Section 93 escreve: uma asserção sobre a working tree do momento
    // vira mina para qualquer slice futura que edite skills/ legitimamente, e um
    // smoke vermelho por isso não diria nada sobre a ausência que esta seção existe
    // para provar. Não "completar" esta seção com esse assert depois.

    // (g) auto-registro em main() por closure — chamada bare é rejeitada pela
    // Section 73, e uma seção não registrada é uma seção que some em silêncio.
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeExecCallSitesRetired\(\); \}/.test(mainBody),
      '(g) Section 96 is registered through a closure in main()');

    pass('(final) Section 96: ausência do transporte aposentado provada AO VIVO pela CLI da T03, '
      + 'predicado mordendo nas duas formas com arquivo e linha, piso anti-silêncio nas duas maneiras de não ler nada, '
      + '3 símbolos ausentes com controle positivo, e a verdade documental corrigida sem reescrever a arqueologia');
  } finally { cleanup(dir); }
}

// ── Section 97 (M018 S06/T05) ──────────────────────────────────────────────
//
// Amarra os cinco entregáveis da S06 numa seção que FALHA quando qualquer um
// deles for desfeito. Todo bloco traz o contrafactual junto da direção que
// passa: um assert que só sabe dizer "sim" não distingue o código correto de um
// predicado que nunca morde — e foi exatamente por isso que a Section 96 da S05
// abriu VERMELHA, que era o desfecho certo.
//
// O que NÃO está aqui, e por quê: nenhum assert contra o `M018-CONTEXT.md` ao
// vivo. O CODE_DIR é um worktree sem `.gsd/` (medido: ENOENT), então um assert
// desses ou deriva um caminho de fora do worktree (frágil, específico da
// máquina) ou degrada em skip silencioso — o piso que esta slice inteira existe
// para sustentar. A paridade doc↔código é critério de aceitação MANUAL (#2 do
// S06-PLAN), rodado à mão com a saída colada no summary. Não "completar" esta
// seção com esse assert depois.
//
// O número 97 foi medido contra o máximo REAL do arquivo (96 = Section 96), não
// herdado do Asset Map — que já esteve 4 seções desatualizado (lição da S04).
function smokeEnvCoverage() {
  process.stdout.write('\n▸ Section 97: cobertura por reason — tabela IN-14, runtime-first, fallback nomeado e os dois itens de backlog\n');
  const dir = mkTmp('env-coverage');
  const root = path.dirname(SCRIPTS);
  const count = (haystack, needle) => haystack.split(needle).length - 1;
  const coverage = require(path.join(SCRIPTS, 'forge-env-coverage.js'));
  const promote = require(path.join(SCRIPTS, 'forge-env-promote.js'));
  const reverifyMod = require(path.join(SCRIPTS, 'forge-reverify.js'));
  const { ENV_REASON_ENUM } = require(path.join(SCRIPTS, 'forge-xllm.js'));
  // Contrato travado da T02: `fallbacks` é CONDICIONALMENTE presente (só existe
  // quando algo caiu no textual), porque um `fallbacks: []` incondicional
  // quebraria o guard de identidade-por-objeto em :8933. Ausente = "nada caiu",
  // nunca "o campo sumiu". Ler de qualquer outra forma reintroduz o bug.
  const fallbacksOf = (r) => (Array.isArray(r.fallbacks) ? r.fallbacks : []);

  try {
    // (a) TABELA IN-14 — mordida nas duas direções sobre fixture-string.
    // As 5 linhas são escritas LITERALMENTE aqui, não geradas a partir de
    // REASON_COVERAGE: uma tabela derivada do mapa passaria por construção
    // (tautologia) e nunca acusaria uma troca de veredito no mapa. Escrita à
    // mão, a fixture íntegra passar JÁ é o confronto literal × mapa.
    const HEADING = coverage.DOC_SECTION_HEADING;
    const docRows = {
      'out-of-scope-test-failure': '| `out-of-scope-test-failure` | promotable | commandExecution.exitCode | n/a (coberto) | A4 classe (b): o runner roda e o runtime emite exit code. |',
      'network-required': '| `network-required` | promotable | commandExecution.exitCode | n/a (coberto) | A4 classe (b): controle negativo de A2 com exitCode 6. |',
      'sandbox-exec-blocked': '| `sandbox-exec-blocked` | measured-gap | nenhuma | true | A4 classe (c) medida: negação só em prosa, zero commandExecution. |',
      'git-commit-required': '| `git-commit-required` | categorical | nenhuma | false | A evidência seria a ausência de uma ação; nenhum stream testemunha ausência. |',
      'gsd-write-refused': '| `gsd-write-refused` | categorical | nenhuma | false | Mesma classe: a escrita em .gsd/** nunca acontece (TASK-020 R1). |',
    };
    const buildDoc = (rows) => [
      '# Fixture',
      '',
      HEADING,
      '',
      '| reason | veredito | fonte runtime | re-testável no upgrade | razão |',
      '|---|---|---|---|---|',
      ...Object.keys(rows).map((r) => rows[r]),
      '',
    ].join('\n');

    {
      const intact = coverage.checkDocTable(buildDoc(docRows));
      assert(intact.ok === true && intact.parsed === 5,
        '(a) tabela íntegra: ok=true e parsed=5 — as 5 linhas foram de fato lidas',
        JSON.stringify(intact));

      // Veredito APAGADO num reason: a célula em branco jamais pode ser lida
      // como concordância com o mapa, e a falha tem de NOMEAR o reason — "5
      // divergências" manda o revisor para uma escavação.
      const erased = { ...docRows, 'network-required': '| `network-required` |  | commandExecution.exitCode | n/a (coberto) | idem. |' };
      const bitten = coverage.checkDocTable(buildDoc(erased));
      const missing = bitten.problems.filter((p) => p.kind === 'missing-verdict');
      assert(bitten.ok === false && missing.length === 1
        && missing[0].reason === 'network-required'
        && missing[0].detail.includes('network-required'),
        '(a) veredito apagado: ok=false E a mensagem NOMEIA o reason afetado',
        JSON.stringify(bitten.problems));

      // Piso anti-silêncio: markdown sem nenhuma linha não é "passou limpo".
      const empty = coverage.checkDocTable('# Fixture\n\nsem tabela nenhuma aqui\n');
      assert(empty.ok === false && empty.parsed === 0
        && empty.problems.length === 1 && empty.problems[0].kind === 'anti-silence',
        '(a) zero linhas parseadas: FALHA por anti-silêncio, jamais um passe limpo',
        JSON.stringify(empty));

      // Vocabulário fechado: um veredito inventado é acusado por nome próprio,
      // não confundido com "ausente".
      const invented = { ...docRows, 'sandbox-exec-blocked': '| `sandbox-exec-blocked` | promovivel | nenhuma | true | idem. |' };
      const unknown = coverage.checkDocTable(buildDoc(invented));
      assert(unknown.ok === false
        && unknown.problems.some((p) => p.kind === 'unknown-verdict' && p.reason === 'sandbox-exec-blocked'),
        '(a) veredito fora do enum: unknown-verdict, distinto de missing-verdict',
        JSON.stringify(unknown.problems));

      // Colapso pelo lado do DOCUMENTO: documentar o measured-gap como
      // não-reabrível é a fusão que a DP5 proíbe, e a coluna a carrega.
      const collapsedDoc = { ...docRows, 'sandbox-exec-blocked': '| `sandbox-exec-blocked` | measured-gap | nenhuma | false | idem. |' };
      const collapsed = coverage.checkDocTable(buildDoc(collapsedDoc));
      assert(collapsed.ok === false
        && collapsed.problems.some((p) => p.kind === 'retestable-mismatch' && p.reason === 'sandbox-exec-blocked'),
        '(a) colapso documental do measured-gap: retestable-mismatch nomeando o reason',
        JSON.stringify(collapsed.problems));

      // S06 review R1: a coluna de FONTE RUNTIME era conferida só por não-vazio,
      // então um doc alegando `agentMessage.text` contra o
      // `commandExecution.exitCode` do mapa PASSAVA no --check-doc. A coluna que
      // carrega a distinção inteira era a única que nada confrontava. Mutação
      // não-vazia-mas-errada: tem de morder, nomeando o reason e os dois valores.
      const wrongSource = {
        ...docRows,
        'network-required': '| `network-required` | promotable | agentMessage.text | n/a (coberto) | idem. |',
      };
      const sourceBitten = coverage.checkDocTable(buildDoc(wrongSource));
      const mismatch = sourceBitten.problems.filter((p) => p.kind === 'runtime-source-mismatch');
      assert(sourceBitten.ok === false && mismatch.length === 1
        && mismatch[0].reason === 'network-required'
        && mismatch[0].detail.includes('agentMessage.text')
        && mismatch[0].detail.includes('commandExecution.exitCode'),
        '(a) R1: fonte runtime não-vazia mas ERRADA morde, nomeando o reason e os dois valores',
        JSON.stringify(sourceBitten.problems));
      // Contrafactual do mesmo predicado: célula VAZIA continua sendo
      // missing-runtime-source, distinta do mismatch. Sem isto, o novo kind
      // poderia ter engolido o antigo.
      const emptySource = {
        ...docRows,
        'network-required': '| `network-required` | promotable |  | n/a (coberto) | idem. |',
      };
      const emptyBitten = coverage.checkDocTable(buildDoc(emptySource));
      assert(emptyBitten.ok === false
        && emptyBitten.problems.some((p) => p.kind === 'missing-runtime-source' && p.reason === 'network-required')
        && !emptyBitten.problems.some((p) => p.kind === 'runtime-source-mismatch'),
        '(a) R1: célula vazia segue missing-runtime-source, jamais confundida com mismatch',
        JSON.stringify(emptyBitten.problems));
      // Controle verde: decoração (crases) não é divergência — a comparação é
      // sobre o VALOR normalizado, não sobre bytes de markdown.
      const decorated = {
        ...docRows,
        'network-required': '| `network-required` | promotable | `commandExecution.exitCode` | n/a (coberto) | idem. |',
      };
      assert(coverage.checkDocTable(buildDoc(decorated)).ok === true,
        '(a) R1: controle — a mesma fonte com crases continua limpa (compara valor, não decoração)');
    }

    // (b) AS TRÊS CLASSES NÃO COLAPSAM (DP5) — asserido por comparação, não por
    // prosa numa célula. O total é conferido contra ENV_REASON_ENUM para que a
    // contagem não possa concordar consigo mesma sobre um mapa encolhido.
    {
      const counts = coverage.coverageCounts();
      assert(counts.promotable === 2 && counts['measured-gap'] === 1 && counts.categorical === 2,
        '(b) contagem por classe: {promotable:2, measured-gap:1, categorical:2}',
        JSON.stringify(counts));
      const total = Object.values(counts).reduce((a, b) => a + b, 0);
      assert(total === ENV_REASON_ENUM.length && total === 5,
        '(b) o total classificado bate com ENV_REASON_ENUM (nada fora do mapa, nada a mais)',
        JSON.stringify({ total, enum: ENV_REASON_ENUM.length }));

      const map = coverage.REASON_COVERAGE;
      assert(map['sandbox-exec-blocked'].retestable_on_upgrade === true
        && map['git-commit-required'].retestable_on_upgrade === false
        && map['gsd-write-refused'].retestable_on_upgrade === false,
        '(b) measured-gap é re-testável e os dois categóricos NÃO são — a distinção é executável',
        JSON.stringify({
          gap: map['sandbox-exec-blocked'].retestable_on_upgrade,
          git: map['git-commit-required'].retestable_on_upgrade,
          gsd: map['gsd-write-refused'].retestable_on_upgrade,
        }));
      // `null` nos promotable é valor OBSERVADO ("não se aplica, já coberto"),
      // nunca sinônimo de false. Coagir os dois ao mesmo valor de célula é o
      // colapso silencioso pelo terceiro lado.
      assert(map['network-required'].retestable_on_upgrade === null
        && map['out-of-scope-test-failure'].retestable_on_upgrade === null,
        '(b) os promotable carregam null (n/a), jamais false');

      // Mordida do invariante: um mapa que FUNDE o gap medido nos categóricos
      // tem de estourar CLASS_COLLAPSE nomeando o reason. Sem isto, os asserts
      // acima seriam compatíveis com um assertReasonCoverage que não checa nada.
      assert(coverage.assertReasonCoverage().ok === true,
        '(b) controle positivo: o mapa íntegro passa em assertReasonCoverage');
      const collapsedMap = {
        ...coverage.REASON_COVERAGE,
        'sandbox-exec-blocked': { ...coverage.REASON_COVERAGE['sandbox-exec-blocked'], verdict: 'categorical' },
      };
      let collapseError = null;
      try { coverage.assertReasonCoverage(ENV_REASON_ENUM, collapsedMap); } catch (e) { collapseError = e; }
      assert(!!collapseError && collapseError.code === 'CLASS_COLLAPSE'
        && collapseError.message.includes('sandbox-exec-blocked'),
        '(b) mapa com as classes fundidas: CLASS_COLLAPSE nomeando sandbox-exec-blocked',
        collapseError ? `${collapseError.code}: ${collapseError.message}` : 'nenhum erro lançado');
    }

    // (c) RUNTIME-FIRST NOS DOIS SENTIDOS, PELA CLI. Spawnar é o ponto: exit
    // code e contrato de saída são propriedades do PROCESSO, não afirmações de
    // um require() no mesmo heap. As duas notas são escolhidas para inverter o
    // veredito textual: em (i) a note DIRIA sim e o runtime recusa; em (ii) a
    // note DIRIA não e o runtime promove. É isso que prova qual dos dois manda.
    {
      const planPath = path.join(dir, 'plan.md');
      fs.writeFileSync(planPath, '# Plano\n\nNada aqui cita caminho de teste.\n', 'utf8');
      const runPromote = (result) => {
        const resultPath = path.join(dir, 'result.json');
        fs.writeFileSync(resultPath, JSON.stringify(result), 'utf8');
        const r = runScript('forge-env-promote.js', ['--result', resultPath, '--plan', planPath, '--json']);
        let json = null;
        try { json = JSON.parse(r.stdout); } catch { /* deixa null — o assert fala */ }
        return { ...r, json };
      };
      const claim = (note, runtimeEvidence) => {
        const base = {
          status: 'partial',
          must_haves_status: [{ item: 'baixar dependências', status: 'unmet', scope: 'environment', reason: 'network-required', note }],
        };
        return runtimeEvidence === undefined ? base : { ...base, runtime_evidence: runtimeEvidence };
      };
      const collected = (entries) => ({ census: { outcome: 'collected' }, entries });

      const refused = runPromote(claim(
        'precisei de network install a partir do registry para provar o item',
        collected([{ kind: 'command', cmd: 'npm test', exit_code: 0 }]),
      ));
      assert(refused.status === 0 && !!refused.json && refused.json.promote === false,
        '(c)(i) stream coletado sem comando de rede que falhe: promote=false pela CLI (exit 0, JSON no stdout)',
        `status=${refused.status} stdout=${refused.stdout}`);
      assert(!!refused.json && refused.json.rejected.length === 1
        && refused.json.rejected[0].why.includes('runtime'),
        '(c)(i) e o why nomeia que a recusa veio da EVIDÊNCIA RUNTIME, jamais de regex',
        JSON.stringify(refused.json && refused.json.rejected));

      const promoted = runPromote(claim(
        'o item não pôde ser provado neste ambiente',
        collected([{ kind: 'command', cmd: 'curl https://registry.npmjs.org/forge', exit_code: 6 }]),
      ));
      assert(promoted.status === 0 && !!promoted.json && promoted.json.promote === true
        && promoted.json.env_constraints.length === 1 && promoted.json.rejected.length === 0,
        '(c)(ii) mesma alegação com curl exit_code 6 observado: promote=true, pela CLI',
        `status=${promoted.status} stdout=${promoted.stdout}`);
      // Controle da direção textual: a note de (ii), SEM stream, é recusada.
      // Sem este assert, (ii) poderia estar passando pelo corroborador textual.
      const textualOnly = runPromote(claim('o item não pôde ser provado neste ambiente'));
      assert(!!textualOnly.json && textualOnly.json.promote === false,
        '(c)(ii) controle: a MESMA note sem stream é recusada — quem promoveu foi o exit code observado',
        JSON.stringify(textualOnly.json));
      // DP4: `null` é valor observado, não falha. Coagi-lo a "≠ 0" seria o edit
      // mais danoso possível — fabricaria uma falha que nada mediu.
      const nullExit = runPromote(claim(
        'o item não pôde ser provado neste ambiente',
        collected([{ kind: 'command', cmd: 'curl https://registry.npmjs.org/forge', exit_code: null }]),
      ));
      assert(!!nullExit.json && nullExit.json.promote === false,
        '(c) exit_code null NÃO corrobora falha (DP4)', JSON.stringify(nullExit.json));
    }

    // (d) FALLBACK NOMEADO E DISTINTO. Quatro estados, quatro nomes próprios —
    // e o censo de PARES comparados junto, molde S07/S04: um comparador que não
    // comparou nada não pode reportar sucesso.
    {
      const planText = '# Plano\n';
      const payload = (runtimeEvidence) => {
        const base = {
          status: 'partial',
          must_haves_status: [{ item: 'baixar dependências', status: 'unmet', scope: 'environment', reason: 'network-required', note: 'network install a partir do registry' }],
        };
        return runtimeEvidence === undefined ? base : { ...base, runtime_evidence: runtimeEvidence };
      };
      const states = {
        'campo ausente': payload(undefined),
        'collector-failed': payload({ census: { outcome: 'collector-failed' }, entries: [] }),
        malformed: payload({ census: { outcome: 'collected' } }),
        'coletado com zero comandos': payload({ census: { outcome: 'collected' }, entries: [{ kind: 'agentMessage', text: 'sem rede' }] }),
      };
      const named = {};
      for (const [label, result] of Object.entries(states)) {
        const out = promote.checkEnvPromotion(result, planText);
        const fb = fallbacksOf(out);
        assert(fb.length === 1 && typeof fb[0].fallback === 'string' && fb[0].fallback.length > 0
          && fb[0].reason === 'network-required',
          `(d) ${label}: cai no textual COM fallback nomeado (nunca aceite silencioso)`,
          JSON.stringify(out));
        named[label] = fb.length === 1 ? fb[0].fallback : null;
      }
      const values = Object.values(named);
      let pairs = 0;
      let distinct = true;
      for (let i = 0; i < values.length; i += 1) {
        for (let j = i + 1; j < values.length; j += 1) {
          pairs += 1;
          if (values[i] === values[j] || values[i] === null) distinct = false;
        }
      }
      assert(pairs === 6 && distinct,
        '(d) os quatro nomes são distintos DOIS A DOIS, com o censo de pares comparados (6)',
        JSON.stringify({ pairs, named }));
      // Contrato de aditividade estrita da T02: sem fallback, a chave NÃO
      // existe. Um `fallbacks: []` incondicional afrouxaria o guard de
      // identidade-por-objeto de :8933 — o próprio guard que isto protege.
      const clean = promote.checkEnvPromotion(payload({
        census: { outcome: 'collected' },
        entries: [{ kind: 'command', cmd: 'npm install', exit_code: 1 }],
      }), planText);
      assert(clean.promote === true && !Object.prototype.hasOwnProperty.call(clean, 'fallbacks'),
        '(d) quando nada cai no textual, a chave fallbacks é AUSENTE (presença é o sinal)',
        JSON.stringify(clean));
    }

    // (e) WIRING DO EVENTO, POR CONTAGEM EXATA (`split(N).length-1`), nunca
    // includes() document-wide: um assert que só sabe dizer "aparece em algum
    // lugar" não distingue a correção do documento errado (M016 S03 R2).
    {
      const EVENT = 'sidecar_env_corroboration_fallback';
      const mirrors = [
        path.join(root, 'skills', 'forge-auto', 'SKILL.md'),
        path.join(root, 'skills', 'forge-next', 'SKILL.md'),
        path.join(root, 'skills', 'forge-task', 'SKILL.md'),
      ];
      const canonical = path.join(root, 'shared', 'forge-dispatch.md');
      const canonicalText = readRepoText(canonical);
      // Composição MEDIDA das 2 ocorrências no canônico (não um "2" herdado):
      // 1 é a definição em negrito que abre o parágrafo, 1 é o campo `"event"`
      // da linha JSONL que ela especifica. Fixar o total em 2 sozinho seria
      // frouxo — uma SEGUNDA definição em outro parágrafo passaria se alguém
      // apagasse a forma JSON. Por isso cada forma é contada em separado: a
      // definição é exatamente uma, e é isso que "declarado aqui e só aqui"
      // quer dizer de forma executável.
      assert(count(canonicalText, `**\`${EVENT}\``) === 1,
        '(e) shared/forge-dispatch.md DEFINE o evento exatamente uma vez (forma em negrito)',
        `count=${count(canonicalText, `**\`${EVENT}\``)}`);
      assert(count(canonicalText, `"event":"${EVENT}"`) === 1,
        '(e) e especifica exatamente uma vez a forma da linha de evento (campo "event")',
        `count=${count(canonicalText, `"event":"${EVENT}"`)}`);
      assert(count(canonicalText, EVENT) === 2,
        '(e) e o total no canônico é 2 = definição + forma JSON, sem terceira menção solta',
        `count=${count(canonicalText, EVENT)}`);
      for (const mirror of mirrors) {
        const text = sidecarSurface(mirror);  // sidecar surface (2026-08-23)
        assert(count(text, EVENT) === 1,
          `(e) ${path.basename(path.dirname(mirror))} invoca o evento exatamente uma vez`,
          `count=${count(text, EVENT)}`);
        // S06 review R8: a contagem exata continua 1, mas 1 não diz ONDE. A
        // frase estava presa ao bullet do `status == "partial"`, enquanto um
        // SEGUNDO caminho (o `status == "done"` com entradas env não atendidas,
        // M016 S01 R1) roda a MESMA invocação do checker e nunca consumia
        // `PROMOTION.fallbacks`. A ocorrência única agora tem de (i) vir DEPOIS
        // do bullet do done — logo não pode estar presa ao do partial — e (ii)
        // nomear os DOIS caminhos no próprio parágrafo.
        const eventIdx = text.indexOf(EVENT);
        const doneBulletIdx = text.indexOf('M016 S01 review R1');
        assert(doneBulletIdx >= 0 && eventIdx > doneBulletIdx,
          `(e) R8: em ${path.basename(path.dirname(mirror))} a emissão vem DEPOIS do bullet do done (não presa ao do partial)`,
          JSON.stringify({ eventIdx, doneBulletIdx }));
        const paragraph = text.slice(text.lastIndexOf('\n', eventIdx) + 1, text.indexOf('\n', eventIdx));
        assert(paragraph.includes('status == "partial"') && paragraph.includes('status == "done"'),
          `(e) R8: e o parágrafo da emissão nomeia AMBAS as invocações em ${path.basename(path.dirname(mirror))}`,
          paragraph);
        // Anti-vacuidade: o arquivo lido é o mirror REAL e a frase pousou no
        // bullet que já existia, não num rodapé solto. Sem isto, um mirror
        // esvaziado passaria no assert de contagem 0 do vocabulário abaixo.
        assert(count(text, 'sidecar_env_promotion') >= 1,
          `(e) e a frase pousou no bullet de promoção que já existia em ${path.basename(path.dirname(mirror))}`,
          `count=${count(text, 'sidecar_env_promotion')}`);
      }
      // Enum-definido-uma-vez virando teste: o vocabulário fechado dos estados
      // vive SÓ no canônico. Os três nomes hifenizados são termos de arte; a
      // palavra nua "malformed" NÃO entra aqui de propósito — é inglês comum e
      // já aparece 2x no forge-auto falando de JSON, então exigir 0 seria falsa
      // precisão, um vermelho que não diz nada sobre o enum.
      // `coverage-unavailable` entrou em S06 review R4 como QUINTO nome do
      // vocabulário fechado: também é termo de arte, também vive só no canônico.
      const VOCAB = ['not-collected', 'collector-failed', 'no-command-entries', 'coverage-unavailable'];
      for (const term of VOCAB) {
        assert(count(canonicalText, term) >= 1,
          `(e) o canônico declara o estado '${term}'`, `count=${count(canonicalText, term)}`);
        for (const mirror of mirrors) {
          assert(count(readRepoText(mirror), term) === 0,
            `(e) e '${term}' NÃO é restatado em ${path.basename(path.dirname(mirror))}`,
            `count=${count(readRepoText(mirror), term)}`);
        }
      }
      // Mordida do (e): sobre um texto que RESTATA o enum, a mesma contagem tem
      // de acusar. Sem isto, os `=== 0` seriam compatíveis com um count() cego.
      const restating = `um mirror que copia o enum: not-collected, collector-failed, no-command-entries, coverage-unavailable.`;
      assert(VOCAB.every((term) => count(restating, term) === 1),
        '(e) mordida: num texto que restata o enum, a contagem acusa os três estados');
    }

    // (f) OS DOIS ITENS DE BACKLOG.
    {
      // `git switch -c` é o alias moderno de `checkout -b`: sem ele uma escrita
      // git legítima lê como não-escrita e a alegação é recusada por engano.
      assert(promote.corroborates({ reason: 'git-commit-required', item: 'x', note: 'rodei git switch -c feature para provar o item' }, '') === null,
        "(f) `git switch -c feature` numa note corrobora git-commit-required (alias novo)");
      assert(promote.corroborates({ reason: 'git-commit-required', item: 'x', note: 'rodei git switch -C feature' }, '') === null,
        '(f) e a variante -C também');
      // Aditivo, não substitutivo: nenhuma operação já reconhecida saiu.
      assert(promote.corroborates({ reason: 'git-commit-required', item: 'x', note: 'rodei git checkout -b feature' }, '') === null,
        '(f) controle: `git checkout -b` continua corroborando (o alias é ADITIVO)');
      // O contrafactual medido da TASK-020, ainda recusado: uma note que apenas
      // MENCIONA git — inclusive a que dizia literalmente que a task proíbe
      // rodar git — não é evidência de escrita nenhuma.
      const merelyMentions = promote.corroborates(
        { reason: 'git-commit-required', item: 'commit the change with git', note: 'the task prohibits running any git command' }, '',
      );
      assert(typeof merelyMentions === 'string' && merelyMentions.includes('git write operation'),
        '(f) contrafactual da TASK-020: note que apenas MENCIONA git segue recusada, com o porquê',
        JSON.stringify(merelyMentions));
      // E o `item` (boilerplate ecoado do plano) nunca corrobora sozinho.
      assert(typeof promote.corroborates({ reason: 'git-commit-required', item: 'git commit -m done', note: '' }, '') === 'string',
        '(f) o item ecoado do plano não corrobora — só a note é relatório de execução');

      // hasDivergentCommandNotes: uma entry cuja note não nomeia runner token
      // NENHUM gateia o veredito em bloco, porque um único exit code não fala
      // sobre ela em direção alguma.
      const tokenless = [
        { item: 'A', status: 'unmet', scope: 'environment', reason: 'out-of-scope-test-failure', note: 'npm test falhou numa suíte alheia' },
        { item: 'B', status: 'unmet', scope: 'environment', reason: 'sandbox-exec-blocked', note: 'o ambiente recusou a operação' },
      ];
      assert(reverifyMod.hasDivergentCommandNotes(tokenless) === true,
        '(f) note sem runner token nenhum: o gate dispara (não entra em veredito de bloco)');
      // Contrafactual: com as duas notes nomeando o MESMO runner, o gate NÃO
      // dispara. Sem este assert, um `return true` incondicional passaria.
      const agreeing = [
        { ...tokenless[0] },
        { ...tokenless[1], note: 'npm test também falhou aqui' },
      ];
      assert(reverifyMod.hasDivergentCommandNotes(agreeing) === false,
        '(f) contrafactual: duas notes nomeando o mesmo runner NÃO gateiam (o gate não é sempre-true)');
      assert(reverifyMod.hasDivergentCommandNotes([tokenless[0]]) === false,
        '(f) e uma entrada só nunca é ambígua');

      // Pela porta da frente (`reverify`), com as entradas conferidas INTOCADAS:
      // o veredito ambíguo retorna ANTES de qualquer resolução de comando, então
      // nada é executado — razão pela qual o caso NEGATIVO acima é asserido no
      // predicado e não por aqui (chamar reverify sem o gate rodaria a suíte do
      // projeto de verdade).
      const result = { status: 'partial', must_haves_status: tokenless.map((e) => ({ ...e })) };
      const emptyCodeDir = path.join(dir, 'code');
      fs.mkdirSync(emptyCodeDir, { recursive: true });
      const outcome = reverifyMod.reverify({ result, codeDir: emptyCodeDir, gsdDir: path.join(emptyCodeDir, '.gsd'), apply: true });
      assert(outcome.verdict === 'ambiguous-multi-command' && outcome.entries === 2,
        '(f) payload de 2 entradas com uma note sem token: verdict=ambiguous-multi-command',
        JSON.stringify(outcome));
      assert(result.must_haves_status.every((e, i) => e.status === 'unmet' && e.scope === 'environment'
        && e.note === tokenless[i].note),
        '(f) e as entradas ficam INTOCADAS mesmo com apply:true',
        JSON.stringify(result.must_haves_status));
    }

    // (h) S06 REVIEW R4 — O FAIL-OPEN NOMEADO, PROVADO COM O MESMO HOOK DE
    // `Module._load` que o achou. Um `catch { promotable = []; }` desligava o
    // gate runtime-first INTEIRO quando forge-env-coverage.js falhava ao
    // carregar: uma REJEIÇÃO runtime explícita virava `promote:true` sem
    // NENHUMA entrada em `fallbacks[]` — aceite silencioso. Deliberado-e-
    // inominado continua inominado.
    //
    // Roda em processo FILHO de propósito: envenenar `Module._load` no heap
    // deste smoke contaminaria todas as seções seguintes.
    {
      const child = path.join(dir, 'r4-coverage-poison.js');
      const promotePath = path.join(SCRIPTS, 'forge-env-promote.js').replace(/\\/g, '\\\\');
      fs.writeFileSync(child, [
        "'use strict';",
        "const Module = require('module');",
        'const load = Module._load;',
        "const poison = process.env.R4_POISON === '1';",
        'Module._load = function (request) {',
        "  if (poison && String(request).includes('forge-env-coverage')) {",
        "    throw new Error('poisoned: forge-env-coverage failed to load');",
        '  }',
        // eslint-disable-next-line prefer-rest-params — repassa a assinatura original
        '  return load.apply(this, arguments);',
        '};',
        `const promote = require('${promotePath}');`,
        // Alegação `network-required` com stream COLETADO e nenhum comando de
        // rede que falhe: o corroborador runtime REJEITA. Textualmente a mesma
        // note seria aceita ("network ... registry"), que é exatamente o flip.
        'const payload = {',
        "  status: 'partial',",
        "  must_haves_status: [{ item: 'baixar deps', status: 'unmet', scope: 'environment', reason: 'network-required', note: 'network install a partir do registry' }],",
        "  runtime_evidence: { census: { outcome: 'collected' }, entries: [{ kind: 'command', cmd: 'npm test', exit_code: 1 }] },",
        '};',
        "process.stdout.write(JSON.stringify(promote.checkEnvPromotion(payload, '# Plano\\n')));",
        '',
      ].join('\n'), 'utf8');

      const runChild = (poisoned) => {
        const r = spawnSync(process.execPath, [child], {
          encoding: 'utf8', env: { ...process.env, R4_POISON: poisoned ? '1' : '0' },
        });
        let json = null;
        try { json = JSON.parse(r.stdout); } catch { /* fica null */ }
        return { status: r.status, stdout: r.stdout || '', stderr: r.stderr || '', json };
      };

      // Controle positivo (módulo íntegro): a rejeição runtime já vale, e NADA
      // cai no textual — a chave `fallbacks` fica AUSENTE. Sem este controle, o
      // assert envenenado abaixo passaria num mundo onde tudo é sempre recusado.
      const healthy = runChild(false);
      assert(healthy.status === 0 && !!healthy.json && healthy.json.promote === false
        && !Object.prototype.hasOwnProperty.call(healthy.json, 'fallbacks'),
        '(h) R4 controle: com o módulo íntegro a rejeição runtime vale e não há fallback nenhum',
        `status=${healthy.status} stdout=${healthy.stdout} stderr=${healthy.stderr}`);

      const poisoned = runChild(true);
      assert(poisoned.status === 0 && !!poisoned.json,
        '(h) R4: com o módulo quebrado o checker ainda responde (a falha de carga não derruba o gate)',
        `status=${poisoned.status} stdout=${poisoned.stdout} stderr=${poisoned.stderr}`);
      const poisonedFallbacks = poisoned.json ? fallbacksOf(poisoned.json) : [];
      assert(poisonedFallbacks.length === 1
        && poisonedFallbacks[0].fallback === promote.COVERAGE_UNAVAILABLE
        && poisonedFallbacks[0].reason === 'network-required',
        '(h) R4: a falha de carga emite SINAL NOMEADO próprio (coverage-unavailable), nunca silêncio',
        JSON.stringify(poisoned.json));
      assert(!!poisoned.json && poisoned.json.promote === false
        && poisoned.json.rejected.length === 1
        && poisoned.json.rejected[0].why.includes('coverage table unavailable'),
        '(h) R4: e a rejeição runtime NÃO vira aceite silencioso — fail-closed com o porquê',
        JSON.stringify(poisoned.json));
      // O quinto nome é distinto dos quatro estados de runtime — não é um
      // apelido de `not-collected` (que diria "o sidecar não coletou nada",
      // uma afirmação falsa sobre um stream que EXISTE).
      assert(!Object.values(promote.RUNTIME_STATES).includes(promote.COVERAGE_UNAVAILABLE),
        '(h) R4: coverage-unavailable é distinto dos estados do stream (não é apelido de not-collected)',
        JSON.stringify({ states: promote.RUNTIME_STATES, name: promote.COVERAGE_UNAVAILABLE }));
      // Sem stream nenhum, a degradação textual continua permitida — mas NOMEADA.
      const noStream = promote.checkEnvPromotion({
        status: 'partial',
        must_haves_status: [{ item: 'x', status: 'unmet', scope: 'environment', reason: 'network-required', note: 'network install a partir do registry' }],
      }, '# Plano\n');
      assert(fallbacksOf(noStream).length === 1,
        '(h) R4: controle — sem stream, o textual segue valendo e continua nomeado em fallbacks');
    }

    // (g) auto-registro em main() por closure — chamada bare é rejeitada pela
    // Section 73, e uma seção não registrada é uma seção que some em silêncio.
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeEnvCoverage\(\); \}/.test(mainBody),
      '(g) Section 97 is registered through a closure in main()');

    pass('(final) Section 97: a tabela IN-14 morde nas duas direções nomeando o reason e falha por anti-silêncio '
      + 'quando não lê linha nenhuma, as três classes não colapsam (CLASS_COLLAPSE provado), o runtime-first foi '
      + 'exercido PELA CLI nos dois sentidos com o controle textual invertido, os quatro fallbacks são nomeados e '
      + 'distintos com censo de 6 pares, o evento tem 1 definição e 1 forma JSON no canônico e é invocado 1x por '
      + 'mirror sem restatar o enum, '
      + 'e os dois itens de backlog têm alias novo aceito com o contrafactual da TASK-020 ainda recusado');
  } finally { cleanup(dir); }
}

// ── Section 98: turn/interrupt antes do SIGKILL ────────────────────────────
// Escreve um mock app-server PRÓPRIO (não o do forge-appserver-client.test.js —
// papel diferente: este é o gate durável que o ROADMAP aloca a S07, não a prova
// rápida junto ao código) que carimba em ARQUIVO cada mensagem recebida, e um
// driver temporário que dá require() no cliente real e chama startAppServerTurn
// diretamente contra o mock. A ordem e a permanência do fallback são provadas
// pelo registro do MOCK (o peer), nunca por leitura do código do cliente.
function writeMockTurnInterrupt(dir) {
  const js = [
    "'use strict';",
    "const fs = require('fs');",
    "const mode = process.env.FORGE_T02_MODE || 'ignored';",
    "const logFile = process.env.FORGE_T02_LOG_FILE;",
    "const grandchildPidFile = process.env.FORGE_T02_GRANDCHILD_PID_FILE;",
    // Um neto no MESMO process group, spawnado ANTES de qualquer resposta —
    // garantido existir quando o timeout dispara. Não é detached: pertence ao
    // grupo que o cliente cria com `detached: true` e só morre por
    // process.kill(-pid); child.kill() sozinho o deixaria vivo.
    'if (grandchildPidFile) {',
    "  const gc = require('child_process').spawn(process.execPath, ['-e', 'setInterval(() => {}, 1000);'], { stdio: 'ignore' });",
    '  fs.writeFileSync(grandchildPidFile, String(gc.pid));',
    '}',
    // O PRÓPRIO PEER carimba o que recebeu — é essa gravação, não o código do
    // cliente, que prova a ordem e alimenta o piso anti-silêncio.
    'function log(method, params) {',
    '  if (!logFile) return;',
    "  fs.appendFileSync(logFile, JSON.stringify({ method, params, at: Date.now() }) + '\\n');",
    '}',
    "function send(v) { process.stdout.write(JSON.stringify(v) + '\\n'); }",
    'let initialized = false;',
    "let pending = '';",
    "process.stdin.setEncoding('utf8');",
    "process.stdin.on('data', (chunk) => {",
    '  pending += chunk;',
    '  let end;',
    "  while ((end = pending.indexOf('\\n')) >= 0) {",
    '    const line = pending.slice(0, end); pending = pending.slice(end + 1);',
    '    if (!line.trim()) continue;',
    '    let msg;',
    '    try { msg = JSON.parse(line); } catch { continue; }',
    '    log(msg.method, msg.params);',
    "    if (msg.method === 'initialize') { send({ id: msg.id, result: { serverInfo: { name: 'forge-smoke-t02-mock' } } }); }",
    "    else if (msg.method === 'initialized') { initialized = true; }",
    "    else if (msg.method === 'thread/start') {",
    '      if (!initialized) continue;',
    "      send({ id: msg.id, result: { thread: { id: 'thread-1' } } });",
    "    } else if (msg.method === 'turn/start') {",
    '      if (!initialized) continue;',
    // (h) no-turn-start: recebe e REGISTRA, mas nunca responde nem notifica —
    // o cliente chega ao timeout sem turnId, único caminho para
    // SKIPPED_NO_TURN_ID. O registro do peer continua existindo, então a
    // barreira de handshake abaixo ainda distingue "não respondeu de
    // propósito" de "a máquina nunca entregou a mensagem".
    "      if (mode === 'no-turn-start') { continue; }",
    "      send({ id: msg.id, result: { turn: { id: 'turn-1' } } });",
    "      send({ method: 'turn/started', params: { turn: { id: 'turn-1' } } });",
    // happy: só existe para MEDIR o handshake nesta máquina sob esta carga —
    // a janela dos cenários é dimensionada a partir dele, nunca de uma
    // constante escolhida numa máquina ociosa.
    "      if (mode === 'happy') {",
    "        send({ method: 'turn/completed', params: { turn: { id: 'turn-1', status: 'completed' } } });",
    '      }',
    "    } else if (msg.method === 'turn/interrupt') {",
    // (a)/(b) ignored: nunca responde — a grace estoura.
    "      if (mode === 'ignored') { /* silêncio deliberado */ }",
    // (c) acked: responde de imediato.
    "      else if (mode === 'acked') { send({ id: msg.id, result: {} }); }",
    // (f) error-ack: responde com ERRO RPC — o cliente classifica ERROR, que
    // não é a mesma coisa que "não respondeu" (GRACE_EXPIRED) nem que
    // "respondeu ok" (ACKNOWLEDGED).
    "      else if (mode === 'error-ack') { send({ id: msg.id, error: { code: -32000, message: 'interrupt refused' } }); }",
    // (d) latch: emite turn/completed{status:'interrupted'} PRIMEIRO, com o ack
    // atrasado (~40ms) — se o ack chegasse no MESMO chunk, a ordem passaria por
    // acaso de microtask em vez de provar o latch (medido pelo T01).
    "      else if (mode === 'then-completed') {",
    "        send({ method: 'turn/completed', params: { turn: { id: 'turn-1', status: 'interrupted' } } });",
    "        setTimeout(() => { send({ id: msg.id, result: {} }); }, 40);",
    '      }',
    '    }',
    '  }',
    '});',
    'setInterval(() => {}, 1000);',
    '',
  ].join('\n');
  const file = path.join(dir, 'mock-turn-interrupt.js');
  fs.writeFileSync(file, js, 'utf8');
  return file;
}

// Driver temporário: dá require() no CLIENTE REAL (caminho absoluto do repo,
// nunca uma cópia) e chama startAppServerTurn diretamente contra o mock —
// "cliente dirige o mock por fora do adapter" (MEM006). Uma linha de JSON no
// stdout é o único contrato com quem o spawnou.
function writeTurnInterruptDriver(dir) {
  const js = [
    "'use strict';",
    "const fs = require('fs');",
    "const { startAppServerTurn } = require(process.env.FORGE_T02_CLIENT_PATH);",
    "const pidFile = process.env.FORGE_T02_PID_FILE;",
    'startAppServerTurn({',
    '  cmd: process.execPath,',
    '  args: [process.env.FORGE_T02_MOCK_PATH],',
    '  env: process.env,',
    '  timeoutMs: Number(process.env.FORGE_T02_TIMEOUT_MS),',
    '  interruptGraceMs: Number(process.env.FORGE_T02_GRACE_MS),',
    "  onSpawn: (pid) => { if (pidFile) fs.writeFileSync(pidFile, String(pid)); },",
    '}).then(',
    "  () => { process.stdout.write(JSON.stringify({ ok: true, message: null, interrupt: null, turnId: null }) + '\\n'); },",
    '  (error) => {',
    '    process.stdout.write(JSON.stringify({',
    '      ok: false, message: error.message, interrupt: error.interrupt, turnId: error.turnId,',
    "    }) + '\\n');",
    '  },',
    ');',
    '',
  ].join('\n');
  const file = path.join(dir, 'turn-interrupt-driver.js');
  fs.writeFileSync(file, js, 'utf8');
  return file;
}

function t02Alive(pid) {
  if (!pid) return false;
  try { process.kill(pid, 0); return true; } catch { return false; }
}

function t02Sleep(ms) {
  return new Promise((resolve) => { setTimeout(resolve, ms); });
}

async function t02WaitForFile(file, timeoutMs) {
  const start = Date.now();
  while (Date.now() - start < timeoutMs) {
    if (fs.existsSync(file)) {
      const raw = fs.readFileSync(file, 'utf8').trim();
      if (raw) return raw;
    }
    await t02Sleep(5);
  }
  return null;
}

// Corre em paralelo ao driver, amostrando alive(pid) a cada 5ms: é essa
// amostragem — feita PELO PROCESSO PAI, nunca pelo peer que está prestes a
// morrer de SIGKILL — que dá o carimbo de "o pid deixou de existir" contra o
// qual o `at` do turn/interrupt registrado pelo mock é comparado.
async function t02WatchDeath(pid, maxWaitMs) {
  const start = Date.now();
  while (Date.now() - start < maxWaitMs) {
    if (!t02Alive(pid)) return Date.now();
    await t02Sleep(5);
  }
  return null;
}

// WATCHDOG (S07 review R5). Resolver só em `close`/`error` deixava esta seção
// capaz de TRAVAR em vez de falhar: se o driver nunca fechasse (cliente
// pendurado, mock que não responde, pipe preso), a Promise nunca resolveria e
// a suíte INTEIRA ficaria sem sinal — medido nesta mesma milestone, >600s com
// 0 bytes de saída. A ironia está no registro: a T02 pôs um watchdog DENTRO do
// mock exatamente por isso e esqueceu o mesmo guard em quem o spawnou. Um
// travamento apaga o sinal; uma falha alta sempre é melhor.
// `timedOut: true` é um desfecho NOMEADO, nunca um `code` inventado — o
// chamador assere que nenhum cenário terminou por aqui.
function t02SpawnDriverAsync(driverPath, env, watchdogMs) {
  const { spawn } = require('child_process');
  return new Promise((resolve) => {
    const child = spawn(process.execPath, [driverPath], { env });
    let stdout = '';
    let done = false;
    const finish = (value) => { if (done) return; done = true; if (timer) clearTimeout(timer); resolve(value); };
    const timer = setTimeout(() => {
      try { child.kill('SIGKILL'); } catch { /* já morto */ }
      finish({ stdout, code: null, timedOut: true, watchdogMs });
    }, watchdogMs);
    if (timer.unref) timer.unref();
    child.stdout.on('data', (d) => { stdout += d.toString('utf8'); });
    child.on('close', (code) => finish({ stdout, code, timedOut: false }));
    child.on('error', (e) => finish({ stdout, code: null, error: e.message, timedOut: false }));
  });
}

function t02ReadLog(file) {
  if (!fs.existsSync(file)) return [];
  return fs.readFileSync(file, 'utf8').split('\n').filter(Boolean).map((line) => JSON.parse(line));
}

async function smokeTurnInterrupt() {
  process.stdout.write('\n▸ Section 98: turn/interrupt antes do SIGKILL — ordem, permanência do fallback e o latch\n');
  const dir = mkTmp('turn-interrupt');
  const clientPath = path.join(SCRIPTS, 'forge-appserver-client.js');
  const { INTERRUPT_OUTCOMES } = require(clientPath);
  const mockPath = writeMockTurnInterrupt(dir);
  const driverPath = writeTurnInterruptDriver(dir);

  // A mensagem de timeout é load-bearing e continua ancorada; só o VALOR se
  // move, e ele vem da MESMA aritmética que o cliente usa — uma mudança de
  // formato ainda falha aqui. Substitui o `0\.09s` fixo, que amarrava a seção
  // a uma janela escolhida numa máquina ociosa (mesma patologia já medida em
  // forge-appserver-client.test.js: o cliente arma o timer no spawn, então o
  // boot do node + handshake precisam CABER na janela; sob contenção, 10 de 12
  // execuções falharam, todas colapsando em SKIPPED_NO_TURN_ID).
  const timeoutMessageRe = (timeoutMs) => {
    const seconds = String(Number((timeoutMs / 1000).toFixed(3))).replace('.', '\\.');
    return new RegExp(`^forge-appserver-client: timeout after ${seconds}s$`);
  };

  const baseEnv = (mode, stem, timeoutMs, graceMs) => ({
    ...process.env,
    FORGE_T02_CLIENT_PATH: clientPath,
    FORGE_T02_MOCK_PATH: mockPath,
    FORGE_T02_PID_FILE: `${stem}-pid.txt`,
    FORGE_T02_TIMEOUT_MS: String(timeoutMs),
    FORGE_T02_GRACE_MS: String(graceMs),
    FORGE_T02_MODE: mode,
    FORGE_T02_LOG_FILE: `${stem}-log.jsonl`,
    FORGE_T02_GRANDCHILD_PID_FILE: `${stem}-grandchild-pid.txt`,
  });

  // Medido, nunca assumido: uma volta completa no caminho feliz nesta máquina,
  // sob ESTA carga, com uma janela folgada que não participa da corrida.
  const measureHandshakeMs = async () => {
    const stem = path.join(dir, 'measure');
    const started = Date.now();
    const result = await t02SpawnDriverAsync(driverPath, baseEnv('happy', stem, 20000, 500), 30000);
    assert(result.timedOut === false, '(medição) o driver do caminho feliz terminou sozinho, sem watchdog', JSON.stringify(result));
    let parsed = null;
    try { parsed = JSON.parse((result.stdout || '').trim().split('\n').filter(Boolean).pop()); } catch { /* o assert fala */ }
    assert(!!parsed && parsed.ok === true,
      '(medição) o caminho feliz resolve — sem isso a janela seria dimensionada por um erro, não por um handshake',
      JSON.stringify({ parsed, stdout: result.stdout }));
    return Date.now() - started;
  };

  const budget = Math.max(90, (await measureHandshakeMs()) * 3);

  // BARREIRA CARIMBADA PELO PEER, não uma esperança: se o mock não registrou
  // `turn/start`, o handshake provadamente não coube na janela — inanição
  // desta máquina, não defeito do cliente —, e só então a janela dobra. Uma
  // tentativa cujo registro MOSTRA turn/start nunca é repetida, então uma
  // regressão real na captura do turnId (mesmo sintoma observável,
  // SKIPPED_NO_TURN_ID) ainda falha na primeira tentativa. Nenhum assert é
  // relaxado — a cura é janela medida + barreira, jamais um sleep maior.
  const runScenario = async (mode, graceFactor, label) => {
    let timeoutMs = Math.round(budget);
    for (let attempt = 1; attempt <= 4; attempt += 1) {
      const stem = path.join(dir, `${mode}-${attempt}`);
      const pidFile = `${stem}-pid.txt`;
      const grandchildPidFile = `${stem}-grandchild-pid.txt`;
      const logFile = `${stem}-log.jsonl`;
      const graceMs = Math.max(120, Math.round(timeoutMs * graceFactor));
      // Folgado de propósito: o watchdog existe para FALHAR ALTO num
      // travamento, não para competir com a janela do cenário.
      const watchdogMs = Math.max(15000, (timeoutMs + graceMs) * 20);
      const driverPromise = t02SpawnDriverAsync(driverPath, baseEnv(mode, stem, timeoutMs, graceMs), watchdogMs);
      const rawPid = await t02WaitForFile(pidFile, 3000);
      const pid = rawPid ? Number(rawPid) : null;
      const deathPromise = pid ? t02WatchDeath(pid, 5000) : Promise.resolve(null);
      const [driverResult, deathAt] = await Promise.all([driverPromise, deathPromise]);
      assert(driverResult.timedOut === false,
        `(watchdog) ${label}: o driver terminou por conta própria — um travamento aqui apagaria o sinal da suíte inteira`,
        JSON.stringify({ watchdogMs, stdout: driverResult.stdout }));
      let parsed = null;
      try { parsed = JSON.parse((driverResult.stdout || '').trim().split('\n').filter(Boolean).pop()); } catch { /* leave null — the assert speaks */ }
      // A grace extra depois de fechado o driver: o SIGKILL é síncrono no cliente,
      // mas a morte OBSERVÁVEL do processo (kernel) pode chegar alguns ms depois.
      await t02Sleep(200);
      const grandchildRaw = fs.existsSync(grandchildPidFile) ? fs.readFileSync(grandchildPidFile, 'utf8').trim() : null;
      const grandchildPid = grandchildRaw ? Number(grandchildRaw) : null;
      const log = t02ReadLog(logFile);
      if (!log.some((e) => e.method === 'turn/start') && attempt < 4) { timeoutMs *= 2; continue; }
      return { parsed, pid, deathAt, grandchildPid, log, timeoutMs };
    }
    throw new Error(`${label}: o peer nunca recebeu turn/start dentro da janela após 4 alargamentos`);
  };

  try {
    // Piso anti-silêncio, checado uma vez por cenário abaixo — nunca deixado
    // implícito no fato de os outros asserts passarem: um mock que não gravou
    // nada é indistinguível de um detector quebrado (molde forge-doc-claims.js).
    const censusNamed = (label, log) => {
      assert(log.length > 0, `(anti-silêncio) ${label}: o registro do mock tem ao menos uma linha`, JSON.stringify(log));
    };

    // (a) ordem + (b) permanência — mesmo cenário: interrupt ignorado, grace
    // estoura, e o process group inteiro (app-server + neto) morre.
    let a;
    {
      a = await runScenario('ignored', 1.5, '(a) ignored');
      censusNamed('(a) ignored', a.log);
      assert(!!a.parsed && a.parsed.ok === false && timeoutMessageRe(a.timeoutMs).test(a.parsed.message || ''),
        '(a) interrupt ignorado: a sessão rejeita com a mensagem de timeout inalterada',
        JSON.stringify({ parsed: a.parsed, timeoutMs: a.timeoutMs }));
      assert(!!a.parsed && a.parsed.interrupt === INTERRUPT_OUTCOMES.GRACE_EXPIRED,
        '(a) o desfecho é INTERRUPT_OUTCOMES.GRACE_EXPIRED, lido da constante exportada', JSON.stringify(a.parsed));
      const interruptEntry = a.log.find((e) => e.method === 'turn/interrupt');
      assert(!!interruptEntry, '(a) o mock registrou ter recebido turn/interrupt', JSON.stringify(a.log));
      assert(a.deathAt !== null, '(a) o pid do app-server deixou de existir dentro da janela observada', `pid=${a.pid}`);
      assert(!!interruptEntry && a.deathAt !== null && interruptEntry.at <= a.deathAt,
        '(a) ORDEM provada pelo registro do próprio mock: turn/interrupt chegou antes de o processo morrer',
        JSON.stringify({ interruptAt: interruptEntry && interruptEntry.at, deathAt: a.deathAt }));
      // (b) permanência: não é só o app-server que morre — o process group
      // INTEIRO, incluindo o neto, é o que prova que o interrupt não substituiu
      // o SIGKILL, apenas o precedeu.
      assert(a.grandchildPid !== null, '(b) o mock spawnou um neto para este cenário significar algo', JSON.stringify(a));
      assert(t02Alive(a.pid) === false, '(b) permanência: o app-server está morto após a grace estourar', `pid=${a.pid}`);
      if (process.platform === 'win32') {
        skip('(b) permanência do neto (grupo de processo negativo)', 'win32: process.kill(-pid) e grupos de processo não existem lá — o cliente usa taskkill /T /F');
      } else {
        assert(t02Alive(a.grandchildPid) === false,
          '(b) permanência: o process group INTEIRO (incluindo o neto) está morto — o SIGKILL não foi substituído',
          `grandchildPid=${a.grandchildPid}`);
      }
    }

    // (c) acked — params corretos, contra o turnId que o T01 passou a capturar.
    let c;
    {
      c = await runScenario('acked', 5, '(c) acked');
      censusNamed('(c) acked', c.log);
      assert(!!c.parsed && c.parsed.interrupt === INTERRUPT_OUTCOMES.ACKNOWLEDGED,
        '(c) interrupt respondido: INTERRUPT_OUTCOMES.ACKNOWLEDGED', JSON.stringify(c.parsed));
      const interruptEntry = c.log.find((e) => e.method === 'turn/interrupt');
      assert(!!interruptEntry && interruptEntry.params
        && interruptEntry.params.threadId === 'thread-1' && interruptEntry.params.turnId === 'turn-1',
        '(c) os params registrados pelo peer têm threadId=thread-1 e turnId=turn-1 — params errados = interrupt inerte',
        JSON.stringify(interruptEntry));
      // Mesmo acked, o desfecho continua sendo o TIMEOUT — um interrupt que
      // funciona nunca vira sucesso (piso anti-silêncio da slice, D-S07-2/3).
      assert(!!c.parsed && c.parsed.ok === false,
        '(c) mesmo com o interrupt reconhecido, a sessão CONTINUA rejeitando com o timeout', JSON.stringify(c.parsed));
    }

    // (d) latch — o critério que mais importa: turn/completed{status:'interrupted'}
    // durante a grace NÃO pode virar sucesso.
    let d;
    {
      d = await runScenario('then-completed', 5, '(d) then-completed');
      censusNamed('(d) then-completed', d.log);
      assert(!!d.parsed && d.parsed.ok === false && timeoutMessageRe(d.timeoutMs).test(d.parsed.message || ''),
        '(d) LATCH: turn/completed{status:"interrupted"} durante a grace NÃO vira sucesso — a sessão rejeita com o timeout '
        + '(sem o latch, isto resolveria como êxito — a patologia que a milestone existe para matar)',
        JSON.stringify(d.parsed));
      assert(!!d.parsed && d.parsed.interrupt === INTERRUPT_OUTCOMES.ACKNOWLEDGED,
        '(d) o interrupt em si foi reconhecido — é o latch, não a falta de ack, que barra o sucesso', JSON.stringify(d.parsed));
    }

    // (f) error — o peer RESPONDE ao interrupt, mas com erro RPC. Sem cenário
    // próprio, ERROR era indistinguível de um desfecho coberto: o assert
    // antigo dizia "ao menos dois distintos" e passava com três dos cinco
    // desfechos jamais exercitados (S07 review R6).
    let f;
    {
      f = await runScenario('error-ack', 5, '(f) error-ack');
      censusNamed('(f) error-ack', f.log);
      assert(!!f.parsed && f.parsed.interrupt === INTERRUPT_OUTCOMES.ERROR,
        '(f) interrupt recusado pelo peer: INTERRUPT_OUTCOMES.ERROR — responder com erro NÃO é o mesmo que não responder',
        JSON.stringify(f.parsed));
      assert(!!f.parsed && f.parsed.ok === false,
        '(f) mesmo recusado, a sessão continua rejeitando com o timeout', JSON.stringify(f.parsed));
    }

    // (h) skipped:no-turn-id — o peer nunca responde a turn/start, então não
    // há turnId bem-formado para enviar. O kill acontece do mesmo jeito: o
    // desfecho é REGISTRADO, nunca convertido em desculpa para não agir.
    let h;
    {
      h = await runScenario('no-turn-start', 5, '(h) no-turn-start');
      censusNamed('(h) no-turn-start', h.log);
      assert(!!h.parsed && h.parsed.interrupt === INTERRUPT_OUTCOMES.SKIPPED_NO_TURN_ID,
        '(h) sem turnId observado: INTERRUPT_OUTCOMES.SKIPPED_NO_TURN_ID', JSON.stringify(h.parsed));
      assert(!!h.parsed && h.parsed.turnId === null,
        '(h) o turnId ausente é reportado como null, não omitido', JSON.stringify(h.parsed));
      const startEntry = h.log.find((e) => e.method === 'turn/start');
      assert(!!startEntry,
        '(h) o peer REGISTROU turn/start (recebeu e escolheu não responder) — sem isso o cenário seria inanição, não o desfecho medido',
        JSON.stringify(h.log));
      assert(h.deathAt !== null, '(h) o app-server morreu mesmo sem interrupt enviável', `pid=${h.pid}`);
    }

    // (e) censo dos desfechos — PARTIÇÃO EXPLÍCITA do enum exportado. Um
    // desfecho não exercitado não pode ser indistinguível de um coberto (a
    // tese inteira desta milestone), então cada valor cai em exatamente um dos
    // dois mapas abaixo e o assert falha se a união não for o enum, se os dois
    // se sobrepuserem, ou se um valor declarado COBERTO não tiver aparecido de
    // fato num desfecho observado.
    {
      const values = Object.values(INTERRUPT_OUTCOMES);
      const observed = {
        [INTERRUPT_OUTCOMES.GRACE_EXPIRED]: '(a) ignored — o peer nunca responde e a grace estoura',
        [INTERRUPT_OUTCOMES.ACKNOWLEDGED]: '(c) acked / (d) then-completed — o peer responde ok',
        [INTERRUPT_OUTCOMES.ERROR]: '(f) error-ack — o peer responde com erro RPC',
        [INTERRUPT_OUTCOMES.SKIPPED_NO_TURN_ID]: '(h) no-turn-start — nunca houve turnId para enviar',
      };
      // NÃO EXERCITADO, e dito em voz alta no próprio assert com o motivo:
      // UNSENT exige que o stream de escrita já esteja destruído no instante
      // do timeout. Deste driver caixa-preta isso é inalcançável — quem
      // destrói o stdin do filho é o próprio cliente (no cleanup, depois de
      // resolvido) e a morte do peer antes do timeout é classificada como
      // saída do processo, não como timeout. Fabricá-lo exigiria o handle do
      // filho, que só o cliente tem. Coberto por teste unitário do lado do
      // cliente, jamais por este smoke.
      const unexercised = {
        [INTERRUPT_OUTCOMES.UNSENT]: 'stdin já destruído no instante do timeout — inalcançável por este driver caixa-preta; '
          + 'o handle do filho pertence ao cliente. Coberto em forge-appserver-client.test.js, não aqui.',
      };
      const covered = Object.keys(observed);
      const declaredUnexercised = Object.keys(unexercised);
      const union = covered.concat(declaredUnexercised).sort();
      assert(JSON.stringify(union) === JSON.stringify(values.slice().sort()),
        '(e) o censo PARTICIONA o enum exportado: todo desfecho ou tem cenário nomeado ou está declarado não-exercitado com motivo '
        + '— um valor novo sem entrada em nenhum dos dois mapas é falha do guard, nunca passe limpo',
        JSON.stringify({ covered, declaredUnexercised, enum: values }));
      assert(covered.every((v) => !declaredUnexercised.includes(v)),
        '(e) os dois mapas são disjuntos — nenhum desfecho pode ser coberto e não-exercitado ao mesmo tempo',
        JSON.stringify({ covered, declaredUnexercised }));
      const exercised = [a.parsed.interrupt, c.parsed.interrupt, d.parsed.interrupt, f.parsed.interrupt, h.parsed.interrupt];
      assert(exercised.every((v) => values.includes(v)),
        '(e) todo desfecho exercitado neste smoke pertence ao enum exportado', JSON.stringify(exercised));
      const missing = covered.filter((v) => !exercised.includes(v));
      assert(missing.length === 0,
        '(e) todo desfecho DECLARADO coberto foi de fato observado num cenário — declarar cobertura sem observá-la é a patologia, '
        + 'não a cura',
        JSON.stringify({ missing, exercised }));
      assert(declaredUnexercised.every((v) => !exercised.includes(v)),
        '(e) um desfecho declarado NÃO-exercitado que aparecer num cenário significa que o motivo declarado ficou obsoleto — '
        + 'atualize o mapa em vez de deixar a declaração mentir',
        JSON.stringify({ declaredUnexercised, exercised }));
    }

    // (g) auto-registro em main() por closure — chamada bare é rejeitada pela
    // Section 73, e uma seção não registrada é uma seção que some em silêncio.
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/async \(\) => \{ await smokeTurnInterrupt\(\); \}/.test(mainBody),
      '(g) Section 98 is registered through a closure in main()');

    pass('(final) Section 98: turn/interrupt é tentado antes do SIGKILL — ordem provada pelo carimbo do próprio mock, '
      + 'o process group inteiro (incluindo o neto) permanece morto no fallback, o latch de terminalidade impede que '
      + 'um turn/completed{status:"interrupted"} durante a grace vire sucesso, os params (threadId/turnId) chegam '
      + 'corretos ao peer, o censo PARTICIONA os 5 desfechos de INTERRUPT_OUTCOMES entre cenários observados e '
      + 'não-exercitados com motivo declarado, a janela é MEDIDA nesta máquina com barreira carimbada pelo peer, '
      + 'todo driver corre sob watchdog (travar apagaria o sinal da suíte) e a seção está registrada em '
      + 'main() por closure com self-check (g)');
  } finally { cleanup(dir); }
}

// ── Section 99: as três rotas inertes do routing, fechadas ─────────────────
// Uma decisão tomada num lugar que não alcança o consumidor é o defeito de
// classe da TASK-021. As três aqui foram MEDIDAS na M018:
//   (1) `worker: claude` no frontmatter vazava para o slot de MODELO
//       (model='claude', alias=null) → o orquestrador omitia `model:` do
//       Agent() e o worker rodava no default do agente, ignorando o tier; e o
//       clamp de effort (chaveado em `claude-(haiku|sonnet)`) não casava com o
//       token, deixando `effort: high` passar para um Sonnet (HTTP 400).
//   (2) o planner decidia o engine em PROSA (key_decisions) e não emitia
//       `worker:` — decisão inerte por construção.
//   (3) o caminho de sucesso da Branch C escrevia o SUMMARY em nome do sidecar
//       e NÃO marcava `status: DONE` no plano, deixando a slice com cara de
//       incompleta para todo consumidor que lê `status:`.
// (1) é provada por COMPORTAMENTO (o resolver de verdade, fixture hermética);
// (2) e (3) são contratos de prompt — provados por presença do texto que
// executa, no canônico E em cada mirror que enumera o passo.
function smokeInertRoutes() {
  process.stdout.write('\n▸ Section 99: as três rotas inertes do routing, fechadas\n');
  const ROOT = path.dirname(SCRIPTS);
  const { resolveDispatch } = require('./forge-dispatch-resolve.js');

  // ── (1) comportamental — a família nunca chega ao slot de modelo ─────────
  // Fixture hermética: o bloco routing: da camada repo vence a cascata, então
  // as prefs globais do operador não podem mudar o resultado desta prova.
  const dir = mkTmp('inert-routes');
  try {
    fs.mkdirSync(path.join(dir, '.gsd'), { recursive: true });
    fs.writeFileSync(path.join(dir, '.gsd', 'forge-prefs.jsonc'),
      '{"routing":{"default":{"executor":{"standard":["claude-sonnet-5","gpt-5.6-luna"],"heavy":["claude-opus-5"]}}}}');
    const plan = (fm) => {
      const p = path.join(dir, `T-${Math.random().toString(36).slice(2)}-PLAN.md`);
      fs.writeFileSync(p, `---\n${fm}---\n# task\n`);
      return p;
    };
    const run = (fm) => resolveDispatch({ unitType: 'execute-task', cwd: dir, planPath: plan(fm) });

    const control = run('');
    assert(control.model === 'claude-sonnet-5' && control.engine === 'claude',
      '(1a) controle: sem worker:, a cadeia roteada resolve normalmente', JSON.stringify(control.chain));

    const pinned = run('worker: claude\ntier: heavy\neffort: high\n');
    assert(pinned.engine === 'claude', '(1b) worker: claude ainda fixa o engine claude', pinned.engine);
    assert(pinned.route_source === 'frontmatter', '(1b) frontmatter ainda vence o rótulo de source', pinned.route_source);
    assert(pinned.model === 'claude-opus-5',
      '(1b) o MODELO vem do tier (heavy), não do token da família — a rota do tier deixou de ser inerte', pinned.model);
    assert(pinned.alias === 'opus',
      '(1b) alias mapeado: o Agent() recebe um model: de verdade em vez de omitir o param', String(pinned.alias));
    assert(pinned.model !== 'claude' && pinned.alias !== null,
      '(1b) o token da família NUNCA aparece no slot de modelo (o defeito medido em M018/S02/T01)');

    const clamped = run('worker: claude\neffort: high\n');
    assert(clamped.model === 'claude-sonnet-5' && clamped.effort === 'medium',
      '(1c) numa task standard o clamp de effort volta a morder (era o HTTP 400 no Sonnet)',
      JSON.stringify({ model: clamped.model, effort: clamped.effort }));
    assert(/clamped:model-cap/.test(clamped.effort_reason),
      '(1c) o clamp é registrado, nunca silencioso', clamped.effort_reason);

    const codex = run('worker: codex\n');
    assert(codex.dispatch_engine === 'codex' && codex.model === 'gpt-5.6-luna' && codex.sidecar_model === 'gpt-5.6-luna',
      '(1d) worker: codex filtra a cadeia para o membro gpt roteado — o sidecar recebe o modelo real',
      JSON.stringify({ e: codex.dispatch_engine, m: codex.model, s: codex.sidecar_model }));

    // Precedência preservada: um id CONCRETO continua vencendo o tier.
    const { resolveRoute } = require('./forge-routing.js');
    const concrete = resolveRoute({ unitType: 'execute-task', tier: 'standard', domain: 'default', frontmatterWorker: 'gpt-5.6-terra', cwd: dir });
    assert(concrete.chain.length === 1 && concrete.chain[0].id === 'gpt-5.6-terra',
      '(1e) um worker: com id concreto continua fixando o modelo (precedência não invertida)', JSON.stringify(concrete.chain));
  } finally { cleanup(dir); }

  // ── (2) o planner emite o campo, e o plan-checker cruza writes × engine ──
  const planner = readRepoText(path.join(ROOT, 'agents', 'forge-planner.md'));
  assert(/^worker:\s*claude\s+#/m.test(planner) || /```yaml\n[\s\S]*?^worker:/m.test(planner),
    '(2a) forge-planner mostra `worker:` como campo de frontmatter a emitir');
  assert(/[Pp]rose is inert|prosa é inerte/.test(planner),
    '(2a) forge-planner diz com todas as letras que a decisão em prosa é INERTE — uma key_decision não roteia nada');
  assert(/MUST\*{0,2}\s*emit that conclusion|\*\*MUST\*\* emit/.test(planner),
    '(2a) a emissão do campo é obrigação, não sugestão');
  assert(/writing\/creating `\.gsd\/\*\*`/.test(planner) && /worker: claude/.test(planner),
    '(2a) a tabela nomeia `.gsd/**` entre os casos em que `worker: claude` é obrigatório');

  const checker = readRepoText(path.join(ROOT, 'agents', 'forge-plan-checker.md'));
  assert(/forge-dispatch-resolve\.js[^\n]*--plan/.test(checker),
    '(2b) o plan-checker resolve o engine pela CLI canônica em vez de adivinhar');
  assert(/dispatch_engine/.test(checker) && /Engine ↔ `\.gsd\/\*\*` check/.test(checker),
    '(2b) existe o cruzamento writes/expected_output `.gsd/**` × engine resolvido');
  assert(/\*\*1 or more\*\* tasks[\s\S]{0,200}?\*\*`fail`\*\*/.test(checker),
    '(2b) uma única ocorrência já é `fail` — a barra do sidecar contra `.gsd/**` é absoluta');
  assert(!/Dimension 11|#### Dimension 1[1-9]/.test(checker),
    '(2b) nenhuma 11ª dimensão foi criada — as 10 travadas seguem travadas (MEM013)');
  // O guard só morde porque (1) foi corrigido: com o bug, `worker: claude`
  // resolvia com model='claude'/engine claude — o cruzamento continuaria
  // apontando claude e o defeito real (plano SEM worker:) é o que ele pega.
  // Ancorado na frase do PRÓPRIO guard: 'camada 1'/'camada 2' já aparecem no
  // Step 3.5 pré-existente, então um anchor solto passaria mesmo com o guard
  // removido (medido ao mutar) — cobertura declarada sem mordida.
  assert(/forge-planner\.md § Worker Engine/.test(checker),
    '(2b) o guard nomeia o constraint do planner que ele detecta (camada 1 ↔ camada 2), e não passa por texto vizinho');

  // ── (3) Branch C fecha o plano, no canônico e em cada mirror que enumera ─
  // Mecanismo espelhado, não inventado: é a MESMA edição do step 13 do
  // agents/forge-executor.md, que é como o caminho Claude marca.
  assert(/13\.\s*\*\*Mark task complete:\*\*\s*update `status: DONE`/.test(
    readRepoText(path.join(ROOT, 'agents', 'forge-executor.md'))),
    '(3a) o caminho Claude marca `status: DONE` no step 13 do executor — a fonte que a Branch C espelha');

  const branchC = [
    ['shared/forge-dispatch.md', 'canônico'],
    ['skills/forge-auto/SKILL.md', 'mirror forge-auto'],
    ['skills/forge-next/SKILL.md', 'mirror forge-next'],
  ];
  for (const [rel, label] of branchC) {
    const text = sidecarSurface(path.join(ROOT, rel));  // sidecar surface (2026-08-23)
    assert(/status: DONE[\s\S]{0,400}?T##-PLAN\.md|T##-PLAN\.md[\s\S]{0,400}?status: DONE/.test(text),
      `(3b) ${label} (${rel}) manda marcar \`status: DONE\` no T##-PLAN.md`);
    assert(/forge-executor\.md`? step 13|step 13 (of|performs)/.test(text),
      `(3b) ${label} referencia o step 13 do executor — espelha o mecanismo existente, não inventa outro`);
  }

  const task = readRepoText(path.join(ROOT, 'skills', 'forge-task', 'SKILL.md'));
  assert(/No plan-status marking here — deliberate, not an omission/.test(task),
    '(3c) forge-task declara EXPLICITAMENTE que não marca — a ausência é decisão registrada, não esquecimento');
  assert(/\{TASK_ID\}-SUMMARY\.md/.test(task),
    '(3c) e nomeia o sinal de done que ele realmente usa (existência do SUMMARY)');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeInertRoutes\(\); \}/.test(mainBody),
    '(4) Section 99 está registrada em main() por closure — seção não-registrada é seção que some em silêncio');

  pass('(final) Section 99: o token de família volta a pinar só o engine (modelo e clamp vêm do tier, provado no resolver '
    + 'real com fixture hermética e precedência de id concreto preservada), o planner é obrigado a emitir `worker:` e o '
    + 'plan-checker cruza `.gsd/**` × engine resolvido dentro das 10 dimensões travadas, e a Branch C fecha o plano com a '
    + 'mesma edição do step 13 no canônico e nos dois mirrors que enumeram o passo — com a não-aplicabilidade do '
    + 'forge-task declarada em vez de silenciosa');
}

// ── Section 100: o campo `transport` chega aos 9 emissores ────────────────
// Um campo decidido num helper e não emitido pelo emissor é o defeito de classe
// da TASK-021: a decisão existe, o consumidor nunca a vê. Aqui a prova é feita
// com LEITURA IN-PROCESS (`fs`), NUNCA com `grep` de shell — o `grep` deste
// ambiente é `ugrep --ignore-files` e honra `.gitignore`, então pode varrer nada
// e ainda assim reportar sucesso (achado da S06).
// Três armadilhas medidas, cada uma com controle positivo (o assert é rodado
// contra uma cópia MUTADA em memória, provando que ele morde de verdade):
//   (a) censo — exatamente 9 linhas de emissor, TODAS com `transport`. Contagem
//       e predicado juntos: acrescentar um 10º emissor sem o campo falha.
//   (b) fence — nos sites 2 e 4 (Branch D) o fence do `echo` precisa RESOLVER
//       $RESULT_FILE ele mesmo; estado de shell não sobrevive à fronteira do
//       Bash tool (foi o que produziu o `hint` permanentemente vazio).
//   (c) sem default otimista — `:-app-server` (ou qualquer default que não seja
//       `unknown`) num fence de emissor transforma "não observei" em "observei".
function smokeTransportField() {
  process.stdout.write('\n▸ Section 100: o campo `transport` chega aos 9 emissores\n');
  const ROOT = path.dirname(SCRIPTS);
  const FILES = [
    path.join(ROOT, 'skills', 'forge-auto', 'SKILL.md'),
    path.join(ROOT, 'skills', 'forge-next', 'SKILL.md'),
    path.join(ROOT, 'skills', 'forge-task', 'SKILL.md'),
  ];
  const EMITTER = '\\"event\\":\\"dispatch\\"';

  const emitterLines = (text) => text.split('\n').filter(l => l.includes(EMITTER) && l.includes('echo '));

  // ── (a) censo: 9 emissores, todos com transport ──────────────────────────
  const all = [];
  for (const file of FILES) all.push(...emitterLines(sidecarSurface(file)).map(line => ({ file, line })));  // sidecar surface (2026-08-23)
  assert(all.length === 9,
    `(a) exatamente 9 linhas de emissor de dispatch nos três SKILL.md (achadas: ${all.length})`,
    all.map(e => path.basename(path.dirname(e.file))).join(', '));
  // Case-insensitive on purpose: the codex emitters carry the field through the
  // shell variable ${TRANSPORT_TAIL}, the claude ones through the literal key.
  const withoutField = all.filter(e => !/transport/i.test(e.line));
  assert(withoutField.length === 0,
    '(a) TODOS os 9 emissores carregam `transport` — contagem e predicado juntos, para que um 10º emissor sem o campo falhe',
    `${withoutField.length} sem o campo`);

  const claudeLines = all.filter(e => e.line.includes('\\"transport\\":\\"in-process\\"'));
  const codexLines = all.filter(e => e.line.includes('${TRANSPORT_TAIL}'));
  assert(claudeLines.length === 4,
    `(a) os 4 emissores do caminho claude carregam a constante in-process (achados: ${claudeLines.length})`);
  assert(codexLines.length === 5,
    `(a) os 5 emissores do caminho codex carregam o TRANSPORT_TAIL derivado do result file (achados: ${codexLines.length})`);
  assert(claudeLines.length + codexLines.length === all.length,
    '(a) o censo PARTICIONA os 9 emissores — nenhum fica fora das duas classes');
  for (const e of claudeLines) {
    assert(!e.line.includes('transport_version') && !e.line.includes('transport_reason'),
      '(a) o caminho claude NÃO emite transport_version nem transport_reason — versão só faz sentido com processo remoto, razão só com kind unknown',
      e.file);
  }

  // ── (b) fence trap: sites 2 e 4 resolvem o estado no próprio fence ───────
  // Um fence é delimitado por ```bash … ```; a busca é pelo bloco que CONTÉM o
  // echo do plan-slice, e o teste é sobre esse bloco, não sobre o arquivo.
  const fenceContaining = (text, needle) => {
    const blocks = text.split('```');
    return blocks.find(b => b.includes(needle) && b.includes('echo '));
  };
  for (const file of FILES.slice(0, 2)) {
    const text = sidecarSurface(file);  // sidecar surface (2026-08-23)
    const fence = fenceContaining(text, 'plan-slice/${S##}');
    assert(!!fence, `(b) fence do emissor plan-slice encontrado em ${path.basename(path.dirname(file))}`);
    assert(/forge-xllm-state\.js"? --mode read/.test(fence),
      '(b) o fence do echo plan-slice RE-RESOLVE o state file nele mesmo — estado de shell não cruza a fronteira do Bash tool',
      file);
    assert(/RESULT_FILE=/.test(fence),
      '(b) e atribui RESULT_FILE no mesmo fence — sem isso o transporte nasce permanentemente vazio (forma da TASK-021)',
      file);
  }

  // ── (c) sem default otimista ─────────────────────────────────────────────
  const OPTIMISTIC = /\$\{TRANSPORT[A-Z_]*:-(?!unknown)[^}]*\}/;
  for (const file of FILES) {
    const text = readRepoText(file);
    assert(!OPTIMISTIC.test(text),
      '(c) nenhum default de shell para o transporte além de `unknown` — `:-app-server` transformaria "não observei" em "observei"',
      file);
    assert(text.includes(':-unknown}') || !text.includes('TRANSPORT'),
      '(c) o default nomeado `unknown` está presente onde o transporte é lido');
  }

  // ── controles positivos: cada assert acima morde ─────────────────────────
  // Um gate que reporta a própria inatividade como boa notícia é o defeito que
  // este repo já pagou três vezes. Cada predicado é rodado contra uma cópia
  // MUTADA que deveria reprová-lo.
  const autoText = sidecarSurface(FILES[0]);  // sidecar surface (2026-08-23)
  const strippedField = autoText.replace(/,\$\{TRANSPORT_TAIL\}/g, '').replace(/,\\"transport\\":\\"in-process\\"/g, '');
  assert(emitterLines(strippedField).some(l => !/transport/i.test(l)),
    '(controle) o predicado do censo REPROVA uma cópia em que o campo foi removido');
  const strippedFence = autoText.replace(/XLLM_STATE=\$\(node "\$FORGE_SCRIPTS_DIR\/forge-xllm-state\.js" --mode read[^\n]*\n/g, '');
  const brokenFence = fenceContaining(strippedFence, 'plan-slice/${S##}');
  assert(!!brokenFence && !/forge-xllm-state\.js"? --mode read/.test(brokenFence),
    '(controle) o predicado do fence REPROVA uma cópia em que a re-resolução foi "simplificada" para fora');
  assert(OPTIMISTIC.test('TRANSPORT_TAIL="\\"transport\\":\\"${TRANSPORT:-app-server}\\""'),
    '(controle) o predicado do default otimista REPROVA um `:-app-server` de verdade');
  assert(!OPTIMISTIC.test('X="${TRANSPORT:-unknown}"'),
    '(controle) e NÃO reprova o default nomeado `unknown` — o predicado distingue os dois');

  // ── o helper existe, exporta o contrato e a doc bate com o emitido ───────
  const transport = require('./forge-transport.js');
  assert(transport.TRANSPORT_KINDS.includes('app-server')
    && transport.TRANSPORT_KINDS.includes('in-process')
    && transport.TRANSPORT_KINDS.includes('unknown'),
    '(d) o enum de kinds do helper cobre os três valores que os emissores escrevem');
  assert(transport.deriveTransport({ initializeResult: {}, threadStartResult: {} }).kind === 'app-server',
    '(d) o kind vem da PRESENÇA — objetos de handshake vazios ainda são app-server (imune à divergência mock × servidor real)');
  assert(transport.deriveTransport({ initializeResult: {}, threadStartResult: null }).kind === 'unknown',
    '(d) e um handshake ausente é `unknown`, nomeado, nunca otimista');

  const doc = readRepoText(path.join(ROOT, 'shared', 'forge-dispatch.md'));
  assert(/\| `transport` \|/.test(doc) && /\| `transport_version` \|/.test(doc) && /\| `transport_reason` \|/.test(doc),
    '(e) as três linhas do contrato estão na tabela de campos de shared/forge-dispatch.md');
  assert(/[Aa]bsence of `transport` means the record predates TASK-022/.test(doc),
    '(e) a doc DIZ que ausência = registro anterior à TASK-022 — nunca in-process, nunca unknown');
  assert(/never the raw `userAgent`/.test(doc),
    '(e) e que só a versão extraída é logada, nunca o userAgent cru (que carrega SO e arquitetura)');

  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeTransportField\(\); \}/.test(mainBody),
    '(f) Section 100 está registrada em main() por closure — seção não-registrada é seção que some em silêncio');

  pass('(final) Section 100: os 9 emissores de dispatch carregam `transport` (5 do codex derivados do result file, 4 do '
    + 'claude com a constante in-process e sem os companheiros), os fences da Branch D re-resolvem $RESULT_FILE neles '
    + 'mesmos, nenhum default de shell é otimista, o kind vem da presença do handshake, e a doc declara o significado da '
    + 'ausência — com controle positivo provando que cada predicado morde');
}

// ── Section 101: routing domains reach the planner through rendered prompts ──
function smokeRoutingDomainsRendered() {
  process.stdout.write('\n▸ Section 101: rendered routing/repository planner headers\n');
  const { renderPrompt, _private } = require('./forge-prompt.js');
  const repoRoot = path.dirname(SCRIPTS);
  const dir = mkTmp('routing-domains-rendered');
  const home = path.join(dir, 'home');
  const templateDir = path.join(dir, 'templates');
  const options = unitType => ({ cwd: dir, unitType, milestoneId: 'M001', sliceId: 'S01', description: 'x', templateDir });
  const inspectRendered = prompt => {
    const reasons = [];
    // Horizontal whitespace ONLY ([^\S\r\n]), never \s — \s matches \n, so on a bare
    // "ROUTING_DOMAINS:\nWORKSPACE_REPOS: api, web" it would swallow the newline and
    // capture the NEXT line, making the value look populated. That silently disables
    // the bare-line check, which is one of the three degenerate forms this predicate
    // exists to reject (CONTEXT Q4) — a verde-inerte guard by construction.
    const domain = prompt.match(/^ROUTING_DOMAINS:[^\S\r\n]*(.*)$/m);
    const repos = prompt.match(/^WORKSPACE_REPOS:[^\S\r\n]*(.*)$/m);
    if (!domain) reasons.push('missing-routing-domains');
    else if (!domain[1]) reasons.push('bare-routing-domains');
    else if (domain[1].includes('{routing_domains}')) reasons.push('raw-routing-token');
    else if (domain[1] === _private.NO_DOMAINS_NOTICE) reasons.push('routing-notice');
    if (!repos) reasons.push('missing-workspace-repos');
    else if (!repos[1]) reasons.push('bare-workspace-repos');
    else if (repos[1].includes('{workspace_repos}')) reasons.push('raw-repos-token');
    else if (repos[1] === _private.SINGLE_REPO_NOTICE) reasons.push('repos-notice');
    return { ok: reasons.length === 0, reasons };
  };
  const oldHome = process.env.HOME;
  const oldUserProfile = process.env.USERPROFILE;
  try {
    fs.mkdirSync(path.join(dir, 'api', '.git'), { recursive: true });
    fs.mkdirSync(path.join(dir, 'web', '.git'), { recursive: true });
    fs.mkdirSync(path.join(dir, '.gsd'), { recursive: true });
    fs.mkdirSync(home, { recursive: true });
    // jsonc, not legacy .md: after the prefs cutover a bare claude-agent-prefs.md is a
    // deliberate hard-stop (`legacy-md-without-jsonc`), so readPrefsCached returns
    // ok:false and listDomains() returns []. A .md fixture would therefore exercise the
    // DEGRADATION path while claiming to be the positive case — the section would be
    // asserting the opposite of what it says. See shared/forge-prefs-cutover.md.
    fs.writeFileSync(path.join(dir, '.gsd', 'forge-prefs.jsonc'), JSON.stringify({ routing: { alpha: {}, beta: {} } }, null, 2));
    fs.mkdirSync(templateDir, { recursive: true });
    for (const name of ['plan-slice.md', 'plan-milestone.md']) fs.copyFileSync(path.join(repoRoot, 'shared', 'templates', 'dispatch', name), path.join(templateDir, name));
    process.env.HOME = home;
    process.env.USERPROFILE = home;
    const slice = renderPrompt(options('plan-slice'));
    const checked = inspectRendered(slice.prompt);
    assert(slice.template_scope === 'explicit', '(a) plan-slice uses the explicitly pinned template root');
    assert(checked.ok, `(a-d) rendered plan-slice headers are populated: ${checked.reasons.join(', ')}`);
    assert(/ROUTING_DOMAINS: alpha, beta/.test(slice.prompt), '(a) rendered domains use fixture routing keys');
    assert(/WORKSPACE_REPOS: (?:api, web|web, api)/.test(slice.prompt), '(a) rendered repositories list both fixture repos');
    assert(!slice.prompt.includes('{routing_domains}') && !slice.prompt.includes('{workspace_repos}'), '(b) rendered slice retains no raw placeholder tokens');
    assert(!slice.prompt.includes(_private.NO_DOMAINS_NOTICE) && !slice.prompt.includes(_private.SINGLE_REPO_NOTICE), '(c) rendered slice retains no degradation notices');
    const milestone = renderPrompt(options('plan-milestone'));
    assert(/^ROUTING_DOMAINS:\s*alpha, beta$/m.test(milestone.prompt) && !milestone.prompt.includes('WORKSPACE_REPOS'), '(e) milestone has populated routing domains and no workspace repos header');

    for (const name of ['plan-slice.md', 'plan-milestone.md']) {
      const target = path.join(templateDir, name);
      fs.writeFileSync(target, fs.readFileSync(target, 'utf8').replace(/^ROUTING_DOMAINS:.*\r?\n|^WORKSPACE_REPOS:.*\r?\n/gm, ''));
    }
    assert(!inspectRendered(renderPrompt(options('plan-slice')).prompt).ok, '(f) predicate goes RED when injected headers are removed');
    fs.copyFileSync(path.join(repoRoot, 'shared', 'templates', 'dispatch', 'plan-slice.md'), path.join(templateDir, 'plan-slice.md'));
    assert(inspectRendered(renderPrompt(options('plan-slice')).prompt).ok, '(f) predicate returns GREEN when headers are restored');
    for (const [prompt, reason] of [
      ['ROUTING_DOMAINS: {routing_domains}\nWORKSPACE_REPOS: api, web\n', 'raw-routing-token'],
      [`ROUTING_DOMAINS: ${_private.NO_DOMAINS_NOTICE}\nWORKSPACE_REPOS: api, web\n`, 'routing-notice'],
      ['ROUTING_DOMAINS:\nWORKSPACE_REPOS: api, web\n', 'bare-routing-domains'],
    ]) assert(inspectRendered(prompt).reasons.includes(reason), `(f) predicate rejects ${reason}`);
    const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
    assert(/smokeRoutingDomainsRendered\(\);/.test(mainBody), '(g) Section 101 is registered in main()');
  } finally {
    if (oldHome === undefined) delete process.env.HOME; else process.env.HOME = oldHome;
    if (oldUserProfile === undefined) delete process.env.USERPROFILE; else process.env.USERPROFILE = oldUserProfile;
    cleanup(dir);
  }
  pass('(final) Section 101: real rendered planner prompts carry routing and repository values with a biting fixture guard');
}

// ── Section 113: VERSION acompanha a linha de release das tags ──────────────
//
// `.github/workflows/release.yml` calcula o semver pelos commits convencionais
// e cria a tag SOZINHO a cada merge com `feat:`/`fix:` — e nunca toca
// `scripts/forge-version.js`. O resultado é drift silencioso: medido em
// 2026-08-15, VERSION dizia `4.11.0` num checkout tagueado `v4.14.2`, ou seja
// quem instalasse da master recebia projeções com `version=4.11.0` no marcador
// de origem. O bump manual anterior tratou UMA instância; a causa é o workflow.
//
// O resolvedor canônico calcula a mesma tag prospectiva usada pelo workflow e
// exige igualdade EXATA. Assim um PR `fix:` declara o próximo patch antes do
// merge, em vez de aceitar drift permanente como ruído.
//
// Vive no smoke porque só o job do smoke faz checkout com `fetch-depth: 0` —
// o job de testes é depth-1 e não enxerga tag nenhuma. Mesmo precedente do
// gate de escopo S07, e pela mesma razão.
function smokeVersionTagLine() {
  process.stdout.write('\n▸ Section 113: VERSION acompanha exatamente a release prospectiva\n');
  // A linha-resumo desta seção só é emitida se os asserts acima seguraram. O
  // padrão da casa a emite incondicionalmente, o que imprime um ✓ afirmando
  // sucesso ao lado de um ✗ real — uma alegação falsa no artefato cuja função é
  // não fazer alegações falsas. Local a esta seção, sem tocar as outras.
  const failsBefore = fails;
  const { VERSION } = require('./forge-version.js');
  const releaseVersion = require('./forge-release-version.js');
  const repoRoot = path.resolve(__dirname, '..');
  let resolution = null;
  try { resolution = releaseVersion.resolveVersion(repoRoot); }
  catch (error) { assert(false, '(a) release prospectiva é mensurável', error.message); }
  assert(Boolean(resolution && resolution.new_tag), '(a) release prospectiva é mensurável');
  let checked = null;
  try { checked = releaseVersion.checkDeclaredVersion(resolution, VERSION); }
  catch (error) { assert(false, `(b) VERSION ${VERSION} casa exatamente com ${resolution.new_tag}`, error.message); }
  assert(Boolean(checked && checked.ok), `(b) VERSION ${VERSION} casa exatamente com ${resolution.new_tag}`);

  // Controle positivo: a comparação precisa MORDER. Uma linha deliberadamente
  // diferente tem de reprovar pelo mesmo predicado.
  let bitten = false;
  try { releaseVersion.checkDeclaredVersion(resolution, '9.99.0'); } catch (_) { bitten = true; }
  assert(bitten, '(c) controle positivo: uma versão divergente é reprovada pelo mesmo predicado');

  if (fails === failsBefore) {
    pass('Section 113: VERSION e a release prospectiva coincidem exatamente, com piso anti-silêncio');
  }
}

// ── Section 102: ledger snapshot proven in the RENDERED prompt + D1 exclusion ──
//
// S02's whole claim in one section: the ledger snapshot reaches plan-slice —
// newest entries whole, oldest omitted, exact-entry marker, literal re-read
// command — proven on the RENDERED prompt (never the template alone, the #77 /
// MEM002 mold: a green guard anchored on the wrong artifact hid an inert wire
// for weeks); and execute-task receives none of it (D1), with a positive
// control proving the absence assert is not blind — the predicate is shown
// seeing the ids in plan-slice BEFORE it is trusted to report their absence in
// execute-task.
//
// The maxTokens budget below is never hand-computed: it is found by scanning
// the REAL renderLedgerSnapshot() until it reports omitted_count === 2 — the
// builder (S02 B1) is the single source of the block shape and the selection,
// so a hardcoded byte count here would silently drift from what it claims to
// measure the moment the block shape changes.
function smokeLedgerSnapshotRendered() {
  process.stdout.write('\n▸ Section 102: ledger snapshot in the rendered plan-slice prompt + D1 exclusion for execute-task\n');
  const { renderPrompt } = require('./forge-prompt.js');
  const projection = require('./forge-projection.js');
  const repoRoot = path.dirname(SCRIPTS);
  const dir = mkTmp('ledger-snapshot-rendered');
  const templateDir = path.join(repoRoot, 'shared', 'templates', 'dispatch');
  try {
    const ledgerDir = path.join(dir, '.gsd', 'ledger');
    fs.mkdirSync(ledgerDir, { recursive: true });

    // 4 deterministic fragments, distinct greppable ids and controlled
    // completed_at dates (molde seções 88-90). Equal-size bodies keep every
    // entry's token weight uniform so the calibration scan below is stable.
    const entries = [
      { id: 'M-20260101000000-oldest-aa', completed_at: '2026-01-01T00:00:00Z', title: 'Oldest' },
      { id: 'M-20260202000000-second-bb', completed_at: '2026-02-02T00:00:00Z', title: 'Second' },
      { id: 'M-20260303000000-recent-cc', completed_at: '2026-03-03T00:00:00Z', title: 'Recent' },
      { id: 'M-20260404000000-newest-dd', completed_at: '2026-04-04T00:00:00Z', title: 'Newest' },
    ];
    const body = 'x'.repeat(200);
    for (const e of entries) {
      const content = [
        '---',
        `id: ${e.id}`,
        `title: ${e.title}`,
        `completed_at: ${e.completed_at}`,
        'slices: []',
        'key_files: []',
        'key_decisions: []',
        '---',
        '',
        body,
        '',
      ].join('\n');
      fs.writeFileSync(path.join(ledgerDir, `${e.id}.md`), content, 'utf8');
    }

    let maxTokens = null;
    let snap = null;
    for (let candidate = 40; candidate <= 2000; candidate += 5) {
      const s = projection.renderLedgerSnapshot(dir, { maxTokens: candidate });
      if (s.omitted_count === 2 && s.included_ids.length === 2) { maxTokens = candidate; snap = s; break; }
    }
    assert(maxTokens != null,
      '(setup) a maxTokens exists where exactly 2 of the 4 fixture entries survive',
      `no candidate in 40..2000 produced omitted_count===2 (last snap=${JSON.stringify(snap)})`);
    assert(!!snap && snap.included_ids.join(',') === 'M-20260404000000-newest-dd,M-20260303000000-recent-cc',
      '(setup) the 2 surviving ids are the 2 NEWEST fragments — recency selection, not directory order',
      snap ? JSON.stringify(snap.included_ids) : '(no snap)');

    // Disk path end-to-end, no options.ledger / ledgerProvider — the coupled
    // API seam (forge-prompt → forge-projection.renderLedgerSnapshot) is what
    // is under test, not a fixture-supplied override.
    const slice = renderPrompt({
      cwd: dir, unitType: 'plan-slice', milestoneId: 'M001', sliceId: 'S01',
      templateDir, ledgerMaxTokens: maxTokens, memories: [],
    });

    assert(slice.prompt.includes('M-20260404000000-newest-dd'),
      '(a) rendered plan-slice prompt contains the newest fixture id');
    assert(slice.prompt.includes('M-20260303000000-recent-cc'),
      '(a) rendered plan-slice prompt contains the second-newest fixture id');
    assert(!slice.prompt.includes('M-20260101000000-oldest-aa'),
      '(b B1) rendered plan-slice prompt does NOT contain the oldest fixture id');
    assert(!slice.prompt.includes('M-20260202000000-second-bb'),
      '(b B1) rendered plan-slice prompt does NOT contain the second-oldest fixture id');
    assert(/\[\.\.\.truncated 2 ledger entries — see node scripts\/forge-projection\.js --render ledger/.test(slice.prompt),
      '(c W1) the marker names exactly the 2 omitted ENTRIES (never sections) and the literal re-read command',
      slice.prompt.slice(-400));
    assert(slice.prompt.includes('[DATA FROM "LEDGER"') && slice.prompt.includes('[END DATA FROM "LEDGER"]'),
      '(c) the snapshot is wrapped in the DATA FROM / END DATA FROM markers');

    // D1 positive control BEFORE the absence assert: the predicate must first
    // be shown seeing the fixture ids at all (it just did, in plan-slice above)
    // so the execute-task absence assert below is not a blind, always-green
    // check on an id nothing ever produces.
    assert(slice.prompt.includes('M-20260404000000-newest-dd'),
      '(d control) positive control — the predicate DOES see fixture ids when they are actually injected (plan-slice)');

    const task = renderPrompt({
      cwd: dir, unitType: 'execute-task', milestoneId: 'M001', sliceId: 'S01', taskId: 'T01',
      templateDir, ledgerMaxTokens: maxTokens, memories: [],
    });
    for (const e of entries) {
      assert(!task.prompt.includes(e.id), `(d D1) rendered execute-task prompt does not contain fixture id ${e.id}`);
    }

    const execTemplate = readRepoText(path.join(templateDir, 'execute-task.md'));
    assert(!execTemplate.includes('{LEDGER}'),
      '(d D1) shared/templates/dispatch/execute-task.md (executable template, never the prose mirror) does not contain {LEDGER}');

    const sliceTemplate = readRepoText(path.join(templateDir, 'plan-slice.md'));
    const dataBlock = sliceTemplate.match(/\[DATA FROM "LEDGER"[^\n]*\n([\s\S]*?)\[END DATA FROM "LEDGER"\]/);
    assert(!!dataBlock, '(e) shared/templates/dispatch/plan-slice.md carries the LEDGER DATA markers');
    assert(!!dataBlock && dataBlock[1].includes('{LEDGER}'),
      '(e) shared/templates/dispatch/plan-slice.md (executable template) contains {LEDGER} between the DATA markers');

    const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
    assert(/smokeLedgerSnapshotRendered\(\);/.test(mainBody), '(f) Section 102 is registered in main()');
  } finally {
    cleanup(dir);
  }
  pass('(final) Section 102: {LEDGER} lands in the RENDERED plan-slice prompt with recency, an exact-entry marker and the '
    + 'literal re-read command; execute-task proves the absence (D1) with a positive control proving the predicate is not '
    + 'blind; and the template-level assert targets plan-slice.md, the executable template, never the prose mirror');
}

// ── Section 103: memory-index command proven in the EXECUTABLE TEMPLATE and ──
// ── in the RENDERED plan-slice prompt (D3: command, not content) ─────────────
//
// T02 wired a query command for scripts/forge-memory-index.js into
// shared/templates/dispatch/plan-slice.md, deliberately never the full index
// content (D3 — the whole point of --file is that the consult stays cheap).
// The MEM002 / PR #77 lesson is that a guard anchored on shared/forge-dispatch.md
// (the prose mirror) proves nothing about what forge-prompt.js actually reads —
// so this section asserts on BOTH: the executable template read straight off
// disk, and a real rendered plan-slice prompt produced by renderPrompt (mold:
// Section 102). A positive control (plan-slice sees the command) is asserted
// BEFORE the negative control (execute-task does not) so the absence assert is
// never a blind, always-green predicate. The token ceiling on the section is
// what makes "command, not content" falsifiable: if anyone ever inlines index
// facts into this block, the section grows past the ceiling and turns red.
function smokeMemoryIndexCommandRendered() {
  process.stdout.write('\n▸ Section 103: memory-index command in the executable template and the rendered plan-slice prompt\n');
  const { renderPrompt } = require('./forge-prompt.js');
  const { countTokens } = require('./forge-tokens.js');
  const repoRoot = path.dirname(SCRIPTS);
  const templateDir = path.join(repoRoot, 'shared', 'templates', 'dispatch');
  const dir = mkTmp('memory-index-command-rendered');
  try {
    // (a) executable template, never the prose mirror (MEM002 / PR #77).
    const sliceTemplate = readRepoText(path.join(templateDir, 'plan-slice.md'));
    const cmdLine = sliceTemplate.split('\n').find(l => l.includes('forge-memory-index.js'));
    assert(!!cmdLine,
      '(a) shared/templates/dispatch/plan-slice.md (executable template) contains a forge-memory-index.js command line');
    assert(!!cmdLine && cmdLine.includes('--file'),
      '(a) the same command line also carries --file, never a bare invocation',
      cmdLine || '(no line found)');
    assert(!!cmdLine && /--cwd\s+"\{WORKING_DIR\}"/.test(cmdLine),
      '(a) --cwd is quoted around {WORKING_DIR} in the template line — S02/R1: a bare path with a space breaks a pasted command',
      cmdLine || '(no line found)');

    // (b) rendered prompt — placeholders resolved, {WORKING_DIR} value quoted.
    const slice = renderPrompt({
      cwd: dir, unitType: 'plan-slice', milestoneId: 'M001', sliceId: 'S01', templateDir, memories: [],
    });
    const renderedLine = slice.prompt.split('\n').find(l => l.includes('forge-memory-index.js'));
    assert(!!renderedLine, '(b) rendered plan-slice prompt contains a forge-memory-index.js command line');
    assert(!!renderedLine && !/\{[A-Z_]+\}/.test(renderedLine),
      '(b) no raw {PLACEHOLDER} token survives on the rendered command line — every brace was resolved',
      renderedLine || '(no line found)');
    assert(!!renderedLine && renderedLine.includes('--file'),
      '(b) the rendered command line also carries --file');
    assert(!!renderedLine && new RegExp(`--cwd\\s+"${dir.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}"`).test(renderedLine),
      '(b) --cwd is quoted around the resolved WORKING_DIR value on the rendered line',
      renderedLine || '(no line found)');

    // (c) controls — positive ordered before negative, so the absence assert
    // below is never a blind predicate (Section 102 mold).
    assert(slice.prompt.includes('forge-memory-index.js'),
      '(c control) positive control — the predicate DOES see the command when it is actually injected (plan-slice)');
    const task = renderPrompt({
      cwd: dir, unitType: 'execute-task', milestoneId: 'M001', sliceId: 'S01', taskId: 'T01', templateDir, memories: [],
    });
    assert(!task.prompt.includes('forge-memory-index.js'),
      '(c) rendered execute-task prompt does not carry the memory-index command');
    const execTemplate = readRepoText(path.join(templateDir, 'execute-task.md'));
    assert(!execTemplate.includes('forge-memory-index.js'),
      '(c) shared/templates/dispatch/execute-task.md (executable template) does not carry the memory-index command');

    // (d) D3 — command, not content: the section itself stays under a small
    // fixed token ceiling, and the rendered prompt never carries an actual
    // index fact line or the index artifact's own header. If someone later
    // injects index content here, both asserts below turn red — that is the
    // design (T03 must-have #4).
    const sectionMatch = sliceTemplate.match(/## Memory Index[\s\S]*?(?=\n## Instructions)/);
    assert(!!sectionMatch, '(d) shared/templates/dispatch/plan-slice.md carries a ## Memory Index section');
    const sectionTokens = sectionMatch ? countTokens(sectionMatch[0]) : Infinity;
    assert(sectionTokens <= 150,
      `(d D3) the ## Memory Index section measures <= 150 tokens (command, not content) — measured ${sectionTokens}`);
    assert(!slice.prompt.includes('# Índice de memória por arquivo-fonte'),
      '(d D3) rendered plan-slice prompt does NOT contain the memory-index artifact\'s own header');
    assert(!/—\s*origem:\s*/.test(slice.prompt),
      '(d D3) rendered plan-slice prompt does NOT contain an index fact line ("— origem: ")');

    // (e) registered in main().
    const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
    assert(/smokeMemoryIndexCommandRendered\(\);/.test(mainBody), '(e) Section 103 is registered in main()');
  } finally {
    cleanup(dir);
  }
  pass('(final) Section 103: the memory-index query command lands in shared/templates/dispatch/plan-slice.md (the '
    + 'executable template, never the prose mirror — MEM002) and in a real rendered plan-slice prompt with placeholders '
    + 'resolved and --cwd quoted; execute-task carries neither (template nor render), proven with a positive control '
    + 'ordered first; and the section itself measures <= 150 tokens with no index fact line ever landing in the '
    + 'rendered prompt — command, not content (D3)');
}

// ── Section 104: canonical Forge script call sites ────────────────────────
function smokeScriptsCallSitesCanonical() {
  process.stdout.write('\n▸ Section 104: canonical Forge script call sites\n');
  const guard = require('./forge-scripts-callsites.js');
  const report = guard.scan({ root: path.resolve(__dirname, '..') });
  assert(report.outcome === 'clean', 'real tree is clean above the per-family census floor');
  for (const family of guard.CALL_SITE_FAMILIES) assert(report.scanned_by_family[family] > 0, `family scanned: ${family}`);
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeScriptsCallSitesCanonical\(\); \}/.test(mainBody), '(e) Section 104 is registered in main()');
  pass('Section 104: canonical path guard is clean, census is non-silent, and registration is biting');
}

// ── Section 105: the contract-miss branch exists in all three orchestrators ──
//
// The defect this guards is an ABSENCE, which is the hardest kind to keep
// fixed: before this work, grepping skills/forge-{auto,next,task} for missing
// result-block handling returned nothing at all, so a truncated worker had no
// named branch and the model improvised one at runtime. A guard on the canonical
// prose alone would repeat the MEM002 / PR #77 mistake — shared/forge-dispatch.md
// is the spec, but the SKILL.md files are what the orchestrator actually reads,
// so both are asserted, and the classifier is exercised behaviorally so the
// section can never go green over a wired-but-inert helper.
function smokeContractMissBranch() {
  process.stdout.write('\n▸ Section 105: contract-miss (Layer 0) branch wired in all three orchestrators\n');
  const repoRoot = path.dirname(SCRIPTS);
  const wr = require('./forge-worker-result.js');

  // (a) canonical spec — the section, its ladder and its boundary.
  const dispatch = readRepoText(path.join(repoRoot, 'shared', 'forge-dispatch.md'));
  assert(dispatch.includes('## Missing worker result (contract miss)'),
    '(a) shared/forge-dispatch.md carries the canonical § Missing worker result (contract miss)');
  const section = dispatch.slice(dispatch.indexOf('## Missing worker result (contract miss)'),
    dispatch.indexOf('## Node Repair'));
  for (const rung of ['worker-event', 'summary-file', 'plan-status', 'vcs-delta']) {
    assert(section.includes(rung), `(a) the canonical section names the ${rung} probe`);
  }
  assert(/never carries a verdict/i.test(section),
    '(a) the canonical section states that the VCS delta alone never carries a verdict');
  assert(/must_haves_status`?\*{0,2}\s+is never synthesized/i.test(section),
    '(a) the canonical section forbids synthesizing must_haves_status');
  assert(/codex-invalid-json/.test(section),
    '(a) the canonical section names the sidecar boundary rather than leaving it implied');

  // (b) Layer 0 is in the precedence table — otherwise the ladder is a section
  //     nothing routes into.
  assert(/\|\s*\*\*0\*\*\s*\|\s*Missing Result Contract\s*\|/.test(dispatch),
    '(b) the recovery-layer precedence table carries the Layer 0 row');

  // (c) executable surfaces — all three skills classify BEFORE parsing status.
  //     The call sites are shell lines, so the script name is followed by a
  //     closing quote before the flag: anchoring on the bare `script --flag`
  //     string matches nothing. That is not a nit — the first run of this
  //     section failed on exactly that, which is the section doing its job on
  //     itself before it ever guarded the feature.
  const CLASSIFY_CALL = /forge-worker-result\.js"?\s+--classify/;
  const SALVAGE_CALL = /forge-worker-result\.js"?\s+--salvage/;
  for (const skill of ['forge-auto', 'forge-next', 'forge-task']) {
    const text = readRepoText(path.join(repoRoot, 'skills', skill, 'SKILL.md'));
    assert(CLASSIFY_CALL.test(text),
      `(c) skills/${skill}/SKILL.md classifies the return before parsing it`);
    assert(SALVAGE_CALL.test(text),
      `(c) skills/${skill}/SKILL.md invokes the disk salvage`);
    assert(text.includes('§ Missing worker result (contract miss)'),
      `(c) skills/${skill}/SKILL.md names the canonical section instead of restating the ladder`);
    const classifyAt = text.search(CLASSIFY_CALL);
    const parseAt = text.search(/Parse the `---GSD-WORKER-RESULT---` block:|\*\*Process result:\*\*/);
    assert(classifyAt !== -1 && parseAt !== -1 && classifyAt < parseAt,
      `(c) skills/${skill}/SKILL.md runs the gate BEFORE the status parse — a Layer 0 that fires after Layer 2 read the status is inert`);
  }

  // (d) behavioral floor — the classifier separates the two returns that the
  //     whole layer exists to tell apart, with the positive control first so
  //     the negative assert is never blind.
  const complete = wr.classifyReturn('did the work\n\n---GSD-WORKER-RESULT---\nstatus: done\nsummary: x\n');
  assert(complete.shape === 'complete' && complete.status === 'done',
    '(d control) positive control — a well-formed return still classifies as complete');
  const truncated = wr.classifyReturn('Implemented T05, ran the gate, and then the message stops mid-sen');
  assert(truncated.shape === 'absent' && truncated.status === null,
    '(d) a truncated return does NOT resolve to a status');
  const cutBlock = wr.classifyReturn('narration\n---GSD-WORKER-RESULT---\nunit_type: execute-ta');
  assert(cutBlock.shape === 'status-missing',
    '(d) a block cut before its status is status-missing, not a verdict');

  // (e) salvage never invents: zero inputs yields a named reason and a full
  //     probe census, never a bare empty object that reads like "all clear".
  const empty = wr.salvageUnit({ unit: 'execute-task/T05' });
  assert(empty.recovered === null && empty.reason === 'no-evidence',
    '(e) a salvage with nothing to read recovers nothing and names why');
  assert(empty.probes.length === 4 && empty.probes.every(p => ['hit', 'miss', 'unavailable'].includes(p.outcome)),
    '(e) every probe is reported with a closed-set outcome — a report of only its hits is indistinguishable from one that never ran');

  // (f) the hook stops laundering a failed-open escape into `done`.
  const hook = readRepoText(path.join(SCRIPTS, 'forge-hook.js'));
  assert(hook.includes('contract-miss.jsonl'),
    '(f) forge-hook.js records the contract miss durably');
  assert(/status\s*:\s*escaped\s*\?\s*'contract-missed'\s*:\s*'done'/.test(hook),
    '(f) the SubagentStop escape path writes contract-missed, not done');

  // (g) registered in main().
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeContractMissBranch\(\); \}/.test(mainBody), '(g) Section 105 is registered in main()');

  pass('(final) Section 105: the Layer 0 contract-miss branch is canonical in shared/forge-dispatch.md (ladder, probe '
    + 'names, the vcs-delta-never-decides rule and the sidecar boundary), sits in the recovery-layer precedence table, '
    + 'and is wired BEFORE the status parse in all three orchestrator skills; the classifier separates a truncated '
    + 'return from a complete one behaviorally, the salvage names its nothing instead of returning a silent empty, and '
    + 'the SubagentStop escape no longer reports a contract-less worker as done');
}

// ── Section 106: the paths that run are the paths that are managed ───────────
//
// Two files have to agree and neither can see the other: `merge-settings.js`
// writes commands into settings.json, and the maintained surfaces — the render
// targets of `forge-source-manifest.json` plus the installer's MANAGED_CORE
// recopy into `~/.forge-agent/` — decide which destinations an update actually
// refreshes. They disagreed twice. First the hook command (settings wired
// `~/.claude/forge-hook.js`, the manifest projected only
// `~/.claude/hooks/forge-hook.js`). Then the statusline: settings wired
// `~/.claude/forge-statusline.js`, a render target of NO source, so the copy
// Claude Code executed froze across releases — and its `__dirname` companions
// (forge-runs.js, forge-accounts.js, …) vanished when retireLegacyScripts
// removed `~/.claude/scripts/`, degrading the account badge, the runs
// indicator and the usage poll in silence. The first fix narrowed this miner
// to `forge-hook\.js` only, which is exactly why the second freeze sailed
// through it: a guard that enumerates one filename is blind to the next one.
// The miner now matches every `forge-*.js` command merge-settings.js emits.
function smokeHookPathManaged() {
  process.stdout.write('\n▸ Section 106: every executed forge-*.js path is a managed projection\n');
  const repoRoot = path.dirname(SCRIPTS);
  const renderer = require('./forge-claude-renderer.js');
  const { MANAGED_CORE } = require('./forge-installer.js');

  // (a) every `node ~/…forge-*.js` command merge-settings.js emits, mined from
  //     its source — any forge script, not one enumerated filename.
  const MINER = /node\s+(~\/[^\s`'"]*forge-[^\s`'"/]*\.js)/g;
  const merge = readRepoText(path.join(SCRIPTS, 'merge-settings.js'));
  const wired = [...merge.matchAll(MINER)].map((m) => m[1]);
  const wiredPaths = [...new Set(wired)];
  assert(wiredPaths.some((p) => /\bforge-hook\.js$/.test(p)),
    '(a) the miner still sees the hook commands — not blind to the family the old regex covered');
  assert(wiredPaths.some((p) => /\bforge-statusline\.js$/.test(p)),
    '(a) the miner sees the statusline command — the exact family the old forge-hook-only regex was blind to');

  // (b) the manifest's projected destinations, expressed in the same `~/…`
  //     vocabulary merge-settings.js writes. The tilde is the USER home, not
  //     the Claude home, so the fake home below is laid out the way a real
  //     install is (`<home>/.claude`, `<home>/.forge-agent`) and paths are made
  //     relative to the user home — comparing against the Claude home instead
  //     yields `~/forge-hook.js` and the agreement check silently never
  //     matches. No source_id filter: filtering to `hooks` was the same
  //     enumeration mistake as the hook-only miner. Destinations outside the
  //     user home (project files) cannot be wired as `~/…` commands and drop
  //     out by construction.
  const userHome = path.join(os.tmpdir(), 'forge-smoke-hookpath-home');
  const report = renderer.render({
    repo: repoRoot,
    projectRoot: repoRoot,
    claudeHome: path.join(userHome, '.claude'),
    forgeHome: path.join(userHome, '.forge-agent'),
  });
  const projected = report.artifacts
    .map((a) => path.relative(userHome, a.destination))
    .filter((rel) => rel && !rel.startsWith('..') && !path.isAbsolute(rel))
    .map((rel) => '~/' + rel.split(path.sep).join('/'));
  assert(projected.length > 0, '(b) the manifest projects at least one destination under the user home');
  const hooksProjected = report.artifacts
    .filter((a) => a.source_id === 'hooks')
    .map((a) => '~/' + path.relative(userHome, a.destination).split(path.sep).join('/'));
  assert(hooksProjected.length > 0 && hooksProjected.every((p) => p.startsWith('~/.claude/')),
    `(b) projected hook paths are expressed against the user home — got ${JSON.stringify(hooksProjected)}`);

  // (b2) the second maintained surface: the installer recopies MANAGED_CORE
  //     verbatim from the repo into the Forge home on EVERY install/update
  //     (forge-installer.js § MANAGED_CORE → copyTree), so a wired path under
  //     `~/.forge-agent/` is maintained iff its top segment is a managed-core
  //     item AND the same relative path exists in this repo. Both legs are
  //     required: prefix alone would bless a typo'd filename that no copy will
  //     ever produce.
  const FORGE_HOME_PREFIX = '~/.forge-agent/';
  const maintainedByCore = (p) => {
    if (!p.startsWith(FORGE_HOME_PREFIX)) return false;
    const rel = p.slice(FORGE_HOME_PREFIX.length).split('/');
    if (!MANAGED_CORE.includes(rel[0])) return false;
    return fs.existsSync(path.join(repoRoot, ...rel));
  };

  // (c) the agreement itself: every wired path is maintained by ONE of the two
  //     surfaces — a manifest projection or the managed-core recopy.
  const maintained = (p) => projected.includes(p) || maintainedByCore(p);
  for (const p of wiredPaths) {
    assert(maintained(p),
      `(c) settings.json runs ${p} but nothing maintains it — that copy will freeze silently`);
  }

  // (d) controls — every predicate above proven capable of failing, so (c) is
  //     never green for any input.
  assert(!wiredPaths.includes('~/.claude/nonexistent-hook.js'),
    '(d control) the wired-path miner does not invent paths');
  const minedSample = [...'run: node ~/.claude/forge-anything.js phase'.matchAll(MINER)].map((m) => m[1]);
  assert(minedSample.length === 1 && minedSample[0] === '~/.claude/forge-anything.js',
    '(d control) the widened miner catches an arbitrary forge-*.js command the old forge-hook-only regex ignored');
  assert(maintained('~/.claude/forge-nonexistent.js') === false,
    '(d control) an unprojected ~/.claude path is NOT maintained — the (c) loop can go red');
  assert(maintainedByCore('~/.forge-agent/scripts/forge-statusline.js') === true,
    '(d control) the managed-core predicate recognizes the real statusline copy under the Forge home');
  assert(maintainedByCore('~/.forge-agent/scripts/forge-no-such-file.js') === false,
    '(d control) a filename absent from the repo is NOT maintained — the managed prefix alone never passes');
  assert(maintainedByCore('~/.forge-agent/unmanaged-dir/forge-hook.js') === false,
    '(d control) a top segment outside MANAGED_CORE is NOT maintained even under the Forge home');

  // (e) script projections carry the ownership proof, so a second --update can
  //     replace them. Without this the fix in (c) maintains a file the write
  //     path still refuses to touch.
  const hookArtifact = report.artifacts.find((a) => a.source_id === 'hooks');
  assert(renderer.hasOriginMarker(hookArtifact.content),
    '(e) the hook projection carries an origin marker — otherwise it is preserved as user_owned forever');
  assert(hookArtifact.content.split('\n')[0].startsWith('#!'),
    '(e) the shebang stays on line 1 — a marker above it stops the file executing');

  // (f) registered in main().
  const source = fs.readFileSync(__filename, 'utf8');
  assert(/\(\) => \{ smokeHookPathManaged\(\); \}/.test(source.slice(source.lastIndexOf('async function main()'))),
    '(f) Section 106 is registered in main()');

  pass('(final) Section 106: every forge-*.js path merge-settings.js wires into settings.json — hook AND statusline — '
    + 'is maintained either by a manifest projection or by the installer\'s MANAGED_CORE recopy into ~/.forge-agent, so '
    + 'the copies Claude Code executes are refreshed rather than frozen; the hook projection carries an origin marker '
    + 'below an intact shebang, and every predicate was shown capable of failing');
}

// ── Merge note (origin/master → forge/M-20260813221024-controle-recursos) ──
// The six sections below were authored as 105-110 on the milestone branch.
// origin/master independently landed its own 105 and 106 while the milestone
// ran, so these six were shifted +2 (105->107 … 110->112) at merge time,
// preserving their creation order and leaving no gap. The provenance comments
// inside each section are left VERBATIM: they record what was actually
// measured at authoring time, and rewriting them to match the post-merge
// numbers would fabricate measurements that were never taken.
// ── Section 107: resolver + scanner bite bidirectionally, no real pressure ──
// Verified against the file's ACTUAL highest section (grep -n "^// ── Section
// [0-9]" | tail -3 → 102, 103, 104 — 104 is the real max at authoring time,
// matching the verification convention of Sections 96-98/99/104), NOT the
// number the task plan guessed (100) — the plan predates three later slices'
// sections landing on this file concurrently. Both mordidas asserted via
// real CLI spawns, never in-process require() of the resolver/scanner
// modules — a spawn is the same boundary a real caller crosses.
function smokeResourcesFoundation() {
  process.stdout.write('\n▸ Section 107: resolver (T01) + scanner (T03) bite both ways, no real pressure\n');
  const NODE = process.execPath;

  // ── (a) resolver: forced critical pressure -> admit:false, named reason ──
  const forcedCritical = spawnSync(NODE, [path.join(SCRIPTS, 'forge-resources.js'), '--json'], {
    encoding: 'utf8',
    env: { ...process.env, FORGE_RESOURCES_PRESSURE: '4' },
  });
  assert(forcedCritical.status === 0, '(a) resolver CLI always exits 0 (advisory posture) even under forced critical', String(forcedCritical.status));
  let forcedCriticalContract;
  try { forcedCriticalContract = JSON.parse(forcedCritical.stdout); } catch (e) { forcedCriticalContract = null; }
  assert(!!forcedCriticalContract, '(a) forced-critical CLI output parses as JSON', forcedCritical.stdout);
  if (forcedCriticalContract) {
    assert(forcedCriticalContract.admit === false, '(a) FORGE_RESOURCES_PRESSURE=4 -> admit:false (forced, never real pressure)', JSON.stringify(forcedCriticalContract));
    assert(forcedCriticalContract.reason === 'pressure-critical:forced-env',
      '(a) reason names the FORCED source, distinct from a measured-pressure reason', forcedCriticalContract.reason);
    assert(forcedCriticalContract.reason !== 'pressure-critical:measured',
      '(a) forced reason is never confusable with the measured-critical reason', forcedCriticalContract.reason);
  }

  // ── (b) resolver: forced normal pressure -> admit:true, sized budget ─────
  const forcedNormal = spawnSync(NODE, [path.join(SCRIPTS, 'forge-resources.js'), '--json'], {
    encoding: 'utf8',
    env: { ...process.env, FORGE_RESOURCES_PRESSURE: '1' },
  });
  assert(forcedNormal.status === 0, '(b) resolver CLI exits 0 under forced normal pressure', String(forcedNormal.status));
  let forcedNormalContract;
  try { forcedNormalContract = JSON.parse(forcedNormal.stdout); } catch (e) { forcedNormalContract = null; }
  assert(!!forcedNormalContract, '(b) forced-normal CLI output parses as JSON', forcedNormal.stdout);
  if (forcedNormalContract) {
    assert(forcedNormalContract.admit === true, '(b) FORGE_RESOURCES_PRESSURE=1 -> admit:true (forced, never real pressure)', JSON.stringify(forcedNormalContract));
    assert(Number.isInteger(forcedNormalContract.workers) && forcedNormalContract.workers >= 1,
      '(b) admitted budget sizes at least one worker', String(forcedNormalContract.workers));
    assert(Number.isFinite(forcedNormalContract.heapMb) && forcedNormalContract.heapMb > 0,
      '(b) admitted budget sizes a positive heapMb', String(forcedNormalContract.heapMb));
  }

  // ── (c) scanner: real scripts/ tree -> clean, scanned > 0 ────────────────
  const realScan = spawnSync(NODE, [path.join(SCRIPTS, 'forge-freemem-callsites.js'), '--check', '--json'], { encoding: 'utf8' });
  let realScanResult;
  try { realScanResult = JSON.parse(realScan.stdout); } catch (e) { realScanResult = null; }
  assert(!!realScanResult, '(c) real-tree scanner CLI output parses as JSON', realScan.stdout);
  if (realScanResult) {
    assert(realScanResult.scanned > 0, '(c) real scripts/ tree scan reaches scanned > 0 (anti-silence floor cleared)', String(realScanResult.scanned));
    assert(realScanResult.outcome === 'clean', '(c) real scripts/ tree has zero banned call sites -> clean', JSON.stringify(realScanResult));
    assert(realScan.status === 0, '(c) clean outcome exits 0', String(realScan.status));
  }

  // ── (d) scanner: temp tree with a planted violation -> non-zero, named file ──
  const violDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-freemem-viol-'));
  const violFile = path.join(violDir, 'planted.js');
  // Built by concatenation so this smoke section's own source is not itself a
  // false positive against forge-freemem-callsites.js's own ban.
  const plantedCall = 'os' + '.' + 'free' + 'mem' + '(';
  try {
    fs.writeFileSync(violFile, `'use strict';\nconst fs = require('fs');\nfunction reportFree() { return ${plantedCall}); }\nmodule.exports = { reportFree };\n`);
    const violScan = spawnSync(NODE, [path.join(SCRIPTS, 'forge-freemem-callsites.js'), '--check', '--json', '--root', violDir], { encoding: 'utf8' });
    assert(violScan.status !== 0, '(d) planted-violation temp tree exits non-zero', String(violScan.status));
    let violResult;
    try { violResult = JSON.parse(violScan.stdout); } catch (e) { violResult = null; }
    assert(!!violResult, '(d) planted-violation CLI output parses as JSON', violScan.stdout);
    if (violResult) {
      assert(violResult.outcome === 'violations', '(d) outcome is violations, not clean and not anti-silence', violResult.outcome);
      assert(violResult.violations.some((v) => v.file === violFile),
        '(d) the violation names the planted file exactly', JSON.stringify(violResult.violations));
    }
  } finally {
    try { fs.rmSync(violDir, { recursive: true, force: true }); } catch (e) { /* ignore */ }
  }

  // ── (e) scanner: empty temp dir -> non-zero, anti-silence reason ─────────
  const emptyDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-freemem-empty-'));
  try {
    const emptyScan = spawnSync(NODE, [path.join(SCRIPTS, 'forge-freemem-callsites.js'), '--check', '--json', '--root', emptyDir], { encoding: 'utf8' });
    assert(emptyScan.status !== 0, '(e) empty temp dir scan exits non-zero (never a silent pass)', String(emptyScan.status));
    let emptyResult;
    try { emptyResult = JSON.parse(emptyScan.stdout); } catch (e) { emptyResult = null; }
    assert(!!emptyResult, '(e) empty-dir CLI output parses as JSON', emptyScan.stdout);
    if (emptyResult) {
      assert(emptyResult.outcome === 'anti-silence', '(e) empty dir outcome is anti-silence, never clean', emptyResult.outcome);
      assert(emptyResult.scanned === 0, '(e) empty dir scanned count is 0', String(emptyResult.scanned));
      assert(typeof emptyResult.reason === 'string' && emptyResult.reason.length > 0
        && emptyResult.reason !== (realScanResult && realScanResult.reason),
        '(e) anti-silence reason is present and distinct from a violations-found reason', emptyResult.reason);
      if (realScanResult === null || realScanResult === undefined) {
        // no-op — real scan already asserted above; this branch only guards
        // against a null-vs-string comparison silently passing.
      }
    }
  } finally {
    try { fs.rmSync(emptyDir, { recursive: true, force: true }); } catch (e) { /* ignore */ }
  }

  // ── (f) registration: the section verifies it is wired into main() ───────
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeResourcesFoundation\(\); \}/.test(mainBody),
    '(f) Section 107 is registered in main() by closure — an unregistered section vanishes silently');

  pass('Section 107: forge-resources.js resolver admits/refuses on forced env (never real pressure), and '
    + 'forge-freemem-callsites.js scanner is clean on the real tree, red on a planted violation naming the '
    + 'file, and red-with-anti-silence-reason on an empty directory — all three via real CLI spawns');
}

// ── Section 108: resource pool (S02) — CLI census, two-process sum, resolver byte-stability ──
// Section number MEASURED at execution time (MEM013), not assumed: grepped
// "Section [0-9]+" across this file and took max+1 (105 was the real max —
// three later sections had already landed on this file by the time this
// section was authored, same drift class MEM013 documents). All three
// mordidas spawn real CLIs (child_process.spawn/spawnSync), never
// require() of forge-resource-pool.js / forge-resources.js in-process — a
// spawn is the same boundary a real caller (and forge-resource-pool.concurrency.test.js)
// crosses.
async function smokeResourcePool() {
  process.stdout.write('\n▸ Section 108: resource pool CLI census, real two-process sum, resolver byte-stability\n');
  const NODE = process.execPath;
  const POOL_CLI = path.join(SCRIPTS, 'forge-resource-pool.js');
  const RESOURCES_CLI = path.join(SCRIPTS, 'forge-resources.js');

  // ── (a) pool CLI --status --json census on a seeded temp pool ────────────
  const censusDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-pool-census-'));
  try {
    fs.mkdirSync(path.join(censusDir, '.gsd'), { recursive: true });
    fs.writeFileSync(path.join(censusDir, 'pool-config.json'), JSON.stringify({ protocol: 1, ceiling: 3, written_at: Date.now() }), 'utf8');
    const status = spawnSync(NODE, [POOL_CLI, '--status', '--json', '--pool-dir', censusDir], { encoding: 'utf8' });
    assert(status.status === 0, '(a) pool CLI --status --json exits 0 on a seeded temp pool', String(status.status));
    let statusContract;
    try { statusContract = JSON.parse(status.stdout); } catch (e) { statusContract = null; }
    assert(!!statusContract, '(a) pool CLI --status --json output parses as JSON', status.stdout);
    if (statusContract) {
      assert(statusContract.ok === true, '(a) census on a seeded pool is ok:true', JSON.stringify(statusContract));
      assert(statusContract.ceiling === 3, '(a) census reports the seeded ceiling (3), not a recomputed value', String(statusContract.ceiling));
      assert(statusContract.held === 0, '(a) census reports 0 held on a fresh pool', String(statusContract.held));
      assert(statusContract.free === 3, '(a) census reports free === ceiling on a fresh pool', String(statusContract.free));
      assert(Array.isArray(statusContract.slots) && statusContract.slots.length === 3, '(a) census enumerates one slot entry per ceiling unit', JSON.stringify(statusContract.slots));
    }
  } finally {
    try { fs.rmSync(censusDir, { recursive: true, force: true }); } catch (e) { /* ignore */ }
  }

  // ── (b) two-process real dispute (compact version of the concurrency suite) ──
  // Ceiling 4, each of two real spawned node processes requests 3 (< ceiling,
  // matches the concurrency test's design — see that file's comment: this
  // keeps the assertion out of the separately-named
  // pool-exhausted-minimum-grant floor and inside the positive grant path).
  const disputeDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-pool-dispute-'));
  try {
    fs.mkdirSync(path.join(disputeDir, '.gsd'), { recursive: true });
    fs.writeFileSync(path.join(disputeDir, 'pool-config.json'), JSON.stringify({ protocol: 1, ceiling: 4, written_at: Date.now() }), 'utf8');
    const outA = path.join(disputeDir, 'out-a.json');
    const outB = path.join(disputeDir, 'out-b.json');
    const readyA = path.join(disputeDir, 'ready-a');
    const readyB = path.join(disputeDir, 'ready-b');
    const goFile = path.join(disputeDir, 'go');
    const workerSrc = `
      'use strict';
      const fs = require('fs');
      const pool = require(process.env.POOL_MODULE);
      const start = Date.now();
      fs.writeFileSync(process.env.READY_FILE, String(process.pid));
      while (!fs.existsSync(process.env.GO_FILE)) {
        if (Date.now() - start > 5000) throw new Error('go barrier deadline exceeded');
      }
      const result = pool.acquireSlots(3, { poolDir: process.env.FORGE_RESOURCE_POOL_DIR, ownerToken: 'owner-' + process.pid });
      fs.writeFileSync(process.env.OUT_FILE, JSON.stringify(result));
    `;
    const { spawn } = require('child_process');
    const envBase = { ...process.env, POOL_MODULE: POOL_CLI, FORGE_RESOURCE_POOL_DIR: disputeDir, GO_FILE: goFile };
    const childA = spawn(NODE, ['-e', workerSrc], { env: { ...envBase, OUT_FILE: outA, READY_FILE: readyA } });
    const childB = spawn(NODE, ['-e', workerSrc], { env: { ...envBase, OUT_FILE: outB, READY_FILE: readyB } });
    const exitedA = new Promise((resolve) => childA.once('exit', resolve));
    const exitedB = new Promise((resolve) => childB.once('exit', resolve));
    const deadline = Date.now() + 8000;
    while (!(fs.existsSync(readyA) && fs.existsSync(readyB))) {
      if (Date.now() > deadline) throw new Error('(b) both dispute children failed to reach the ready barrier in time');
    }
    fs.writeFileSync(goFile, 'go');
    const outDeadline = Date.now() + 8000;
    while (!(fs.existsSync(outA) && fs.existsSync(outB))) {
      if (Date.now() > outDeadline) throw new Error('(b) both dispute children failed to write output in time');
    }
    await exitedA; await exitedB;
    const resultA = JSON.parse(fs.readFileSync(outA, 'utf8'));
    const resultB = JSON.parse(fs.readFileSync(outB, 'utf8'));
    assert(resultA.ok === true && resultB.ok === true, '(b) both real dispute processes report ok:true', JSON.stringify({ resultA, resultB }));
    const sum = resultA.granted + resultB.granted;
    assert(sum === 4, '(b) two real processes disputing a shared ceiling-4 pool sum to exactly the ceiling', String(sum));
  } finally {
    try { fs.rmSync(disputeDir, { recursive: true, force: true }); } catch (e) { /* ignore */ }
  }

  // ── (c) forge-resources.js CLI: stable prefix keys + maxConcurrentClamp, pool absent without the seam ──
  const resourcesDir = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-pool-resources-'));
  try {
    fs.mkdirSync(path.join(resourcesDir, '.gsd'), { recursive: true });
    const resources = spawnSync(NODE, [RESOURCES_CLI, '--json', '--cwd', resourcesDir], { encoding: 'utf8' });
    assert(resources.status === 0, '(c) forge-resources.js CLI always exits 0 (advisory posture)', String(resources.status));
    let contract;
    try { contract = JSON.parse(resources.stdout); } catch (e) { contract = null; }
    assert(!!contract, '(c) forge-resources.js CLI output parses as JSON', resources.stdout);
    if (contract) {
      for (const key of ['admit', 'workers', 'heapMb', 'playwrightWorkers', 'reason', 'pressureLevel', 'enforcement', 'shadowWait', 'source']) {
        assert(Object.prototype.hasOwnProperty.call(contract, key), `(c) S01 stable prefix key present: ${key}`, JSON.stringify(contract));
      }
      assert(Object.prototype.hasOwnProperty.call(contract, 'maxConcurrentClamp'), '(c) additive maxConcurrentClamp key is always present (S02)', JSON.stringify(contract));
      assert(!Object.prototype.hasOwnProperty.call(contract, 'pool'), '(c) additive pool key is ABSENT via the CLI, which never injects opts.pool — proves the seam stays optional', JSON.stringify(contract));
    }
  } finally {
    try { fs.rmSync(resourcesDir, { recursive: true, force: true }); } catch (e) { /* ignore */ }
  }

  // ── (d) real-default-root guard ────────────────────────────────────────
  const realRoot = path.join(os.homedir(), '.claude', 'forge', 'resource-pool');
  assert(!fs.existsSync(realRoot) || fs.statSync(realRoot).isDirectory(),
    '(d) this section never creates the real machine pool root under an unexpected shape (sanity)', realRoot);

  // ── (e) registration: the section verifies it is wired into main() ───────
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ await smokeResourcePool\(\); \}/.test(mainBody),
    '(e) Section 108 is registered in main() by closure — an unregistered section vanishes silently');

  pass('Section 108: pool CLI census on a seeded temp pool, two REAL spawned processes disputing a shared '
    + 'ceiling sum to exactly it, and forge-resources.js CLI keeps the S01 prefix stable with maxConcurrentClamp '
    + 'always present and pool absent without the opts.pool seam — all via real CLI/process spawns');
}

// ── Section 109: S03/T04 — B1 latency ceiling, E2E child-side equivalence, census ──
// Section number MEASURED at execution time (`grep -nE "^// ── Section
// [0-9]+" scripts/forge-smoke.js | tail`), not assumed: 106 was the real max
// (T03's S02 section) at authoring time. Never require()s forge-hook.js —
// every mordida spawns the real hook CLI as a child process, the same
// boundary forge-hook-rewrite.test.js (T03) crosses. FORGE_RESOURCE_POOL_DIR
// always points at a temp pool — the real ~/.claude/forge/resource-pool is
// never touched.
function smokeRewriteCeilingAndE2E() {
  process.stdout.write('\n▸ Section 109: B1 latency ceiling, child-side E2E equivalence, census sum\n');
  const NODE = process.execPath;
  const HOOK = path.join(SCRIPTS, 'forge-hook.js');
  const rewriteMod = require(path.join(SCRIPTS, 'forge-command-rewrite.js'));

  function tmpWorkspace(prefix) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
    fs.mkdirSync(path.join(dir, '.gsd', 'forge'), { recursive: true });
    return dir;
  }
  function runPre(cmd, { cwd, env = {}, sessionId } = {}) {
    const payload = { session_id: sessionId || 'sess-109', cwd, tool_name: 'Bash', tool_input: { command: cmd } };
    const r = spawnSync(NODE, [HOOK, 'pre'], {
      input: JSON.stringify(payload), encoding: 'utf8', cwd: cwd || os.tmpdir(),
      env: Object.assign({}, process.env, env),
    });
    return { status: r.status, stdout: r.stdout || '', stderr: r.stderr || '' };
  }
  function readEvents(cwd) {
    const p = path.join(cwd, '.gsd', 'forge', 'events.jsonl');
    try { return fs.readFileSync(p, 'utf8').trim().split('\n').filter(Boolean).map((l) => JSON.parse(l)); }
    catch { return []; }
  }
  function releaseBridge(sessionId, poolDir) {
    const bridgeFile = path.join(os.tmpdir(), `forge-rewrite-grant-${String(sessionId).replace(/[^\w.\-]/g, '_')}.json`);
    if (!fs.existsSync(bridgeFile)) return;
    try {
      const bridge = JSON.parse(fs.readFileSync(bridgeFile, 'utf8'));
      const poolMod = require(path.join(SCRIPTS, 'forge-resource-pool.js'));
      poolMod.releaseSlots(bridge.grant.slots, { poolDir });
    } catch { /* best-effort test hygiene */ }
    try { fs.unlinkSync(bridgeFile); } catch { /* ignore */ }
  }

  // ── (a) B1 ceiling — 10,000 calls of looksLikeRunnerCommand over a 20-command,
  // representative NON-runner corpus, MEASURED (never asserted a made-up
  // number), ceiling declared here: < 200 ms total for the 10,000-call loop.
  const corpus = [
    'ls -la', 'git status', 'cat package.json', 'node scripts/x.js', 'curl https://example.com',
    'echo hello', 'pwd', 'mkdir -p tmp', 'rm -rf tmp', 'cp a b', 'mv a b', 'grep -n foo bar.js',
    'find . -name "*.js"', 'sed -n "1,5p" file.txt', 'awk "{print $1}" file.txt', 'chmod +x script.sh',
    'python3 script.py', 'go build ./...', 'docker ps', 'kubectl get pods',
  ];
  const iterations = 10000;
  const t0 = Date.now();
  for (let i = 0; i < iterations; i += 1) {
    rewriteMod.looksLikeRunnerCommand(corpus[i % corpus.length]);
  }
  const measuredMs = Date.now() - t0;
  const CEILING_MS = 200;
  process.stdout.write(`  measured: ${iterations} calls over a ${corpus.length}-command non-runner corpus took ${measuredMs}ms (declared ceiling: ${CEILING_MS}ms)\n`);
  assert(measuredMs < CEILING_MS, `(a) B1 in-process ceiling: ${iterations} looksLikeRunnerCommand calls over a ${corpus.length}-command corpus complete in under ${CEILING_MS}ms`, `measured ${measuredMs}ms`);

  // ── (b) B1 outside-the-process direction — a real spawned hook process on a
  // non-runner command performs ZERO fs/pool operations: empty stdout AND the
  // temp pool directory has zero entries afterward (I/O-free short-circuit
  // observed from OUTSIDE the process, not by inspecting require.cache).
  const bDir = tmpWorkspace('smoke109-b-');
  const bPool = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke109-b-pool-'));
  try {
    const res = runPre('git status', { cwd: bDir, env: { FORGE_RESOURCE_POOL_DIR: bPool } });
    assert(res.status === 0, '(b) non-runner command (git status) is allowed', String(res.status));
    assert(res.stdout === '', '(b) non-runner command emits no rewrite stdout', res.stdout);
    const poolEntries = fs.existsSync(bPool) ? fs.readdirSync(bPool) : [];
    assert(poolEntries.length === 0, '(b) temp pool dir remains untouched (zero slot files created) for a non-candidate command', JSON.stringify(poolEntries));
  } finally {
    try { fs.rmSync(bDir, { recursive: true, force: true }); } catch { /* ignore */ }
    try { fs.rmSync(bPool, { recursive: true, force: true }); } catch { /* ignore */ }
  }

  // ── (c)-(f) E2E child-side equivalence — real fixture, real npm, real spawned
  // dump shims. `sh -c <updatedInput.command>` executes the hook's OWN output
  // string against a fixture whose "vitest"/"jest" node_modules/.bin shims
  // dump their argv+env to a file — proving hook-output → executed-child
  // equivalence without spending claude tokens (the claude-honors-updatedInput
  // half was proven once, live, in T02 and is cited here, not re-run).
  const fixture = tmpWorkspace('smoke109-fixture-');
  const cPool = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke109-fixture-pool-'));
  try {
    fs.writeFileSync(path.join(fixture, 'package.json'), JSON.stringify({
      name: 'smoke109-fixture', version: '1.0.0', scripts: { test: 'vitest', testjest: 'jest' },
    }), 'utf8');
    fs.writeFileSync(path.join(fixture, 'package-lock.json'), JSON.stringify({ name: 'smoke109-fixture', version: '1.0.0', lockfileVersion: 3 }), 'utf8');
    const binDir = path.join(fixture, 'node_modules', '.bin');
    fs.mkdirSync(binDir, { recursive: true });
    const shimSrc = [
      '#!/usr/bin/env node',
      "const fs = require('fs');",
      'fs.writeFileSync(process.env.DUMP_FILE, JSON.stringify({',
      '  argv: process.argv.slice(2),',
      '  env: {',
      '    VITEST_MAX_FORKS: process.env.VITEST_MAX_FORKS || null,',
      '    VITEST_MAX_THREADS: process.env.VITEST_MAX_THREADS || null,',
      '    NODE_OPTIONS: process.env.NODE_OPTIONS || null,',
      '  },',
      '}));',
      '',
    ].join('\n');
    for (const bin of ['vitest', 'jest']) {
      const binPath = path.join(binDir, bin);
      fs.writeFileSync(binPath, shimSrc, 'utf8');
      fs.chmodSync(binPath, 0o755);
    }

    let candidatesSent = 0;

    // (c) recognized: `npm test` → rewritten (env-prefix path, vitest) — dump
    // shows the clamped VITEST_MAX_FORKS/VITEST_MAX_THREADS/NODE_OPTIONS.
    const dumpA = path.join(fixture, 'dump-a.json');
    const sessA = 'sess-109-a';
    const resA = runPre('npm test', { cwd: fixture, sessionId: sessA, env: { FORGE_RESOURCE_POOL_DIR: cPool } });
    assert(resA.status === 0, '(c) recognized npm-test payload: hook exits 0', String(resA.status));
    candidatesSent += 1;
    const linesA = resA.stdout.trim().split('\n').filter(Boolean);
    assert(linesA.length === 1, '(c) recognized path: exactly one stdout JSON line', resA.stdout);
    let parsedA = null;
    try { parsedA = JSON.parse(linesA[0]); } catch { /* asserted below */ }
    assert(!!(parsedA && parsedA.hookSpecificOutput && parsedA.hookSpecificOutput.updatedInput), '(c) recognized path: updatedInput.command present', resA.stdout);
    if (parsedA) {
      const rewritten = parsedA.hookSpecificOutput.updatedInput.command;
      const forksMatch = /VITEST_MAX_FORKS='(\d+)'/.exec(rewritten);
      const heapMatch = /--max-old-space-size=(\d+)/.exec(rewritten);
      assert(!!forksMatch, '(c) rewritten command carries a VITEST_MAX_FORKS env prefix', rewritten);
      if (forksMatch && heapMatch) {
        // R11: this suite is measured on win32 too — `/bin/sh` does not exist
        // there. Reuse the same resolvePosixSh() the mock-codex shim already
        // uses (:2033-2034), prepending its `bin` to the child PATH.
        const { sh: shA, bin: shBinA } = resolvePosixSh();
        const envA = shBinA
          ? Object.assign({}, process.env, { DUMP_FILE: dumpA, PATH: shBinA + path.delimiter + (process.env.PATH || '') })
          : Object.assign({}, process.env, { DUMP_FILE: dumpA });
        const exec = spawnSync(shA, ['-c', rewritten], {
          cwd: fixture, encoding: 'utf8', env: envA,
        });
        assert(exec.status === 0, '(c) executing the hook-emitted command via sh -c exits 0', `status=${exec.status} stderr=${exec.stderr}`);
        let dumpA_ = null;
        try { dumpA_ = JSON.parse(fs.readFileSync(dumpA, 'utf8')); } catch { /* asserted below */ }
        assert(!!dumpA_, '(c) fixture shim wrote its argv/env dump', String(fs.existsSync(dumpA)));
        if (dumpA_) {
          assert(dumpA_.env.VITEST_MAX_FORKS === forksMatch[1], '(c) child process observed the SAME clamped VITEST_MAX_FORKS the hook emitted (child-side equivalence)', JSON.stringify(dumpA_.env));
          assert(dumpA_.env.NODE_OPTIONS && dumpA_.env.NODE_OPTIONS.includes(`--max-old-space-size=${heapMatch[1]}`), '(c) child process observed the SAME NODE_OPTIONS heap clamp the hook emitted', JSON.stringify(dumpA_.env));
        }
      }
      const events = readEvents(fixture);
      assert(events.some((e) => e.event === 'rewrite-applied'), '(c) rewrite-applied event recorded for the recognized payload', JSON.stringify(events));
    }
    releaseBridge(sessA, cPool);

    // (d) intact/skip: a DIRECT vitest invocation with an explicit --shard is
    // left intact (never overrides a human choice, T03's shipped "intact"
    // semantics) — no stdout, byte-identical (branch never touches the
    // string), rewrite-skipped event present with a named enum reason.
    const sessD = 'sess-109-d';
    const resD = runPre('vitest run --shard=1/2', { cwd: fixture, sessionId: sessD, env: { FORGE_RESOURCE_POOL_DIR: cPool } });
    assert(resD.status === 0, '(d) intact/skip payload: hook exits 0', String(resD.status));
    assert(resD.stdout === '', '(d) intact/skip payload: no updatedInput emission — command stays byte-identical', resD.stdout);
    candidatesSent += 1;
    releaseBridge(sessD, cPool);

    // (e) chain: `true && npm run testjest` — only the npm-run segment is a
    // runner candidate (T03's shipped chain semantics); rewritten to append
    // the jest argv flag after `--`. Dump shows the clamped --maxWorkers flag.
    const dumpE = path.join(fixture, 'dump-e.json');
    const sessE = 'sess-109-e';
    const resE = runPre('true && npm run testjest', { cwd: fixture, sessionId: sessE, env: { FORGE_RESOURCE_POOL_DIR: cPool } });
    assert(resE.status === 0, '(e) chain payload: hook exits 0', String(resE.status));
    candidatesSent += 1;
    let parsedE = null;
    try { parsedE = JSON.parse(resE.stdout.trim().split('\n').filter(Boolean)[0]); } catch { /* asserted below */ }
    assert(!!(parsedE && parsedE.hookSpecificOutput && parsedE.hookSpecificOutput.updatedInput), '(e) chain payload: updatedInput.command present for the rewritten segment', resE.stdout);
    if (parsedE) {
      const rewrittenE = parsedE.hookSpecificOutput.updatedInput.command;
      const workersMatch = /--maxWorkers=(\d+)/.exec(rewrittenE);
      assert(!!workersMatch, '(e) chain rewrite carries a --maxWorkers argv flag (jest, via npm -- forwarding)', rewrittenE);
      if (workersMatch) {
        const { sh: shE, bin: shBinE } = resolvePosixSh();
        const envE = shBinE
          ? Object.assign({}, process.env, { DUMP_FILE: dumpE, PATH: shBinE + path.delimiter + (process.env.PATH || '') })
          : Object.assign({}, process.env, { DUMP_FILE: dumpE });
        const execE = spawnSync(shE, ['-c', rewrittenE], {
          cwd: fixture, encoding: 'utf8', env: envE,
        });
        assert(execE.status === 0, '(e) executing the chain-rewritten command via sh -c exits 0 (the `true` segment ran too)', `status=${execE.status} stderr=${execE.stderr}`);
        let dumpE_ = null;
        try { dumpE_ = JSON.parse(fs.readFileSync(dumpE, 'utf8')); } catch { /* asserted below */ }
        assert(!!dumpE_, '(e) fixture jest shim wrote its argv/env dump', String(fs.existsSync(dumpE)));
        if (dumpE_) {
          assert(dumpE_.argv.includes(`--maxWorkers=${workersMatch[1]}`), '(e) child process observed the SAME clamped --maxWorkers the hook emitted (child-side equivalence)', JSON.stringify(dumpE_.argv));
        }
      }
    }
    releaseBridge(sessE, cPool);

    // (f) literal subshell: `(npm test)` fails tokenization entirely — the B1
    // lexical gate returns false BEFORE planRewrite is ever reached, so this
    // is NOT a "candidate" (S03-PLAN Notes: commands that fail the lexical
    // gate emit nothing from the pre-hook). Deliberately excluded from
    // `candidatesSent` below — its zero-event, zero-stdout outcome is the
    // proof, not an omission.
    const resF = runPre('(npm test)', { cwd: fixture, sessionId: 'sess-109-f', env: { FORGE_RESOURCE_POOL_DIR: cPool } });
    assert(resF.status === 0, '(f) syntactically-refused subshell command is allowed through unrewritten', String(resF.status));
    assert(resF.stdout === '', '(f) subshell command emits no rewrite stdout — byte-identical, branch never engaged', resF.stdout);

    // ── (g) census (W3): rewrite-applied + rewrite-skipped events sum EXACTLY
    // to the number of LEXICAL-GATE-CANDIDATE payloads sent — no remainder.
    // The subshell (f) is excluded by construction (never a candidate); a
    // full reconciliation against the PostToolUse evidence log (which
    // records 100% of Bash calls, including non-candidates) is S05's
    // `--check resources` per S03-PLAN Notes — this section asserts only the
    // candidate half.
    const finalEvents = readEvents(fixture).filter((e) => e.event === 'rewrite-applied' || e.event === 'rewrite-skipped');
    assert(finalEvents.length === candidatesSent, `(g) census: rewrite-applied + rewrite-skipped events sum EXACTLY to the ${candidatesSent} candidate payloads sent, no remainder`, JSON.stringify(finalEvents));

    // ── (h) self-bite — FORGE_REWRITE_FAULT='emission' (existing seam, T03)
    // deliberately breaks the recognized path AFTER tokenizer/resolver/pool
    // succeed: the emitted command must fall back byte-identical (no
    // VITEST_MAX_FORKS prefix), proving this section's own assertions are
    // sensitive to a broken rewrite path, not tautological.
    const sessH = 'sess-109-h';
    const resH = runPre('npm test', { cwd: fixture, sessionId: sessH, env: { FORGE_RESOURCE_POOL_DIR: cPool, FORGE_REWRITE_FAULT: 'emission' } });
    assert(resH.status === 0, '(h) self-bite: faulted emission stage still exits 0', String(resH.status));
    assert(resH.stdout === '', '(h) self-bite: faulted emission stage emits NO rewrite stdout — falls through byte-identical', resH.stdout);
    releaseBridge(sessH, cPool);
  } finally {
    try { fs.rmSync(fixture, { recursive: true, force: true }); } catch { /* ignore */ }
    try { fs.rmSync(cPool, { recursive: true, force: true }); } catch { /* ignore */ }
  }

  // ── (i) registration: the section verifies it is wired into main() ───────
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeRewriteCeilingAndE2E\(\); \}/.test(mainBody),
    '(i) Section 109 is registered in main() by closure — an unregistered section vanishes silently');

  pass(`Section 109: B1 ceiling measured at ${measuredMs}ms/${iterations} calls (< ${CEILING_MS}ms), outside-process zero-pool-I/O `
    + 'proven, real npm+sh -c child-side equivalence for env-prefix (vitest) and argv-flag (jest via chain) rewrites, '
    + 'census sums exactly to candidates sent, and a faulted emission stage falls back byte-identical (self-bite)');
}

// ── Section 110: S04/T04 — verify.js/reverify.js child-side clamp E2E, byte-identity, W5 census ──
// Section number MEASURED at execution time (`grep -oE "Section ([0-9]+)"
// scripts/forge-smoke.js | grep -oE "[0-9]+" | sort -n | tail -1`), not
// assumed: 107 was the real max at authoring time. Never require()s
// forge-verify.js/forge-reverify.js — every assertion spawns the REAL CLI as
// a child process, and every clamp claim is read from a dump the CHILD
// process itself writes (never inferred from what the parent intended to
// pass — the exact "environment is only proven by the child" lesson S04's
// own plan cites from S03/T02).
function smokeVerifyReverifyChildSideE2E() {
  process.stdout.write('\n▸ Section 110: forge-verify.js/forge-reverify.js child-side clamp E2E, byte-identity, W5 census\n');
  const NODE = process.execPath;
  const VERIFY_CLI = path.join(SCRIPTS, 'forge-verify.js');
  const REVERIFY_CLI = path.join(SCRIPTS, 'forge-reverify.js');
  const POOL_CLI = path.join(SCRIPTS, 'forge-resource-pool.js');
  const isPosix = process.platform !== 'win32';

  function tmpWorkspace(prefix) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), prefix));
    fs.mkdirSync(path.join(dir, '.gsd', 'forge'), { recursive: true });
    return dir;
  }
  function poolCensus(poolDir) {
    const r = spawnSync(NODE, [POOL_CLI, '--status', '--json', '--pool-dir', poolDir], { encoding: 'utf8' });
    try { return JSON.parse(r.stdout); } catch { return { ok: false, held: -1 }; }
  }
  function shimBody(dumpFile, { exitCode = 0, delayMs = 0 } = {}) {
    return [
      '#!/usr/bin/env node',
      "const fs = require('fs');",
      `fs.writeFileSync(${JSON.stringify(dumpFile)}, JSON.stringify({ argv: process.argv, env: process.env }));`,
      delayMs > 0 ? `setTimeout(() => { process.exit(${exitCode}); }, ${delayMs});` : `process.exit(${exitCode});`,
      '',
    ].join('\n');
  }
  function writeShim(binPath, dumpFile, opts) {
    fs.mkdirSync(path.dirname(binPath), { recursive: true });
    fs.writeFileSync(binPath, shimBody(dumpFile, opts), { mode: 0o755 });
  }
  function hasMakeBinary() {
    try { return spawnSync('make', ['--version'], { encoding: 'utf8' }).status === 0; } catch { return false; }
  }
  // Runs `fn` against a COPY of scripts/ (in tmp) with
  // forge-command-rewrite.js deleted from the copy — so a FRESHLY spawned
  // child's require() throws MODULE_NOT_FOUND (the strongest form of
  // "wiring disabled": the module genuinely absent from disk), WITHOUT ever
  // mutating the real tracked checkout (R10, S04 review). The original
  // in-place rename left a window — covered by `finally`, but not SIGKILL —
  // where a concurrent Forge process on the same machine (this milestone's
  // own premise) could observe the module missing, or a killed smoke run
  // could leave the checkout without it. `fn` receives the copy's scripts/
  // dir so callers can build CLI paths (`path.join(copyScriptsDir, ...)`)
  // that resolve `require()`s inside the copy, never the real tree. Some
  // scripts reach up to `../shared/**` (e.g. forge-xllm.js's
  // `../shared/schemas/*.json`) — a symlink from the copy root back to the
  // REAL `shared/` dir preserves that relative resolution read-only,
  // without copying (or ever writing to) it.
  function withRewriteModuleDisabled(fn) {
    const copyRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-repo-copy-'));
    const copyScriptsDir = path.join(copyRoot, 'scripts');
    try {
      fs.cpSync(SCRIPTS, copyScriptsDir, { recursive: true });
      fs.rmSync(path.join(copyScriptsDir, 'forge-command-rewrite.js'), { force: true });
      fs.symlinkSync(path.join(SCRIPTS, '..', 'shared'), path.join(copyRoot, 'shared'), 'dir');
      return fn(copyScriptsDir);
    } finally {
      try { fs.rmSync(copyRoot, { recursive: true, force: true }); } catch { /* best-effort */ }
    }
  }
  function writeResultFile(p) {
    const result = { must_haves_status: [{ status: 'unmet', scope: 'environment', reason: 'sandbox-exec-blocked', note: 'run the test suite' }] };
    fs.writeFileSync(p, JSON.stringify(result), 'utf8');
    return p;
  }

  // ── Real pool root: never created/touched by anything in this section ────
  const realPoolRoot = path.join(os.homedir(), '.claude', 'forge', 'resource-pool');
  const realPoolExistedBefore = fs.existsSync(realPoolRoot);
  const realPoolListingBefore = realPoolExistedBefore ? fs.readdirSync(realPoolRoot).sort() : null;

  if (!isPosix) {
    skip('Section 110: verify.js/reverify.js child-side clamp E2E', 'posix-only shebang fixtures (mirrors T02/T03 suites)');
    return;
  }

  // ═══ Consumer A: forge-verify.js ══════════════════════════════════════
  const aDir = tmpWorkspace('smoke110-verify-');
  const aPoolOn = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-verify-pool-on-'));
  const aPoolOff = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-verify-pool-off-'));
  const aPoolFail = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-verify-pool-fail-'));
  const aPoolTimeout = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-verify-pool-to-'));
  try {
    // (a) clamp ON: taskPlanVerify:'vitest' resolved via a PATH-injected shim.
    const binOnDir = path.join(aDir, 'bin-on');
    const dumpOn = path.join(aDir, 'dump-on.json');
    writeShim(path.join(binOnDir, 'vitest'), dumpOn);
    const planA = path.join(aDir, 'plan-a.md');
    fs.writeFileSync(planA, '---\nverify: vitest\n---\n# fixture\n', 'utf8');
    const envA = Object.assign({}, process.env, {
      PATH: binOnDir + path.delimiter + process.env.PATH,
      FORGE_RESOURCE_POOL_DIR: aPoolOn, FORGE_RESOURCES_PRESSURE: '1',
    });
    const resA = spawnSync(NODE, [VERIFY_CLI, '--plan', planA, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-a'], { encoding: 'utf8', env: envA });
    assert(resA.status === 0, '(a) forge-verify.js CLI exits 0 for the clamp-ON fixture', String(resA.status) + resA.stderr);
    assert(fs.existsSync(dumpOn), '(a) the CHILD process wrote its own argv/env dump — clamp observed child-side, never inferred', dumpOn);
    const dumpOnJson = JSON.parse(fs.readFileSync(dumpOn, 'utf8'));
    assert(typeof dumpOnJson.env.NODE_OPTIONS === 'string' && /--max-old-space-size=\d+/.test(dumpOnJson.env.NODE_OPTIONS),
      '(a) clamp ON: child dump carries NODE_OPTIONS from the resource contract', JSON.stringify(dumpOnJson.env));
    assert(typeof dumpOnJson.env.VITEST_MAX_FORKS === 'string' && dumpOnJson.env.VITEST_MAX_FORKS.length > 0,
      '(a) clamp ON: child dump carries the VITEST_MAX_FORKS worker clamp', JSON.stringify(dumpOnJson.env));

    // (b) clamp OFF: SAME fixture body, non-runner binary name — bite reverses.
    const binOffDir = path.join(aDir, 'bin-off');
    const dumpOff = path.join(aDir, 'dump-off.json');
    const offBin = path.join(binOffDir, 'not-a-real-runner');
    writeShim(offBin, dumpOff);
    const planB = path.join(aDir, 'plan-b.md');
    fs.writeFileSync(planB, `---\nverify: ${offBin}\n---\n# fixture\n`, 'utf8');
    const envB = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: aPoolOff, FORGE_RESOURCES_PRESSURE: '1' });
    const resB = spawnSync(NODE, [VERIFY_CLI, '--plan', planB, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-b'], { encoding: 'utf8', env: envB });
    assert(resB.status === 0, '(b) forge-verify.js CLI exits 0 for the clamp-OFF fixture', String(resB.status) + resB.stderr);
    const dumpOffJson = JSON.parse(fs.readFileSync(dumpOff, 'utf8'));
    assert(dumpOffJson.env.NODE_OPTIONS === undefined, '(b) clamp OFF: NODE_OPTIONS is ABSENT from the child env (bite reverses)', JSON.stringify(dumpOffJson.env));
    assert(dumpOffJson.env.VITEST_MAX_FORKS === undefined, '(b) clamp OFF: VITEST_MAX_FORKS is ABSENT from the child env', JSON.stringify(dumpOffJson.env));

    // (c) W5 outside-process: a FAILING command releases the lease.
    const binFailDir = path.join(aDir, 'bin-fail');
    const dumpFail = path.join(aDir, 'dump-fail.json');
    writeShim(path.join(binFailDir, 'vitest'), dumpFail, { exitCode: 7 });
    const planC = path.join(aDir, 'plan-c.md');
    fs.writeFileSync(planC, '---\nverify: vitest\n---\n# fixture\n', 'utf8');
    const envC = Object.assign({}, process.env, {
      PATH: binFailDir + path.delimiter + process.env.PATH,
      FORGE_RESOURCE_POOL_DIR: aPoolFail, FORGE_RESOURCES_PRESSURE: '1',
    });
    const resC = spawnSync(NODE, [VERIFY_CLI, '--plan', planC, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-c'], { encoding: 'utf8', env: envC });
    let parsedC = null;
    try { parsedC = JSON.parse(resC.stdout); } catch { /* asserted below */ }
    assert(!!parsedC && parsedC.passed === false && parsedC.checks[0].exitCode === 7,
      '(c) failing command reports the project exit code (7) through the real CLI', resC.stdout);
    const censusC = poolCensus(aPoolFail);
    assert(censusC.ok === true && censusC.held === 0, '(c) W5 outside-process: pool census shows ZERO held slots after a FAILED forge-verify.js command', JSON.stringify(censusC));

    // (d) W5 outside-process: a TIMING-OUT command releases the lease.
    const binToDir = path.join(aDir, 'bin-timeout');
    const dumpTo = path.join(aDir, 'dump-timeout.json');
    writeShim(path.join(binToDir, 'vitest'), dumpTo, { delayMs: 4000 });
    const planD = path.join(aDir, 'plan-d.md');
    fs.writeFileSync(planD, '---\nverify: vitest\n---\n# fixture\n', 'utf8');
    const envD = Object.assign({}, process.env, {
      PATH: binToDir + path.delimiter + process.env.PATH,
      FORGE_RESOURCE_POOL_DIR: aPoolTimeout, FORGE_RESOURCES_PRESSURE: '1',
    });
    const resD = spawnSync(NODE, [VERIFY_CLI, '--plan', planD, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-d', '--timeout', '300'], { encoding: 'utf8', env: envD });
    let parsedD = null;
    try { parsedD = JSON.parse(resD.stdout); } catch { /* asserted below */ }
    assert(!!parsedD && parsedD.checks[0].exitCode === 124 && parsedD.checks[0].skipped === 'timeout',
      '(d) timing-out command maps to exitCode 124 through the real CLI', resD.stdout);
    const censusD = poolCensus(aPoolTimeout);
    assert(censusD.ok === true && censusD.held === 0, '(d) W5 outside-process: pool census shows ZERO held slots after a TIMED-OUT forge-verify.js command', JSON.stringify(censusD));

    // (e) byte-identity (consumer A): an unrecognized command runs
    // identically whether the command-rewrite module is present or
    // genuinely absent from disk.
    const binUnrecDir = path.join(aDir, 'bin-unrec');
    const unrecBin = path.join(binUnrecDir, 'totally-unrecognized-runner');
    const dumpUnrec1 = path.join(aDir, 'dump-unrec-1.json');
    const dumpUnrec2 = path.join(aDir, 'dump-unrec-2.json');
    const planE = path.join(aDir, 'plan-e.md');
    fs.writeFileSync(planE, `---\nverify: ${unrecBin} --flag x\n---\n# fixture\n`, 'utf8');
    const envE = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: aPoolOn, FORGE_RESOURCES_PRESSURE: '1' });

    writeShim(unrecBin, dumpUnrec1);
    const resE1 = spawnSync(NODE, [VERIFY_CLI, '--plan', planE, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-e1'], { encoding: 'utf8', env: envE });
    writeShim(unrecBin, dumpUnrec2);
    const resE2 = withRewriteModuleDisabled((copyScriptsDir) => spawnSync(NODE, [path.join(copyScriptsDir, 'forge-verify.js'), '--plan', planE, '--cwd', aDir, '--gsd-dir', path.join(aDir, '.gsd'), '--unit', 'smoke110-e2'], { encoding: 'utf8', env: envE }));

    assert(resE1.status === 0 && resE2.status === 0, '(e) both unrecognized-command runs (wiring present/absent) exit 0', `${resE1.status}/${resE2.status}`);
    const dumpUnrec1Json = JSON.parse(fs.readFileSync(dumpUnrec1, 'utf8'));
    const dumpUnrec2Json = JSON.parse(fs.readFileSync(dumpUnrec2, 'utf8'));
    assert(JSON.stringify(dumpUnrec1Json.argv) === JSON.stringify(dumpUnrec2Json.argv),
      '(e) byte-identity (consumer A): the child process observed the SAME argv with the rewrite module present vs genuinely absent from disk — strict equality',
      JSON.stringify({ a: dumpUnrec1Json.argv, b: dumpUnrec2Json.argv }));
    const parsedE1 = JSON.parse(resE1.stdout);
    const parsedE2 = JSON.parse(resE2.stdout);
    assert(parsedE1.checks[0].command === parsedE2.checks[0].command && parsedE1.checks[0].exitCode === parsedE2.checks[0].exitCode,
      '(e) byte-identity (consumer A): the reported command/exitCode is IDENTICAL in both modes', JSON.stringify({ e1: parsedE1.checks[0], e2: parsedE2.checks[0] }));
  } finally {
    try { fs.rmSync(aDir, { recursive: true, force: true }); } catch { /* best-effort */ }
    for (const d of [aPoolOn, aPoolOff, aPoolFail, aPoolTimeout]) {
      try { fs.rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
    }
  }

  // ═══ Consumer B: forge-reverify.js ════════════════════════════════════
  const bDir = tmpWorkspace('smoke110-reverify-');
  const bPoolOn = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-pool-on-'));
  const bPoolOff = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-pool-off-'));
  const bPoolFail = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-pool-fail-'));
  const bPoolTimeout = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-pool-to-'));
  const bPoolMake = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-pool-make-'));
  let offDir = null;
  let makeDir = null;
  try {
    // (f) clamp ON: package.json's "test" script is a single-segment
    // "vitest" body — npm resolves node_modules/.bin/vitest, the REAL shim,
    // over a REAL spawned npm (S03/T04 Section 109's precedent).
    const dumpF = path.join(bDir, 'dump-f.json');
    fs.writeFileSync(path.join(bDir, 'package.json'), JSON.stringify({ name: 'smoke110-b', version: '1.0.0', scripts: { test: 'vitest' } }), 'utf8');
    fs.writeFileSync(path.join(bDir, 'package-lock.json'), JSON.stringify({ name: 'smoke110-b', version: '1.0.0', lockfileVersion: 3 }), 'utf8');
    writeShim(path.join(bDir, 'node_modules', '.bin', 'vitest'), dumpF);
    const resultF = writeResultFile(path.join(bDir, 'result-f.json'));
    const envF = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolOn, FORGE_RESOURCES_PRESSURE: '1' });
    const resF = spawnSync(NODE, [REVERIFY_CLI, '--result', resultF, '--code-dir', bDir, '--gsd-dir', path.join(bDir, '.gsd'), '--apply'], { encoding: 'utf8', cwd: bDir, env: envF });
    assert(resF.status === 0, '(f) forge-reverify.js CLI exits 0 for the clamp-ON fixture', String(resF.status) + resF.stderr);
    assert(fs.existsSync(dumpF), '(f) the CHILD process wrote its own argv/env dump (child-side observation)', dumpF);
    const dumpFJson = JSON.parse(fs.readFileSync(dumpF, 'utf8'));
    assert(typeof dumpFJson.env.NODE_OPTIONS === 'string' && /--max-old-space-size=\d+/.test(dumpFJson.env.NODE_OPTIONS),
      '(f) clamp ON: reverify child dump carries NODE_OPTIONS from the resource contract', JSON.stringify(dumpFJson.env));
    assert(typeof dumpFJson.env.VITEST_MAX_FORKS === 'string' && dumpFJson.env.VITEST_MAX_FORKS.length > 0,
      '(f) clamp ON: reverify child dump carries VITEST_MAX_FORKS', JSON.stringify(dumpFJson.env));
    assert(!dumpFJson.argv.slice(2).some((tok) => /^[A-Za-z_]\w*=/.test(tok)),
      '(f) NO argv element is a NAME=value assignment — the structural guarantee of T01/T03 (shell:false)', JSON.stringify(dumpFJson.argv));
    const parsedF = JSON.parse(resF.stdout);
    assert(parsedF.verdict === 'verified', '(f) re-verification applied a "verified" outcome for the environment must-have', resF.stdout);

    // (g) clamp OFF: same shape, package.json's "test" script is NOT a
    // recognized runner body — bite reverses on the SAME code path.
    const dumpG = path.join(bDir, 'dump-g.json');
    offDir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-reverify-off-'));
    fs.mkdirSync(path.join(offDir, '.gsd', 'forge'), { recursive: true });
    fs.writeFileSync(path.join(offDir, 'package.json'), JSON.stringify({ name: 'smoke110-b-off', version: '1.0.0', scripts: { test: 'node dump.js' } }), 'utf8');
    fs.writeFileSync(path.join(offDir, 'dump.js'), `const fs=require('fs');fs.writeFileSync(${JSON.stringify(dumpG)}, JSON.stringify({argv:process.argv,env:process.env}));`, 'utf8');
    const resultG = writeResultFile(path.join(offDir, 'result-g.json'));
    const envG = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolOff, FORGE_RESOURCES_PRESSURE: '1' });
    const resG = spawnSync(NODE, [REVERIFY_CLI, '--result', resultG, '--code-dir', offDir, '--gsd-dir', path.join(offDir, '.gsd'), '--apply'], { encoding: 'utf8', cwd: offDir, env: envG });
    assert(resG.status === 0, '(g) forge-reverify.js CLI exits 0 for the clamp-OFF fixture', String(resG.status) + resG.stderr);
    const dumpGJson = JSON.parse(fs.readFileSync(dumpG, 'utf8'));
    assert(dumpGJson.env.VITEST_MAX_FORKS === undefined, '(g) clamp OFF: VITEST_MAX_FORKS is ABSENT — command is not runner-shaped, bite reverses', JSON.stringify(dumpGJson.env));

    // (h) W5 outside-process: a FAILING command releases the lease.
    const dumpH = path.join(bDir, 'dump-h.json');
    writeShim(path.join(bDir, 'node_modules', '.bin', 'vitest'), dumpH, { exitCode: 5 });
    const resultH = writeResultFile(path.join(bDir, 'result-h.json'));
    const envH = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolFail, FORGE_RESOURCES_PRESSURE: '1' });
    const resH = spawnSync(NODE, [REVERIFY_CLI, '--result', resultH, '--code-dir', bDir, '--gsd-dir', path.join(bDir, '.gsd')], { encoding: 'utf8', cwd: bDir, env: envH });
    const parsedH = JSON.parse(resH.stdout);
    assert(parsedH.verdict === 'failed' && parsedH.exit_code === 5, '(h) failing command reports the project exit code (5) through the real CLI', resH.stdout);
    const censusH = poolCensus(bPoolFail);
    assert(censusH.ok === true && censusH.held === 0, '(h) W5 outside-process: pool census shows ZERO held slots after a FAILED forge-reverify.js command', JSON.stringify(censusH));

    // (i) W5 outside-process: a TIMING-OUT command releases the lease.
    const dumpI = path.join(bDir, 'dump-i.json');
    writeShim(path.join(bDir, 'node_modules', '.bin', 'vitest'), dumpI, { delayMs: 4000 });
    const resultI = writeResultFile(path.join(bDir, 'result-i.json'));
    const envI = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolTimeout, FORGE_RESOURCES_PRESSURE: '1' });
    const resI = spawnSync(NODE, [REVERIFY_CLI, '--result', resultI, '--code-dir', bDir, '--gsd-dir', path.join(bDir, '.gsd'), '--timeout-ms', '300'], { encoding: 'utf8', cwd: bDir, env: envI });
    const parsedI = JSON.parse(resI.stdout);
    assert(parsedI.verdict === 'no-command', '(i) timed-out command surfaces as no-command through the real CLI (ETIMEDOUT mapping)', resI.stdout);
    const censusI = poolCensus(bPoolTimeout);
    assert(censusI.ok === true && censusI.held === 0, '(i) W5 outside-process: pool census shows ZERO held slots after a TIMED-OUT forge-reverify.js command', JSON.stringify(censusI));

    // (j) byte-identity (consumer B): a Makefile-resolved command
    // (unrecognized runner form — S04-PLAN step 6's own example, and
    // resolveVerifyCommand's own precedent) runs byte-identical whether the
    // command-rewrite module is present or genuinely absent from disk.
    if (hasMakeBinary()) {
      makeDir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke110-make-'));
      fs.mkdirSync(path.join(makeDir, '.gsd', 'forge'), { recursive: true });
      const dumpJ1 = path.join(makeDir, 'dump-j1.json');
      const dumpJ2 = path.join(makeDir, 'dump-j2.json');
      fs.writeFileSync(path.join(makeDir, 'dump.js'), "const fs=require('fs');fs.writeFileSync(process.env.SMOKE110_DUMP_FILE, JSON.stringify({argv:process.argv}));", 'utf8');
      fs.writeFileSync(path.join(makeDir, 'Makefile'), 'test:\n\tnode dump.js\n', 'utf8');

      const resultJ1 = writeResultFile(path.join(makeDir, 'result-j1.json'));
      const envJ1 = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolMake, FORGE_RESOURCES_PRESSURE: '1', SMOKE110_DUMP_FILE: dumpJ1 });
      const resJ1 = spawnSync(NODE, [REVERIFY_CLI, '--result', resultJ1, '--code-dir', makeDir, '--gsd-dir', path.join(makeDir, '.gsd')], { encoding: 'utf8', cwd: makeDir, env: envJ1 });

      const resultJ2 = writeResultFile(path.join(makeDir, 'result-j2.json'));
      const envJ2 = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: bPoolMake, FORGE_RESOURCES_PRESSURE: '1', SMOKE110_DUMP_FILE: dumpJ2 });
      const resJ2 = withRewriteModuleDisabled((copyScriptsDir) => spawnSync(NODE, [path.join(copyScriptsDir, 'forge-reverify.js'), '--result', resultJ2, '--code-dir', makeDir, '--gsd-dir', path.join(makeDir, '.gsd')], { encoding: 'utf8', cwd: makeDir, env: envJ2 }));

      assert(resJ1.status === 0 && resJ2.status === 0, '(j) both make-test runs (wiring present/absent) exit 0', `${resJ1.status}/${resJ2.status}`);
      const parsedJ1 = JSON.parse(resJ1.stdout);
      const parsedJ2 = JSON.parse(resJ2.stdout);
      assert(parsedJ1.verdict === parsedJ2.verdict && parsedJ1.exit_code === parsedJ2.exit_code && parsedJ1.command === parsedJ2.command,
        '(j) byte-identity (consumer B): reverify CLI outcome (verdict/exit_code/command) is IDENTICAL with the rewrite module present vs genuinely absent from disk',
        JSON.stringify({ parsedJ1, parsedJ2 }));
      const dumpJ1Json = JSON.parse(fs.readFileSync(dumpJ1, 'utf8'));
      const dumpJ2Json = JSON.parse(fs.readFileSync(dumpJ2, 'utf8'));
      assert(JSON.stringify(dumpJ1Json.argv) === JSON.stringify(dumpJ2Json.argv),
        '(j) byte-identity (consumer B): the child process observed the SAME argv in both runs — strict equality, not "looks equal"',
        JSON.stringify({ a: dumpJ1Json.argv, b: dumpJ2Json.argv }));
    } else {
      skip('(j) byte-identity Makefile scenario', 'no `make` binary on PATH on this machine');
    }
  } finally {
    try { fs.rmSync(bDir, { recursive: true, force: true }); } catch { /* best-effort */ }
    if (offDir) { try { fs.rmSync(offDir, { recursive: true, force: true }); } catch { /* best-effort */ } }
    if (makeDir) { try { fs.rmSync(makeDir, { recursive: true, force: true }); } catch { /* best-effort */ } }
    for (const d of [bPoolOn, bPoolOff, bPoolFail, bPoolTimeout, bPoolMake]) {
      try { fs.rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
    }
  }

  // ── (k) real pool root untouched by ANY spawn above ───────────────────
  const realPoolExistedAfter = fs.existsSync(realPoolRoot);
  const realPoolListingAfter = realPoolExistedAfter ? fs.readdirSync(realPoolRoot).sort() : null;
  assert(realPoolExistedBefore === realPoolExistedAfter && JSON.stringify(realPoolListingBefore) === JSON.stringify(realPoolListingAfter),
    '(k) the real machine pool root (~/.claude/forge/resource-pool) is untouched — every fixture above used FORGE_RESOURCE_POOL_DIR pointed at a tmpdir',
    JSON.stringify({ before: realPoolListingBefore, after: realPoolListingAfter }));

  // ── (l) registration: the section verifies it is wired into main() ───
  const source = fs.readFileSync(__filename, 'utf8');
  const mainBody = source.slice(source.lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeVerifyReverifyChildSideE2E\(\); \}/.test(mainBody),
    '(l) Section 110 is registered in main() by closure — an unregistered section vanishes silently');

  pass('Section 110: forge-verify.js and forge-reverify.js clamp/unclamp proven CHILD-side via real CLI spawns, '
    + 'W5 census zeroed after failure AND timeout for both consumers, byte-identity proven for an unrecognized command '
    + 'with the rewrite module genuinely absent from disk (both consumers), and the real machine pool root never touched');
}

// ── Section 111: S05/T04 — forge-doctor --check resources + statusline clamp indicator, census bite both ways ──
// Section number MEASURED at execution time (`grep -o "Section [0-9]\+"
// scripts/forge-smoke.js | sort -n -k2 | tail -1` -> 108 was the real max),
// never assumed (MEM013: S01 assumed 100/real 104, S04 measured 107->108).
// Every claim here is proven by spawning the REAL `forge-doctor.js` and
// `forge-statusline.js` CLIs as child processes — never by requiring their
// modules in-process and reading return values, and never by reading a
// source comment.
function smokeResourcesObservabilityCensus() {
  process.stdout.write('\n▸ Section 111: forge-doctor --check resources + statusline clamp indicator, census bite both ways\n');
  const NODE = process.execPath;
  const DOCTOR_CLI = path.join(SCRIPTS, 'forge-doctor.js');
  const STATUSLINE_CLI = path.join(SCRIPTS, 'forge-statusline.js');

  function mkTmp(label) {
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), `smoke111-${label}-`));
    fs.mkdirSync(path.join(dir, '.gsd', 'forge'), { recursive: true });
    return dir;
  }
  function eventsPath(root) { return path.join(root, '.gsd', 'forge', 'events.jsonl'); }
  function appendEvent(root, obj) { fs.appendFileSync(eventsPath(root), `${JSON.stringify(obj)}\n`, 'utf8'); }
  function sha256File(p) {
    if (!fs.existsSync(p)) return null;
    return crypto.createHash('sha256').update(fs.readFileSync(p)).digest('hex');
  }
  function runStatusline(cwd, poolDir) {
    const input = JSON.stringify({ cwd, model: { display_name: 'smoke111' }, context_window: { used_percentage: 1 } });
    const env = Object.assign({}, process.env, { FORGE_RESOURCE_POOL_DIR: poolDir });
    return spawnSync(NODE, [STATUSLINE_CLI], { input, encoding: 'utf8', env, cwd: SCRIPTS });
  }

  // ── Real machine surfaces: never touched by anything in this section ─────
  const realPoolRoot = path.join(os.homedir(), '.claude', 'forge', 'resource-pool');
  const realPoolExistedBefore = fs.existsSync(realPoolRoot);
  const realPoolListingBefore = realPoolExistedBefore ? fs.readdirSync(realPoolRoot).sort() : null;

  const degradedRoot = mkTmp('degraded');
  const cleanRoot = mkTmp('empty');
  const dualFieldRoot = mkTmp('dualfield');
  const platformRoot = mkTmp('platform');
  const pollutionRoot = mkTmp('pollution');
  // R6 fix: every doctor spawn below reads through `checkResources ->
  // poolStatus`, which without `--pool-dir` resolves to the REAL machine-wide
  // `~/.claude/forge/resource-pool`. Reads are harmless (poolStatus/observe
  // never mutate), but they still touch an unowned machine surface, and
  // assertion (i) below claims every fixture used an isolated pool dir — a
  // claim that must be true, not just plausible. Give each doctor fixture its
  // own tmp pool dir, same isolation discipline the statusline fixtures (f)
  // already use.
  const doctorPoolDir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke111-doctor-pool-'));
  let stlHeldDir = null;
  let stlEmptyDir = null;
  let stlPoolHeldRoot = null;
  let stlPoolEmptyRoot = null;

  try {
    // ── (a) advisory absolute: real spawn exit 0, degraded fixture ─────────
    appendEvent(degradedRoot, { ts: new Date().toISOString(), kind: 'resource-admission', reason: 'platform-unsupported:linux' });
    const resA1 = spawnSync(NODE, [DOCTOR_CLI, '--check', 'resources', '--cwd', degradedRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resA1.status === 0, '(a) `--check resources` exits 0 by real spawn, with a degraded fixture present', String(resA1.status) + resA1.stderr);
    assert(/degraded/.test(resA1.stdout), '(a) degraded fixture surfaces the degraded verdict in stdout', resA1.stdout);
    // `--check all` also runs the (unrelated) non-advisory schema check —
    // stamp SCHEMA-VERSION so THIS assertion isolates the resources check
    // specifically (same fixture shape as forge-doctor-resources.test.js's
    // own `--check all` case; derived from the module, never hand-written).
    const { CURRENT_SCHEMA: DOCTOR_CURRENT_SCHEMA } = require(path.join(SCRIPTS, 'forge-doctor.js'));
    fs.writeFileSync(path.join(degradedRoot, '.gsd', 'SCHEMA-VERSION'), `${DOCTOR_CURRENT_SCHEMA}\n`, 'utf8');
    const resA2 = spawnSync(NODE, [DOCTOR_CLI, '--check', 'all', '--cwd', degradedRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resA2.status === 0, '(a) `--check all` also exits 0 by real spawn with the same degraded fixture', String(resA2.status) + resA2.stderr);
    assert(/Resource control/.test(resA2.stdout), '(a) `--check all` output includes the resources check', resA2.stdout);

    // ── (b) anti-silence floor: zero events -> inconclusive, never clean ───
    const resB = spawnSync(NODE, [DOCTOR_CLI, '--check', 'resources', '--cwd', cleanRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resB.status === 0, '(b) zero-events fixture still exits 0', String(resB.status) + resB.stderr);
    assert(/inconclusive/.test(resB.stdout), '(b) zero events examined reads inconclusive', resB.stdout);
    assert(!/\bclean\b/.test(resB.stdout), '(b) zero events examined NEVER reads clean — the floor is first in verdict order', resB.stdout);

    // ── (c) positive bite: BOTH field names (`kind` and `event`), reason count >= 1 ──
    appendEvent(dualFieldRoot, { ts: new Date().toISOString(), kind: 'resource-admission', reason: 'platform-unsupported:linux' });
    appendEvent(dualFieldRoot, { ts: new Date().toISOString(), event: 'resource-degradation', reason: 'platform-unsupported:linux' });
    const resC = spawnSync(NODE, [DOCTOR_CLI, '--check', 'resources', '--cwd', dualFieldRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resC.status === 0, '(c) dual-field-name fixture exits 0', String(resC.status) + resC.stderr);
    assert(/platform-unsupported:linux/.test(resC.stdout) && /2/.test(resC.stdout),
      '(c) BOTH `kind` and `event` field names are counted into the same reason with count >= 1 (a `kind`-only reader would see half the stream — the exact S03 rewrite-event blind spot this slice exists to close)',
      resC.stdout);

    // ── (d) forced platform degradation is NAMED, not passed clean ─────────
    const resD = spawnSync(NODE, [DOCTOR_CLI, '--check', 'resources', '--cwd', platformRoot, '--platform', 'linux', '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resD.status === 0, '(d) forced-platform fixture exits 0', String(resD.status) + resD.stderr);
    assert(/platform-unsupported:linux/.test(resD.stdout), '(d) --platform linux is NAMED in the live pressure line, never silently passed', resD.stdout);

    // ── (e) non-pollution: events.jsonl is byte-identical before/after ─────
    appendEvent(pollutionRoot, { ts: new Date().toISOString(), kind: 'shadow-wait', reason: 'shadow-wait' });
    const beforeHash = sha256File(eventsPath(pollutionRoot));
    const resE = spawnSync(NODE, [DOCTOR_CLI, '--check', 'resources', '--cwd', pollutionRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
    assert(resE.status === 0, '(e) non-pollution fixture check exits 0', String(resE.status) + resE.stderr);
    const afterHash = sha256File(eventsPath(pollutionRoot));
    assert(beforeHash !== null && beforeHash === afterHash,
      '(e) events.jsonl is byte-identical before/after `--check resources` — the diagnostic never contaminates the census it reports (noEvents:true)',
      `before=${beforeHash} after=${afterHash}`);

    // ── (f) statusline: pool occupied -> indicator present; empty -> absent ──
    stlHeldDir = mkTmp('stl-held-dir');
    stlPoolHeldRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke111-stl-pool-held-'));
    let acquireSlots = null;
    try { ({ acquireSlots } = require(path.join(SCRIPTS, 'forge-resource-pool.js'))); } catch { /* asserted below */ }
    const granted = acquireSlots ? acquireSlots(1, { poolDir: stlPoolHeldRoot, ncpu: 4, commandTimeoutMs: 120000, ownerToken: 'smoke111' }) : null;
    assert(!!granted && granted.ok, '(f) setup: real pool grant succeeds via forge-resource-pool.js (never a hand-authored lease file)', JSON.stringify(granted));
    const resF1 = runStatusline(stlHeldDir, stlPoolHeldRoot);
    assert(resF1.status === 0, '(f) statusline exits 0 with a held slot', JSON.stringify({ status: resF1.status, stderr: resF1.stderr }));
    assert((resF1.stdout || '').includes('\u{1F9EE}'), '(f) clamp indicator glyph is PRESENT when the pool holds a slot, by real spawn with JSON on stdin', resF1.stdout);

    stlEmptyDir = mkTmp('stl-empty-dir');
    stlPoolEmptyRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke111-stl-pool-empty-'));
    const resF2 = runStatusline(stlEmptyDir, stlPoolEmptyRoot);
    assert(resF2.status === 0, '(f) statusline exits 0 with an empty pool', JSON.stringify({ status: resF2.status, stderr: resF2.stderr }));
    assert(!(resF2.stdout || '').includes('\u{1F9EE}'), '(f) clamp indicator glyph is ABSENT when the pool is free and no degradation event exists — bite reverses on the SAME code path', resF2.stdout);

    // ── (g) negative-direction bite: neuter the anti-silence floor in a COPY,
    // never in the real checkout (precedent: S04/T04 R10 — copy to tmp, mutate
    // the copy, never rename/edit the tracked tree). Confirm the mutated copy
    // FAILS to read inconclusive on a zero-events fixture, proving assertion
    // (b) above actually bites; the real checkout is never touched, so no
    // restore step is needed — the copy is simply discarded.
    const mutCopyRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke111-mutcopy-'));
    const mutScriptsDir = path.join(mutCopyRoot, 'scripts');
    // R7 fix: hoisted to the outer scope (was declared inside the inner try,
    // whose `finally` removed only `mutCopyRoot`) — every smoke run leaked a
    // `smoke111-mut-fixture-*` tmpdir. Cleaned up in this block's own
    // `finally` below, alongside `mutCopyRoot`.
    let mutRoot = null;
    try {
      fs.cpSync(SCRIPTS, mutScriptsDir, { recursive: true });
      const censusPath = path.join(mutScriptsDir, 'forge-resources-census.js');
      const originalSrc = fs.readFileSync(censusPath, 'utf8');
      const originalOnDisk = fs.readFileSync(path.join(SCRIPTS, 'forge-resources-census.js'), 'utf8');
      // Both halves of the floor are neutered (buildCensus's own header names
      // both as "proven to BITE" — neutering only the first would still catch
      // a truly-empty fixture on the second `resource_events === 0` branch and
      // produce a false-negative bite that looks like a real one).
      assert(/if \(events_scanned === 0\) \{/.test(originalSrc) && /else if \(resource_events === 0\) \{/.test(originalSrc),
        '(g) precondition: BOTH halves of the anti-silence floor exist verbatim in the copy before mutation', 'floor lines not found');
      const neuteredSrc = originalSrc
        .replace('if (events_scanned === 0) {', 'if (false) {')
        .replace('else if (resource_events === 0) {', 'else if (false) {');
      assert(neuteredSrc !== originalSrc, '(g) the floor-neutering replacement actually changed the source (not a no-op substitution)', 'replace() produced no change');
      fs.writeFileSync(censusPath, neuteredSrc, 'utf8');
      const mutDoctorCli = path.join(mutScriptsDir, 'forge-doctor.js');
      mutRoot = mkTmp('mut-fixture');
      const resG = spawnSync(NODE, [mutDoctorCli, '--check', 'resources', '--cwd', mutRoot, '--pool-dir', doctorPoolDir], { encoding: 'utf8' });
      assert(resG.status === 0, '(g) mutated-copy CLI still exits 0 (advisory posture survives the mutation)', String(resG.status) + resG.stderr);
      assert(!/inconclusive/.test(resG.stdout),
        '(g) MORDIDA NEGATIVA: with the anti-silence floor neutered, a zero-events fixture NO LONGER reads inconclusive — the assertion in (b) would FAIL against this build, proving the floor is what makes (b) pass, not coincidence',
        resG.stdout);
      // Real checkout on disk is provably untouched by this mutation (we only
      // ever wrote to mutScriptsDir, a tmp copy) — restore is implicit.
      const stillOnDisk = fs.readFileSync(path.join(SCRIPTS, 'forge-resources-census.js'), 'utf8');
      assert(stillOnDisk === originalOnDisk, '(g) the REAL checkout file is byte-identical before/after this mutation exercise — only the tmp copy was ever written', 'checkout file drifted');
    } finally {
      try { fs.rmSync(mutCopyRoot, { recursive: true, force: true }); } catch { /* best-effort */ }
      if (mutRoot) { try { fs.rmSync(mutRoot, { recursive: true, force: true }); } catch { /* best-effort */ } }
    }

    // ── (h) registration: the section verifies it is wired into main() ─────
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeResourcesObservabilityCensus\(\); \}/.test(mainBody),
      '(h) Section 111 is registered in main() by closure — an unregistered section vanishes silently');
  } finally {
    for (const d of [degradedRoot, cleanRoot, dualFieldRoot, platformRoot, pollutionRoot, stlHeldDir, stlEmptyDir, stlPoolHeldRoot, stlPoolEmptyRoot, doctorPoolDir]) {
      if (d) { try { fs.rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ } }
    }
  }

  // ── (i) real pool root and real .gsd/ never touched by any fixture above ─
  // R6 fix: the doctor-CLI fixtures (a)-(e)/(g) now also pass `--pool-dir`
  // pointed at `doctorPoolDir` — this label previously overclaimed
  // ("every fixture above used ...") while those spawns actually read the
  // real machine-wide pool root via `poolStatus`'s default resolution.
  const realPoolExistedAfter = fs.existsSync(realPoolRoot);
  const realPoolListingAfter = realPoolExistedAfter ? fs.readdirSync(realPoolRoot).sort() : null;
  assert(realPoolExistedBefore === realPoolExistedAfter && JSON.stringify(realPoolListingBefore) === JSON.stringify(realPoolListingAfter),
    '(i) the real machine pool root (~/.claude/forge/resource-pool) is untouched — every statusline fixture used FORGE_RESOURCE_POOL_DIR and every doctor-CLI fixture used --pool-dir, all pointed at a tmpdir',
    JSON.stringify({ before: realPoolListingBefore, after: realPoolListingAfter }));

  pass('Section 111: forge-doctor --check resources and the statusline clamp indicator proven exit-0-always by real spawn, '
    + 'dual event-field-name census bite proven positive, anti-silence floor bite proven negative via copy-mutation, '
    + 'zero pollution of events.jsonl, and the real machine pool root never touched');
}

// ── Section 114: routing contract projected into the project instruction file ──
//
// Section number MEASURED at execution time (`grep -oE "Section [0-9]+"
// scripts/forge-smoke.js | sort -u`) — measured AFTER a first draft collided with
// the existing Section 113 (smokeVersionTagLine) because the grep was run after
// the insert instead of before it. Measure on the tree you are changing, not the
// one you already changed.
//
// The defect this guards is the one TASK-021 already paid for once: the routing
// decision is made by a resolver, but the agent that READS it is the session
// itself, and a rule the session never reads cannot bind it. The contract lives
// in the project's instruction file for that reason — so this section asserts
// (a) the projector exists and behaves, (b) every start-of-work entry point
// actually calls it (wiring, not intention), (c) the canonical spec carries the
// section, and (d) the projector is non-destructive under the two conditions a
// naive implementation gets wrong: a quoted marker pair, and a malformed block.
//
// (a) and (d) are BEHAVIORAL — run against a real temp project — because a
// presence-only guard goes green over a wired-but-inert helper, which is the
// exact failure this repo has shipped before.
function smokeRoutingContractProjection() {
  process.stdout.write('\n▸ Section 114: routing contract projected into CLAUDE.md\n');
  const repoRoot = path.dirname(SCRIPTS);
  const mod = require('./forge-instructions.js');

  // (a) behavioral: sync writes the block, and a second sync changes nothing.
  const root = fs.mkdtempSync(path.join(os.tmpdir(), 'forge-smoke-contract-'));
  try {
    fs.writeFileSync(path.join(root, 'CLAUDE.md'), '# Projeto\n\nRegras do operador.\n', 'utf8');
    const first = mod.syncInstructions(root);
    assert(first.files.find((f) => f.host === 'claude').outcome === 'updated', '(a) primeiro sync escreve');
    const bytes = fs.readFileSync(path.join(root, 'CLAUDE.md'), 'utf8');
    assert(bytes.includes('forge-dispatch-resolve.js') && bytes.includes('worker-engine-fallback'),
      '(a) o bloco escrito nomeia o resolvedor e o fallback nomeado');
    const second = mod.syncInstructions(root);
    assert(second.changed === 0 && fs.readFileSync(path.join(root, 'CLAUDE.md'), 'utf8') === bytes,
      '(a) o segundo sync é byte-idêntico');

    // (d1) malformed block: refused by name, nothing written.
    const bad = `# P\n\n${mod.MARKER_END}\n`;
    fs.writeFileSync(path.join(root, 'CLAUDE.md'), bad, 'utf8');
    const refused = mod.syncInstructions(root).files.find((f) => f.host === 'claude');
    assert(refused.outcome === 'skipped' && /^malformed-block:/.test(refused.reason),
      '(d1) bloco malformado recusado por nome');
    assert(fs.readFileSync(path.join(root, 'CLAUDE.md'), 'utf8') === bad,
      '(d1) recusa que ainda escreveu — a forma de falha que um assert de string não vê');

    // (d2) a marker pair quoted inside a code fence is documentation, and the
    // positive control proves the fixture would fool a naive detector.
    const quoted = ['```markdown', `${mod.MARKER_START} version=X -->`, 'NAO-PODE-SUMIR', mod.MARKER_END, '```', ''].join('\n');
    assert(/^<!-- forge:routing-contract:start[^\n]*-->[ \t]*$/m.test(quoted),
      '(d2) controle positivo: o fixture casaria num detector ingênuo');
    assert(mod.findBlock(quoted) === null, '(d2) marcador em fence lido como bloco');
    fs.writeFileSync(path.join(root, 'CLAUDE.md'), quoted, 'utf8');
    mod.syncInstructions(root);
    assert(fs.readFileSync(path.join(root, 'CLAUDE.md'), 'utf8').includes('NAO-PODE-SUMIR'),
      '(d2) o splice comeu o exemplo citado');
  } finally {
    try { fs.rmSync(root, { recursive: true, force: true }); } catch { /* best effort */ }
  }

  // (b) wiring: every start-of-work entry point invokes the projector. Intention
  // in prose is not wiring — the call must be in an executable line.
  const CALL_SITES = [
    'skills/forge-auto/SKILL.md',
    'skills/forge-next/SKILL.md',
    'skills/forge-task/SKILL.md',
    'commands/forge.md',
    'commands/forge-init.md',
  ];
  for (const relative of CALL_SITES) {
    const text = readRepoText(path.join(repoRoot, relative));
    assert(/^node "\$FORGE_SCRIPTS_DIR\/forge-instructions\.js" --sync/m.test(text),
      `(b) ${relative} não invoca forge-instructions.js --sync`);
  }

  // (c) canonical spec carries the section the mirrors point at.
  const dispatch = readRepoText(path.join(repoRoot, 'shared', 'forge-dispatch.md'));
  assert(dispatch.includes('### Routing Contract Projection'), '(c) spec sem a seção canônica');
  assert(dispatch.includes('scripts/forge-instructions.js'), '(c) spec não nomeia o projetor');

  // (e) registration bites — the section must be reachable from main().
  const mainBody = fs.readFileSync(__filename, 'utf8').slice(fs.readFileSync(__filename, 'utf8').lastIndexOf('async function main()'));
  assert(/\(\) => \{ smokeRoutingContractProjection\(\); \}/.test(mainBody), '(e) Section 114 registrada em main()');

  pass('Section 114: routing contract is projected, wired at every entry point, and non-destructive');
}

// ── Section 112: S06/T01-T04 guard — signal-not-clock SIGINT, enforcement:off ─
// bypass contrast, bench JSONL+prefs-restore, and anti-silence floor bite on
// the bench harness — number MEASURED at execution time (max observed was
// 109; 110 is the first free slot), never assumed (MEM013). Every claim is
// proven by spawning the REAL `forge-status.js` and `forge-resources-bench.js`
// CLIs (and `forge-verify.js`'s CLI entrypoint for the enforcement contrast)
// as child processes — never by requiring the modules under test in-process.
function smokeResourcesFlakeAndBenchGuard() {
  process.stdout.write('\n▸ Section 112: T01 signal-not-clock SIGINT, T03 enforcement:off contrast, T04 bench JSONL+restore, T04 anti-silence bite\n');
  const NODE = process.execPath;
  const STATUS_CLI = path.join(SCRIPTS, 'forge-status.js');
  const VERIFY_CLI = path.join(SCRIPTS, 'forge-verify.js');
  const BENCH_CLI = path.join(SCRIPTS, 'forge-resources-bench.js');

  // ── shared fixture helpers ────────────────────────────────────────────────
  const ROADMAP_TEXT = [
    '# M-20260101120000-alpha: Alpha Milestone — Roadmap',
    '',
    '- [x] **S01: Done one** `risk:low`',
    '- [ ] **S02: Active one** `risk:high`',
    '',
  ].join('\n');
  const PLAN_TEXT = [
    '# S02 Plan',
    '',
    '- [x] T01: plain done',
    '- [ ] T02: plain active',
    '',
  ].join('\n');
  function stateText(milestoneId) {
    const nowIso = new Date().toISOString();
    return [
      '---',
      `milestone: ${milestoneId}`,
      'kind: milestone',
      `created: ${nowIso}`,
      `last_updated: ${nowIso}`,
      'isolation_mode: shared',
      '---',
      '',
      `# ${milestoneId} State`,
      '',
      '**Active Slice:** S02',
      '**Active Task:** T02',
      '**Phase:** execute-task',
      '**Auto-mode:** on',
      '**Next Action:** Continue T02',
      '',
    ].join('\n');
  }
  function makeStatusFixture() {
    const milestoneId = 'M-20260101120000-alpha';
    const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke112-status-'));
    const mDir = path.join(dir, '.gsd', 'milestones', milestoneId);
    fs.mkdirSync(path.join(mDir, 'slices', 'S02'), { recursive: true });
    fs.writeFileSync(path.join(mDir, `${milestoneId}-ROADMAP.md`), ROADMAP_TEXT, 'utf8');
    fs.writeFileSync(path.join(mDir, `${milestoneId}-STATE.md`), stateText(milestoneId), 'utf8');
    fs.writeFileSync(path.join(mDir, 'slices', 'S02', 'S02-PLAN.md'), PLAN_TEXT, 'utf8');
    return dir;
  }

  const isPosix = process.platform !== 'win32';
  const dirsToClean = [];

  try {
    // ── (a) T01: flaky-by-order fixed — wait for an OBSERVABLE readiness ────
    // signal (the child's own "refresh #1" output), never a fixed-duration
    // sleep. Named-reason ceiling (READY_TIMEOUT) replaces the sleep-0.2
    // gamble the original R2 test used — same mechanism forge-status.test.js
    // R2 introduced, read from there, not re-invented here.
    if (!isPosix) {
      skip('Section 112(a): forge-status --watch SIGINT-after-readiness-signal', 'posix-only /bin/sh + kill fixture (mirrors forge-status.test.js R2)');
    } else {
      const statusDir = makeStatusFixture();
      dirsToClean.push(statusDir);
      const outFile = path.join(statusDir, '.watch-out.txt');
      const script = `"${NODE}" "${STATUS_CLI}" --watch=0.5 --cwd "${statusDir}" >"${outFile}" 2>&1 & pid=$!; i=0; while ! grep -q "refresh #1" "${outFile}" 2>/dev/null; do i=$((i+1)); if [ "$i" -ge 150 ]; then echo READY_TIMEOUT; kill -INT "$pid" 2>/dev/null; wait "$pid" 2>/dev/null; exit 0; fi; sleep 0.02; done; kill -INT "$pid"; wait "$pid"; echo "EXIT:$?"`;
      const resA = spawnSync('/bin/sh', ['-c', script], { encoding: 'utf8', timeout: 8000 });
      assert(!/READY_TIMEOUT/.test(resA.stdout || ''),
        '(a) child signaled readiness ("refresh #1" observed) within the named ceiling — never a fixed-duration sleep',
        `stdout=${resA.stdout} stderr=${resA.stderr}`);
      const m = (resA.stdout || '').match(/EXIT:(\d+)/);
      assert(m, '(a) EXIT:<code> marker present in stdout', String(resA.stdout));
      assert(!!m && m[1] === '0', '(a) real spawn: --watch child exits 0 on SIGINT sent right after the readiness signal, by a REAL spawned CLI (D5: only a process this block itself created)', String(resA.stdout));
    }

    // ── (b) T03: resources.enforcement:off bypass — CONTRAST with `clamp` on ─
    // the exact same entry (positive control). Only the `off` cell would pass
    // green under a bypass that is always-on; only `clamp` would pass green
    // under a bypass that is inert — asserting both is what proves the toggle
    // actually gates the rewrite (S06-PLAN.md A1).
    if (!isPosix) {
      skip('Section 112(b): forge-verify.js CLI enforcement:off/clamp contrast', 'posix-only shebang fixture (mirrors forge-resources-enforcement.test.js)');
    } else {
      function runVerifyCell(enforcement) {
        const cwd = fs.mkdtempSync(path.join(os.tmpdir(), `smoke112-enf-${enforcement}-`));
        dirsToClean.push(cwd);
        fs.mkdirSync(path.join(cwd, '.gsd', 'forge'), { recursive: true });
        fs.writeFileSync(path.join(cwd, '.gsd', 'forge-prefs.jsonc'), JSON.stringify({ resources: { enforcement } }, null, 2) + '\n', 'utf8');
        const binDir = path.join(cwd, 'bin');
        fs.mkdirSync(binDir, { recursive: true });
        const dumpFile = path.join(cwd, 'dump.json');
        fs.writeFileSync(path.join(binDir, 'vitest'),
          `#!/usr/bin/env node\nconst fs = require('fs');\nfs.writeFileSync(${JSON.stringify(dumpFile)}, JSON.stringify({ env: process.env, argv: process.argv }));\nprocess.exit(0);\n`,
          { mode: 0o755 });
        const poolDir = fs.mkdtempSync(path.join(os.tmpdir(), `smoke112-enf-pool-${enforcement}-`));
        dirsToClean.push(poolDir);
        const env = Object.assign({}, process.env, {
          PATH: binDir + path.delimiter + process.env.PATH,
          FORGE_RESOURCE_POOL_DIR: poolDir,
          FORGE_RESOURCES_PRESSURE: '1',
          NODE_OPTIONS: '',
        });
        const res = spawnSync(NODE, [VERIFY_CLI, '--cwd', cwd, '--unit', 'smoke112', '--gsd-dir', path.join(cwd, '.gsd'), '--preference', 'vitest'], { encoding: 'utf8', env });
        assert(res.status === 0, `(b) forge-verify.js CLI exits 0 under enforcement:${enforcement}`, `status=${res.status} stderr=${res.stderr}`);
        assert(fs.existsSync(dumpFile), `(b) fixture never ran under enforcement:${enforcement} — real spawn produced no child-observed dump`, res.stdout + res.stderr);
        return JSON.parse(fs.readFileSync(dumpFile, 'utf8'));
      }
      const dumpOff = runVerifyCell('off');
      const dumpClamp = runVerifyCell('clamp');
      assert(dumpOff.env.VITEST_MAX_FORKS === undefined, '(b) enforcement:off — the verification command reaches the child argv/env byte-identical (no VITEST_MAX_FORKS injected)', String(dumpOff.env.VITEST_MAX_FORKS));
      assert(dumpOff.env.NODE_OPTIONS === undefined || dumpOff.env.NODE_OPTIONS === '', '(b) enforcement:off — no heap NODE_OPTIONS injected', String(dumpOff.env.NODE_OPTIONS));
      assert(typeof dumpClamp.env.VITEST_MAX_FORKS === 'string' && dumpClamp.env.VITEST_MAX_FORKS.length > 0,
        '(b) POSITIVE CONTROL: the SAME entry under enforcement:clamp IS rewritten (VITEST_MAX_FORKS present) — proves the off-cell above passed because of the toggle, not because the rewrite is dead',
        JSON.stringify(dumpClamp.env.VITEST_MAX_FORKS));
      assert(typeof dumpClamp.env.NODE_OPTIONS === 'string' && /--max-old-space-size=\d+/.test(dumpClamp.env.NODE_OPTIONS),
        '(b) clamp cell also carries the heap NODE_OPTIONS overlay', String(dumpClamp.env.NODE_OPTIONS));
    }

    // ── (c) T04: bench harness — real CLI spawn, incremental JSONL, prefs restored ──
    const benchCwd = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke112-bench-cwd-'));
    dirsToClean.push(benchCwd);
    fs.mkdirSync(path.join(benchCwd, '.gsd', 'forge'), { recursive: true });
    const prefsPath = path.join(benchCwd, '.gsd', 'forge-prefs.jsonc');
    const originalPrefs = JSON.stringify({ marker: 'smoke112-untouched', other: 42 }, null, 2) + '\n';
    fs.writeFileSync(prefsPath, originalPrefs, 'utf8');
    const outFile = path.join(benchCwd, 'bench-out.jsonl');
    const shortCmd = JSON.stringify([NODE, '-e', 'process.exit(0)']);
    const resC = spawnSync(NODE, [
      BENCH_CLI, '--cwd', benchCwd, '--cells', 'solo/off', '--reps', '3',
      '--out', outFile, '--command', shortCmd, '--timeout-ms', '10000',
    ], { encoding: 'utf8' });
    assert(resC.status === 0, '(c) forge-resources-bench.js CLI real spawn exits 0 with an injected instant command', `status=${resC.status} stdout=${resC.stdout} stderr=${resC.stderr}`);
    const lines = fs.readFileSync(outFile, 'utf8').split('\n').filter(Boolean);
    assert(lines.length === 3, '(c) JSONL has exactly one valid line per corrida — written incrementally (survives interruption by A4 design), never batched at the end', String(lines.length));
    for (const line of lines) {
      const rec = JSON.parse(line);
      assert(rec.cell === 'solo/off', '(c) each JSONL record names its cell', line);
      assert(rec.status === 'ok', '(c) each corrida of the injected instant command completed ok', line);
    }
    const restoredPrefs = fs.readFileSync(prefsPath, 'utf8');
    assert(restoredPrefs === originalPrefs, '(c) the project-local prefs file is byte-identical to its original content after the bench run — every corrida\'s enforcement write is restored on exit, never left mutated', restoredPrefs);

    // ── (d) T04: anti-silence floor bite — neutered in a COPY only ──────────
    // (precedent: S04/T04, S05/T04) — copy scripts/ to a tmpdir, mutate ONLY
    // the copy, spawn the mutated copy's CLI, and prove the floor's absence
    // produces a false "measured" verdict where the REAL script correctly
    // reports "inconclusive". The checkout is never edited in place; the
    // mutation-copy tmpdir is removed in this block's own cleanup (R7 of S05
    // — the mutation-fixture leak precedent — never repeated).
    const mutCopyRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke112-mutcopy-'));
    let mutFixtureRoot = null;
    try {
      const mutScriptsDir = path.join(mutCopyRoot, 'scripts');
      fs.cpSync(SCRIPTS, mutScriptsDir, { recursive: true });
      const benchPath = path.join(mutScriptsDir, 'forge-resources-bench.js');
      const originalSrc = fs.readFileSync(benchPath, 'utf8');
      const originalOnDisk = fs.readFileSync(path.join(SCRIPTS, 'forge-resources-bench.js'), 'utf8');
      const target = "if (ok.length === 0) {";
      assert(originalSrc.includes(target), '(d) precondition: the anti-silence-floor guard line exists verbatim in the copy before mutation', 'guard line not found');
      const neuteredSrc = originalSrc.replace(target, 'if (false) {');
      assert(neuteredSrc !== originalSrc, '(d) the floor-neutering replacement actually changed the source (not a no-op substitution)', 'replace() produced no change');
      fs.writeFileSync(benchPath, neuteredSrc, 'utf8');

      mutFixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke112-mut-fixture-'));
      const mutOutFile = path.join(mutFixtureRoot, 'bench-out.jsonl');
      // Zero-ok fixture: the injected command always FAILS, so there are zero
      // `ok` corridas — exactly the case the anti-silence floor exists to
      // catch and report as `inconclusive`.
      const failCmd = JSON.stringify([NODE, '-e', 'process.exit(1)']);
      const resD = spawnSync(NODE, [
        path.join(mutScriptsDir, 'forge-resources-bench.js'),
        '--cwd', mutFixtureRoot, '--cells', 'solo/off', '--reps', '3',
        '--out', mutOutFile, '--command', failCmd, '--timeout-ms', '10000',
      ], { encoding: 'utf8' });
      assert(resD.status === 0, '(d) mutated-copy CLI still exits 0 (the harness never fails hard on a zero-ok cell)', `status=${resD.status} stderr=${resD.stderr}`);
      assert(!/inconclusive/.test(resD.stdout),
        '(d) MORDIDA NEGATIVA: with the anti-silence floor neutered, a zero-ok cell no longer reads inconclusive — this is the exact assertion the REAL script satisfies below, proving the floor (not coincidence) is what makes it pass',
        resD.stdout);

      const stillOnDisk = fs.readFileSync(path.join(SCRIPTS, 'forge-resources-bench.js'), 'utf8');
      assert(stillOnDisk === originalOnDisk, '(d) the REAL checkout file is byte-identical before/after this mutation exercise — only the tmp copy was ever written', 'checkout file drifted');

      // Contrast: the REAL (unmutated) script, same zero-ok fixture, DOES read inconclusive.
      const realFixtureRoot = fs.mkdtempSync(path.join(os.tmpdir(), 'smoke112-real-fixture-'));
      dirsToClean.push(realFixtureRoot);
      const realOutFile = path.join(realFixtureRoot, 'bench-out.jsonl');
      const resReal = spawnSync(NODE, [
        BENCH_CLI, '--cwd', realFixtureRoot, '--cells', 'solo/off', '--reps', '3',
        '--out', realOutFile, '--command', failCmd, '--timeout-ms', '10000',
      ], { encoding: 'utf8' });
      assert(resReal.status === 0, '(d) real script also exits 0 on the same zero-ok fixture', `status=${resReal.status} stderr=${resReal.stderr}`);
      assert(/inconclusive/.test(resReal.stdout), '(d) the REAL (unmutated) script correctly reads inconclusive on the same zero-ok fixture — the positive half of the bidirectional bite', resReal.stdout);
    } finally {
      try { fs.rmSync(mutCopyRoot, { recursive: true, force: true }); } catch { /* best-effort */ }
      if (mutFixtureRoot) { try { fs.rmSync(mutFixtureRoot, { recursive: true, force: true }); } catch { /* best-effort */ } }
    }

    // ── (e) registration: the section verifies it is wired into main() ──────
    const source = fs.readFileSync(__filename, 'utf8');
    const mainBody = source.slice(source.lastIndexOf('async function main()'));
    assert(/\(\) => \{ smokeResourcesFlakeAndBenchGuard\(\); \}/.test(mainBody),
      '(e) Section 112 is registered in main() by closure — an unregistered section vanishes silently');
  } finally {
    for (const d of dirsToClean) {
      try { fs.rmSync(d, { recursive: true, force: true }); } catch { /* best-effort */ }
    }
  }

  pass('Section 112: forge-status --watch SIGINT-after-signal proven by real spawn (T01), forge-verify.js enforcement:off/clamp '
    + 'contrast proven child-side on the same entry (T03), forge-resources-bench.js CLI proven to write per-corrida JSONL and '
    + 'restore prefs byte-identical (T04), and the bench anti-silence floor proven to bite bidirectionally via copy-mutation (T04)');
}

async function main() {
  process.stdout.write('forge-smoke — M004+ multi-run primitives\n');
  process.stdout.write('─'.repeat(50) + '\n');

  const start = Date.now();
  try {
    // Sections are isolated from one another: a throw inside one is recorded as
    // a failure and every later section still runs. Before this, a single
    // try/catch wrapped the whole list, so one unguarded dereference in an early
    // section skipped all 45 sections behind it — roughly 1200 assertions —
    // while the summary still printed an ordinary "Results: N passed, M failed"
    // and exit 1. A release gate that can drop three quarters of its coverage
    // without saying so is worse than a red one.
    for (const body of [
      () => { smokeRuns(); },
      () => { smokeLock(); },
      () => { smokeState(); },
      () => { smokeDashboard(); },
      () => { smokeMerger(); },
      () => { smokeFilelock(); },
      () => { smokeRepos(); },
      () => { smokeCliHelpers(); },
      () => { smokeIsolation(); },
      () => { smokeLivenessBanner(); },
      () => { smokeSymbolAndTestQuality(); },
      () => { smokeContextMonitor(); },
      () => { smokeNodeRepair(); },
      () => { smokeStopHook(); },
      () => { smokeNotifications(); },
      () => { smokeReviewEngine(); },
      () => { smokeAccounts(); },
      () => { smokeEffort(); },
      () => { smokeUsageIndicator(); },
      () => { smokePlanGateDegradation(); },
      () => { smokeXllm(); },
      async () => { await smokeXllmExecute(); },
      async () => { await smokeSidecarContextParity(); },
      () => { smokeModelAlias(); },
      () => { smokeChallengerWiring(); },
      () => { smokeAdvocateModel(); },
      () => { smokeStatusPackaging(); },
      () => { smokeEngineDispatch(); },
      async () => { await smokeXllmPlan(); },
      () => { smokeTierChain(); },
      () => { smokeReviewPairing(); },
      () => { smokeReviewPairingWiring(); },
      () => { smokeReviewPairingPrefsSchema(); },
      () => { smokeRouting(); },
      () => { smokeRoutingWiring(); },
      () => { smokeDomainEmission(); },
      () => { smokeGeminiFamily(); },
      () => { smokeRoutingScaffoldDocs(); },
      () => { smokePrefsEngine(); },
      () => { smokePrefsCatalog(); },
      () => { smokePrefsCutover(); },
      () => { smokeSkillsCutover(); },
      () => { smokePrefsMigration(); },
      () => { smokePrefsViewerDoctor(); },
      () => { smokePrefsMigrationFidelity(); },
      () => { smokeInitSetupScaffold(); },
      () => { smokeStubPatternRobustness(); },
      () => { smokeDispatchResolve(); },
      () => { smokeSurgicalReset(); },
      () => { smokeSidecarLayer1Retry(); },
      () => { smokeSidecarPolicyGuard(); },
      () => { smokePrefsChokepoints(); },
      () => { smokePrefsConsumers(); },
      () => { smokePrefsCutoverGuards(); },
      () => { smokeHeartbeatContract(); },
      () => { smokeSidecarGptCap(); },
      () => { smokeSidecarEnvContract(); },
      () => { smokeSchemaExtraction(); },
      () => { smokeRequireWorktree(); },
      () => { smokeSidecarEnvPromotion(); },
      () => { smokeSandboxExecBlocked(); },
      () => { smokeCleanupRegistryMode(); },
      () => { smokeXllmStateSliceQualified(); },
      () => { smokeReviewModelDiscipline(); },
      () => { smokeXllmResultFileGuard(); },
      () => { smokeRoutingDomains(); },
      () => { smokeInitGitGuarantee(); },
      () => { smokeCodeDirMultiRepo(); },
      () => { smokeWorkspaceRepos(); },
      () => { smokeDoctorPlanRepo(); },
      () => { smokeReviewAgentUnavailable(); },
      () => { smokeSharedGlob(); },
      () => { smokePhasesTable(); },
      () => { smokeSidecarModel(); },
      () => { smokeVerifierCodeDir(); },
      () => { smokeWindowsSandboxAndWorktreeDeps(); },
      () => { smokeSvnFixture(); },
      () => { smokeVcsSeam(); },
      () => { smokeSvnPrimitives(); },
      () => { smokeSvnRevisionGuard(); },
      () => { smokeSidecarDiffCanonical(); },
      () => { smokeXllmSvn(); },
      () => { smokeIsolationSvnAndVcsTelemetry(); },
      () => { smokeRouteAudit(); },
      () => { smokeRegistrySchemaAndEnogsd(); },
      () => { smokeHierarchyDerived(); },
      () => { smokeMultiRepoResolution(); },
      () => { smokeConcurrentRunAddresses(); },
      () => { smokeDocClaimsGuard(); },
      () => { smokeRunOverlapSignal(); },
      () => { smokeSchemaGuardWiring(); },
      () => { smokeControlBytes(); },
      () => { smokeAppServerSchemaPin(); },
      async () => { await smokeAppServerTransport(); },
      async () => { await smokeCapabilityPerTurn(); },
      () => { smokeEvidenceRuntime(); },
      () => { smokeExecCallSitesRetired(); },
      () => { smokeEnvCoverage(); },
      async () => { await smokeTurnInterrupt(); },
      () => { smokeInertRoutes(); },
      () => { smokeTransportField(); },
      () => { smokeRoutingDomainsRendered(); },
      () => { smokeLedgerSnapshotRendered(); },
      () => { smokeMemoryIndexCommandRendered(); },
      () => { smokeScriptsCallSitesCanonical(); },
      () => { smokeContractMissBranch(); },
      () => { smokeHookPathManaged(); },
      () => { smokeResourcesFoundation(); },
      async () => { await smokeResourcePool(); },
      () => { smokeRewriteCeilingAndE2E(); },
      () => { smokeVerifyReverifyChildSideE2E(); },
      () => { smokeResourcesObservabilityCensus(); },
      () => { smokeResourcesFlakeAndBenchGuard(); },
      () => { smokeRoutingContractProjection(); },
      () => { smokeVersionTagLine(); },
      async () => { await smokeSectionIsolation(); },
    ]) await runSection(body);
  } catch (e) {
    fail('unhandled exception', e.stack || e.message);
  }

  const ms = Date.now() - start;
  process.stdout.write('\n' + '─'.repeat(50) + '\n');
  // Loud by construction: a crashed section costs every assertion behind it, so
  // it must never be readable as "just another failure" in the tally.
  if (crashedSections.length > 0) {
    process.stdout.write(`⚠ ${crashedSections.length} section(s) crashed and did not finish: ${crashedSections.join(', ')}\n`);
  }
  process.stdout.write(`Results: ${passes} passed, ${fails} failed, ${skips} skipped (${ms}ms)\n`);
  if (skips > 0) {
    process.stdout.write('\nSkipped:\n');
    for (const s of skipped) process.stdout.write(`  ⊘ ${s.name}: ${s.reason}\n`);
  }
  if (failures.length > 0) {
    process.stdout.write('\nFailures:\n');
    for (const f of failures) process.stdout.write(`  ✗ ${f.name}: ${f.detail}\n`);
    process.exit(1);
  }
  process.exit(0);
}

if (require.main === module) main();
